CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.CREATE_MODEL(
  MODEL_NAME,
  PUBLISHED_SCHEMA,
  DESCRIPTION,
  OWNER_ROLE
) AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end

local function optional_text(value)
    if missing(value) then
        return null
    end
    return tostring(value)
end

local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then
        return nil
    end
    return rows[1][1]
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local published_schema = normalize_name(PUBLISHED_SCHEMA, "PUBLISHED_SCHEMA")

local existing = scalar([[
    SELECT COUNT(*)
    FROM SYS_SEMANTIC.MODELS
    WHERE UPPER(MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name})
if tonumber(existing or 0) > 0 then
    error("SEMANTIC_ADMIN_010: duplicate model name: " .. model_name)
end

query([[
    INSERT INTO SYS_SEMANTIC.MODELS (
      MODEL_NAME, PUBLISHED_SCHEMA, DESCRIPTION, OWNER_ROLE, STATUS,
      PREPROCESSOR_SCHEMA, PREPROCESSOR_SCRIPT, SURFACE_TYPE
    ) VALUES (
      :model_name, :published_schema, :description, :owner_role, 'DRAFT',
      'SEMANTIC_ADMIN', 'SEMANTIC_PREPROCESSOR', 'VIEW_PREPROCESSOR'
    )
]], {
    model_name = model_name,
    published_schema = published_schema,
    description = optional_text(DESCRIPTION),
    owner_role = optional_text(OWNER_ROLE)
})

local model_id = scalar([[
    SELECT MODEL_ID
    FROM SYS_SEMANTIC.MODELS
    WHERE UPPER(MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name})

query([[
    INSERT INTO SYS_SEMANTIC.MODEL_VERSIONS (
      MODEL_ID, VERSION_NUMBER, VERSION_LABEL, STATUS, CHANGE_SUMMARY
    ) VALUES (
      :model_id, 1, 'initial', 'DRAFT', 'Initial model version'
    )
]], {model_id = model_id})

local version_id = scalar([[
    SELECT VERSION_ID
    FROM SYS_SEMANTIC.MODEL_VERSIONS
    WHERE MODEL_ID = :model_id AND VERSION_NUMBER = 1
]], {model_id = model_id})

query([[
    UPDATE SYS_SEMANTIC.MODELS
    SET ACTIVE_VERSION_ID = :version_id,
        UPDATED_AT = CURRENT_TIMESTAMP,
        UPDATED_BY = CURRENT_USER
    WHERE MODEL_ID = :model_id
]], {version_id = version_id, model_id = model_id})
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.DROP_MODEL(
  MODEL_NAME
)
RETURNS TABLE AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

local function upper(value)
    return string.upper(tostring(value))
end

local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end

local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end

local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then
        return nil
    end
    return row_value(rows[1], "VALUE", 1) or rows[1][1]
end

local function quote_ident(name)
    return '"' .. string.gsub(tostring(name), '"', '""') .. '"'
end

local requested_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local model_rows = query([[
    SELECT MODEL_ID, MODEL_NAME, PUBLISHED_SCHEMA
    FROM SYS_SEMANTIC.MODELS
    WHERE UPPER(MODEL_NAME) = UPPER(:model_name)
]], {model_name = requested_name})
if model_rows == nil or #model_rows == 0 then
    error("SEMANTIC_ADMIN_011: model not found: " .. requested_name)
end

local model_id = row_value(model_rows[1], "MODEL_ID", 1)
local model_name = row_value(model_rows[1], "MODEL_NAME", 2)
local published_schema = row_value(model_rows[1], "PUBLISHED_SCHEMA", 3)
local schema_dropped = false

if not missing(published_schema) then
    local normalized_schema = upper(published_schema)
    local protected_schemas = {
        SYS = true,
        EXA_STATISTICS = true,
        SYS_SEMANTIC = true,
        SEMANTIC_ADMIN = true,
        SEMANTIC_CATALOG = true,
        SEMANTIC_AGENT = true,
        MART = true,
    }
    local other_models = scalar([[
        SELECT COUNT(*)
        FROM SYS_SEMANTIC.MODELS
        WHERE MODEL_ID <> :model_id
          AND UPPER(PUBLISHED_SCHEMA) = UPPER(:published_schema)
    ]], {model_id = model_id, published_schema = published_schema})
    local schema_exists = scalar([[
        SELECT COUNT(*)
        FROM SYS.EXA_ALL_SCHEMAS
        WHERE UPPER(SCHEMA_NAME) = UPPER(:published_schema)
    ]], {published_schema = published_schema})
    if tonumber(other_models or 0) == 0
        and tonumber(schema_exists or 0) > 0
        and not protected_schemas[normalized_schema] then
        query("DROP SCHEMA " .. quote_ident(published_schema) .. " CASCADE")
        schema_dropped = true
    end
end

query([[
    DELETE FROM SYS_SEMANTIC.MODEL_EVOLUTION_SUGGESTIONS
    WHERE MODEL_ID = :model_id
       OR AGENT_REQUEST_ID IN (
            SELECT AGENT_REQUEST_ID FROM SYS_SEMANTIC.AGENT_REQUEST_LOG
            WHERE MODEL_ID = :model_id
       )
       OR QUERY_LOG_ID IN (
            SELECT QUERY_LOG_ID FROM SYS_SEMANTIC.QUERY_LOG
            WHERE MODEL_ID = :model_id
       )
       OR FEEDBACK_ID IN (
            SELECT FEEDBACK_ID FROM SYS_SEMANTIC.AGENT_FEEDBACK
            WHERE AGENT_REQUEST_ID IN (
                    SELECT AGENT_REQUEST_ID FROM SYS_SEMANTIC.AGENT_REQUEST_LOG
                    WHERE MODEL_ID = :model_id
                  )
               OR QUERY_LOG_ID IN (
                    SELECT QUERY_LOG_ID FROM SYS_SEMANTIC.QUERY_LOG
                    WHERE MODEL_ID = :model_id
                  )
       )
]], {model_id = model_id})
query([[
    DELETE FROM SYS_SEMANTIC.AGENT_FEEDBACK
    WHERE AGENT_REQUEST_ID IN (
            SELECT AGENT_REQUEST_ID FROM SYS_SEMANTIC.AGENT_REQUEST_LOG
            WHERE MODEL_ID = :model_id
          )
       OR QUERY_LOG_ID IN (
            SELECT QUERY_LOG_ID FROM SYS_SEMANTIC.QUERY_LOG
            WHERE MODEL_ID = :model_id
          )
]], {model_id = model_id})
query([[
    DELETE FROM SYS_SEMANTIC.VALIDATION_RESULTS
    WHERE MODEL_ID = :model_id
       OR VALIDATION_RUN_ID IN (
            SELECT VALIDATION_RUN_ID FROM SYS_SEMANTIC.VALIDATION_RUNS
            WHERE MODEL_ID = :model_id
       )
]], {model_id = model_id})
query([[
    DELETE FROM SYS_SEMANTIC.UNIQUE_KEY_COLUMNS
    WHERE UNIQUE_KEY_ID IN (
        SELECT UNIQUE_KEY_ID FROM SYS_SEMANTIC.UNIQUE_KEYS WHERE MODEL_ID = :model_id
    )
]], {model_id = model_id})
query([[
    DELETE FROM SYS_SEMANTIC.RELATIONSHIP_KEY_MAPPINGS
    WHERE RELATIONSHIP_ID IN (
        SELECT RELATIONSHIP_ID FROM SYS_SEMANTIC.RELATIONSHIPS WHERE MODEL_ID = :model_id
    )
]], {model_id = model_id})
query([[
    DELETE FROM SYS_SEMANTIC.OBJECT_COLUMNS
    WHERE OBJECT_ID IN (
        SELECT OBJECT_ID FROM SYS_SEMANTIC.SEMANTIC_OBJECTS WHERE MODEL_ID = :model_id
    )
]], {model_id = model_id})
query([[
    DELETE FROM SYS_SEMANTIC.METRIC_DEPENDENCIES
    WHERE METRIC_ID IN (
        SELECT METRIC_ID FROM SYS_SEMANTIC.METRICS WHERE MODEL_ID = :model_id
    )
]], {model_id = model_id})
query([[
    DELETE FROM SYS_SEMANTIC.METRIC_INPUTS
    WHERE METRIC_ID IN (
        SELECT METRIC_ID FROM SYS_SEMANTIC.METRICS WHERE MODEL_ID = :model_id
    )
]], {model_id = model_id})
query([[
    DELETE FROM SYS_SEMANTIC.METRIC_FILTERS
    WHERE METRIC_ID IN (
        SELECT METRIC_ID FROM SYS_SEMANTIC.METRICS WHERE MODEL_ID = :model_id
    )
]], {model_id = model_id})
query([[
    DELETE FROM SYS_SEMANTIC.MATERIALIZATION_COLUMNS
    WHERE MATERIALIZATION_ID IN (
        SELECT MATERIALIZATION_ID FROM SYS_SEMANTIC.MATERIALIZATIONS
        WHERE MODEL_ID = :model_id
    )
]], {model_id = model_id})
query([[
    DELETE FROM SYS_SEMANTIC.COMPILE_CACHE
    WHERE MODEL_VERSION_ID IN (
        SELECT VERSION_ID FROM SYS_SEMANTIC.MODEL_VERSIONS WHERE MODEL_ID = :model_id
    )
]], {model_id = model_id})

local model_tables = {
    "METRIC_DIMENSION_MATRIX",
    "MODEL_ROLE_GRANTS",
    "MODEL_PUBLISH_HISTORY",
    "MATERIALIZATIONS",
    "AGENT_INSTRUCTIONS",
    "VERIFIED_QUERIES",
    "CUSTOM_EXTENSIONS",
    "SYNONYMS",
    "SEMANTIC_DEFINITION_SOURCES",
    "IDENTITY_MAPPING_RELATIONS",
    "IDENTITY_BINDINGS",
    "SEMANTIC_IDENTITIES",
    "ATTRIBUTE_FUSION_POLICIES",
    "ATTRIBUTE_BINDINGS",
    "DIMENSIONS",
    "FACTS",
    "METRICS",
    "RELATIONSHIPS",
    "SEMANTIC_OBJECTS",
    "UNIQUE_KEYS",
    "REPRESENTATION_AUTHORITIES",
    "ENTITY_REPRESENTATIONS",
    "ENTITIES",
    "AGENT_REQUEST_LOG",
    "QUERY_LOG",
    "VALIDATION_RUNS",
    "MODEL_VERSIONS",
}
for _, table_name in ipairs(model_tables) do
    query("DELETE FROM SYS_SEMANTIC." .. table_name .. " WHERE MODEL_ID = :model_id",
        {model_id = model_id})
end
query("DELETE FROM SYS_SEMANTIC.MODELS WHERE MODEL_ID = :model_id", {model_id = model_id})

exit({{model_name, published_schema or null, schema_dropped, "DROPPED"}}, [[
  MODEL_NAME VARCHAR(256),
  PUBLISHED_SCHEMA VARCHAR(256),
  SCHEMA_DROPPED BOOLEAN,
  STATUS VARCHAR(32)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_ENTITY(
  MODEL_NAME,
  ENTITY_NAME,
  SOURCE_SCHEMA,
  SOURCE_OBJECT,
  SOURCE_ALIAS,
  PRIMARY_KEY_EXPR,
  GRAIN_DESCRIPTION,
  DESCRIPTION
) AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end

local function optional_text(value)
    if missing(value) then
        return null
    end
    return tostring(value)
end

local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end

local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then
        return nil
    end
    return rows[1][1]
end

local function model_row(model_name)
    local rows = query([[
        SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID AS VERSION_ID
        FROM SYS_SEMANTIC.MODELS m
        WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
    ]], {model_name = model_name})
    if rows == nil or #rows == 0 then
        error("SEMANTIC_ADMIN_011: model not found: " .. model_name)
    end
    return {
        model_id = row_value(rows[1], "MODEL_ID", 1),
        version_id = row_value(rows[1], "VERSION_ID", 2)
    }
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local entity_name = normalize_name(ENTITY_NAME, "ENTITY_NAME")
local source_schema = normalize_name(SOURCE_SCHEMA, "SOURCE_SCHEMA")
local source_object = normalize_name(SOURCE_OBJECT, "SOURCE_OBJECT")
local source_alias = normalize_name(SOURCE_ALIAS, "SOURCE_ALIAS")
local reserved_alias = scalar([[
    SELECT COUNT(*)
    FROM SYS.EXA_SQL_KEYWORDS
    WHERE UPPER(KEYWORD) = UPPER(:source_alias)
      AND RESERVED = TRUE
]], {source_alias = source_alias})
if tonumber(reserved_alias or 0) > 0 then
    error("SEMANTIC_ADMIN_044: entity alias '" .. source_alias
        .. "' is an Exasol reserved word; choose another alias")
end
local model = model_row(model_name)

local duplicate_name = scalar([[
    SELECT COUNT(*)
    FROM SYS_SEMANTIC.ENTITIES
    WHERE MODEL_ID = :model_id
      AND VERSION_ID = :version_id
      AND UPPER(ENTITY_NAME) = UPPER(:entity_name)
]], {model_id = model.model_id, version_id = model.version_id, entity_name = entity_name})
if tonumber(duplicate_name or 0) > 0 then
    error("SEMANTIC_ADMIN_012: duplicate entity name: " .. entity_name)
end

local duplicate_alias = scalar([[
    SELECT COUNT(*)
    FROM SYS_SEMANTIC.ENTITIES
    WHERE MODEL_ID = :model_id
      AND VERSION_ID = :version_id
      AND UPPER(SOURCE_ALIAS) = UPPER(:source_alias)
]], {model_id = model.model_id, version_id = model.version_id, source_alias = source_alias})
if tonumber(duplicate_alias or 0) > 0 then
    error("SEMANTIC_ADMIN_013: duplicate entity alias: " .. source_alias)
end

query([[
    INSERT INTO SYS_SEMANTIC.ENTITIES (
      MODEL_ID, VERSION_ID, ENTITY_NAME, SOURCE_SCHEMA, SOURCE_OBJECT,
      SOURCE_ALIAS, PRIMARY_KEY_EXPR, GRAIN_DESCRIPTION, DESCRIPTION, STATUS
    ) VALUES (
      :model_id, :version_id, :entity_name, :source_schema, :source_object,
      :source_alias, :primary_key_expr, :grain_description, :description, 'ACTIVE'
    )
]], {
    model_id = model.model_id,
    version_id = model.version_id,
    entity_name = entity_name,
    source_schema = source_schema,
    source_object = source_object,
    source_alias = source_alias,
    primary_key_expr = optional_text(PRIMARY_KEY_EXPR),
    grain_description = optional_text(GRAIN_DESCRIPTION),
    description = optional_text(DESCRIPTION)
})

local entity_id = scalar([[
    SELECT ENTITY_ID
    FROM SYS_SEMANTIC.ENTITIES
    WHERE MODEL_ID = :model_id
      AND VERSION_ID = :version_id
      AND UPPER(ENTITY_NAME) = UPPER(:entity_name)
]], {model_id = model.model_id, version_id = model.version_id, entity_name = entity_name})
-- Derived, not declared: ADD_ENTITY takes no SOURCE_KIND, so the primary
-- representation of a federated entity used to be recorded as RELATION --
-- unrecordable truth in a model whose whole point is that the source is
-- federated. The catalog already knows, and the doc calls the distinction a
-- planning input, so a wrong label is a wrong plan input rather than a
-- cosmetic one.
local primary_source_kind = "RELATION"
if tonumber(scalar([[
    SELECT COUNT(*) FROM SYS.EXA_ALL_VIRTUAL_SCHEMAS
    WHERE UPPER(SCHEMA_NAME) = UPPER(:source_schema)
]], {source_schema = source_schema}) or 0) > 0 then
    primary_source_kind = "VIRTUAL_SCHEMA"
end
query([[
    INSERT INTO SYS_SEMANTIC.ENTITY_REPRESENTATIONS (
      MODEL_ID, VERSION_ID, ENTITY_ID, REPRESENTATION_NAME, SOURCE_KIND,
      SOURCE_SCHEMA, SOURCE_OBJECT, SOURCE_ALIAS, REPRESENTATION_ROLE,
      PRIORITY, STATUS
    ) VALUES (
      :model_id, :version_id, :entity_id, 'primary', :source_kind,
      :source_schema, :source_object, :source_alias, 'PRIMARY', 1, 'ACTIVE'
    )
]], {source_kind = primary_source_kind, 
    model_id = model.model_id,
    version_id = model.version_id,
    entity_id = entity_id,
    source_schema = source_schema,
    source_object = source_object,
    source_alias = source_alias,
})
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.RECERTIFY_MODEL_IF_PUBLISHED(
  MODEL_NAME
)
RETURNS TABLE AS
-- NULL arrives as userdata, and userdata is truthy: `MODEL_NAME or ""`
-- would render an address and sail past the check below.
local model_name = (MODEL_NAME == nil or MODEL_NAME == null) and ""
    or tostring(MODEL_NAME):match("^%s*(.-)%s*$")
if model_name == "" then
    error("SEMANTIC_ADMIN_001: MODEL_NAME is required")
end
local rows = query([[
    SELECT STATUS FROM SYS_SEMANTIC.MODELS
    WHERE UPPER(MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_011: model not found: " .. model_name)
end
local model_status = rows[1].STATUS or rows[1].status or rows[1][1]
local validation_status = "NOT_REQUIRED"
if tostring(model_status) == "PUBLISHED" then
    local validation_rows = query(
        "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
        {model_name = model_name})
    validation_status = "OK"
    for _, validation_row in ipairs(validation_rows or {}) do
        local severity = validation_row.SEVERITY or validation_row.severity
            or validation_row[1]
        if tostring(severity) == "ERROR" or tostring(severity) == "PRECONDITION" then
            validation_status = tostring(severity)
            break
        elseif tostring(severity) == "WARNING" and validation_status == "OK" then
            validation_status = "WARNING"
        end
    end
end
exit({{model_name, model_status, validation_status}}, [[
  MODEL_NAME VARCHAR(256), MODEL_STATUS VARCHAR(32), VALIDATION_STATUS VARCHAR(32)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_ENTITY_REPRESENTATION(
  MODEL_NAME,
  ENTITY_NAME,
  REPRESENTATION_NAME,
  SOURCE_KIND,
  SOURCE_SCHEMA,
  SOURCE_OBJECT,
  PRIORITY,
  FRESHNESS_POLICY
)
RETURNS TABLE AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

local function upper(value)
    return string.upper(tostring(value))
end

local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end

local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end

local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then return nil end
    return row_value(rows[1], "VALUE", 1) or rows[1][1]
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local entity_name = normalize_name(ENTITY_NAME, "ENTITY_NAME")
local representation_name = normalize_name(REPRESENTATION_NAME, "REPRESENTATION_NAME")
local source_schema = normalize_name(SOURCE_SCHEMA, "SOURCE_SCHEMA")
local source_object = normalize_name(SOURCE_OBJECT, "SOURCE_OBJECT")
local source_kind = missing(SOURCE_KIND) and "RELATION" or upper(trim(SOURCE_KIND))
if source_kind ~= "RELATION" and source_kind ~= "VIRTUAL_SCHEMA" then
    error("SEMANTIC_ADMIN_003: invalid SOURCE_KIND: " .. tostring(SOURCE_KIND))
end
-- The catalog settles it, so a declared kind that disagrees is refused rather
-- than stored. SOURCE_KIND was free text: VIRTUAL_SCHEMA over an ordinary table
-- and RELATION over a virtual schema were both accepted, and the compiler treats
-- the distinction as a planning input.
do
    local declared_virtual = source_kind == "VIRTUAL_SCHEMA"
    local actually_virtual = tonumber(scalar([[
        SELECT COUNT(*) FROM SYS.EXA_ALL_VIRTUAL_SCHEMAS
        WHERE UPPER(SCHEMA_NAME) = UPPER(:source_schema)
    ]], {source_schema = source_schema}) or 0) > 0
    if declared_virtual ~= actually_virtual then
        error("SEMANTIC_ADMIN_218: SOURCE_KIND " .. source_kind .. " disagrees with"
            .. " the catalog: " .. tostring(source_schema) .. " is "
            .. (actually_virtual and "a virtual schema" or "not a virtual schema")
            .. ". Declare " .. (actually_virtual and "VIRTUAL_SCHEMA" or "RELATION")
            .. ", or omit SOURCE_KIND and let it default.")
    end
end
local priority = missing(PRIORITY) and 100 or tonumber(PRIORITY)
if priority == nil or priority < 1 or priority % 1 ~= 0 then
    error("SEMANTIC_ADMIN_003: PRIORITY must be a positive integer")
end

local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, e.ENTITY_ID, p.SOURCE_ALIAS,
           m.STATUS
    FROM SYS_SEMANTIC.MODELS m
    JOIN SYS_SEMANTIC.ENTITIES e
      ON e.MODEL_ID = m.MODEL_ID
     AND e.VERSION_ID = m.ACTIVE_VERSION_ID
     AND UPPER(e.ENTITY_NAME) = UPPER(:entity_name)
     AND e.STATUS = 'ACTIVE'
    JOIN SYS_SEMANTIC.ENTITY_REPRESENTATIONS p
      ON p.ENTITY_ID = e.ENTITY_ID
     AND p.MODEL_ID = e.MODEL_ID
     AND p.VERSION_ID = e.VERSION_ID
     AND p.REPRESENTATION_ROLE = 'PRIMARY'
     AND p.STATUS = 'ACTIVE'
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name, entity_name = entity_name})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_014: entity or active primary representation not found: " .. entity_name)
end
local model_id = row_value(rows[1], "MODEL_ID", 1)
local version_id = row_value(rows[1], "ACTIVE_VERSION_ID", 2)
local entity_id = row_value(rows[1], "ENTITY_ID", 3)
local source_alias = row_value(rows[1], "SOURCE_ALIAS", 4)
local model_status = row_value(rows[1], "STATUS", 5)

local duplicate = scalar([[
    SELECT COUNT(*)
    FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS
    WHERE ENTITY_ID = :entity_id
      AND UPPER(REPRESENTATION_NAME) = UPPER(:representation_name)
]], {entity_id = entity_id, representation_name = representation_name})
if tonumber(duplicate or 0) > 0 then
    error("SEMANTIC_ADMIN_046: duplicate representation name: " .. representation_name)
end

query([[
    INSERT INTO SYS_SEMANTIC.ENTITY_REPRESENTATIONS (
      MODEL_ID, VERSION_ID, ENTITY_ID, REPRESENTATION_NAME, SOURCE_KIND,
      SOURCE_SCHEMA, SOURCE_OBJECT, SOURCE_ALIAS, REPRESENTATION_ROLE,
      PRIORITY, FRESHNESS_POLICY, STATUS
    ) VALUES (
      :model_id, :version_id, :entity_id, :representation_name, :source_kind,
      :source_schema, :source_object, :source_alias, 'ALTERNATE',
      :priority, :freshness_policy, 'ACTIVE'
    )
]], {
    model_id = model_id,
    version_id = version_id,
    entity_id = entity_id,
    representation_name = representation_name,
    source_kind = source_kind,
    source_schema = source_schema,
    source_object = source_object,
    source_alias = source_alias,
    priority = priority,
    freshness_policy = missing(FRESHNESS_POLICY) and null or tostring(FRESHNESS_POLICY),
})
local representation_id = scalar([[
    SELECT REPRESENTATION_ID
    FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS
    WHERE ENTITY_ID = :entity_id
      AND UPPER(REPRESENTATION_NAME) = UPPER(:representation_name)
]], {entity_id = entity_id, representation_name = representation_name})
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = version_id})
query([[
    UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE'
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND STATUS IN ('OK', 'WARNING')
]], {model_id = model_id, version_id = version_id})

-- Registering a representation seeds compatibility bindings, and a seeded
-- binding that does not hold is the single most common reason the next
-- authoring call fails. Report them here the way the F5 compound call already
-- did, instead of leaving the modeller to find them in a later VALIDATE_MODEL.
local candidate_validation = query(
    "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
    {model_name = model_name})
local validation_errors = {}
local generated_binding_issues = {}
local binding_suffix = "@" .. upper(representation_name)
for _, validation_row in ipairs(candidate_validation or {}) do
    local severity = tostring(row_value(validation_row, "SEVERITY", 1))
    if severity == "ERROR" or severity == "PRECONDITION" then
        local rule_code = row_value(validation_row, "RULE_CODE", 4)
            or "SEMANTIC_MODEL_ERROR"
        local message = row_value(validation_row, "MESSAGE", 5)
            or "model validation failed"
        local object_type = row_value(validation_row, "OBJECT_TYPE", 2) or "MODEL"
        local object_name = row_value(validation_row, "OBJECT_NAME", 3) or model_name
        local detail = tostring(rule_code) .. " [" .. tostring(object_type)
            .. " " .. tostring(object_name) .. "] " .. tostring(message)
        validation_errors[#validation_errors + 1] = detail
        -- An issue belongs to this registration when it is attributed to one of
        -- its seeded bindings, to the representation itself, or when the
        -- message names it -- SEMANTIC_MODEL_017 reports "in representation(s):
        -- <name>" against the *dimension*, which is the common case.
        local normalized_object_name = upper(object_name)
        local normalized_name = upper(representation_name)
        if (upper(object_type) == "ATTRIBUTE_BINDING"
                and string.sub(normalized_object_name, -#binding_suffix) == binding_suffix)
            or (upper(object_type) == "ENTITY_REPRESENTATION"
                and string.sub(normalized_object_name, -#normalized_name - 1)
                    == "." .. normalized_name)
            or string.find(upper(message), "REPRESENTATION(S): ", 1, true) ~= nil
                and string.find(upper(message), normalized_name, 1, true) ~= nil then
            generated_binding_issues[#generated_binding_issues + 1] = detail
        end
    end
end

if tostring(model_status) == "PUBLISHED" and #validation_errors > 0 then
    query("DELETE FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS WHERE REPRESENTATION_ID = :representation_id",
        {representation_id = representation_id})
    query("DELETE FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS WHERE REPRESENTATION_ID = :representation_id",
        {representation_id = representation_id})
    query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
        {model_name = model_name})
    error("SEMANTIC_ADMIN_094: published representation change rejected and restored; "
        .. "candidate introduced validation error: " .. validation_errors[1])
end

exit({{representation_id, model_name, entity_name, representation_name,
    source_kind, source_schema, source_object, source_alias, "ALTERNATE", priority,
    #generated_binding_issues,
    #generated_binding_issues == 0 and null
        or table.concat(generated_binding_issues, "; ")}}, [[
  REPRESENTATION_ID DECIMAL(18,0),
  MODEL_NAME VARCHAR(256),
  ENTITY_NAME VARCHAR(256),
  REPRESENTATION_NAME VARCHAR(256),
  SOURCE_KIND VARCHAR(64),
  SOURCE_SCHEMA VARCHAR(256),
  SOURCE_OBJECT VARCHAR(256),
  SOURCE_ALIAS VARCHAR(128),
  REPRESENTATION_ROLE VARCHAR(64),
  PRIORITY DECIMAL(18,0),
  GENERATED_BINDING_ISSUE_COUNT DECIMAL(18,0),
  GENERATED_BINDING_ISSUES VARCHAR(2000000)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.CALL_ADMIN_JSON(
  SCRIPT_NAME,
  ARGS_JSON
)
RETURNS TABLE AS
-- Call any SEMANTIC_ADMIN script with a JSON object instead of positional
-- arguments.
--
-- Exasol checks parameter arity in the SQL layer, before a script body runs, so
-- a positional mistake can only ever surface as `expected N script parameters
-- but got M` -- no script name, no parameter name, and no way for the script to
-- improve it. Named arguments remove the failure mode instead of describing it:
-- an unknown or missing parameter is reported here, by name, against the
-- signature published in SEMANTIC_CATALOG.ADMIN_SCRIPT_PARAMETERS.
import("SEMANTIC_ADMIN.SEMANTIC_DEFINITION_RUNTIME", "semantic_definition")

-- NULL arrives as userdata, and userdata is truthy: `value or ""` would render
-- it as an address and defeat the required-parameter check below.
local function trim(value)
    if value == nil or value == null then return "" end
    return tostring(value):match("^%s*(.-)%s*$")
end
local function upper(value) return string.upper(trim(value)) end
local function row_value(row, name, position)
    if row == nil then return nil end
    return row[name] or row[string.lower(name)] or row[position]
end
local function sql_string(value)
    if value == nil or value == null then return "NULL" end
    return "'" .. string.gsub(tostring(value), "'", "''") .. "'"
end

local script_name = upper(SCRIPT_NAME)
if script_name == "" then
    error("SEMANTIC_ADMIN_001: SCRIPT_NAME is required")
end
if script_name == "CALL_ADMIN_JSON" then
    error("SEMANTIC_ADMIN_100: CALL_ADMIN_JSON cannot call itself")
end

local signature_rows = query([[
    SELECT ORDINAL_POSITION, PARAMETER_NAME, PARAMETER_COUNT, CALL_TEMPLATE
    FROM SEMANTIC_CATALOG.ADMIN_SCRIPT_PARAMETERS
    WHERE SCRIPT_NAME = :script_name
    ORDER BY ORDINAL_POSITION
]], {script_name = script_name})
if signature_rows == nil or #signature_rows == 0 then
    error("SEMANTIC_ADMIN_100: unknown admin script: " .. script_name
        .. ". Query SEMANTIC_CATALOG.ADMIN_SCRIPT_PARAMETERS for the scripts and "
        .. "their parameters.")
end

local parameters = {}
local known = {}
local call_template = nil
for _, signature_row in ipairs(signature_rows) do
    local parameter_name = row_value(signature_row, "PARAMETER_NAME", 2)
    call_template = call_template or row_value(signature_row, "CALL_TEMPLATE", 4)
    if parameter_name ~= nil and parameter_name ~= null then
        parameters[#parameters + 1] = tostring(parameter_name)
        known[upper(parameter_name)] = true
    end
end

local args = {}
local args_text = trim(ARGS_JSON)
if args_text ~= "" and upper(args_text) ~= "NULL" then
    local ok, decoded = pcall(semantic_definition.decode_json, args_text)
    if not ok or type(decoded) ~= "table" then
        error("SEMANTIC_ADMIN_101: ARGS_JSON must be a JSON object of parameter "
            .. "names for " .. script_name .. ". Expected: " .. tostring(call_template))
    end
    for key, value in pairs(decoded) do
        args[upper(key)] = value
    end
end

local unknown = {}
for key, _ in pairs(args) do
    if not known[key] then unknown[#unknown + 1] = key end
end
if #unknown > 0 then
    table.sort(unknown)
    error("SEMANTIC_ADMIN_101: unknown parameter(s) for " .. script_name .. ": "
        .. table.concat(unknown, ", ") .. ". Expected: " .. tostring(call_template))
end

local call_args = {}
for _, parameter_name in ipairs(parameters) do
    local value = args[upper(parameter_name)]
    if value == nil or value == null then
        call_args[#call_args + 1] = "NULL"
    elseif type(value) == "boolean" then
        call_args[#call_args + 1] = value and "TRUE" or "FALSE"
    elseif type(value) == "number" then
        call_args[#call_args + 1] = tostring(value)
    elseif type(value) == "table" then
        call_args[#call_args + 1] = sql_string(semantic_definition.encode_json(value))
    else
        call_args[#call_args + 1] = sql_string(value)
    end
end

local statement = "EXECUTE SCRIPT SEMANTIC_ADMIN." .. script_name
    .. "(" .. table.concat(call_args, ", ") .. ")"
local rows = query(statement)

local result = {}
for _, result_row in ipairs(rows or {}) do
    local values = {}
    local index = 1
    while result_row[index] ~= nil do
        local value = result_row[index]
        values[index] = (value == null) and null or value
        index = index + 1
    end
    result[#result + 1] = values
end

exit({{"OK", script_name, #result, semantic_definition.encode_json(result), statement}}, [[
  STATUS VARCHAR(32),
  SCRIPT_NAME VARCHAR(128),
  ROW_COUNT DECIMAL(18,0),
  RESULT_JSON VARCHAR(2000000),
  EXECUTED_STATEMENT VARCHAR(2000000)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_ENTITY_REPRESENTATION_WITH_AUTHORITY(
  MODEL_NAME,
  ENTITY_NAME,
  REPRESENTATION_NAME,
  SOURCE_KIND,
  SOURCE_SCHEMA,
  SOURCE_OBJECT,
  PRIORITY,
  FRESHNESS_POLICY,
  AUTHORITY_ROLE
)
RETURNS TABLE AS
-- Register an alternate representation and declare its authority in one step.
--
-- F4 needs both: a representation with no authority declaration defaults to
-- PREFER, so the two-call sequence passes through a state that says something
-- the modeller did not mean, and on a published model each call is validated
-- separately. This composes the two, and unwinds the representation if the
-- authority declaration is refused -- so the pair either both land or neither
-- does, which is what the other compound calls guarantee.
local function row_value(row, name, position)
    if row == nil then return nil end
    return row[name] or row[string.lower(name)] or row[position]
end
-- NULL arrives as userdata, and userdata is truthy: `value or ""` would render
-- it as an address and defeat the required-parameter check below.
local function trim(value)
    if value == nil or value == null then return "" end
    return tostring(value):match("^%s*(.-)%s*$")
end
local function upper(value) return string.upper(trim(value)) end

local model_name = trim(MODEL_NAME)
local entity_name = trim(ENTITY_NAME)
local representation_name = trim(REPRESENTATION_NAME)
local authority_role = upper(AUTHORITY_ROLE)
if authority_role ~= "AUTHORITATIVE" and authority_role ~= "PREFER"
    and authority_role ~= "SUPPLEMENTAL" then
    error("SEMANTIC_ADMIN_003: AUTHORITY_ROLE must be AUTHORITATIVE, PREFER, or SUPPLEMENTAL")
end

local added = query([[
    EXECUTE SCRIPT SEMANTIC_ADMIN.ADD_ENTITY_REPRESENTATION(
        :model_name, :entity_name, :representation_name, :source_kind,
        :source_schema, :source_object, :priority, :freshness_policy)
]], {
    model_name = model_name,
    entity_name = entity_name,
    representation_name = representation_name,
    source_kind = SOURCE_KIND,
    source_schema = SOURCE_SCHEMA,
    source_object = SOURCE_OBJECT,
    priority = PRIORITY,
    freshness_policy = FRESHNESS_POLICY,
})
local added_row = added ~= nil and added[1] or nil
if added_row == nil then
    error("SEMANTIC_ADMIN_046: representation was not registered: " .. representation_name)
end

local ok, authority_error = pcall(query, [[
    EXECUTE SCRIPT SEMANTIC_ADMIN.SET_REPRESENTATION_AUTHORITY(
        :model_name, :entity_name, :representation_name, :authority_role)
]], {
    model_name = model_name,
    entity_name = entity_name,
    representation_name = representation_name,
    authority_role = authority_role,
})
if not ok then
    -- Unwind the half-applied pair, so a refused authority declaration does not
    -- leave a representation the caller did not ask for on its own.
    pcall(query, [[
        EXECUTE SCRIPT SEMANTIC_ADMIN.REMOVE_ENTITY_REPRESENTATION(
            :model_name, :entity_name, :representation_name)
    ]], {
        model_name = model_name,
        entity_name = entity_name,
        representation_name = representation_name,
    })
    error("SEMANTIC_ADMIN_094: representation-with-authority candidate rejected and "
        .. "restored; the authority declaration failed: " .. tostring(authority_error))
end

exit({{
    row_value(added_row, "REPRESENTATION_ID", 1),
    model_name,
    entity_name,
    representation_name,
    row_value(added_row, "SOURCE_KIND", 5),
    row_value(added_row, "SOURCE_SCHEMA", 6),
    row_value(added_row, "SOURCE_OBJECT", 7),
    row_value(added_row, "SOURCE_ALIAS", 8),
    authority_role,
    row_value(added_row, "PRIORITY", 10),
    row_value(added_row, "GENERATED_BINDING_ISSUE_COUNT", 11),
    row_value(added_row, "GENERATED_BINDING_ISSUES", 12),
}}, [[
  REPRESENTATION_ID DECIMAL(18,0),
  MODEL_NAME VARCHAR(256),
  ENTITY_NAME VARCHAR(256),
  REPRESENTATION_NAME VARCHAR(256),
  SOURCE_KIND VARCHAR(64),
  SOURCE_SCHEMA VARCHAR(256),
  SOURCE_OBJECT VARCHAR(256),
  SOURCE_ALIAS VARCHAR(128),
  AUTHORITY_ROLE VARCHAR(32),
  PRIORITY DECIMAL(18,0),
  GENERATED_BINDING_ISSUE_COUNT DECIMAL(18,0),
  GENERATED_BINDING_ISSUES VARCHAR(2000000)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_SEMANTIC_IDENTITY(
  MODEL_NAME, ENTITY_NAME, IDENTITY_NAME, IDENTITY_KIND, DATA_TYPE, DESCRIPTION
)
RETURNS TABLE AS
-- NULL arrives as userdata, and userdata is truthy: `value or ""` would render
-- it as an address and defeat the required-parameter check below.
local function trim(value)
    if value == nil or value == null then return "" end
    return tostring(value):match("^%s*(.-)%s*$")
end
local function upper(value) return string.upper(trim(value)) end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local model_name = trim(MODEL_NAME)
local entity_name = trim(ENTITY_NAME)
local identity_name = trim(IDENTITY_NAME)
local identity_kind = upper(IDENTITY_KIND)
local data_type = trim(DATA_TYPE)
if model_name == "" or entity_name == "" or identity_name == "" or data_type == "" then
    error("SEMANTIC_ADMIN_001: model, entity, identity, and data type are required")
end
if identity_kind ~= "BUSINESS" and identity_kind ~= "GLOBAL" then
    error("SEMANTIC_ADMIN_003: IDENTITY_KIND must be BUSINESS or GLOBAL")
end
local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, e.ENTITY_ID, m.STATUS
    FROM SYS_SEMANTIC.MODELS m JOIN SYS_SEMANTIC.ENTITIES e
      ON e.MODEL_ID = m.MODEL_ID AND e.VERSION_ID = m.ACTIVE_VERSION_ID
     AND UPPER(e.ENTITY_NAME) = UPPER(:entity_name) AND e.STATUS = 'ACTIVE'
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name, entity_name = entity_name})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_014: entity not found: " .. entity_name)
end
local model_id = row_value(rows[1], "MODEL_ID", 1)
local version_id = row_value(rows[1], "ACTIVE_VERSION_ID", 2)
local entity_id = row_value(rows[1], "ENTITY_ID", 3)
local model_status = row_value(rows[1], "STATUS", 4)
local existing = query([[
    SELECT IDENTITY_ID, IDENTITY_KIND, DATA_TYPE, DESCRIPTION
    FROM SYS_SEMANTIC.SEMANTIC_IDENTITIES
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND ENTITY_ID = :entity_id AND UPPER(IDENTITY_NAME) = UPPER(:identity_name)
      AND STATUS = 'ACTIVE'
]], {model_id = model_id, version_id = version_id, entity_id = entity_id,
      identity_name = identity_name})
local conflicting = query([[
    SELECT IDENTITY_ID FROM SYS_SEMANTIC.SEMANTIC_IDENTITIES
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND UPPER(IDENTITY_NAME) = UPPER(:identity_name)
      AND ENTITY_ID <> :entity_id AND STATUS = 'ACTIVE'
]], {model_id = model_id, version_id = version_id, entity_id = entity_id,
      identity_name = identity_name})
if conflicting ~= nil and #conflicting > 0 then
    error("SEMANTIC_ADMIN_011: duplicate semantic identity name: " .. identity_name)
end
local entity_identity = query([[
    SELECT IDENTITY_NAME FROM SYS_SEMANTIC.SEMANTIC_IDENTITIES
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND ENTITY_ID = :entity_id AND UPPER(IDENTITY_NAME) <> UPPER(:identity_name)
      AND STATUS = 'ACTIVE'
]], {model_id = model_id, version_id = version_id, entity_id = entity_id,
      identity_name = identity_name})
if entity_identity ~= nil and #entity_identity > 0 then
    error("SEMANTIC_ADMIN_051: entity already has an active semantic identity: "
        .. tostring(row_value(entity_identity[1], "IDENTITY_NAME", 1)))
end
local identity_id
local was_update = existing ~= nil and #existing > 0
local previous_identity_kind = was_update
    and row_value(existing[1], "IDENTITY_KIND", 2) or nil
local previous_data_type = was_update
    and row_value(existing[1], "DATA_TYPE", 3) or nil
local previous_description = was_update
    and (row_value(existing[1], "DESCRIPTION", 4) or null) or null
if existing ~= nil and #existing > 0 then
    identity_id = row_value(existing[1], "IDENTITY_ID", 1)
    query([[
        UPDATE SYS_SEMANTIC.SEMANTIC_IDENTITIES
        SET IDENTITY_KIND = :identity_kind, DATA_TYPE = :data_type,
            DESCRIPTION = :description, UPDATED_AT = CURRENT_TIMESTAMP,
            UPDATED_BY = CURRENT_USER
        WHERE IDENTITY_ID = :identity_id
    ]], {identity_id = identity_id, identity_kind = identity_kind,
          data_type = data_type, description = DESCRIPTION})
else
    query([[
        INSERT INTO SYS_SEMANTIC.SEMANTIC_IDENTITIES (
          MODEL_ID, VERSION_ID, ENTITY_ID, IDENTITY_NAME, IDENTITY_KIND,
          DATA_TYPE, DESCRIPTION, STATUS
        ) VALUES (
          :model_id, :version_id, :entity_id, :identity_name, :identity_kind,
          :data_type, :description, 'ACTIVE'
        )
    ]], {model_id = model_id, version_id = version_id, entity_id = entity_id,
          identity_name = identity_name, identity_kind = identity_kind,
          data_type = data_type, description = DESCRIPTION})
    local ids = query("SELECT MAX(IDENTITY_ID) FROM SYS_SEMANTIC.SEMANTIC_IDENTITIES WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id",
        {model_id = model_id, version_id = version_id})
    identity_id = ids[1][1]
end
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = version_id})
query("UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE' WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id AND STATUS IN ('OK', 'WARNING')",
    {model_id = model_id, version_id = version_id})
if tostring(model_status) == "PUBLISHED" then
    local validation_rows = query(
        "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
        {model_name = model_name})
    for _, validation_row in ipairs(validation_rows or {}) do
        if tostring(row_value(validation_row, "SEVERITY", 1)) == "ERROR"
            or tostring(row_value(validation_row, "SEVERITY", 1)) == "PRECONDITION" then
            local rule_code = row_value(validation_row, "RULE_CODE", 4)
                or "SEMANTIC_MODEL_ERROR"
            local message = row_value(validation_row, "MESSAGE", 5)
                or "model validation failed"
            if was_update then
                query([[
                    UPDATE SYS_SEMANTIC.SEMANTIC_IDENTITIES
                    SET IDENTITY_KIND = :identity_kind, DATA_TYPE = :data_type,
                        DESCRIPTION = :description, UPDATED_AT = CURRENT_TIMESTAMP,
                        UPDATED_BY = CURRENT_USER
                    WHERE IDENTITY_ID = :identity_id
                ]], {identity_id = identity_id,
                      identity_kind = previous_identity_kind,
                      data_type = previous_data_type,
                      description = previous_description})
            else
                query("DELETE FROM SYS_SEMANTIC.SEMANTIC_IDENTITIES WHERE IDENTITY_ID = :identity_id",
                    {identity_id = identity_id})
            end
            query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
                {model_name = model_name})
            error("SEMANTIC_ADMIN_094: published semantic-identity change rejected and restored; "
                .. "candidate introduced validation error: "
                .. tostring(rule_code) .. " " .. tostring(message))
        end
    end
end
exit({{identity_id, model_name, entity_name, identity_name, identity_kind, data_type}}, [[
  IDENTITY_ID DECIMAL(18,0), MODEL_NAME VARCHAR(256), ENTITY_NAME VARCHAR(256),
  IDENTITY_NAME VARCHAR(256), IDENTITY_KIND VARCHAR(32), DATA_TYPE VARCHAR(128)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_SEMANTIC_IDENTITY_WITH_BINDINGS(
  MODEL_NAME, ENTITY_NAME, IDENTITY_NAME, IDENTITY_KIND, DATA_TYPE, DESCRIPTION,
  BINDINGS_JSON
)
RETURNS TABLE AS
import("SEMANTIC_ADMIN.SEMANTIC_DEFINITION_RUNTIME", "semantic_definition")
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end
-- NULL arrives as userdata, and userdata is truthy: `value or ""` would render
-- it as an address and defeat the required-parameter check below.
local function trim(value)
    if value == nil or value == null then return "" end
    return tostring(value):match("^%s*(.-)%s*$")
end
local function upper(value) return string.upper(trim(value)) end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local function json_scalar(value)
    if type(value) == "table" then return nil end
    return value
end
local function required_json(item, field, label)
    local value = json_scalar(item[field])
    if missing(value) then
        error("SEMANTIC_ADMIN_063: " .. label .. " is required")
    end
    return trim(value)
end
local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then return nil end
    return rows[1][1]
end

local model_name = trim(MODEL_NAME)
local entity_name = trim(ENTITY_NAME)
local identity_name = trim(IDENTITY_NAME)
local identity_kind = upper(IDENTITY_KIND)
local data_type = trim(DATA_TYPE)
if model_name == "" or entity_name == "" or identity_name == "" or data_type == "" then
    error("SEMANTIC_ADMIN_001: model, entity, identity, and data type are required")
end
if identity_kind ~= "BUSINESS" and identity_kind ~= "GLOBAL" then
    error("SEMANTIC_ADMIN_003: IDENTITY_KIND must be BUSINESS or GLOBAL")
end
local decoded, bindings = pcall(semantic_definition.decode_json,
    missing(BINDINGS_JSON) and "" or tostring(BINDINGS_JSON))
if not decoded or type(bindings) ~= "table" or #bindings == 0 then
    error("SEMANTIC_ADMIN_063: BINDINGS_JSON must be a non-empty JSON array: "
        .. tostring(bindings))
end

local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, m.STATUS, e.ENTITY_ID
    FROM SYS_SEMANTIC.MODELS m
    JOIN SYS_SEMANTIC.ENTITIES e
      ON e.MODEL_ID = m.MODEL_ID AND e.VERSION_ID = m.ACTIVE_VERSION_ID
     AND UPPER(e.ENTITY_NAME) = UPPER(:entity_name) AND e.STATUS = 'ACTIVE'
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name, entity_name = entity_name})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_014: entity not found: " .. entity_name)
end
local model_id = row_value(rows[1], "MODEL_ID", 1)
local version_id = row_value(rows[1], "ACTIVE_VERSION_ID", 2)
local model_status = row_value(rows[1], "STATUS", 3)
local entity_id = row_value(rows[1], "ENTITY_ID", 4)
local existing = scalar([[
    SELECT COUNT(*) FROM SYS_SEMANTIC.SEMANTIC_IDENTITIES
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND (ENTITY_ID = :entity_id OR UPPER(IDENTITY_NAME) = UPPER(:identity_name))
      AND STATUS = 'ACTIVE'
]], {model_id = model_id, version_id = version_id, entity_id = entity_id,
      identity_name = identity_name})
if tonumber(existing or 0) > 0 then
    error("SEMANTIC_ADMIN_051: entity or identity name already has an active semantic identity")
end
local representation_rows = query([[
    SELECT REPRESENTATION_ID, REPRESENTATION_NAME
    FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND ENTITY_ID = :entity_id AND STATUS = 'ACTIVE'
]], {model_id = model_id, version_id = version_id, entity_id = entity_id})
local representations = {}
for _, representation_row in ipairs(representation_rows or {}) do
    local name = row_value(representation_row, "REPRESENTATION_NAME", 2)
    representations[upper(name)] = {
        id = row_value(representation_row, "REPRESENTATION_ID", 1),
        name = name,
    }
end

local prepared = {}
local seen = {}
for index, item in ipairs(bindings) do
    if type(item) ~= "table" then
        error("SEMANTIC_ADMIN_063: binding " .. tostring(index) .. " must be an object")
    end
    local representation_name = required_json(
        item, "representation_name", "binding representation_name")
    local representation = representations[upper(representation_name)]
    if representation == nil then
        error("SEMANTIC_ADMIN_063: binding references an inactive or unknown representation: "
            .. representation_name)
    end
    if seen[upper(representation_name)] then
        error("SEMANTIC_ADMIN_063: duplicate binding for representation: "
            .. representation_name)
    end
    seen[upper(representation_name)] = true
    local binding_kind = upper(required_json(item, "binding_kind", "binding_kind"))
    if binding_kind ~= "DIRECT" and binding_kind ~= "MAPPED" then
        error("SEMANTIC_ADMIN_003: BINDING_KIND must be DIRECT or MAPPED")
    end
    local mapping = item.mapping
    if binding_kind == "DIRECT" and mapping ~= nil and mapping ~= null then
        error("SEMANTIC_ADMIN_063: DIRECT binding must not include mapping metadata: "
            .. representation_name)
    end
    if binding_kind == "MAPPED" and type(mapping) ~= "table" then
        error("SEMANTIC_ADMIN_063: MAPPED binding requires a mapping object: "
            .. representation_name)
    end
    local prepared_mapping = nil
    if binding_kind == "MAPPED" then
        local certification = upper(required_json(
            mapping, "certification_status", "mapping certification_status"))
        if certification ~= "CERTIFIED" then
            error("SEMANTIC_ADMIN_003: runtime identity mappings must be CERTIFIED")
        end
        prepared_mapping = {
            source_schema = required_json(mapping, "source_schema", "mapping source_schema"),
            source_object = required_json(mapping, "source_object", "mapping source_object"),
            source_local_column = required_json(
                mapping, "source_local_column", "mapping source_local_column"),
            semantic_key_column = required_json(
                mapping, "semantic_key_column", "mapping semantic_key_column"),
            certification_status = certification,
        }
    end
    prepared[#prepared + 1] = {
        representation = representation,
        source_expression = required_json(
            item, "source_expression", "binding source_expression"),
        binding_kind = binding_kind,
        mapping = prepared_mapping,
    }
end
for representation_key, representation in pairs(representations) do
    if not seen[representation_key] then
        error("SEMANTIC_ADMIN_063: no binding supplied for active representation: "
            .. tostring(representation.name))
    end
end

query([[
    INSERT INTO SYS_SEMANTIC.SEMANTIC_IDENTITIES (
      MODEL_ID, VERSION_ID, ENTITY_ID, IDENTITY_NAME, IDENTITY_KIND,
      DATA_TYPE, DESCRIPTION, STATUS
    ) VALUES (
      :model_id, :version_id, :entity_id, :identity_name, :identity_kind,
      :data_type, :description, 'ACTIVE'
    )
]], {model_id = model_id, version_id = version_id, entity_id = entity_id,
      identity_name = identity_name, identity_kind = identity_kind,
      data_type = data_type, description = DESCRIPTION})
local identity_id = scalar([[
    SELECT IDENTITY_ID FROM SYS_SEMANTIC.SEMANTIC_IDENTITIES
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND ENTITY_ID = :entity_id AND UPPER(IDENTITY_NAME) = UPPER(:identity_name)
      AND STATUS = 'ACTIVE'
]], {model_id = model_id, version_id = version_id, entity_id = entity_id,
      identity_name = identity_name})
local result = {}
for _, item in ipairs(prepared) do
    query([[
        INSERT INTO SYS_SEMANTIC.IDENTITY_BINDINGS (
          MODEL_ID, VERSION_ID, ENTITY_ID, IDENTITY_ID, REPRESENTATION_ID,
          SOURCE_EXPRESSION, BINDING_KIND, STATUS
        ) VALUES (
          :model_id, :version_id, :entity_id, :identity_id, :representation_id,
          :source_expression, :binding_kind, 'ACTIVE'
        )
    ]], {model_id = model_id, version_id = version_id, entity_id = entity_id,
          identity_id = identity_id, representation_id = item.representation.id,
          source_expression = item.source_expression, binding_kind = item.binding_kind})
    local binding_id = scalar([[
        SELECT IDENTITY_BINDING_ID FROM SYS_SEMANTIC.IDENTITY_BINDINGS
        WHERE IDENTITY_ID = :identity_id AND REPRESENTATION_ID = :representation_id
          AND STATUS = 'ACTIVE'
    ]], {identity_id = identity_id,
          representation_id = item.representation.id})
    if item.mapping ~= nil then
        query([[
            INSERT INTO SYS_SEMANTIC.IDENTITY_MAPPING_RELATIONS (
              MODEL_ID, VERSION_ID, IDENTITY_BINDING_ID, SOURCE_SCHEMA,
              SOURCE_OBJECT, SOURCE_LOCAL_COLUMN, SEMANTIC_KEY_COLUMN,
              CERTIFICATION_STATUS, STATUS
            ) VALUES (
              :model_id, :version_id, :binding_id, :source_schema,
              :source_object, :source_local_column, :semantic_key_column,
              :certification_status, 'ACTIVE'
            )
        ]], {model_id = model_id, version_id = version_id, binding_id = binding_id,
              source_schema = item.mapping.source_schema,
              source_object = item.mapping.source_object,
              source_local_column = item.mapping.source_local_column,
              semantic_key_column = item.mapping.semantic_key_column,
              certification_status = item.mapping.certification_status})
    end
    result[#result + 1] = {identity_id, binding_id, model_name, entity_name,
        identity_name, item.representation.name, item.binding_kind}
end
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = version_id})
query("UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE' WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id AND STATUS IN ('OK', 'WARNING')",
    {model_id = model_id, version_id = version_id})
if tostring(model_status) == "PUBLISHED" then
    local candidate_validation = query(
        "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
        {model_name = model_name})
    for _, validation_row in ipairs(candidate_validation or {}) do
        if tostring(row_value(validation_row, "SEVERITY", 1)) == "ERROR"
            or tostring(row_value(validation_row, "SEVERITY", 1)) == "PRECONDITION" then
            local rule_code = row_value(validation_row, "RULE_CODE", 4)
                or "SEMANTIC_MODEL_ERROR"
            local message = row_value(validation_row, "MESSAGE", 5)
                or "model validation failed"
            query([[
                DELETE FROM SYS_SEMANTIC.IDENTITY_MAPPING_RELATIONS
                WHERE IDENTITY_BINDING_ID IN (
                  SELECT IDENTITY_BINDING_ID FROM SYS_SEMANTIC.IDENTITY_BINDINGS
                  WHERE IDENTITY_ID = :identity_id
                )
            ]], {identity_id = identity_id})
            query("DELETE FROM SYS_SEMANTIC.IDENTITY_BINDINGS WHERE IDENTITY_ID = :identity_id",
                {identity_id = identity_id})
            query("DELETE FROM SYS_SEMANTIC.SEMANTIC_IDENTITIES WHERE IDENTITY_ID = :identity_id",
                {identity_id = identity_id})
            query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
                {model_name = model_name})
            error("SEMANTIC_ADMIN_094: published identity-with-bindings candidate rejected and restored; "
                .. "candidate introduced validation error: "
                .. tostring(rule_code) .. " " .. tostring(message))
        end
    end
end
exit(result, [[
  IDENTITY_ID DECIMAL(18,0), IDENTITY_BINDING_ID DECIMAL(18,0),
  MODEL_NAME VARCHAR(256), ENTITY_NAME VARCHAR(256), IDENTITY_NAME VARCHAR(256),
  REPRESENTATION_NAME VARCHAR(256), BINDING_KIND VARCHAR(32)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_IDENTITY_BINDING(
  MODEL_NAME, IDENTITY_NAME, REPRESENTATION_NAME, SOURCE_EXPRESSION, BINDING_KIND
)
RETURNS TABLE AS
-- NULL arrives as userdata, and userdata is truthy: `value or ""` would render
-- it as an address and defeat the required-parameter check below.
local function trim(value)
    if value == nil or value == null then return "" end
    return tostring(value):match("^%s*(.-)%s*$")
end
local function upper(value) return string.upper(trim(value)) end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local model_name = trim(MODEL_NAME)
local identity_name = trim(IDENTITY_NAME)
local representation_name = trim(REPRESENTATION_NAME)
local source_expression = trim(SOURCE_EXPRESSION)
local binding_kind = upper(BINDING_KIND)
if source_expression == "" then error("SEMANTIC_ADMIN_001: SOURCE_EXPRESSION is required") end
if binding_kind ~= "DIRECT" and binding_kind ~= "MAPPED" then
    error("SEMANTIC_ADMIN_003: BINDING_KIND must be DIRECT or MAPPED")
end
local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, si.ENTITY_ID, si.IDENTITY_ID,
           er.REPRESENTATION_ID
    FROM SYS_SEMANTIC.MODELS m
    JOIN SYS_SEMANTIC.SEMANTIC_IDENTITIES si
      ON si.MODEL_ID = m.MODEL_ID AND si.VERSION_ID = m.ACTIVE_VERSION_ID
     AND UPPER(si.IDENTITY_NAME) = UPPER(:identity_name) AND si.STATUS = 'ACTIVE'
    JOIN SYS_SEMANTIC.ENTITY_REPRESENTATIONS er
      ON er.ENTITY_ID = si.ENTITY_ID AND er.VERSION_ID = si.VERSION_ID
     AND UPPER(er.REPRESENTATION_NAME) = UPPER(:representation_name)
     AND er.STATUS = 'ACTIVE'
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name, identity_name = identity_name,
      representation_name = representation_name})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_049: identity or representation not found")
end
local model_id = row_value(rows[1], "MODEL_ID", 1)
local version_id = row_value(rows[1], "ACTIVE_VERSION_ID", 2)
local entity_id = row_value(rows[1], "ENTITY_ID", 3)
local identity_id = row_value(rows[1], "IDENTITY_ID", 4)
local representation_id = row_value(rows[1], "REPRESENTATION_ID", 5)
local existing = query([[
    SELECT IDENTITY_BINDING_ID FROM SYS_SEMANTIC.IDENTITY_BINDINGS
    WHERE IDENTITY_ID = :identity_id AND REPRESENTATION_ID = :representation_id
      AND STATUS = 'ACTIVE'
]], {identity_id = identity_id, representation_id = representation_id})
local binding_id
if existing ~= nil and #existing > 0 then
    binding_id = row_value(existing[1], "IDENTITY_BINDING_ID", 1)
    query([[
        UPDATE SYS_SEMANTIC.IDENTITY_BINDINGS
        SET SOURCE_EXPRESSION = :source_expression, BINDING_KIND = :binding_kind,
            UPDATED_AT = CURRENT_TIMESTAMP, UPDATED_BY = CURRENT_USER
        WHERE IDENTITY_BINDING_ID = :binding_id
    ]], {binding_id = binding_id, source_expression = source_expression,
          binding_kind = binding_kind})
else
    query([[
        INSERT INTO SYS_SEMANTIC.IDENTITY_BINDINGS (
          MODEL_ID, VERSION_ID, ENTITY_ID, IDENTITY_ID, REPRESENTATION_ID,
          SOURCE_EXPRESSION, BINDING_KIND, STATUS
        ) VALUES (
          :model_id, :version_id, :entity_id, :identity_id, :representation_id,
          :source_expression, :binding_kind, 'ACTIVE'
        )
    ]], {model_id = model_id, version_id = version_id, entity_id = entity_id,
          identity_id = identity_id, representation_id = representation_id,
          source_expression = source_expression, binding_kind = binding_kind})
    local ids = query("SELECT MAX(IDENTITY_BINDING_ID) FROM SYS_SEMANTIC.IDENTITY_BINDINGS WHERE IDENTITY_ID = :identity_id",
        {identity_id = identity_id})
    binding_id = ids[1][1]
end
if binding_kind == "DIRECT" then
    query("DELETE FROM SYS_SEMANTIC.IDENTITY_MAPPING_RELATIONS WHERE IDENTITY_BINDING_ID = :binding_id",
        {binding_id = binding_id})
end
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = version_id})
query("UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE' WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id AND STATUS IN ('OK', 'WARNING')",
    {model_id = model_id, version_id = version_id})
query("EXECUTE SCRIPT SEMANTIC_ADMIN.RECERTIFY_MODEL_IF_PUBLISHED(:model_name)",
    {model_name = model_name})
exit({{binding_id, model_name, identity_name, representation_name,
    source_expression, binding_kind}}, [[
  IDENTITY_BINDING_ID DECIMAL(18,0), MODEL_NAME VARCHAR(256),
  IDENTITY_NAME VARCHAR(256), REPRESENTATION_NAME VARCHAR(256),
  SOURCE_EXPRESSION VARCHAR(2000000), BINDING_KIND VARCHAR(32)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_IDENTITY_MAPPING_RELATION(
  MODEL_NAME, IDENTITY_NAME, REPRESENTATION_NAME, SOURCE_SCHEMA, SOURCE_OBJECT,
  SOURCE_LOCAL_COLUMN, SEMANTIC_KEY_COLUMN, CERTIFICATION_STATUS
)
RETURNS TABLE AS
-- NULL arrives as userdata, and userdata is truthy: `value or ""` would render
-- it as an address and defeat the required-parameter check below.
local function trim(value)
    if value == nil or value == null then return "" end
    return tostring(value):match("^%s*(.-)%s*$")
end
local function upper(value) return string.upper(trim(value)) end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local certification = upper(CERTIFICATION_STATUS)
if trim(MODEL_NAME) == "" or trim(IDENTITY_NAME) == ""
    or trim(REPRESENTATION_NAME) == "" or trim(SOURCE_SCHEMA) == ""
    or trim(SOURCE_OBJECT) == "" or trim(SOURCE_LOCAL_COLUMN) == ""
    or trim(SEMANTIC_KEY_COLUMN) == "" then
    error("SEMANTIC_ADMIN_001: model, identity, representation, mapping source, and mapping columns are required")
end
if certification ~= "CERTIFIED" then
    error("SEMANTIC_ADMIN_003: runtime identity mappings must be CERTIFIED")
end
local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, ib.IDENTITY_BINDING_ID
    FROM SYS_SEMANTIC.MODELS m
    JOIN SYS_SEMANTIC.SEMANTIC_IDENTITIES si
      ON si.MODEL_ID = m.MODEL_ID AND si.VERSION_ID = m.ACTIVE_VERSION_ID
     AND UPPER(si.IDENTITY_NAME) = UPPER(:identity_name) AND si.STATUS = 'ACTIVE'
    JOIN SYS_SEMANTIC.ENTITY_REPRESENTATIONS er
      ON er.ENTITY_ID = si.ENTITY_ID AND er.VERSION_ID = si.VERSION_ID
     AND UPPER(er.REPRESENTATION_NAME) = UPPER(:representation_name)
     AND er.STATUS = 'ACTIVE'
    JOIN SYS_SEMANTIC.IDENTITY_BINDINGS ib
      ON ib.IDENTITY_ID = si.IDENTITY_ID AND ib.REPRESENTATION_ID = er.REPRESENTATION_ID
     AND ib.BINDING_KIND = 'MAPPED' AND ib.STATUS = 'ACTIVE'
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
]], {model_name = trim(MODEL_NAME), identity_name = trim(IDENTITY_NAME),
      representation_name = trim(REPRESENTATION_NAME)})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_050: active MAPPED identity binding not found")
end
local model_id = row_value(rows[1], "MODEL_ID", 1)
local version_id = row_value(rows[1], "ACTIVE_VERSION_ID", 2)
local binding_id = row_value(rows[1], "IDENTITY_BINDING_ID", 3)
query("DELETE FROM SYS_SEMANTIC.IDENTITY_MAPPING_RELATIONS WHERE IDENTITY_BINDING_ID = :binding_id",
    {binding_id = binding_id})
query([[
    INSERT INTO SYS_SEMANTIC.IDENTITY_MAPPING_RELATIONS (
      MODEL_ID, VERSION_ID, IDENTITY_BINDING_ID, SOURCE_SCHEMA, SOURCE_OBJECT,
      SOURCE_LOCAL_COLUMN, SEMANTIC_KEY_COLUMN, CERTIFICATION_STATUS, STATUS
    ) VALUES (
      :model_id, :version_id, :binding_id, :source_schema, :source_object,
      :source_local_column, :semantic_key_column, :certification, 'ACTIVE'
    )
]], {model_id = model_id, version_id = version_id, binding_id = binding_id,
      source_schema = trim(SOURCE_SCHEMA), source_object = trim(SOURCE_OBJECT),
      source_local_column = trim(SOURCE_LOCAL_COLUMN),
      semantic_key_column = trim(SEMANTIC_KEY_COLUMN), certification = certification})
local ids = query("SELECT MAX(IDENTITY_MAPPING_ID) FROM SYS_SEMANTIC.IDENTITY_MAPPING_RELATIONS WHERE IDENTITY_BINDING_ID = :binding_id",
    {binding_id = binding_id})
local mapping_id = ids[1][1]
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = version_id})
query("UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE' WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id AND STATUS IN ('OK', 'WARNING')",
    {model_id = model_id, version_id = version_id})
query("EXECUTE SCRIPT SEMANTIC_ADMIN.RECERTIFY_MODEL_IF_PUBLISHED(:model_name)",
    {model_name = trim(MODEL_NAME)})
exit({{mapping_id, trim(MODEL_NAME), trim(IDENTITY_NAME),
    trim(REPRESENTATION_NAME), trim(SOURCE_SCHEMA), trim(SOURCE_OBJECT), certification}}, [[
  IDENTITY_MAPPING_ID DECIMAL(18,0), MODEL_NAME VARCHAR(256),
  IDENTITY_NAME VARCHAR(256), REPRESENTATION_NAME VARCHAR(256),
  SOURCE_SCHEMA VARCHAR(256), SOURCE_OBJECT VARCHAR(256),
  CERTIFICATION_STATUS VARCHAR(32)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.REMOVE_IDENTITY_MAPPING_RELATION(
  MODEL_NAME, IDENTITY_NAME, REPRESENTATION_NAME
)
RETURNS TABLE AS
-- NULL arrives as userdata, and userdata is truthy: `value or ""` would render
-- it as an address and defeat the required-parameter check below.
local function trim(value)
    if value == nil or value == null then return "" end
    return tostring(value):match("^%s*(.-)%s*$")
end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local model_name = trim(MODEL_NAME)
local identity_name = trim(IDENTITY_NAME)
local representation_name = trim(REPRESENTATION_NAME)
if model_name == "" or identity_name == "" or representation_name == "" then
    error("SEMANTIC_ADMIN_001: model, identity, and representation are required")
end
local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, im.IDENTITY_MAPPING_ID
    FROM SYS_SEMANTIC.MODELS m
    JOIN SYS_SEMANTIC.SEMANTIC_IDENTITIES si
      ON si.MODEL_ID = m.MODEL_ID AND si.VERSION_ID = m.ACTIVE_VERSION_ID
     AND UPPER(si.IDENTITY_NAME) = UPPER(:identity_name) AND si.STATUS = 'ACTIVE'
    JOIN SYS_SEMANTIC.ENTITY_REPRESENTATIONS er
      ON er.ENTITY_ID = si.ENTITY_ID AND er.VERSION_ID = si.VERSION_ID
     AND UPPER(er.REPRESENTATION_NAME) = UPPER(:representation_name)
     AND er.STATUS = 'ACTIVE'
    JOIN SYS_SEMANTIC.IDENTITY_BINDINGS ib
      ON ib.IDENTITY_ID = si.IDENTITY_ID AND ib.REPRESENTATION_ID = er.REPRESENTATION_ID
     AND ib.STATUS = 'ACTIVE'
    JOIN SYS_SEMANTIC.IDENTITY_MAPPING_RELATIONS im
      ON im.IDENTITY_BINDING_ID = ib.IDENTITY_BINDING_ID AND im.STATUS = 'ACTIVE'
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name, identity_name = identity_name,
      representation_name = representation_name})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_052: active identity mapping relation not found")
end
local model_id = row_value(rows[1], "MODEL_ID", 1)
local version_id = row_value(rows[1], "ACTIVE_VERSION_ID", 2)
local mapping_id = row_value(rows[1], "IDENTITY_MAPPING_ID", 3)
query("DELETE FROM SYS_SEMANTIC.IDENTITY_MAPPING_RELATIONS WHERE IDENTITY_MAPPING_ID = :mapping_id",
    {mapping_id = mapping_id})
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = version_id})
query("UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE' WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id AND STATUS IN ('OK', 'WARNING')",
    {model_id = model_id, version_id = version_id})
query("EXECUTE SCRIPT SEMANTIC_ADMIN.RECERTIFY_MODEL_IF_PUBLISHED(:model_name)",
    {model_name = model_name})
exit({{mapping_id, model_name, identity_name, representation_name, "REMOVED"}}, [[
  IDENTITY_MAPPING_ID DECIMAL(18,0), MODEL_NAME VARCHAR(256),
  IDENTITY_NAME VARCHAR(256), REPRESENTATION_NAME VARCHAR(256), STATUS VARCHAR(32)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.REMOVE_IDENTITY_BINDING(
  MODEL_NAME, IDENTITY_NAME, REPRESENTATION_NAME
)
RETURNS TABLE AS
-- NULL arrives as userdata, and userdata is truthy: `value or ""` would render
-- it as an address and defeat the required-parameter check below.
local function trim(value)
    if value == nil or value == null then return "" end
    return tostring(value):match("^%s*(.-)%s*$")
end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then return nil end
    return rows[1][1]
end
local model_name = trim(MODEL_NAME)
local identity_name = trim(IDENTITY_NAME)
local representation_name = trim(REPRESENTATION_NAME)
if model_name == "" or identity_name == "" or representation_name == "" then
    error("SEMANTIC_ADMIN_001: model, identity, and representation are required")
end
local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, ib.IDENTITY_BINDING_ID
    FROM SYS_SEMANTIC.MODELS m
    JOIN SYS_SEMANTIC.SEMANTIC_IDENTITIES si
      ON si.MODEL_ID = m.MODEL_ID AND si.VERSION_ID = m.ACTIVE_VERSION_ID
     AND UPPER(si.IDENTITY_NAME) = UPPER(:identity_name) AND si.STATUS = 'ACTIVE'
    JOIN SYS_SEMANTIC.ENTITY_REPRESENTATIONS er
      ON er.ENTITY_ID = si.ENTITY_ID AND er.VERSION_ID = si.VERSION_ID
     AND UPPER(er.REPRESENTATION_NAME) = UPPER(:representation_name)
     AND er.STATUS = 'ACTIVE'
    JOIN SYS_SEMANTIC.IDENTITY_BINDINGS ib
      ON ib.IDENTITY_ID = si.IDENTITY_ID AND ib.REPRESENTATION_ID = er.REPRESENTATION_ID
     AND ib.STATUS = 'ACTIVE'
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name, identity_name = identity_name,
      representation_name = representation_name})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_053: active identity binding not found")
end
local model_id = row_value(rows[1], "MODEL_ID", 1)
local version_id = row_value(rows[1], "ACTIVE_VERSION_ID", 2)
local binding_id = row_value(rows[1], "IDENTITY_BINDING_ID", 3)
local mapping_count = scalar([[
    SELECT COUNT(*) FROM SYS_SEMANTIC.IDENTITY_MAPPING_RELATIONS
    WHERE IDENTITY_BINDING_ID = :binding_id AND STATUS = 'ACTIVE'
]], {binding_id = binding_id})
if tonumber(mapping_count or 0) > 0 then
    error("SEMANTIC_ADMIN_054: cannot remove an identity binding with an active mapping relation; remove the mapping relation first")
end
query("DELETE FROM SYS_SEMANTIC.IDENTITY_BINDINGS WHERE IDENTITY_BINDING_ID = :binding_id",
    {binding_id = binding_id})
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = version_id})
query("UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE' WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id AND STATUS IN ('OK', 'WARNING')",
    {model_id = model_id, version_id = version_id})
query("EXECUTE SCRIPT SEMANTIC_ADMIN.RECERTIFY_MODEL_IF_PUBLISHED(:model_name)",
    {model_name = model_name})
exit({{binding_id, model_name, identity_name, representation_name, "REMOVED"}}, [[
  IDENTITY_BINDING_ID DECIMAL(18,0), MODEL_NAME VARCHAR(256),
  IDENTITY_NAME VARCHAR(256), REPRESENTATION_NAME VARCHAR(256), STATUS VARCHAR(32)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.REMOVE_SEMANTIC_IDENTITY(
  MODEL_NAME, ENTITY_NAME, IDENTITY_NAME
)
RETURNS TABLE AS
-- NULL arrives as userdata, and userdata is truthy: `value or ""` would render
-- it as an address and defeat the required-parameter check below.
local function trim(value)
    if value == nil or value == null then return "" end
    return tostring(value):match("^%s*(.-)%s*$")
end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then return nil end
    return rows[1][1]
end
local model_name = trim(MODEL_NAME)
local entity_name = trim(ENTITY_NAME)
local identity_name = trim(IDENTITY_NAME)
if model_name == "" or entity_name == "" or identity_name == "" then
    error("SEMANTIC_ADMIN_001: model, entity, and identity are required")
end
local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, si.IDENTITY_ID
    FROM SYS_SEMANTIC.MODELS m
    JOIN SYS_SEMANTIC.ENTITIES e
      ON e.MODEL_ID = m.MODEL_ID AND e.VERSION_ID = m.ACTIVE_VERSION_ID
     AND UPPER(e.ENTITY_NAME) = UPPER(:entity_name) AND e.STATUS = 'ACTIVE'
    JOIN SYS_SEMANTIC.SEMANTIC_IDENTITIES si
      ON si.ENTITY_ID = e.ENTITY_ID AND si.VERSION_ID = e.VERSION_ID
     AND UPPER(si.IDENTITY_NAME) = UPPER(:identity_name) AND si.STATUS = 'ACTIVE'
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name, entity_name = entity_name,
      identity_name = identity_name})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_055: active semantic identity not found")
end
local model_id = row_value(rows[1], "MODEL_ID", 1)
local version_id = row_value(rows[1], "ACTIVE_VERSION_ID", 2)
local identity_id = row_value(rows[1], "IDENTITY_ID", 3)
local binding_count = scalar([[
    SELECT COUNT(*) FROM SYS_SEMANTIC.IDENTITY_BINDINGS
    WHERE IDENTITY_ID = :identity_id AND STATUS = 'ACTIVE'
]], {identity_id = identity_id})
if tonumber(binding_count or 0) > 0 then
    error("SEMANTIC_ADMIN_056: cannot remove a semantic identity with active bindings; remove the bindings first")
end
query("DELETE FROM SYS_SEMANTIC.SEMANTIC_IDENTITIES WHERE IDENTITY_ID = :identity_id",
    {identity_id = identity_id})
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = version_id})
query("UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE' WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id AND STATUS IN ('OK', 'WARNING')",
    {model_id = model_id, version_id = version_id})
query("EXECUTE SCRIPT SEMANTIC_ADMIN.RECERTIFY_MODEL_IF_PUBLISHED(:model_name)",
    {model_name = model_name})
exit({{identity_id, model_name, entity_name, identity_name, "REMOVED"}}, [[
  IDENTITY_ID DECIMAL(18,0), MODEL_NAME VARCHAR(256), ENTITY_NAME VARCHAR(256),
  IDENTITY_NAME VARCHAR(256), STATUS VARCHAR(32)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.SET_REPRESENTATION_AUTHORITY(
  MODEL_NAME,
  ENTITY_NAME,
  REPRESENTATION_NAME,
  AUTHORITY_ROLE
)
RETURNS TABLE AS
-- NULL arrives as userdata, and userdata is truthy: `value or ""` would render
-- it as an address and defeat the required-parameter check below.
local function trim(value)
    if value == nil or value == null then return "" end
    return tostring(value):match("^%s*(.-)%s*$")
end
local function upper(value) return string.upper(trim(value)) end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local model_name = trim(MODEL_NAME)
local entity_name = trim(ENTITY_NAME)
local representation_name = trim(REPRESENTATION_NAME)
local authority_role = upper(AUTHORITY_ROLE)
if model_name == "" or entity_name == "" or representation_name == "" then
    error("SEMANTIC_ADMIN_001: model, entity, and representation names are required")
end
if authority_role ~= "AUTHORITATIVE" and authority_role ~= "PREFER"
    and authority_role ~= "SUPPLEMENTAL" then
    error("SEMANTIC_ADMIN_003: AUTHORITY_ROLE must be AUTHORITATIVE, PREFER, or SUPPLEMENTAL")
end
local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, e.ENTITY_ID, er.REPRESENTATION_ID
    FROM SYS_SEMANTIC.MODELS m
    JOIN SYS_SEMANTIC.ENTITIES e
      ON e.MODEL_ID = m.MODEL_ID AND e.VERSION_ID = m.ACTIVE_VERSION_ID
     AND UPPER(e.ENTITY_NAME) = UPPER(:entity_name) AND e.STATUS = 'ACTIVE'
    JOIN SYS_SEMANTIC.ENTITY_REPRESENTATIONS er
      ON er.ENTITY_ID = e.ENTITY_ID AND er.MODEL_ID = e.MODEL_ID
     AND er.VERSION_ID = e.VERSION_ID
     AND UPPER(er.REPRESENTATION_NAME) = UPPER(:representation_name)
     AND er.STATUS = 'ACTIVE'
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name, entity_name = entity_name,
      representation_name = representation_name})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_047: active representation not found: " .. representation_name)
end
local model_id = row_value(rows[1], "MODEL_ID", 1)
local version_id = row_value(rows[1], "ACTIVE_VERSION_ID", 2)
local entity_id = row_value(rows[1], "ENTITY_ID", 3)
local representation_id = row_value(rows[1], "REPRESENTATION_ID", 4)
local existing_rows = query([[
    SELECT AUTHORITY_ROLE FROM SYS_SEMANTIC.REPRESENTATION_AUTHORITIES
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND REPRESENTATION_ID = :representation_id
]], {model_id = model_id, version_id = version_id,
      representation_id = representation_id})
local had_row = existing_rows ~= nil and #existing_rows > 0
local previous_role = had_row and row_value(existing_rows[1], "AUTHORITY_ROLE", 1) or nil

-- Prospective on a published model: authority decides which representation wins
-- a reconciliation, so one call can leave a live model failing validation and
-- dark for every consumer. Apply, revalidate, and restore the prior state if
-- the candidate does not hold -- the contract ADD_ENTITY_REPRESENTATION already
-- honours (SEMANTIC_ADMIN_094).
local function apply_authority(role)
    if role == nil then
        query([[
            DELETE FROM SYS_SEMANTIC.REPRESENTATION_AUTHORITIES
            WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
              AND REPRESENTATION_ID = :representation_id
        ]], {model_id = model_id, version_id = version_id,
              representation_id = representation_id})
    elseif not had_row and role == authority_role then
        query([[
            INSERT INTO SYS_SEMANTIC.REPRESENTATION_AUTHORITIES (
              MODEL_ID, VERSION_ID, ENTITY_ID, REPRESENTATION_ID, AUTHORITY_ROLE, STATUS
            ) VALUES (
              :model_id, :version_id, :entity_id, :representation_id, :authority_role, 'ACTIVE'
            )
        ]], {model_id = model_id, version_id = version_id, entity_id = entity_id,
              representation_id = representation_id, authority_role = role})
    else
        query([[
            UPDATE SYS_SEMANTIC.REPRESENTATION_AUTHORITIES
            SET AUTHORITY_ROLE = :authority_role, STATUS = 'ACTIVE',
                UPDATED_AT = CURRENT_TIMESTAMP, UPDATED_BY = CURRENT_USER
            WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
              AND REPRESENTATION_ID = :representation_id
        ]], {model_id = model_id, version_id = version_id,
              representation_id = representation_id, authority_role = role})
    end
    query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
        {version_id = version_id})
    query([[
        UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE'
        WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
          AND STATUS IN ('OK', 'WARNING')
    ]], {model_id = model_id, version_id = version_id})
    return query("EXECUTE SCRIPT SEMANTIC_ADMIN.RECERTIFY_MODEL_IF_PUBLISHED(:model_name)",
        {model_name = model_name})
end

local recertified = apply_authority(authority_role)
-- A draft is left STALE rather than reverted: compilation is gated on
-- validation status, so a stale draft serves nothing, and reverting would block
-- the repair sequence a modeller needs on a model that is already invalid.
local validation_status = "NOT_REQUIRED"
if recertified ~= nil and #recertified > 0 then
    validation_status = tostring(row_value(recertified[1], "VALIDATION_STATUS", 3))
end
if validation_status == "ERROR" or validation_status == "PRECONDITION" then
    local detail_rows = query([[
        SELECT RULE_CODE, MESSAGE
        FROM SYS_SEMANTIC.VALIDATION_RESULTS
        WHERE VALIDATION_RUN_ID = (
            SELECT MAX(VALIDATION_RUN_ID) FROM SYS_SEMANTIC.VALIDATION_RUNS
            WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id)
          AND SEVERITY IN ('ERROR', 'PRECONDITION')
        ORDER BY VALIDATION_RESULT_ID
        LIMIT 1
    ]], {model_id = model_id, version_id = version_id})
    local detail = "model validation failed"
    if detail_rows ~= nil and #detail_rows > 0 then
        detail = tostring(row_value(detail_rows[1], "RULE_CODE", 1)) .. " "
            .. tostring(row_value(detail_rows[1], "MESSAGE", 2))
    end
    apply_authority(previous_role)
    error("SEMANTIC_ADMIN_094: published authority change rejected and restored; "
        .. "candidate introduced validation error: " .. detail)
end
exit({{model_name, entity_name, representation_name, authority_role}}, [[
  MODEL_NAME VARCHAR(256), ENTITY_NAME VARCHAR(256),
  REPRESENTATION_NAME VARCHAR(256), AUTHORITY_ROLE VARCHAR(32)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.SET_ATTRIBUTE_FUSION_POLICY(
  MODEL_NAME,
  ATTRIBUTE_TYPE,
  ATTRIBUTE_NAME,
  FUSION_STRATEGY
)
RETURNS TABLE AS
-- NULL arrives as userdata, and userdata is truthy: `value or ""` would render
-- it as an address and defeat the required-parameter check below.
local function trim(value)
    if value == nil or value == null then return "" end
    return tostring(value):match("^%s*(.-)%s*$")
end
local function upper(value) return string.upper(trim(value)) end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local model_name = trim(MODEL_NAME)
local attribute_type = upper(ATTRIBUTE_TYPE)
local attribute_name = trim(ATTRIBUTE_NAME)
local fusion_strategy = upper(FUSION_STRATEGY)
if attribute_type ~= "DIMENSION" and attribute_type ~= "FACT" then
    error("SEMANTIC_ADMIN_003: ATTRIBUTE_TYPE must be DIMENSION or FACT")
end
if fusion_strategy ~= "PREFER" and fusion_strategy ~= "COALESCE"
    and fusion_strategy ~= "RECONCILE" then
    error("SEMANTIC_ADMIN_003: FUSION_STRATEGY must be PREFER, COALESCE, or RECONCILE")
end
local table_name = attribute_type == "DIMENSION" and "DIMENSIONS" or "FACTS"
local id_column = attribute_type == "DIMENSION" and "DIMENSION_ID" or "FACT_ID"
local name_column = attribute_type == "DIMENSION" and "DIMENSION_NAME" or "FACT_NAME"
local rows = query(
    "SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, a.ENTITY_ID, a." .. id_column
      .. " FROM SYS_SEMANTIC.MODELS m JOIN SYS_SEMANTIC." .. table_name .. " a"
      .. " ON a.MODEL_ID = m.MODEL_ID AND a.VERSION_ID = m.ACTIVE_VERSION_ID"
      .. " AND UPPER(a." .. name_column .. ") = UPPER(:attribute_name)"
      .. " AND a.STATUS = 'ACTIVE' WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)",
    {model_name = model_name, attribute_name = attribute_name})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_021: " .. attribute_type .. " not found: " .. attribute_name)
end
local model_id = row_value(rows[1], "MODEL_ID", 1)
local version_id = row_value(rows[1], "ACTIVE_VERSION_ID", 2)
local entity_id = row_value(rows[1], "ENTITY_ID", 3)
local attribute_id = row_value(rows[1], id_column, 4)
local existing_rows = query([[
    SELECT FUSION_STRATEGY FROM SYS_SEMANTIC.ATTRIBUTE_FUSION_POLICIES
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND ATTRIBUTE_TYPE = :attribute_type AND ATTRIBUTE_ID = :attribute_id
]], {model_id = model_id, version_id = version_id,
      attribute_type = attribute_type, attribute_id = attribute_id})
local had_row = existing_rows ~= nil and #existing_rows > 0
local previous_strategy = had_row
    and row_value(existing_rows[1], "FUSION_STRATEGY", 1) or nil

-- Prospective on a published model. COALESCE and RECONCILE carry contracts the
-- validator checks -- bindings on at least two representations, exactly one
-- AUTHORITATIVE for RECONCILE -- and a policy that fails them leaves a live
-- published model failing validation, which takes every consumer offline until
-- someone works out which change to undo. Apply, revalidate, restore on error.
local function apply_policy(strategy)
    if strategy == nil then
        query([[
            DELETE FROM SYS_SEMANTIC.ATTRIBUTE_FUSION_POLICIES
            WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
              AND ATTRIBUTE_TYPE = :attribute_type AND ATTRIBUTE_ID = :attribute_id
        ]], {model_id = model_id, version_id = version_id,
              attribute_type = attribute_type, attribute_id = attribute_id})
    elseif not had_row and strategy == fusion_strategy then
        query([[
            INSERT INTO SYS_SEMANTIC.ATTRIBUTE_FUSION_POLICIES (
              MODEL_ID, VERSION_ID, ENTITY_ID, ATTRIBUTE_TYPE, ATTRIBUTE_ID,
              FUSION_STRATEGY, STATUS
            ) VALUES (
              :model_id, :version_id, :entity_id, :attribute_type, :attribute_id,
              :fusion_strategy, 'ACTIVE'
            )
        ]], {model_id = model_id, version_id = version_id, entity_id = entity_id,
              attribute_type = attribute_type, attribute_id = attribute_id,
              fusion_strategy = strategy})
    else
        query([[
            UPDATE SYS_SEMANTIC.ATTRIBUTE_FUSION_POLICIES
            SET FUSION_STRATEGY = :fusion_strategy, STATUS = 'ACTIVE',
                UPDATED_AT = CURRENT_TIMESTAMP, UPDATED_BY = CURRENT_USER
            WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
              AND ATTRIBUTE_TYPE = :attribute_type AND ATTRIBUTE_ID = :attribute_id
        ]], {model_id = model_id, version_id = version_id,
              attribute_type = attribute_type, attribute_id = attribute_id,
              fusion_strategy = strategy})
    end
    query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
        {version_id = version_id})
    query([[
        UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE'
        WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
          AND STATUS IN ('OK', 'WARNING')
    ]], {model_id = model_id, version_id = version_id})
    return query("EXECUTE SCRIPT SEMANTIC_ADMIN.RECERTIFY_MODEL_IF_PUBLISHED(:model_name)",
        {model_name = model_name})
end

local recertified = apply_policy(fusion_strategy)
-- A draft is left STALE rather than reverted, for the same reason as every
-- other mutator: compilation is gated on validation status, and reverting would
-- block the repair sequence on a model that is already invalid.
local validation_status = "NOT_REQUIRED"
if recertified ~= nil and #recertified > 0 then
    validation_status = tostring(row_value(recertified[1], "VALIDATION_STATUS", 3))
end
if validation_status == "ERROR" or validation_status == "PRECONDITION" then
    local detail_rows = query([[
        SELECT RULE_CODE, MESSAGE
        FROM SYS_SEMANTIC.VALIDATION_RESULTS
        WHERE VALIDATION_RUN_ID = (
            SELECT MAX(VALIDATION_RUN_ID) FROM SYS_SEMANTIC.VALIDATION_RUNS
            WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id)
          AND SEVERITY IN ('ERROR', 'PRECONDITION')
        ORDER BY VALIDATION_RESULT_ID
        LIMIT 1
    ]], {model_id = model_id, version_id = version_id})
    local detail = "model validation failed"
    if detail_rows ~= nil and #detail_rows > 0 then
        detail = tostring(row_value(detail_rows[1], "RULE_CODE", 1)) .. " "
            .. tostring(row_value(detail_rows[1], "MESSAGE", 2))
    end
    apply_policy(previous_strategy)
    error("SEMANTIC_ADMIN_094: published fusion-policy change rejected and restored; "
        .. "candidate introduced validation error: " .. detail)
end
exit({{model_name, attribute_type, attribute_name, fusion_strategy}}, [[
  MODEL_NAME VARCHAR(256), ATTRIBUTE_TYPE VARCHAR(32),
  ATTRIBUTE_NAME VARCHAR(256), FUSION_STRATEGY VARCHAR(32)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.SET_REPRESENTATION_COVERAGE(
  MODEL_NAME,
  ENTITY_NAME,
  REPRESENTATION_NAME,
  COVERAGE_PREDICATE,
  VALID_FROM,
  VALID_TO
)
RETURNS TABLE AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

local function normalize_name(value, label)
    if missing(value) then error("SEMANTIC_ADMIN_001: " .. label .. " is required") end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end

local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local entity_name = normalize_name(ENTITY_NAME, "ENTITY_NAME")
local representation_name = normalize_name(REPRESENTATION_NAME, "REPRESENTATION_NAME")
local predicate = missing(COVERAGE_PREDICATE) and null or trim(COVERAGE_PREDICATE)
local valid_from = missing(VALID_FROM) and null or VALID_FROM
local valid_to = missing(VALID_TO) and null or VALID_TO
if predicate == null and (valid_from ~= null or valid_to ~= null) then
    error("SEMANTIC_ADMIN_003: coverage bounds require COVERAGE_PREDICATE")
end
if predicate ~= null and valid_from == null and valid_to == null then
    error("SEMANTIC_ADMIN_003: UNION partition requires VALID_FROM or VALID_TO")
end

local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, er.REPRESENTATION_ID,
           m.STATUS, er.COVERAGE_PREDICATE, er.VALID_FROM, er.VALID_TO
    FROM SYS_SEMANTIC.MODELS m
    JOIN SYS_SEMANTIC.ENTITIES e
      ON e.MODEL_ID = m.MODEL_ID
     AND e.VERSION_ID = m.ACTIVE_VERSION_ID
     AND UPPER(e.ENTITY_NAME) = UPPER(:entity_name)
     AND e.STATUS = 'ACTIVE'
    JOIN SYS_SEMANTIC.ENTITY_REPRESENTATIONS er
      ON er.ENTITY_ID = e.ENTITY_ID
     AND er.MODEL_ID = e.MODEL_ID
     AND er.VERSION_ID = e.VERSION_ID
     AND UPPER(er.REPRESENTATION_NAME) = UPPER(:representation_name)
     AND er.STATUS = 'ACTIVE'
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
]], {
    model_name = model_name,
    entity_name = entity_name,
    representation_name = representation_name,
})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_047: active representation not found: " .. representation_name)
end
local model_id = row_value(rows[1], "MODEL_ID", 1)
local version_id = row_value(rows[1], "ACTIVE_VERSION_ID", 2)
local representation_id = row_value(rows[1], "REPRESENTATION_ID", 3)
local model_status = row_value(rows[1], "STATUS", 4)
local previous_predicate = row_value(rows[1], "COVERAGE_PREDICATE", 5) or null
local previous_valid_from = row_value(rows[1], "VALID_FROM", 6) or null
local previous_valid_to = row_value(rows[1], "VALID_TO", 7) or null

query([[
    UPDATE SYS_SEMANTIC.ENTITY_REPRESENTATIONS
    SET COVERAGE_PREDICATE = :coverage_predicate,
        VALID_FROM = :valid_from,
        VALID_TO = :valid_to,
        UPDATED_AT = CURRENT_TIMESTAMP,
        UPDATED_BY = CURRENT_USER
    WHERE REPRESENTATION_ID = :representation_id
]], {
    representation_id = representation_id,
    coverage_predicate = predicate,
    valid_from = valid_from,
    valid_to = valid_to,
})
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = version_id})
query([[
    UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE'
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND STATUS IN ('OK', 'WARNING')
]], {model_id = model_id, version_id = version_id})

if tostring(model_status) == "PUBLISHED" then
    local candidate_validation = query(
        "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
        {model_name = model_name})
    for _, validation_row in ipairs(candidate_validation or {}) do
        if tostring(row_value(validation_row, "SEVERITY", 1)) == "ERROR"
            or tostring(row_value(validation_row, "SEVERITY", 1)) == "PRECONDITION" then
            local rule_code = row_value(validation_row, "RULE_CODE", 4)
                or "SEMANTIC_MODEL_ERROR"
            local message = row_value(validation_row, "MESSAGE", 5)
                or "model validation failed"
            query([[
                UPDATE SYS_SEMANTIC.ENTITY_REPRESENTATIONS
                SET COVERAGE_PREDICATE = :coverage_predicate,
                    VALID_FROM = :valid_from,
                    VALID_TO = :valid_to,
                    UPDATED_AT = CURRENT_TIMESTAMP,
                    UPDATED_BY = CURRENT_USER
                WHERE REPRESENTATION_ID = :representation_id
            ]], {representation_id = representation_id,
                coverage_predicate = previous_predicate,
                valid_from = previous_valid_from,
                valid_to = previous_valid_to})
            -- Re-certify the restored published catalog. The failed candidate
            -- run remains as audit history but never gates the live surface.
            query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
                {model_name = model_name})
            error("SEMANTIC_ADMIN_059: published coverage change rejected and restored; "
                .. "candidate introduced validation error: "
                .. tostring(rule_code) .. " " .. tostring(message))
        end
    end
end

exit({{representation_id, model_name, entity_name, representation_name,
    predicate == null and "NONE" or "UNION", predicate, valid_from, valid_to}}, [[
  REPRESENTATION_ID DECIMAL(18,0),
  MODEL_NAME VARCHAR(256),
  ENTITY_NAME VARCHAR(256),
  REPRESENTATION_NAME VARCHAR(256),
  FUSION_STRATEGY VARCHAR(32),
  COVERAGE_PREDICATE VARCHAR(2000000),
  VALID_FROM TIMESTAMP,
  VALID_TO TIMESTAMP
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.SET_REPRESENTATION_COVERAGE_BATCH(
  MODEL_NAME,
  ENTITY_NAME,
  COVERAGE_JSON
)
RETURNS TABLE AS
local JSON_NULL = {}
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end
local function trim(value) return tostring(value):match("^%s*(.-)%s*$") end
local function normalize_name(value, label)
    if missing(value) then error("SEMANTIC_ADMIN_001: " .. label .. " is required") end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local function json_decode(text)
    if missing(text) then error("empty JSON payload") end
    text = tostring(text)
    local pos = 1
    local function peek() return string.sub(text, pos, pos) end
    local function skip_ws()
        while pos <= #text do
            local c = peek()
            if c == " " or c == "\n" or c == "\r" or c == "\t" then
                pos = pos + 1
            else
                return
            end
        end
    end
    local function parse_string()
        if peek() ~= '"' then error("expected string at byte " .. tostring(pos)) end
        pos = pos + 1
        local out = {}
        while pos <= #text do
            local c = peek()
            if c == '"' then
                pos = pos + 1
                return table.concat(out)
            elseif c == "\\" then
                local e = string.sub(text, pos + 1, pos + 1)
                if e == '"' or e == "\\" or e == "/" then
                    out[#out + 1] = e
                    pos = pos + 2
                elseif e == "b" then
                    out[#out + 1] = "\b"
                    pos = pos + 2
                elseif e == "f" then
                    out[#out + 1] = "\f"
                    pos = pos + 2
                elseif e == "n" then
                    out[#out + 1] = "\n"
                    pos = pos + 2
                elseif e == "r" then
                    out[#out + 1] = "\r"
                    pos = pos + 2
                elseif e == "t" then
                    out[#out + 1] = "\t"
                    pos = pos + 2
                elseif e == "u" then
                    out[#out + 1] = "?"
                    pos = pos + 6
                else error("invalid escape at byte " .. tostring(pos)) end
            else
                out[#out + 1] = c
                pos = pos + 1
            end
        end
        error("unterminated string")
    end
    local parse_value
    local function parse_number()
        local start_pos = pos
        if peek() == "-" then pos = pos + 1 end
        while string.match(peek(), "%d") do pos = pos + 1 end
        if peek() == "." then
            pos = pos + 1
            while string.match(peek(), "%d") do pos = pos + 1 end
        end
        local c = peek()
        if c == "e" or c == "E" then
            pos = pos + 1
            c = peek()
            if c == "+" or c == "-" then pos = pos + 1 end
            while string.match(peek(), "%d") do pos = pos + 1 end
        end
        local value = tonumber(string.sub(text, start_pos, pos - 1))
        if value == nil then error("invalid number at byte " .. tostring(start_pos)) end
        return value
    end
    local function parse_array()
        pos = pos + 1
        local out = {}
        skip_ws()
        if peek() == "]" then
            pos = pos + 1
            return out
        end
        while true do
            out[#out + 1] = parse_value()
            skip_ws()
            local c = peek()
            if c == "]" then
                pos = pos + 1
                return out
            elseif c == "," then pos = pos + 1
            else error("expected array comma or close at byte " .. tostring(pos)) end
        end
    end
    local function parse_object()
        pos = pos + 1
        local out = {}
        skip_ws()
        if peek() == "}" then
            pos = pos + 1
            return out
        end
        while true do
            skip_ws()
            local name = parse_string()
            skip_ws()
            if peek() ~= ":" then error("expected object colon at byte " .. tostring(pos)) end
            pos = pos + 1
            out[name] = parse_value()
            skip_ws()
            local c = peek()
            if c == "}" then
                pos = pos + 1
                return out
            elseif c == "," then pos = pos + 1
            else error("expected object comma or close at byte " .. tostring(pos)) end
        end
    end
    function parse_value()
        skip_ws()
        local c = peek()
        if c == '"' then return parse_string()
        elseif c == "{" then return parse_object()
        elseif c == "[" then return parse_array()
        elseif c == "-" or string.match(c, "%d") then return parse_number()
        elseif string.sub(text, pos, pos + 3) == "true" then
            pos = pos + 4
            return true
        elseif string.sub(text, pos, pos + 4) == "false" then
            pos = pos + 5
            return false
        elseif string.sub(text, pos, pos + 3) == "null" then
            pos = pos + 4
            return JSON_NULL
        end
        error("unexpected JSON token at byte " .. tostring(pos))
    end
    local value = parse_value()
    skip_ws()
    if pos <= #text then error("unexpected trailing JSON at byte " .. tostring(pos)) end
    return value
end
local function json_field(item, name)
    local value = item[name]
    if value == JSON_NULL then return nil end
    return value
end
local function sql_value(value)
    if value == nil then return null end
    return value
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local entity_name = normalize_name(ENTITY_NAME, "ENTITY_NAME")
local ok, declarations = pcall(json_decode, COVERAGE_JSON)
if not ok or type(declarations) ~= "table" or #declarations == 0 then
    local detail = not ok and tostring(declarations)
        or (type(declarations) ~= "table" and "top-level value is not an array"
            or "array is empty")
    error("SEMANTIC_ADMIN_060: COVERAGE_JSON must be a non-empty JSON array: "
        .. detail)
end
local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, m.STATUS, er.REPRESENTATION_ID,
           er.REPRESENTATION_NAME, er.COVERAGE_PREDICATE, er.VALID_FROM, er.VALID_TO
    FROM SYS_SEMANTIC.MODELS m
    JOIN SYS_SEMANTIC.ENTITIES e
      ON e.MODEL_ID = m.MODEL_ID AND e.VERSION_ID = m.ACTIVE_VERSION_ID
     AND UPPER(e.ENTITY_NAME) = UPPER(:entity_name) AND e.STATUS = 'ACTIVE'
    JOIN SYS_SEMANTIC.ENTITY_REPRESENTATIONS er
      ON er.ENTITY_ID = e.ENTITY_ID AND er.MODEL_ID = e.MODEL_ID
     AND er.VERSION_ID = e.VERSION_ID AND er.STATUS = 'ACTIVE'
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
    ORDER BY er.PRIORITY, er.REPRESENTATION_ID
]], {model_name = model_name, entity_name = entity_name})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_014: entity or active representations not found: " .. entity_name)
end
local model_id = row_value(rows[1], "MODEL_ID", 1)
local version_id = row_value(rows[1], "ACTIVE_VERSION_ID", 2)
local model_status = row_value(rows[1], "STATUS", 3)
local representations = {}
for _, row in ipairs(rows) do
    local name = tostring(row_value(row, "REPRESENTATION_NAME", 5))
    representations[string.upper(name)] = {
        id = row_value(row, "REPRESENTATION_ID", 4),
        name = name,
        previous_predicate = row_value(row, "COVERAGE_PREDICATE", 6) or null,
        previous_valid_from = row_value(row, "VALID_FROM", 7) or null,
        previous_valid_to = row_value(row, "VALID_TO", 8) or null,
    }
end
local seen = {}
local prepared = {}
for index, item in ipairs(declarations) do
    if type(item) ~= "table" then
        error("SEMANTIC_ADMIN_060: coverage declaration " .. tostring(index) .. " must be an object")
    end
    local representation_name = normalize_name(
        json_field(item, "representation_name"),
        "COVERAGE_JSON[" .. tostring(index) .. "].representation_name")
    local key = string.upper(representation_name)
    local representation = representations[key]
    if representation == nil then
        error("SEMANTIC_ADMIN_047: active representation not found: " .. representation_name)
    end
    if seen[key] then
        error("SEMANTIC_ADMIN_060: duplicate coverage declaration: " .. representation_name)
    end
    seen[key] = true
    local predicate = json_field(item, "coverage_predicate")
    local valid_from = json_field(item, "valid_from")
    local valid_to = json_field(item, "valid_to")
    if predicate ~= nil then predicate = trim(predicate) end
    if predicate == nil and (valid_from ~= nil or valid_to ~= nil) then
        error("SEMANTIC_ADMIN_003: coverage bounds require COVERAGE_PREDICATE for "
            .. representation_name)
    end
    if predicate ~= nil and valid_from == nil and valid_to == nil then
        error("SEMANTIC_ADMIN_003: UNION partition requires VALID_FROM or VALID_TO for "
            .. representation_name)
    end
    prepared[#prepared + 1] = {
        representation = representation,
        predicate = sql_value(predicate),
        valid_from = sql_value(valid_from),
        valid_to = sql_value(valid_to),
    }
end
for key, representation in pairs(representations) do
    if not seen[key] then
        error("SEMANTIC_ADMIN_060: coverage batch must declare every active representation; missing: "
            .. representation.name)
    end
end

for _, item in ipairs(prepared) do
    query([[
        UPDATE SYS_SEMANTIC.ENTITY_REPRESENTATIONS
        SET COVERAGE_PREDICATE = :coverage_predicate,
            VALID_FROM = :valid_from, VALID_TO = :valid_to,
            UPDATED_AT = CURRENT_TIMESTAMP, UPDATED_BY = CURRENT_USER
        WHERE REPRESENTATION_ID = :representation_id
    ]], {representation_id = item.representation.id,
          coverage_predicate = item.predicate,
          valid_from = item.valid_from, valid_to = item.valid_to})
end
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = version_id})
query([[
    UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE'
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND STATUS IN ('OK', 'WARNING')
]], {model_id = model_id, version_id = version_id})

if tostring(model_status) == "PUBLISHED" then
    local candidate_validation = query(
        "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
        {model_name = model_name})
    for _, validation_row in ipairs(candidate_validation or {}) do
        if tostring(row_value(validation_row, "SEVERITY", 1)) == "ERROR"
            or tostring(row_value(validation_row, "SEVERITY", 1)) == "PRECONDITION" then
            local rule_code = row_value(validation_row, "RULE_CODE", 4)
                or "SEMANTIC_MODEL_ERROR"
            local message = row_value(validation_row, "MESSAGE", 5)
                or "model validation failed"
            for _, representation in pairs(representations) do
                query([[
                    UPDATE SYS_SEMANTIC.ENTITY_REPRESENTATIONS
                    SET COVERAGE_PREDICATE = :coverage_predicate,
                        VALID_FROM = :valid_from, VALID_TO = :valid_to,
                        UPDATED_AT = CURRENT_TIMESTAMP, UPDATED_BY = CURRENT_USER
                    WHERE REPRESENTATION_ID = :representation_id
                ]], {representation_id = representation.id,
                      coverage_predicate = representation.previous_predicate,
                      valid_from = representation.previous_valid_from,
                      valid_to = representation.previous_valid_to})
            end
            query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
                {model_name = model_name})
            error("SEMANTIC_ADMIN_059: published coverage batch rejected and restored; "
                .. "candidate introduced validation error: "
                .. tostring(rule_code) .. " " .. tostring(message))
        end
    end
end

local result = {}
for _, item in ipairs(prepared) do
    result[#result + 1] = {item.representation.id, model_name, entity_name,
        item.representation.name, item.predicate == null and "NONE" or "UNION",
        item.predicate, item.valid_from, item.valid_to}
end
exit(result, [[
  REPRESENTATION_ID DECIMAL(18,0), MODEL_NAME VARCHAR(256),
  ENTITY_NAME VARCHAR(256), REPRESENTATION_NAME VARCHAR(256),
  FUSION_STRATEGY VARCHAR(32), COVERAGE_PREDICATE VARCHAR(2000000),
  VALID_FROM TIMESTAMP, VALID_TO TIMESTAMP
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_ENTITY_REPRESENTATION_WITH_COVERAGE(
  MODEL_NAME,
  ENTITY_NAME,
  REPRESENTATION_NAME,
  SOURCE_KIND,
  SOURCE_SCHEMA,
  SOURCE_OBJECT,
  PRIORITY,
  FRESHNESS_POLICY,
  COVERAGE_JSON
)
RETURNS TABLE AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end
local function trim(value) return tostring(value):match("^%s*(.-)%s*$") end
local function upper(value) return string.upper(trim(value)) end
local function normalize_name(value, label)
    if missing(value) then error("SEMANTIC_ADMIN_001: " .. label .. " is required") end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then return nil end
    return rows[1][1]
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local entity_name = normalize_name(ENTITY_NAME, "ENTITY_NAME")
local representation_name = normalize_name(REPRESENTATION_NAME, "REPRESENTATION_NAME")
local source_schema = normalize_name(SOURCE_SCHEMA, "SOURCE_SCHEMA")
local source_object = normalize_name(SOURCE_OBJECT, "SOURCE_OBJECT")
local source_kind = missing(SOURCE_KIND) and "RELATION" or upper(SOURCE_KIND)
if source_kind ~= "RELATION" and source_kind ~= "VIRTUAL_SCHEMA" then
    error("SEMANTIC_ADMIN_003: invalid SOURCE_KIND: " .. tostring(SOURCE_KIND))
end
-- The catalog settles it, so a declared kind that disagrees is refused rather
-- than stored. SOURCE_KIND was free text: VIRTUAL_SCHEMA over an ordinary table
-- and RELATION over a virtual schema were both accepted, and the compiler treats
-- the distinction as a planning input.
do
    local declared_virtual = source_kind == "VIRTUAL_SCHEMA"
    local actually_virtual = tonumber(scalar([[
        SELECT COUNT(*) FROM SYS.EXA_ALL_VIRTUAL_SCHEMAS
        WHERE UPPER(SCHEMA_NAME) = UPPER(:source_schema)
    ]], {source_schema = source_schema}) or 0) > 0
    if declared_virtual ~= actually_virtual then
        error("SEMANTIC_ADMIN_218: SOURCE_KIND " .. source_kind .. " disagrees with"
            .. " the catalog: " .. tostring(source_schema) .. " is "
            .. (actually_virtual and "a virtual schema" or "not a virtual schema")
            .. ". Declare " .. (actually_virtual and "VIRTUAL_SCHEMA" or "RELATION")
            .. ", or omit SOURCE_KIND and let it default.")
    end
end
local priority = missing(PRIORITY) and 100 or tonumber(PRIORITY)
if priority == nil or priority < 1 or priority % 1 ~= 0 then
    error("SEMANTIC_ADMIN_003: PRIORITY must be a positive integer")
end
if missing(COVERAGE_JSON) then
    error("SEMANTIC_ADMIN_060: COVERAGE_JSON is required")
end
local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, m.STATUS, e.ENTITY_ID,
           p.SOURCE_ALIAS
    FROM SYS_SEMANTIC.MODELS m
    JOIN SYS_SEMANTIC.ENTITIES e
      ON e.MODEL_ID = m.MODEL_ID AND e.VERSION_ID = m.ACTIVE_VERSION_ID
     AND UPPER(e.ENTITY_NAME) = UPPER(:entity_name) AND e.STATUS = 'ACTIVE'
    JOIN SYS_SEMANTIC.ENTITY_REPRESENTATIONS p
      ON p.ENTITY_ID = e.ENTITY_ID AND p.VERSION_ID = e.VERSION_ID
     AND p.REPRESENTATION_ROLE = 'PRIMARY' AND p.STATUS = 'ACTIVE'
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name, entity_name = entity_name})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_014: entity or active primary representation not found: "
        .. entity_name)
end
local model_id = row_value(rows[1], "MODEL_ID", 1)
local version_id = row_value(rows[1], "ACTIVE_VERSION_ID", 2)
local model_status = row_value(rows[1], "STATUS", 3)
local entity_id = row_value(rows[1], "ENTITY_ID", 4)
local source_alias = row_value(rows[1], "SOURCE_ALIAS", 5)
local duplicate = scalar([[
    SELECT COUNT(*) FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS
    WHERE ENTITY_ID = :entity_id
      AND UPPER(REPRESENTATION_NAME) = UPPER(:representation_name)
]], {entity_id = entity_id, representation_name = representation_name})
if tonumber(duplicate or 0) > 0 then
    error("SEMANTIC_ADMIN_046: duplicate representation name: " .. representation_name)
end
query([[
    INSERT INTO SYS_SEMANTIC.ENTITY_REPRESENTATIONS (
      MODEL_ID, VERSION_ID, ENTITY_ID, REPRESENTATION_NAME, SOURCE_KIND,
      SOURCE_SCHEMA, SOURCE_OBJECT, SOURCE_ALIAS, REPRESENTATION_ROLE,
      PRIORITY, FRESHNESS_POLICY, STATUS
    ) VALUES (
      :model_id, :version_id, :entity_id, :representation_name, :source_kind,
      :source_schema, :source_object, :source_alias, 'ALTERNATE',
      :priority, :freshness_policy, 'ACTIVE'
    )
]], {model_id = model_id, version_id = version_id, entity_id = entity_id,
      representation_name = representation_name, source_kind = source_kind,
      source_schema = source_schema, source_object = source_object,
      source_alias = source_alias, priority = priority,
      freshness_policy = missing(FRESHNESS_POLICY) and null or tostring(FRESHNESS_POLICY)})
local representation_id = scalar([[
    SELECT REPRESENTATION_ID FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS
    WHERE ENTITY_ID = :entity_id
      AND UPPER(REPRESENTATION_NAME) = UPPER(:representation_name)
]], {entity_id = entity_id, representation_name = representation_name})
-- F3 compilation requires an explicit binding on every partition. Seed the
-- new representation from the governed legacy expressions; validation below
-- proves that those expressions exist on the new physical source.
query([[
    INSERT INTO SYS_SEMANTIC.ATTRIBUTE_BINDINGS (
      MODEL_ID, VERSION_ID, ENTITY_ID, ATTRIBUTE_TYPE, ATTRIBUTE_ID,
      REPRESENTATION_ID, SOURCE_EXPRESSION, BINDING_ROLE,
      BINDING_PRIORITY, IS_DEFAULT, STATUS
    )
    SELECT d.MODEL_ID, d.VERSION_ID, d.ENTITY_ID, 'DIMENSION', d.DIMENSION_ID,
           :representation_id, d.EXPRESSION, 'PREFER', 1, FALSE, 'ACTIVE'
    FROM SYS_SEMANTIC.DIMENSIONS d
    WHERE d.MODEL_ID = :model_id AND d.VERSION_ID = :version_id
      AND d.ENTITY_ID = :entity_id AND d.STATUS = 'ACTIVE'
    UNION ALL
    SELECT f.MODEL_ID, f.VERSION_ID, f.ENTITY_ID, 'FACT', f.FACT_ID,
           :representation_id, f.EXPRESSION, 'PREFER', 1, FALSE, 'ACTIVE'
    FROM SYS_SEMANTIC.FACTS f
    WHERE f.MODEL_ID = :model_id AND f.VERSION_ID = :version_id
      AND f.ENTITY_ID = :entity_id AND f.STATUS = 'ACTIVE'
]], {representation_id = representation_id, model_id = model_id,
      version_id = version_id, entity_id = entity_id})
local applied, apply_result = pcall(query,
    "EXECUTE SCRIPT SEMANTIC_ADMIN.SET_REPRESENTATION_COVERAGE_BATCH("
      .. ":model_name, :entity_name, :coverage_json)",
    {model_name = model_name, entity_name = entity_name,
     coverage_json = tostring(COVERAGE_JSON)})
if not applied then
    query("DELETE FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS WHERE REPRESENTATION_ID = :representation_id",
        {representation_id = representation_id})
    query("DELETE FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS WHERE REPRESENTATION_ID = :representation_id",
        {representation_id = representation_id})
    query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
        {version_id = version_id})
    if tostring(model_status) == "PUBLISHED" then
        query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
            {model_name = model_name})
    end
    error("SEMANTIC_ADMIN_061: representation-plus-coverage candidate rejected and restored: "
        .. tostring(apply_result))
end
exit({{representation_id, model_name, entity_name, representation_name,
    source_kind, source_schema, source_object, source_alias, "ALTERNATE", priority}}, [[
  REPRESENTATION_ID DECIMAL(18,0), MODEL_NAME VARCHAR(256),
  ENTITY_NAME VARCHAR(256), REPRESENTATION_NAME VARCHAR(256),
  SOURCE_KIND VARCHAR(64), SOURCE_SCHEMA VARCHAR(256), SOURCE_OBJECT VARCHAR(256),
  SOURCE_ALIAS VARCHAR(128), REPRESENTATION_ROLE VARCHAR(64), PRIORITY DECIMAL(18,0)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_ENTITY_REPRESENTATION_WITH_IDENTITY_BINDING(
  MODEL_NAME,
  ENTITY_NAME,
  REPRESENTATION_NAME,
  SOURCE_KIND,
  SOURCE_SCHEMA,
  SOURCE_OBJECT,
  PRIORITY,
  FRESHNESS_POLICY,
  IDENTITY_NAME,
  SOURCE_EXPRESSION,
  BINDING_KIND,
  MAPPING_JSON
)
RETURNS TABLE AS
import("SEMANTIC_ADMIN.SEMANTIC_DEFINITION_RUNTIME", "semantic_definition")
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end
-- NULL arrives as userdata, and userdata is truthy: `value or ""` would render
-- it as an address and defeat the required-parameter check below.
local function trim(value)
    if value == nil or value == null then return "" end
    return tostring(value):match("^%s*(.-)%s*$")
end
local function upper(value) return string.upper(trim(value)) end
local function normalize_name(value, label)
    if missing(value) then error("SEMANTIC_ADMIN_001: " .. label .. " is required") end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local function json_scalar(value)
    if type(value) == "table" then return nil end
    return value
end
local function required_mapping(mapping, field)
    local value = json_scalar(mapping[field])
    if missing(value) then
        error("SEMANTIC_ADMIN_064: mapping " .. field .. " is required")
    end
    return trim(value)
end
local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then return nil end
    return rows[1][1]
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local entity_name = normalize_name(ENTITY_NAME, "ENTITY_NAME")
local representation_name = normalize_name(REPRESENTATION_NAME, "REPRESENTATION_NAME")
local source_schema = normalize_name(SOURCE_SCHEMA, "SOURCE_SCHEMA")
local source_object = normalize_name(SOURCE_OBJECT, "SOURCE_OBJECT")
local identity_name = normalize_name(IDENTITY_NAME, "IDENTITY_NAME")
local source_expression = trim(SOURCE_EXPRESSION)
if source_expression == "" then
    error("SEMANTIC_ADMIN_001: SOURCE_EXPRESSION is required")
end
local source_kind = missing(SOURCE_KIND) and "RELATION" or upper(SOURCE_KIND)
if source_kind ~= "RELATION" and source_kind ~= "VIRTUAL_SCHEMA" then
    error("SEMANTIC_ADMIN_003: invalid SOURCE_KIND: " .. tostring(SOURCE_KIND))
end
-- The catalog settles it, so a declared kind that disagrees is refused rather
-- than stored. SOURCE_KIND was free text: VIRTUAL_SCHEMA over an ordinary table
-- and RELATION over a virtual schema were both accepted, and the compiler treats
-- the distinction as a planning input.
do
    local declared_virtual = source_kind == "VIRTUAL_SCHEMA"
    local actually_virtual = tonumber(scalar([[
        SELECT COUNT(*) FROM SYS.EXA_ALL_VIRTUAL_SCHEMAS
        WHERE UPPER(SCHEMA_NAME) = UPPER(:source_schema)
    ]], {source_schema = source_schema}) or 0) > 0
    if declared_virtual ~= actually_virtual then
        error("SEMANTIC_ADMIN_218: SOURCE_KIND " .. source_kind .. " disagrees with"
            .. " the catalog: " .. tostring(source_schema) .. " is "
            .. (actually_virtual and "a virtual schema" or "not a virtual schema")
            .. ". Declare " .. (actually_virtual and "VIRTUAL_SCHEMA" or "RELATION")
            .. ", or omit SOURCE_KIND and let it default.")
    end
end
local binding_kind = upper(BINDING_KIND)
if binding_kind ~= "DIRECT" and binding_kind ~= "MAPPED" then
    error("SEMANTIC_ADMIN_003: BINDING_KIND must be DIRECT or MAPPED")
end
local priority = missing(PRIORITY) and 100 or tonumber(PRIORITY)
if priority == nil or priority < 1 or priority % 1 ~= 0 then
    error("SEMANTIC_ADMIN_003: PRIORITY must be a positive integer")
end
local mapping = nil
if binding_kind == "DIRECT" then
    if not missing(MAPPING_JSON) then
        error("SEMANTIC_ADMIN_064: DIRECT binding must not include MAPPING_JSON")
    end
else
    if missing(MAPPING_JSON) then
        error("SEMANTIC_ADMIN_064: MAPPED binding requires MAPPING_JSON")
    end
    local decoded, value = pcall(
        semantic_definition.decode_json, tostring(MAPPING_JSON))
    if not decoded or type(value) ~= "table" then
        error("SEMANTIC_ADMIN_064: MAPPING_JSON must be a JSON object: "
            .. tostring(value))
    end
    local certification = upper(required_mapping(value, "certification_status"))
    if certification ~= "CERTIFIED" then
        error("SEMANTIC_ADMIN_003: runtime identity mappings must be CERTIFIED")
    end
    mapping = {
        source_schema = required_mapping(value, "source_schema"),
        source_object = required_mapping(value, "source_object"),
        source_local_column = required_mapping(value, "source_local_column"),
        semantic_key_column = required_mapping(value, "semantic_key_column"),
        certification_status = certification,
    }
end

local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, m.STATUS, e.ENTITY_ID,
           p.SOURCE_ALIAS, si.IDENTITY_ID
    FROM SYS_SEMANTIC.MODELS m
    JOIN SYS_SEMANTIC.ENTITIES e
      ON e.MODEL_ID = m.MODEL_ID AND e.VERSION_ID = m.ACTIVE_VERSION_ID
     AND UPPER(e.ENTITY_NAME) = UPPER(:entity_name) AND e.STATUS = 'ACTIVE'
    JOIN SYS_SEMANTIC.ENTITY_REPRESENTATIONS p
      ON p.MODEL_ID = e.MODEL_ID AND p.VERSION_ID = e.VERSION_ID
     AND p.ENTITY_ID = e.ENTITY_ID AND p.REPRESENTATION_ROLE = 'PRIMARY'
     AND p.STATUS = 'ACTIVE'
    JOIN SYS_SEMANTIC.SEMANTIC_IDENTITIES si
      ON si.MODEL_ID = e.MODEL_ID AND si.VERSION_ID = e.VERSION_ID
     AND si.ENTITY_ID = e.ENTITY_ID
     AND UPPER(si.IDENTITY_NAME) = UPPER(:identity_name)
     AND si.STATUS = 'ACTIVE'
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name, entity_name = entity_name,
      identity_name = identity_name})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_064: entity, primary representation, or active identity not found")
end
local model_id = row_value(rows[1], "MODEL_ID", 1)
local version_id = row_value(rows[1], "ACTIVE_VERSION_ID", 2)
local model_status = row_value(rows[1], "STATUS", 3)
local entity_id = row_value(rows[1], "ENTITY_ID", 4)
local source_alias = row_value(rows[1], "SOURCE_ALIAS", 5)
local identity_id = row_value(rows[1], "IDENTITY_ID", 6)
local duplicate = scalar([[
    SELECT COUNT(*) FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS
    WHERE ENTITY_ID = :entity_id
      AND UPPER(REPRESENTATION_NAME) = UPPER(:representation_name)
]], {entity_id = entity_id, representation_name = representation_name})
if tonumber(duplicate or 0) > 0 then
    error("SEMANTIC_ADMIN_046: duplicate representation name: " .. representation_name)
end

query([[
    INSERT INTO SYS_SEMANTIC.ENTITY_REPRESENTATIONS (
      MODEL_ID, VERSION_ID, ENTITY_ID, REPRESENTATION_NAME, SOURCE_KIND,
      SOURCE_SCHEMA, SOURCE_OBJECT, SOURCE_ALIAS, REPRESENTATION_ROLE,
      PRIORITY, FRESHNESS_POLICY, STATUS
    ) VALUES (
      :model_id, :version_id, :entity_id, :representation_name, :source_kind,
      :source_schema, :source_object, :source_alias, 'ALTERNATE',
      :priority, :freshness_policy, 'ACTIVE'
    )
]], {model_id = model_id, version_id = version_id, entity_id = entity_id,
      representation_name = representation_name, source_kind = source_kind,
      source_schema = source_schema, source_object = source_object,
      source_alias = source_alias, priority = priority,
      freshness_policy = missing(FRESHNESS_POLICY) and null
          or tostring(FRESHNESS_POLICY)})
local representation_id = scalar([[
    SELECT REPRESENTATION_ID FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS
    WHERE ENTITY_ID = :entity_id
      AND UPPER(REPRESENTATION_NAME) = UPPER(:representation_name)
]], {entity_id = entity_id, representation_name = representation_name})
-- Keep the compound identity path symmetric with representation-plus-coverage.
-- Explicit bindings make the complete candidate visible to one validation run.
query([[
    INSERT INTO SYS_SEMANTIC.ATTRIBUTE_BINDINGS (
      MODEL_ID, VERSION_ID, ENTITY_ID, ATTRIBUTE_TYPE, ATTRIBUTE_ID,
      REPRESENTATION_ID, SOURCE_EXPRESSION, BINDING_ROLE,
      BINDING_PRIORITY, IS_DEFAULT, STATUS
    )
    SELECT d.MODEL_ID, d.VERSION_ID, d.ENTITY_ID, 'DIMENSION', d.DIMENSION_ID,
           :representation_id, d.EXPRESSION, 'PREFER', 1, FALSE, 'ACTIVE'
    FROM SYS_SEMANTIC.DIMENSIONS d
    WHERE d.MODEL_ID = :model_id AND d.VERSION_ID = :version_id
      AND d.ENTITY_ID = :entity_id AND d.STATUS = 'ACTIVE'
    UNION ALL
    SELECT f.MODEL_ID, f.VERSION_ID, f.ENTITY_ID, 'FACT', f.FACT_ID,
           :representation_id, f.EXPRESSION, 'PREFER', 1, FALSE, 'ACTIVE'
    FROM SYS_SEMANTIC.FACTS f
    WHERE f.MODEL_ID = :model_id AND f.VERSION_ID = :version_id
      AND f.ENTITY_ID = :entity_id AND f.STATUS = 'ACTIVE'
]], {representation_id = representation_id, model_id = model_id,
      version_id = version_id, entity_id = entity_id})
query([[
    INSERT INTO SYS_SEMANTIC.IDENTITY_BINDINGS (
      MODEL_ID, VERSION_ID, ENTITY_ID, IDENTITY_ID, REPRESENTATION_ID,
      SOURCE_EXPRESSION, BINDING_KIND, STATUS
    ) VALUES (
      :model_id, :version_id, :entity_id, :identity_id, :representation_id,
      :source_expression, :binding_kind, 'ACTIVE'
    )
]], {model_id = model_id, version_id = version_id, entity_id = entity_id,
      identity_id = identity_id, representation_id = representation_id,
      source_expression = source_expression, binding_kind = binding_kind})
local binding_id = scalar([[
    SELECT IDENTITY_BINDING_ID FROM SYS_SEMANTIC.IDENTITY_BINDINGS
    WHERE IDENTITY_ID = :identity_id AND REPRESENTATION_ID = :representation_id
      AND STATUS = 'ACTIVE'
]], {identity_id = identity_id, representation_id = representation_id})
local mapping_id = null
if mapping ~= nil then
    query([[
        INSERT INTO SYS_SEMANTIC.IDENTITY_MAPPING_RELATIONS (
          MODEL_ID, VERSION_ID, IDENTITY_BINDING_ID, SOURCE_SCHEMA,
          SOURCE_OBJECT, SOURCE_LOCAL_COLUMN, SEMANTIC_KEY_COLUMN,
          CERTIFICATION_STATUS, STATUS
        ) VALUES (
          :model_id, :version_id, :binding_id, :source_schema,
          :source_object, :source_local_column, :semantic_key_column,
          :certification_status, 'ACTIVE'
        )
    ]], {model_id = model_id, version_id = version_id, binding_id = binding_id,
          source_schema = mapping.source_schema,
          source_object = mapping.source_object,
          source_local_column = mapping.source_local_column,
          semantic_key_column = mapping.semantic_key_column,
          certification_status = mapping.certification_status})
    mapping_id = scalar([[
        SELECT IDENTITY_MAPPING_ID
        FROM SYS_SEMANTIC.IDENTITY_MAPPING_RELATIONS
        WHERE IDENTITY_BINDING_ID = :binding_id AND STATUS = 'ACTIVE'
    ]], {binding_id = binding_id})
end
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = version_id})
query("UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE' WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id AND STATUS IN ('OK', 'WARNING')",
    {model_id = model_id, version_id = version_id})
local candidate_validation = query(
    "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
    {model_name = model_name})
local validation_errors = {}
local generated_binding_issues = {}
local binding_suffix = "@" .. upper(representation_name)
for _, validation_row in ipairs(candidate_validation or {}) do
        if tostring(row_value(validation_row, "SEVERITY", 1)) == "ERROR"
            or tostring(row_value(validation_row, "SEVERITY", 1)) == "PRECONDITION" then
        local rule_code = row_value(validation_row, "RULE_CODE", 4)
            or "SEMANTIC_MODEL_ERROR"
        local message = row_value(validation_row, "MESSAGE", 5)
            or "model validation failed"
        local object_type = row_value(validation_row, "OBJECT_TYPE", 2)
            or "MODEL"
        local object_name = row_value(validation_row, "OBJECT_NAME", 3)
            or model_name
        local detail = tostring(rule_code)
            .. " [" .. tostring(object_type) .. " " .. tostring(object_name)
            .. "] " .. tostring(message)
        validation_errors[#validation_errors + 1] = detail
        local normalized_object_name = upper(object_name)
        if upper(object_type) == "ATTRIBUTE_BINDING"
                and string.sub(normalized_object_name, -#binding_suffix) == binding_suffix then
            generated_binding_issues[#generated_binding_issues + 1] = detail
        end
    end
end
if tostring(model_status) == "PUBLISHED" then
    if #validation_errors > 0 then
        query("DELETE FROM SYS_SEMANTIC.IDENTITY_MAPPING_RELATIONS WHERE IDENTITY_BINDING_ID = :binding_id",
            {binding_id = binding_id})
        query("DELETE FROM SYS_SEMANTIC.IDENTITY_BINDINGS WHERE IDENTITY_BINDING_ID = :binding_id",
            {binding_id = binding_id})
        query("DELETE FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS WHERE REPRESENTATION_ID = :representation_id",
            {representation_id = representation_id})
        query("DELETE FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS WHERE REPRESENTATION_ID = :representation_id",
            {representation_id = representation_id})
        query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
            {model_name = model_name})
        error("SEMANTIC_ADMIN_094: published representation-with-identity candidate rejected and restored; "
            .. "candidate introduced " .. tostring(#validation_errors)
            .. " validation error(s): " .. table.concat(validation_errors, "; "))
    end
end
exit({{representation_id, binding_id, mapping_id, model_name, entity_name,
    representation_name, identity_name, binding_kind, #generated_binding_issues,
    #generated_binding_issues == 0 and null
        or table.concat(generated_binding_issues, "; ")}}, [[
  REPRESENTATION_ID DECIMAL(18,0), IDENTITY_BINDING_ID DECIMAL(18,0),
  IDENTITY_MAPPING_ID DECIMAL(18,0), MODEL_NAME VARCHAR(256),
  ENTITY_NAME VARCHAR(256), REPRESENTATION_NAME VARCHAR(256),
  IDENTITY_NAME VARCHAR(256), BINDING_KIND VARCHAR(32),
  GENERATED_BINDING_ISSUE_COUNT DECIMAL(18,0),
  GENERATED_BINDING_ISSUES VARCHAR(2000000)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_ENTITY_REPRESENTATION_WITH_DECLARATIONS(
  MODEL_NAME,
  ENTITY_NAME,
  REPRESENTATION_NAME,
  SOURCE_KIND,
  SOURCE_SCHEMA,
  SOURCE_OBJECT,
  PRIORITY,
  FRESHNESS_POLICY,
  DECLARATIONS_JSON
)
RETURNS TABLE AS
-- One entry point for registering a representation with whatever has to be
-- declared alongside it.
--
-- The four earlier forms are each one-dimensional -- plain, _WITH_AUTHORITY,
-- _WITH_COVERAGE, _WITH_IDENTITY_BINDING -- while authority x coverage x
-- identity is eight combinations. BUG-G04 was the report of a missing fifth: F5
-- identity is what unlocks F4 authority across mismatched keys, so combining them
-- is the documented use case and no single call did it. Adding a fifth script
-- would have picked one more point in that space; this covers all of it.
--
-- DECLARATIONS_JSON is a closed object:
--   {"authority": "AUTHORITATIVE" | "PREFER" | "SUPPLEMENTAL",
--    "coverage":  [ ... as ADD_ENTITY_REPRESENTATION_WITH_COVERAGE's COVERAGE_JSON ... ],
--    "identity":  {"identity_name": ..., "source_expression": ...,
--                  "binding_kind": "DIRECT" | "MAPPED", "mapping": { ... }}}
-- Every key is optional; an empty object registers a plain representation.
--
-- This *dispatches* to the existing forms instead of merging them, which is the
-- whole point. _WITH_COVERAGE and _WITH_IDENTITY_BINDING deliberately stage their
-- declaration before validating, because a representation is invalid until it
-- carries one -- reimplementing that staging is how a half-declared model gets
-- shipped. Authority is the one aspect that can be applied afterwards, because an
-- undeclared authority defaults to PREFER and validates, so it composes onto any
-- of them; if it is refused the representation is unwound, so the pair either
-- both land or neither does.
--
-- coverage together with identity is refused rather than unimplemented:
-- SEMANTIC_MODEL_047 already rejects an F5 identity combined with F3 coverage on
-- the same entity, so every *valid* combination is reachable through this call.
import("SEMANTIC_ADMIN.SEMANTIC_DEFINITION_RUNTIME", "semantic_definition")
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end
-- NULL is userdata here, not nil, and it is truthy: `tostring(value or "")`
-- renders it as "userdata: 0x..." and would forward that as a name. The
-- one-dimensional forms report SEMANTIC_ADMIN_001 for an absent name, and
-- passing "" on makes their own `missing` check produce exactly that.
local function trim(value)
    if value == nil or value == null then return "" end
    return tostring(value):match("^%s*(.-)%s*$")
end
local function upper(value) return string.upper(trim(value)) end
local function row_value(row, name, position)
    if row == nil then return nil end
    return row[name] or row[string.lower(name)] or row[position]
end
-- Same shape as ADD_ENTITY_REPRESENTATION's, because the staged path below
-- does that script's job and has to refuse the same inputs it would.
local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end

local model_name = trim(MODEL_NAME)
local entity_name = trim(ENTITY_NAME)
local representation_name = trim(REPRESENTATION_NAME)

local declarations = {}
if not missing(DECLARATIONS_JSON) and upper(DECLARATIONS_JSON) ~= "NULL" then
    local decoded_ok, decoded = pcall(semantic_definition.decode_json,
        tostring(DECLARATIONS_JSON))
    if not decoded_ok or type(decoded) ~= "table" then
        error("SEMANTIC_ADMIN_214: DECLARATIONS_JSON must be a JSON object with any"
            .. " of the keys: authority, coverage, identity, attribute_bindings.")
    end
    -- A JSON array decodes to a table too, and would otherwise be reported as
    -- an unknown key named "1".
    if decoded[1] ~= nil then
        error("SEMANTIC_ADMIN_214: DECLARATIONS_JSON must be a JSON object, not an"
            .. " array. Allowed keys: authority, coverage, identity,"
            .. " attribute_bindings.")
    end
    declarations = decoded
end

-- Closed contract, like the compile request: a misspelled key must not be
-- silently ignored, or the call reports success without doing what was asked.
local allowed = {authority = true, coverage = true, identity = true,
    attribute_bindings = true}
local unknown = {}
for declaration_key, _ in pairs(declarations) do
    if not allowed[tostring(declaration_key)] then
        unknown[#unknown + 1] = tostring(declaration_key)
    end
end
if #unknown > 0 then
    table.sort(unknown)
    error("SEMANTIC_ADMIN_214: unknown DECLARATIONS_JSON key(s): "
        .. table.concat(unknown, ", ") .. ". Allowed keys: authority, coverage,"
        .. " identity, attribute_bindings.")
end

local authority = declarations.authority
local coverage = declarations.coverage
local identity = declarations.identity
local bindings = declarations.attribute_bindings
local has_authority = not missing(authority)
local has_coverage = type(coverage) == "table"
local has_identity = type(identity) == "table"
local has_bindings = type(bindings) == "table" and #bindings > 0
if bindings ~= nil and not has_bindings then
    error("SEMANTIC_ADMIN_216: attribute_bindings must be a non-empty JSON array"
        .. " of {attribute_type, attribute_name, source_expression} objects.")
end

if has_coverage and has_identity then
    error("SEMANTIC_ADMIN_215: coverage and identity cannot be declared on the"
        .. " same representation. F3 temporal coverage and an F5 semantic identity"
        .. " on one entity are rejected by SEMANTIC_MODEL_047, so this combination"
        .. " has no valid outcome. Declare one of them.")
end

-- Staging the representation here, rather than dispatching, is the only way a
-- declared binding can be part of the same candidate.
--
-- Every representation-registering script inserts the row, then runs
-- VALIDATE_MODEL, then -- if the model is PUBLISHED -- deletes the row again
-- when validation failed. The bindings that make a *narrower* supplemental
-- source valid have to exist between that insert and that validation, and there
-- is no seam to reach in from outside. So when attribute_bindings are declared
-- this script does the insert itself and hands a complete candidate to the
-- coverage/identity/authority steps, which then validate against something that
-- can actually pass.
--
-- Without this, the canonical F4 shape -- a supplemental source that does not
-- carry every column the primary's dimensions reference -- was unreachable on a
-- published model by any route: the plain form fails SEMANTIC_MODEL_017, the
-- collapsed form fails SEMANTIC_MODEL_040 on the seeded binding, and a
-- document's entity-level bindings arrive after the representation has already
-- been validated and rolled back.
local declared = {}
local added_row = nil
local staged_representation_id = nil
local staged_status = nil
if has_bindings then
    local model_name_checked = normalize_name(model_name, "MODEL_NAME")
    local entity_name_checked = normalize_name(entity_name, "ENTITY_NAME")
    local representation_checked =
        normalize_name(representation_name, "REPRESENTATION_NAME")
    local source_schema_checked = normalize_name(SOURCE_SCHEMA, "SOURCE_SCHEMA")
    local source_object_checked = normalize_name(SOURCE_OBJECT, "SOURCE_OBJECT")
    local source_kind_checked = missing(SOURCE_KIND) and "RELATION"
        or upper(SOURCE_KIND)
    if source_kind_checked ~= "RELATION" and source_kind_checked ~= "VIRTUAL_SCHEMA" then
        error("SEMANTIC_ADMIN_003: invalid SOURCE_KIND: " .. tostring(SOURCE_KIND))
    end
    local priority_checked = missing(PRIORITY) and 100 or tonumber(PRIORITY)
    if priority_checked == nil or priority_checked < 1
        or priority_checked % 1 ~= 0 then
        error("SEMANTIC_ADMIN_003: PRIORITY must be a positive integer")
    end

    local context = query([[
        SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, e.ENTITY_ID, p.SOURCE_ALIAS, m.STATUS
        FROM SYS_SEMANTIC.MODELS m
        JOIN SYS_SEMANTIC.ENTITIES e
          ON e.MODEL_ID = m.MODEL_ID AND e.VERSION_ID = m.ACTIVE_VERSION_ID
         AND UPPER(e.ENTITY_NAME) = UPPER(:entity_name) AND e.STATUS = 'ACTIVE'
        JOIN SYS_SEMANTIC.ENTITY_REPRESENTATIONS p
          ON p.ENTITY_ID = e.ENTITY_ID AND p.REPRESENTATION_ROLE = 'PRIMARY'
         AND p.STATUS = 'ACTIVE'
        WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
    ]], {model_name = model_name_checked, entity_name = entity_name_checked})
    if context == nil or #context == 0 then
        error("SEMANTIC_ADMIN_014: entity or active primary representation not"
            .. " found: " .. entity_name_checked)
    end
    local model_id = row_value(context[1], "MODEL_ID", 1)
    local version_id = row_value(context[1], "ACTIVE_VERSION_ID", 2)
    local entity_id = row_value(context[1], "ENTITY_ID", 3)
    local source_alias = row_value(context[1], "SOURCE_ALIAS", 4)
    local model_status = upper(row_value(context[1], "STATUS", 5))
    staged_status = model_status

    local duplicate = query([[
        SELECT COUNT(*) FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS
        WHERE ENTITY_ID = :entity_id
          AND UPPER(REPRESENTATION_NAME) = UPPER(:representation_name)
    ]], {entity_id = entity_id, representation_name = representation_checked})
    if tonumber(tostring(row_value(duplicate[1], "COUNT", 1) or 0)) > 0 then
        error("SEMANTIC_ADMIN_046: duplicate representation name: "
            .. representation_checked)
    end

    query([[
        INSERT INTO SYS_SEMANTIC.ENTITY_REPRESENTATIONS (
          MODEL_ID, VERSION_ID, ENTITY_ID, REPRESENTATION_NAME, SOURCE_KIND,
          SOURCE_SCHEMA, SOURCE_OBJECT, SOURCE_ALIAS, REPRESENTATION_ROLE,
          PRIORITY, FRESHNESS_POLICY, STATUS
        ) VALUES (
          :model_id, :version_id, :entity_id, :representation_name, :source_kind,
          :source_schema, :source_object, :source_alias, 'ALTERNATE',
          :priority, :freshness_policy, 'ACTIVE'
        )
    ]], {model_id = model_id, version_id = version_id, entity_id = entity_id,
        representation_name = representation_checked,
        source_kind = source_kind_checked, source_schema = source_schema_checked,
        source_object = source_object_checked, source_alias = source_alias,
        priority = priority_checked,
        freshness_policy = missing(FRESHNESS_POLICY) and null
            or tostring(FRESHNESS_POLICY)})
    local staged = query([[
        SELECT REPRESENTATION_ID FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS
        WHERE ENTITY_ID = :entity_id
          AND UPPER(REPRESENTATION_NAME) = UPPER(:representation_name)
    ]], {entity_id = entity_id, representation_name = representation_checked})
    staged_representation_id = row_value(staged[1], "REPRESENTATION_ID", 1)

    -- Seed from the governed expressions, exactly as _WITH_COVERAGE does, so
    -- every attribute of the entity resolves on the new source by default.
    query([[
        INSERT INTO SYS_SEMANTIC.ATTRIBUTE_BINDINGS (
          MODEL_ID, VERSION_ID, ENTITY_ID, ATTRIBUTE_TYPE, ATTRIBUTE_ID,
          REPRESENTATION_ID, SOURCE_EXPRESSION, BINDING_ROLE,
          BINDING_PRIORITY, IS_DEFAULT, STATUS
        )
        SELECT d.MODEL_ID, d.VERSION_ID, d.ENTITY_ID, 'DIMENSION', d.DIMENSION_ID,
               :representation_id, d.EXPRESSION, 'PREFER', 1, FALSE, 'ACTIVE'
        FROM SYS_SEMANTIC.DIMENSIONS d
        WHERE d.MODEL_ID = :model_id AND d.VERSION_ID = :version_id
          AND d.ENTITY_ID = :entity_id AND d.STATUS = 'ACTIVE'
        UNION ALL
        SELECT f.MODEL_ID, f.VERSION_ID, f.ENTITY_ID, 'FACT', f.FACT_ID,
               :representation_id, f.EXPRESSION, 'PREFER', 1, FALSE, 'ACTIVE'
        FROM SYS_SEMANTIC.FACTS f
        WHERE f.MODEL_ID = :model_id AND f.VERSION_ID = :version_id
          AND f.ENTITY_ID = :entity_id AND f.STATUS = 'ACTIVE'
    ]], {representation_id = staged_representation_id, model_id = model_id,
        version_id = version_id, entity_id = entity_id})

    -- Then overwrite the ones the caller declared. This is the whole point: a
    -- CAST(NULL AS ...) FALLBACK is how a source says "no opinion about this
    -- attribute", and it has to replace the seeded governed expression before
    -- anything validates.
    for index, binding in ipairs(bindings) do
        if type(binding) ~= "table" then
            error("SEMANTIC_ADMIN_216: attribute_bindings[" .. index
                .. "] must be a JSON object")
        end
        local attribute_type = upper(binding.attribute_type)
        if attribute_type ~= "DIMENSION" and attribute_type ~= "FACT" then
            error("SEMANTIC_ADMIN_216: attribute_bindings[" .. index
                .. "].attribute_type must be DIMENSION or FACT")
        end
        local attribute_name = trim(binding.attribute_name)
        local expression = trim(binding.source_expression)
        if attribute_name == "" or expression == "" then
            error("SEMANTIC_ADMIN_216: attribute_bindings[" .. index
                .. "] requires attribute_name and source_expression")
        end
        local role = upper(binding.binding_role)
        if role ~= "PREFER" and role ~= "FALLBACK" then role = "PREFER" end
        local binding_priority = tonumber(tostring(binding.binding_priority or 1)) or 1
        local updated = query([[
            UPDATE SYS_SEMANTIC.ATTRIBUTE_BINDINGS
            SET SOURCE_EXPRESSION = :expression, BINDING_ROLE = :role,
                BINDING_PRIORITY = :binding_priority,
                UPDATED_AT = CURRENT_TIMESTAMP, UPDATED_BY = CURRENT_USER
            WHERE REPRESENTATION_ID = :representation_id
              AND ATTRIBUTE_TYPE = :attribute_type
              AND ATTRIBUTE_ID IN (
                SELECT DIMENSION_ID FROM SYS_SEMANTIC.DIMENSIONS
                WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
                  AND UPPER(DIMENSION_NAME) = UPPER(:attribute_name)
                  AND :attribute_type = 'DIMENSION'
                UNION ALL
                SELECT FACT_ID FROM SYS_SEMANTIC.FACTS
                WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
                  AND UPPER(FACT_NAME) = UPPER(:attribute_name)
                  AND :attribute_type = 'FACT'
              )
        ]], {expression = expression, role = role,
            binding_priority = binding_priority,
            representation_id = staged_representation_id,
            attribute_type = attribute_type, attribute_name = attribute_name,
            model_id = model_id, version_id = version_id})
        local present = query([[
            SELECT COUNT(*) FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS b
            LEFT JOIN SYS_SEMANTIC.DIMENSIONS d
              ON b.ATTRIBUTE_TYPE = 'DIMENSION' AND d.DIMENSION_ID = b.ATTRIBUTE_ID
            LEFT JOIN SYS_SEMANTIC.FACTS f
              ON b.ATTRIBUTE_TYPE = 'FACT' AND f.FACT_ID = b.ATTRIBUTE_ID
            WHERE b.REPRESENTATION_ID = :representation_id
              AND UPPER(b.ATTRIBUTE_TYPE) = UPPER(:attribute_type)
              AND UPPER(COALESCE(d.DIMENSION_NAME, f.FACT_NAME)) = UPPER(:attribute_name)
              AND b.SOURCE_EXPRESSION = :expression
        ]], {representation_id = staged_representation_id,
            attribute_type = attribute_type, attribute_name = attribute_name,
            expression = expression})
        if tonumber(tostring(row_value(present[1], "COUNT", 1) or 0)) == 0 then
            query("DELETE FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS"
                .. " WHERE REPRESENTATION_ID = :representation_id",
                {representation_id = staged_representation_id})
            query("DELETE FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS"
                .. " WHERE REPRESENTATION_ID = :representation_id",
                {representation_id = staged_representation_id})
            error("SEMANTIC_ADMIN_217: attribute_bindings names an attribute the"
                .. " entity does not have, or one not bound to this"
                .. " representation: " .. attribute_type .. " "
                .. attribute_name .. ". Nothing was registered.")
        end
    end
    query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
        {version_id = version_id})
    query([[
        UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE'
        WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
          AND STATUS IN ('OK', 'WARNING')
    ]], {model_id = model_id, version_id = version_id})
    added_row = {staged_representation_id}
    declared[#declared + 1] = "attribute_bindings"
elseif has_identity then
    local mapping_json = null
    if type(identity.mapping) == "table" then
        mapping_json = semantic_definition.encode_json(identity.mapping)
    end
    local added = query([[
        EXECUTE SCRIPT SEMANTIC_ADMIN.ADD_ENTITY_REPRESENTATION_WITH_IDENTITY_BINDING(
            :model_name, :entity_name, :representation_name, :source_kind,
            :source_schema, :source_object, :priority, :freshness_policy,
            :identity_name, :source_expression, :binding_kind, :mapping_json)
    ]], {model_name = model_name, entity_name = entity_name,
        representation_name = representation_name, source_kind = SOURCE_KIND,
        source_schema = SOURCE_SCHEMA, source_object = SOURCE_OBJECT,
        priority = PRIORITY, freshness_policy = FRESHNESS_POLICY,
        identity_name = identity.identity_name,
        source_expression = identity.source_expression,
        binding_kind = identity.binding_kind, mapping_json = mapping_json})
    added_row = added ~= nil and added[1] or nil
    declared[#declared + 1] = "identity"
elseif has_coverage then
    local added = query([[
        EXECUTE SCRIPT SEMANTIC_ADMIN.ADD_ENTITY_REPRESENTATION_WITH_COVERAGE(
            :model_name, :entity_name, :representation_name, :source_kind,
            :source_schema, :source_object, :priority, :freshness_policy,
            :coverage_json)
    ]], {model_name = model_name, entity_name = entity_name,
        representation_name = representation_name, source_kind = SOURCE_KIND,
        source_schema = SOURCE_SCHEMA, source_object = SOURCE_OBJECT,
        priority = PRIORITY, freshness_policy = FRESHNESS_POLICY,
        coverage_json = semantic_definition.encode_json(coverage)})
    added_row = added ~= nil and added[1] or nil
    declared[#declared + 1] = "coverage"
else
    local added = query([[
        EXECUTE SCRIPT SEMANTIC_ADMIN.ADD_ENTITY_REPRESENTATION(
            :model_name, :entity_name, :representation_name, :source_kind,
            :source_schema, :source_object, :priority, :freshness_policy)
    ]], {model_name = model_name, entity_name = entity_name,
        representation_name = representation_name, source_kind = SOURCE_KIND,
        source_schema = SOURCE_SCHEMA, source_object = SOURCE_OBJECT,
        priority = PRIORITY, freshness_policy = FRESHNESS_POLICY})
    added_row = added ~= nil and added[1] or nil
end
if added_row == nil then
    error("SEMANTIC_ADMIN_046: representation was not registered: "
        .. representation_name)
end

local function unwind_staged()
    if staged_representation_id == nil then return end
    pcall(query, "DELETE FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS"
        .. " WHERE REPRESENTATION_ID = :representation_id",
        {representation_id = staged_representation_id})
    pcall(query, "DELETE FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS"
        .. " WHERE REPRESENTATION_ID = :representation_id",
        {representation_id = staged_representation_id})
end

-- In the staged path the remaining declarations go on top of a candidate whose
-- bindings already resolve, so each of these sub-calls validates against
-- something that can pass -- which is exactly what they cannot do when the
-- representation arrives on its own.
if has_bindings and has_coverage then
    local applied, coverage_error = pcall(query, [[
        EXECUTE SCRIPT SEMANTIC_ADMIN.SET_REPRESENTATION_COVERAGE_BATCH(
            :model_name, :entity_name, :coverage_json)
    ]], {model_name = model_name, entity_name = entity_name,
        coverage_json = semantic_definition.encode_json(coverage)})
    if not applied then
        unwind_staged()
        error("SEMANTIC_ADMIN_094: representation candidate rejected and restored;"
            .. " the coverage declaration failed: " .. tostring(coverage_error))
    end
    declared[#declared + 1] = "coverage"
end

if has_bindings and has_identity then
    local applied, identity_error = pcall(function()
        query([[
            EXECUTE SCRIPT SEMANTIC_ADMIN.ADD_IDENTITY_BINDING(
                :model_name, :identity_name, :representation_name,
                :source_expression, :binding_kind)
        ]], {model_name = model_name, identity_name = identity.identity_name,
            representation_name = representation_name,
            source_expression = identity.source_expression,
            binding_kind = identity.binding_kind})
        if type(identity.mapping) == "table" then
            local mapping = identity.mapping
            query([[
                EXECUTE SCRIPT SEMANTIC_ADMIN.ADD_IDENTITY_MAPPING_RELATION(
                    :model_name, :identity_name, :representation_name,
                    :source_schema, :source_object, :source_local_column,
                    :semantic_key_column, :certification_status)
            ]], {model_name = model_name, identity_name = identity.identity_name,
                representation_name = representation_name,
                source_schema = mapping.source_schema,
                source_object = mapping.source_object,
                source_local_column = mapping.source_local_column,
                semantic_key_column = mapping.semantic_key_column,
                certification_status = missing(mapping.certification_status)
                    and "CERTIFIED" or upper(mapping.certification_status)})
        end
    end)
    if not applied then
        unwind_staged()
        error("SEMANTIC_ADMIN_094: representation candidate rejected and restored;"
            .. " the identity declaration failed: " .. tostring(identity_error))
    end
    declared[#declared + 1] = "identity"
end

local authority_role = null
if has_authority then
    authority_role = upper(authority)
    local applied, authority_error = pcall(query, [[
        EXECUTE SCRIPT SEMANTIC_ADMIN.SET_REPRESENTATION_AUTHORITY(
            :model_name, :entity_name, :representation_name, :authority_role)
    ]], {model_name = model_name, entity_name = entity_name,
        representation_name = representation_name, authority_role = authority_role})
    if not applied then
        -- Unwind, so a refused authority declaration does not leave a
        -- representation the caller did not ask for on its own.
        pcall(query, [[
            EXECUTE SCRIPT SEMANTIC_ADMIN.REMOVE_ENTITY_REPRESENTATION(
                :model_name, :entity_name, :representation_name)
        ]], {model_name = model_name, entity_name = entity_name,
            representation_name = representation_name})
        error("SEMANTIC_ADMIN_094: representation candidate rejected and restored;"
            .. " the authority declaration failed: " .. tostring(authority_error))
    end
    declared[#declared + 1] = "authority"
end

-- One proof for the whole candidate. The dispatched paths validate inside their
-- sub-script; the staged path has to do it here, and unwind the same way.
if has_bindings then
    local blocking = {}
    for _, row in ipairs(query(
        "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
        {model_name = model_name}) or {}) do
        local severity = upper(row_value(row, "SEVERITY", 1))
        if severity == "ERROR" or severity == "PRECONDITION" then
            blocking[#blocking + 1] = tostring(row_value(row, "RULE_CODE", 4))
                .. " [" .. tostring(row_value(row, "OBJECT_TYPE", 2)) .. " "
                .. tostring(row_value(row, "OBJECT_NAME", 3)) .. "] "
                .. tostring(row_value(row, "MESSAGE", 5))
        end
    end
    if staged_status == "PUBLISHED" and #blocking > 0 then
        unwind_staged()
        pcall(query, "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
            {model_name = model_name})
        error("SEMANTIC_ADMIN_094: published representation-with-bindings candidate"
            .. " rejected and restored; candidate introduced "
            .. tostring(#blocking) .. " validation error(s): "
            .. table.concat(blocking, "; "))
    end
    -- The staged path marked VALIDATION_RUNS stale on its way in, and the
    -- candidate has just been proved. Recertify so the compile cache is usable
    -- again rather than leaving a published model with no current validation --
    -- which is the contract the older representation scripts predate.
    pcall(query, "EXECUTE SCRIPT SEMANTIC_ADMIN.RECERTIFY_MODEL_IF_PUBLISHED(:model_name)",
        {model_name = model_name})
end

exit({{
    row_value(added_row, "REPRESENTATION_ID", 1),
    model_name,
    entity_name,
    representation_name,
    #declared > 0 and table.concat(declared, ",") or null,
    authority_role,
}}, [[
  REPRESENTATION_ID DECIMAL(18,0),
  MODEL_NAME VARCHAR(256),
  ENTITY_NAME VARCHAR(256),
  REPRESENTATION_NAME VARCHAR(256),
  DECLARED VARCHAR(256),
  AUTHORITY_ROLE VARCHAR(32)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.SET_PRIMARY_REPRESENTATION(
  MODEL_NAME,
  ENTITY_NAME,
  REPRESENTATION_NAME
)
RETURNS TABLE AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end
local function trim(value) return tostring(value):match("^%s*(.-)%s*$") end
local function normalize_name(value, label)
    if missing(value) then error("SEMANTIC_ADMIN_001: " .. label .. " is required") end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local function scalar(sql_text, params)
    local scalar_rows = query(sql_text, params or {})
    if scalar_rows == nil or #scalar_rows == 0 then return nil end
    return scalar_rows[1][1]
end
local function direct_column(expression, source_alias)
    if expression == nil or expression == null then return nil end
    local text = tostring(expression):match("^%s*(.-)%s*$")
    local alias, column = string.match(text,
        "^([A-Za-z_][A-Za-z0-9_]*)%s*%.%s*([A-Za-z_][A-Za-z0-9_]*)$")
    if alias ~= nil and string.upper(alias) == string.upper(tostring(source_alias)) then
        return string.upper(column)
    end
    alias, column = string.match(text,
        '^([A-Za-z_][A-Za-z0-9_]*)%s*%.%s*"([^"]+)"$')
    if alias ~= nil and string.upper(alias) == string.upper(tostring(source_alias)) then
        return column
    end
    return nil
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local entity_name = normalize_name(ENTITY_NAME, "ENTITY_NAME")
local representation_name = normalize_name(REPRESENTATION_NAME, "REPRESENTATION_NAME")
local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, e.ENTITY_ID,
           er.REPRESENTATION_ID, er.SOURCE_SCHEMA, er.SOURCE_OBJECT,
           er.SOURCE_ALIAS, e.SOURCE_ALIAS AS ENTITY_SOURCE_ALIAS,
           er.REPRESENTATION_ROLE, er.VALID_FROM, er.VALID_TO,
           er.COVERAGE_PREDICATE
    FROM SYS_SEMANTIC.MODELS m
    JOIN SYS_SEMANTIC.ENTITIES e
      ON e.MODEL_ID = m.MODEL_ID
     AND e.VERSION_ID = m.ACTIVE_VERSION_ID
     AND UPPER(e.ENTITY_NAME) = UPPER(:entity_name)
     AND e.STATUS = 'ACTIVE'
    JOIN SYS_SEMANTIC.ENTITY_REPRESENTATIONS er
      ON er.ENTITY_ID = e.ENTITY_ID
     AND er.MODEL_ID = e.MODEL_ID
     AND er.VERSION_ID = e.VERSION_ID
     AND UPPER(er.REPRESENTATION_NAME) = UPPER(:representation_name)
     AND er.STATUS = 'ACTIVE'
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name, entity_name = entity_name,
    representation_name = representation_name})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_045: active representation not found: " .. representation_name)
end
local row = rows[1]
local model_id = row_value(row, "MODEL_ID", 1)
local version_id = row_value(row, "ACTIVE_VERSION_ID", 2)
local entity_id = row_value(row, "ENTITY_ID", 3)
local representation_id = row_value(row, "REPRESENTATION_ID", 4)
local source_schema = row_value(row, "SOURCE_SCHEMA", 5)
local source_object = row_value(row, "SOURCE_OBJECT", 6)
local source_alias = row_value(row, "SOURCE_ALIAS", 7)
local entity_source_alias = row_value(row, "ENTITY_SOURCE_ALIAS", 8)
if string.upper(tostring(source_alias)) ~= string.upper(tostring(entity_source_alias)) then
    error("SEMANTIC_ADMIN_048: representation alias does not match the entity alias: "
        .. tostring(entity_source_alias))
end
local previous_rows = query([[
    SELECT REPRESENTATION_ID, REPRESENTATION_NAME, SOURCE_SCHEMA,
           SOURCE_OBJECT, SOURCE_ALIAS
    FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS
    WHERE ENTITY_ID = :entity_id
      AND REPRESENTATION_ROLE = 'PRIMARY'
      AND STATUS = 'ACTIVE'
]], {entity_id = entity_id})
local previous_representation_id = previous_rows and previous_rows[1]
    and row_value(previous_rows[1], "REPRESENTATION_ID", 1) or nil
local previous_name = previous_rows and previous_rows[1]
    and row_value(previous_rows[1], "REPRESENTATION_NAME", 2) or null
local previous_source_schema = previous_rows and previous_rows[1]
    and row_value(previous_rows[1], "SOURCE_SCHEMA", 3) or nil
local previous_source_object = previous_rows and previous_rows[1]
    and row_value(previous_rows[1], "SOURCE_OBJECT", 4) or nil
local previous_source_alias = previous_rows and previous_rows[1]
    and row_value(previous_rows[1], "SOURCE_ALIAS", 5) or nil
local changed = tostring(row_value(row, "REPRESENTATION_ROLE", 9)) ~= "PRIMARY"

if changed then
    -- Promotion changes which representation anchors canonical keys. Reject a
    -- target that can only be valid as an alternate before mutating roles.
    local key_columns = query([[
        SELECT DISTINCT ukc.COLUMN_NAME
        FROM SYS_SEMANTIC.UNIQUE_KEYS uk
        JOIN SYS_SEMANTIC.UNIQUE_KEY_COLUMNS ukc
          ON ukc.UNIQUE_KEY_ID = uk.UNIQUE_KEY_ID
        WHERE uk.ENTITY_ID = :entity_id
          AND uk.STATUS = 'ACTIVE'
          AND ukc.COLUMN_NAME IS NOT NULL
          AND ukc.EXPRESSION IS NULL
        ORDER BY ukc.COLUMN_NAME
    ]], {entity_id = entity_id})
    for _, key_row in ipairs(key_columns or {}) do
        local key_column = row_value(key_row, "COLUMN_NAME", 1)
        local column_count = scalar([[
            SELECT COUNT(*)
            FROM SYS.EXA_ALL_COLUMNS
            WHERE (COLUMN_SCHEMA = :source_schema OR COLUMN_SCHEMA = UPPER(:source_schema))
              AND (COLUMN_TABLE = :source_object OR COLUMN_TABLE = UPPER(:source_object))
              AND (COLUMN_NAME = :column_name OR COLUMN_NAME = UPPER(:column_name))
        ]], {source_schema = source_schema, source_object = source_object,
            column_name = key_column})
        if tonumber(column_count or 0) == 0 then
            error("SEMANTIC_ADMIN_058: promotion rejected; target representation '"
                .. representation_name .. "' cannot anchor declared unique-key column "
                .. tostring(key_column) .. ". Normalize the source to expose the canonical "
                .. "column or keep it as an alternate representation.")
        end
    end

    local anchored_identity_rows = query([[
        SELECT DISTINCT ukc.COLUMN_NAME, ib.BINDING_KIND, ib.SOURCE_EXPRESSION
        FROM SYS_SEMANTIC.UNIQUE_KEYS uk
        JOIN SYS_SEMANTIC.UNIQUE_KEY_COLUMNS ukc
          ON ukc.UNIQUE_KEY_ID = uk.UNIQUE_KEY_ID
        JOIN SYS_SEMANTIC.RELATIONSHIPS r
          ON r.MODEL_ID = uk.MODEL_ID AND r.VERSION_ID = uk.VERSION_ID
         AND (r.FROM_ENTITY_ID = uk.ENTITY_ID OR r.TO_ENTITY_ID = uk.ENTITY_ID)
         AND r.STATUS = 'ACTIVE'
        JOIN SYS_SEMANTIC.RELATIONSHIP_KEY_MAPPINGS rkm
          ON rkm.RELATIONSHIP_ID = r.RELATIONSHIP_ID
         AND ((r.FROM_ENTITY_ID = uk.ENTITY_ID
               AND rkm.FROM_COLUMN_NAME = ukc.COLUMN_NAME)
           OR (r.TO_ENTITY_ID = uk.ENTITY_ID
               AND rkm.TO_COLUMN_NAME = ukc.COLUMN_NAME))
        JOIN SYS_SEMANTIC.SEMANTIC_IDENTITIES si
          ON si.ENTITY_ID = uk.ENTITY_ID AND si.STATUS = 'ACTIVE'
        LEFT JOIN SYS_SEMANTIC.IDENTITY_BINDINGS ib
          ON ib.IDENTITY_ID = si.IDENTITY_ID
         AND ib.REPRESENTATION_ID = :representation_id
         AND ib.STATUS = 'ACTIVE'
        WHERE uk.ENTITY_ID = :entity_id
          AND uk.STATUS = 'ACTIVE'
          AND ukc.COLUMN_NAME IS NOT NULL
          AND ukc.EXPRESSION IS NULL
          AND 1 = (SELECT COUNT(*)
                   FROM SYS_SEMANTIC.UNIQUE_KEY_COLUMNS scalar_key
                   WHERE scalar_key.UNIQUE_KEY_ID = uk.UNIQUE_KEY_ID)
    ]], {entity_id = entity_id, representation_id = representation_id})
    for _, identity_row in ipairs(anchored_identity_rows or {}) do
        local key_column = row_value(identity_row, "COLUMN_NAME", 1)
        local binding_kind = row_value(identity_row, "BINDING_KIND", 2)
        local binding_expression = row_value(identity_row, "SOURCE_EXPRESSION", 3)
        local bound_column = direct_column(binding_expression, source_alias)
        if tostring(binding_kind) ~= "DIRECT"
            or bound_column == nil
            or tostring(bound_column) ~= tostring(key_column) then
            error("SEMANTIC_ADMIN_058: promotion rejected; target representation '"
                .. representation_name .. "' does not anchor relationship key "
                .. tostring(key_column) .. " with a bare DIRECT identity binding. "
                .. "Keep it as an alternate or bind the canonical key directly.")
        end
    end

    -- A stale clean run is recovery evidence only when the current primary is
    -- itself trapped by one of the prospective checks above. Unrelated stale
    -- validation history must not authorize a new promotion.
    local recovery_from_invalid_primary = false
    for _, key_row in ipairs(key_columns or {}) do
        local key_column = row_value(key_row, "COLUMN_NAME", 1)
        local column_count = scalar([[
            SELECT COUNT(*)
            FROM SYS.EXA_ALL_COLUMNS
            WHERE (COLUMN_SCHEMA = :source_schema OR COLUMN_SCHEMA = UPPER(:source_schema))
              AND (COLUMN_TABLE = :source_object OR COLUMN_TABLE = UPPER(:source_object))
              AND (COLUMN_NAME = :column_name OR COLUMN_NAME = UPPER(:column_name))
        ]], {source_schema = previous_source_schema,
            source_object = previous_source_object, column_name = key_column})
        if tonumber(column_count or 0) == 0 then
            recovery_from_invalid_primary = true
        end
    end
    local previous_identity_rows = query([[
        SELECT DISTINCT ukc.COLUMN_NAME, ib.BINDING_KIND, ib.SOURCE_EXPRESSION
        FROM SYS_SEMANTIC.UNIQUE_KEYS uk
        JOIN SYS_SEMANTIC.UNIQUE_KEY_COLUMNS ukc
          ON ukc.UNIQUE_KEY_ID = uk.UNIQUE_KEY_ID
        JOIN SYS_SEMANTIC.RELATIONSHIPS r
          ON r.MODEL_ID = uk.MODEL_ID AND r.VERSION_ID = uk.VERSION_ID
         AND (r.FROM_ENTITY_ID = uk.ENTITY_ID OR r.TO_ENTITY_ID = uk.ENTITY_ID)
         AND r.STATUS = 'ACTIVE'
        JOIN SYS_SEMANTIC.RELATIONSHIP_KEY_MAPPINGS rkm
          ON rkm.RELATIONSHIP_ID = r.RELATIONSHIP_ID
         AND ((r.FROM_ENTITY_ID = uk.ENTITY_ID
               AND rkm.FROM_COLUMN_NAME = ukc.COLUMN_NAME)
           OR (r.TO_ENTITY_ID = uk.ENTITY_ID
               AND rkm.TO_COLUMN_NAME = ukc.COLUMN_NAME))
        JOIN SYS_SEMANTIC.SEMANTIC_IDENTITIES si
          ON si.ENTITY_ID = uk.ENTITY_ID AND si.STATUS = 'ACTIVE'
        LEFT JOIN SYS_SEMANTIC.IDENTITY_BINDINGS ib
          ON ib.IDENTITY_ID = si.IDENTITY_ID
         AND ib.REPRESENTATION_ID = :representation_id
         AND ib.STATUS = 'ACTIVE'
        WHERE uk.ENTITY_ID = :entity_id
          AND uk.STATUS = 'ACTIVE'
          AND ukc.COLUMN_NAME IS NOT NULL
          AND ukc.EXPRESSION IS NULL
          AND 1 = (SELECT COUNT(*)
                   FROM SYS_SEMANTIC.UNIQUE_KEY_COLUMNS scalar_key
                   WHERE scalar_key.UNIQUE_KEY_ID = uk.UNIQUE_KEY_ID)
    ]], {entity_id = entity_id,
        representation_id = previous_representation_id})
    for _, identity_row in ipairs(previous_identity_rows or {}) do
        local key_column = row_value(identity_row, "COLUMN_NAME", 1)
        local binding_kind = row_value(identity_row, "BINDING_KIND", 2)
        local binding_expression = row_value(identity_row, "SOURCE_EXPRESSION", 3)
        local bound_column = direct_column(binding_expression,
            previous_source_alias)
        if tostring(binding_kind) ~= "DIRECT"
            or bound_column == nil
            or tostring(bound_column) ~= tostring(key_column) then
            recovery_from_invalid_primary = true
        end
    end

    local stale_default_count = scalar([[
        SELECT COUNT(*)
        FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS defaults
        WHERE defaults.ENTITY_ID = :entity_id
          AND defaults.REPRESENTATION_ID = :previous_representation_id
          AND defaults.IS_DEFAULT = TRUE
          AND defaults.STATUS = 'ACTIVE'
          AND EXISTS (
            SELECT 1
            FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS explicit
            WHERE explicit.ATTRIBUTE_TYPE = defaults.ATTRIBUTE_TYPE
              AND explicit.ATTRIBUTE_ID = defaults.ATTRIBUTE_ID
              AND explicit.REPRESENTATION_ID = defaults.REPRESENTATION_ID
              AND explicit.IS_DEFAULT = FALSE
              AND explicit.STATUS = 'ACTIVE'
          )
    ]], {entity_id = entity_id,
        previous_representation_id = previous_representation_id})

    if tonumber(stale_default_count or 0) > 0 then
        -- Repair catalog states produced by the pre-fix promotion path. Move a
        -- collided compatibility default back to the requested representation
        -- when that representation has no binding for the attribute. If it
        -- already has an explicit binding, the stale default is redundant.
        query([[
            UPDATE SYS_SEMANTIC.ATTRIBUTE_BINDINGS
            SET REPRESENTATION_ID = :representation_id,
                UPDATED_AT = CURRENT_TIMESTAMP, UPDATED_BY = CURRENT_USER
            WHERE ATTRIBUTE_BINDING_ID IN (
              SELECT defaults.ATTRIBUTE_BINDING_ID
              FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS defaults
              WHERE defaults.ENTITY_ID = :entity_id
                AND defaults.REPRESENTATION_ID = :previous_representation_id
                AND defaults.IS_DEFAULT = TRUE
                AND defaults.STATUS = 'ACTIVE'
                AND EXISTS (
                  SELECT 1 FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS explicit
                  WHERE explicit.ATTRIBUTE_TYPE = defaults.ATTRIBUTE_TYPE
                    AND explicit.ATTRIBUTE_ID = defaults.ATTRIBUTE_ID
                    AND explicit.REPRESENTATION_ID = defaults.REPRESENTATION_ID
                    AND explicit.IS_DEFAULT = FALSE
                    AND explicit.STATUS = 'ACTIVE'
                )
                AND NOT EXISTS (
                  SELECT 1 FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS target
                  WHERE target.ATTRIBUTE_TYPE = defaults.ATTRIBUTE_TYPE
                    AND target.ATTRIBUTE_ID = defaults.ATTRIBUTE_ID
                    AND target.REPRESENTATION_ID = :representation_id
                    AND target.STATUS = 'ACTIVE'
                )
            )
        ]], {entity_id = entity_id, representation_id = representation_id,
            previous_representation_id = previous_representation_id})
        query([[
            DELETE FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS
            WHERE ATTRIBUTE_BINDING_ID IN (
              SELECT defaults.ATTRIBUTE_BINDING_ID
              FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS defaults
              WHERE defaults.ENTITY_ID = :entity_id
                AND defaults.REPRESENTATION_ID = :previous_representation_id
                AND defaults.IS_DEFAULT = TRUE
                AND defaults.STATUS = 'ACTIVE'
                AND EXISTS (
                  SELECT 1 FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS explicit
                  WHERE explicit.ATTRIBUTE_TYPE = defaults.ATTRIBUTE_TYPE
                    AND explicit.ATTRIBUTE_ID = defaults.ATTRIBUTE_ID
                    AND explicit.REPRESENTATION_ID = defaults.REPRESENTATION_ID
                    AND explicit.IS_DEFAULT = FALSE
                    AND explicit.STATUS = 'ACTIVE'
                )
            )
        ]], {entity_id = entity_id,
            previous_representation_id = previous_representation_id})
        local repair_validation = query(
            "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
            {model_name = model_name})
        for _, validation_row in ipairs(repair_validation or {}) do
        if tostring(row_value(validation_row, "SEVERITY", 1)) == "ERROR"
            or tostring(row_value(validation_row, "SEVERITY", 1)) == "PRECONDITION" then
                error("SEMANTIC_ADMIN_048: stale default bindings were repaired, but model validation still fails: "
                    .. tostring(row_value(validation_row, "RULE_CODE", 4) or "SEMANTIC_MODEL_ERROR")
                    .. " " .. tostring(row_value(validation_row, "MESSAGE", 5) or "validation failed"))
            end
        end
    else
        local validation_rows = query([[
            SELECT VALIDATION_RUN_ID
            FROM SYS_SEMANTIC.VALIDATION_RUNS
            WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
              AND (STATUS IN ('OK', 'WARNING')
                   OR STATUS = 'STALE' AND :allow_stale_recovery = TRUE)
              AND ERROR_COUNT = 0
            ORDER BY VALIDATION_RUN_ID DESC LIMIT 1
        ]], {model_id = model_id, version_id = version_id,
            allow_stale_recovery = recovery_from_invalid_primary})
        if validation_rows == nil or #validation_rows == 0 then
            error("SEMANTIC_ADMIN_048: representations must have a clean VALIDATE_MODEL run before promotion")
        end
    end
    query([[
        UPDATE SYS_SEMANTIC.ENTITY_REPRESENTATIONS
        SET REPRESENTATION_ROLE = 'ALTERNATE',
            UPDATED_AT = CURRENT_TIMESTAMP, UPDATED_BY = CURRENT_USER
        WHERE ENTITY_ID = :entity_id
          AND REPRESENTATION_ROLE = 'PRIMARY'
          AND STATUS = 'ACTIVE'
    ]], {entity_id = entity_id})
    query([[
        UPDATE SYS_SEMANTIC.ENTITY_REPRESENTATIONS
        SET REPRESENTATION_ROLE = 'PRIMARY',
            UPDATED_AT = CURRENT_TIMESTAMP, UPDATED_BY = CURRENT_USER
        WHERE REPRESENTATION_ID = :representation_id
    ]], {representation_id = representation_id})
    query([[
        UPDATE SYS_SEMANTIC.ENTITIES
        SET SOURCE_SCHEMA = :source_schema, SOURCE_OBJECT = :source_object,
            SOURCE_ALIAS = :source_alias
        WHERE ENTITY_ID = :entity_id
    ]], {entity_id = entity_id, source_schema = source_schema,
        source_object = source_object, source_alias = source_alias})
    query([[
        UPDATE SYS_SEMANTIC.ATTRIBUTE_BINDINGS
        SET REPRESENTATION_ID = :representation_id,
            UPDATED_AT = CURRENT_TIMESTAMP, UPDATED_BY = CURRENT_USER
        WHERE ATTRIBUTE_BINDING_ID IN (
          SELECT defaults.ATTRIBUTE_BINDING_ID
          FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS defaults
          WHERE defaults.ENTITY_ID = :entity_id
            AND defaults.REPRESENTATION_ID = :previous_representation_id
            AND defaults.IS_DEFAULT = TRUE
            AND defaults.STATUS = 'ACTIVE'
            AND NOT EXISTS (
              SELECT 1
              FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS explicit
              WHERE explicit.ATTRIBUTE_TYPE = defaults.ATTRIBUTE_TYPE
                AND explicit.ATTRIBUTE_ID = defaults.ATTRIBUTE_ID
                AND explicit.REPRESENTATION_ID = :representation_id
                AND explicit.IS_DEFAULT = FALSE
                AND explicit.STATUS = 'ACTIVE'
            )
          )
    ]], {entity_id = entity_id, representation_id = representation_id,
        previous_representation_id = previous_representation_id})
    query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
        {version_id = version_id})
    query([[
        UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE'
        WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
          AND STATUS IN ('OK', 'WARNING')
    ]], {model_id = model_id, version_id = version_id})
end

-- Promotion is accepted on a valid model and the numbers stay correct, so
-- neither of these is an error. Both leave a catalog state whose next reader
-- draws the wrong conclusion, and nothing else reports them: the role flip is
-- silent, and VALIDATE_MODEL sees a legal model afterwards.
--
--   * A representation whose coverage is a closed window or a predicate is now
--     the entity's PRIMARY, so the representation that answers for uncovered
--     rows is an ALTERNATE. Under F3 that is a deliberate shape for a rebuild
--     and a mistake the rest of the time, and only the caller knows which.
--   * REPRESENTATION_NAME is free text and 'primary' is the conventional name
--     for the F0 compatibility row. Promoting anything else leaves a
--     representation *named* primary holding role ALTERNATE, which reads as a
--     catalog inconsistency to everyone who meets it later. The advisory names
--     RENAME_ENTITY_REPRESENTATION, which exists because this warning needed it:
--     for three evaluations it told the reader to rename and the product had no
--     rename, so the one state it reports was the one state nobody could leave.
--
-- Both are advisory, and they say so by arriving in the WARNINGS column of the
-- result row rather than as a raised error. That is the only thing that marks
-- them advisory: the codes are ordinary SEMANTIC_ADMIN_NNN, because severity is
-- carried by the channel here exactly as VALIDATE_MODEL carries it in its
-- SEVERITY column. They were briefly SEMANTIC_ADMIN_W060/W061 -- a 'W' prefix
-- invented for advisory codes -- which put two numbering conventions in one
-- namespace to express what the column already said. 060 and 061 were taken by
-- refusals, hence 220.
local warnings = {}
if changed then
    local valid_from = row_value(row, "VALID_FROM", 10)
    local valid_to = row_value(row, "VALID_TO", 11)
    local coverage_predicate = row_value(row, "COVERAGE_PREDICATE", 12)
    -- VALID_TO is the whole test. A representation with only a VALID_FROM is
    -- still the open-ended one -- it is the partition new rows land in -- and
    -- warning on it would fire on the ordinary act of promoting the hot
    -- partition back, training the reader to ignore the column.
    if not missing(valid_to) then
        local window = {"VALID_TO " .. tostring(valid_to)}
        if not missing(valid_from) then
            window[#window + 1] = "VALID_FROM " .. tostring(valid_from)
        end
        if not missing(coverage_predicate) then
            window[#window + 1] = "COVERAGE_PREDICATE "
                .. tostring(coverage_predicate)
        end
        warnings[#warnings + 1] = "SEMANTIC_ADMIN_220: representation '"
            .. representation_name .. "' is now PRIMARY for entity '"
            .. entity_name .. "' but its coverage is bounded ("
            .. table.concat(window, ", ")
            .. "), so rows outside that window are answered by an ALTERNATE."
            .. " Promote the open-ended representation instead, or widen this"
            .. " one's coverage, unless a bounded primary is intended."
    end
    if previous_name ~= null
        and string.upper(tostring(previous_name)) == "PRIMARY"
        and string.upper(representation_name) ~= "PRIMARY" then
        warnings[#warnings + 1] = "SEMANTIC_ADMIN_221: representation named '"
            .. tostring(previous_name) .. "' now holds role ALTERNATE, because '"
            .. representation_name .. "' took role PRIMARY. The name and the role"
            .. " disagree from here on. Rename it after its source instead --"
            .. " EXECUTE SCRIPT SEMANTIC_ADMIN.RENAME_ENTITY_REPRESENTATION('"
            .. model_name .. "', '" .. entity_name .. "', '"
            .. tostring(previous_name) .. "', '<new_name>') -- which is a pure"
            .. " relabel: every reference to a representation is by"
            .. " REPRESENTATION_ID, so nothing else moves."
    end
end
local warning_text = null
if #warnings > 0 then
    warning_text = table.concat(warnings, " ")
end

exit({{representation_id, model_name, entity_name, previous_name,
    representation_name, source_schema, source_object, changed, warning_text}}, [[
  REPRESENTATION_ID DECIMAL(18,0),
  MODEL_NAME VARCHAR(256),
  ENTITY_NAME VARCHAR(256),
  PREVIOUS_PRIMARY VARCHAR(256),
  PRIMARY_REPRESENTATION VARCHAR(256),
  SOURCE_SCHEMA VARCHAR(256),
  SOURCE_OBJECT VARCHAR(256),
  CHANGED BOOLEAN,
  WARNINGS VARCHAR(2000000)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.RENAME_ENTITY_REPRESENTATION(
  MODEL_NAME,
  ENTITY_NAME,
  REPRESENTATION_NAME,
  NEW_REPRESENTATION_NAME
)
RETURNS TABLE AS
-- The rename SEMANTIC_ADMIN_221 has been telling callers to perform.
--
-- ADD_ENTITY mints the name 'primary' for an entity's first representation and
-- REPRESENTATION_ROLE is a separate column, so the first promotion anyone
-- performs leaves a row *named* primary holding role ALTERNATE. That is not an
-- error and the numbers stay right, so SET_PRIMARY_REPRESENTATION reports it as
-- an advisory -- which said "rename either representation to keep
-- ENTITY_REPRESENTATIONS readable", and no rename existed. A warning whose
-- remedy the product does not offer is worse than no warning: it tells the
-- reader the state is fixable and then strands them in it permanently.
--
-- This is a pure relabel, and the catalog is what makes that true.
-- REPRESENTATION_NAME occurs in exactly one column of one table, and every
-- reference to a representation -- ATTRIBUTE_BINDINGS, IDENTITY_BINDINGS,
-- REPRESENTATION_AUTHORITIES -- is by REPRESENTATION_ID. Nothing points at the
-- name, no expression embeds it, and no role, coverage, authority or binding
-- moves. So this script needs none of the candidate-and-rollback machinery its
-- neighbours carry, and it is short for a reason rather than by omission.
--
-- It clears the compile cache because cached PLAN_JSON records the old label in
-- its provenance. It deliberately does *not* mark VALIDATION_RUNS stale: a
-- relabel cannot change a verdict, and marking stale would drop a published
-- model to NEEDS_VALIDATION over a cosmetic fix. Validation results keep the
-- old name until the next run, which is the same by-design staleness 001
-- documents for VALIDATION_RESULTS.OBJECT_NAME -- results are recorded by name
-- so an issue survives its object being dropped.
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end
local function trim(value) return tostring(value):match("^%s*(.-)%s*$") end
local function normalize_name(value, label)
    if missing(value) then error("SEMANTIC_ADMIN_001: " .. label .. " is required") end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local function scalar(sql_text, params)
    local scalar_rows = query(sql_text, params or {})
    if scalar_rows == nil or #scalar_rows == 0 then return nil end
    return scalar_rows[1][1]
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local entity_name = normalize_name(ENTITY_NAME, "ENTITY_NAME")
local representation_name = normalize_name(REPRESENTATION_NAME, "REPRESENTATION_NAME")
local new_name = normalize_name(NEW_REPRESENTATION_NAME, "NEW_REPRESENTATION_NAME")

local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, e.ENTITY_ID, er.REPRESENTATION_ID,
           er.REPRESENTATION_NAME, er.REPRESENTATION_ROLE
    FROM SYS_SEMANTIC.MODELS m
    JOIN SYS_SEMANTIC.ENTITIES e
      ON e.MODEL_ID = m.MODEL_ID
     AND e.VERSION_ID = m.ACTIVE_VERSION_ID
     AND UPPER(e.ENTITY_NAME) = UPPER(:entity_name)
     AND e.STATUS = 'ACTIVE'
    JOIN SYS_SEMANTIC.ENTITY_REPRESENTATIONS er
      ON er.ENTITY_ID = e.ENTITY_ID
     AND er.MODEL_ID = e.MODEL_ID
     AND er.VERSION_ID = e.VERSION_ID
     AND UPPER(er.REPRESENTATION_NAME) = UPPER(:representation_name)
     AND er.STATUS = 'ACTIVE'
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name, entity_name = entity_name,
    representation_name = representation_name})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_045: active representation not found: " .. representation_name)
end
local model_id = row_value(rows[1], "MODEL_ID", 1)
local version_id = row_value(rows[1], "ACTIVE_VERSION_ID", 2)
local entity_id = row_value(rows[1], "ENTITY_ID", 3)
local representation_id = row_value(rows[1], "REPRESENTATION_ID", 4)
local previous_name = tostring(row_value(rows[1], "REPRESENTATION_NAME", 5))
local representation_role = tostring(row_value(rows[1], "REPRESENTATION_ROLE", 6))

local result_columns = [[
  REPRESENTATION_ID DECIMAL(18,0),
  MODEL_NAME VARCHAR(256),
  ENTITY_NAME VARCHAR(256),
  PREVIOUS_NAME VARCHAR(256),
  REPRESENTATION_NAME VARCHAR(256),
  REPRESENTATION_ROLE VARCHAR(32),
  CHANGED BOOLEAN
]]

-- Renaming a representation to the name it already carries is a no-op, not a
-- collision with itself. Re-running an authoring script has to be safe here for
-- the same reason it is everywhere else in this API.
if string.upper(previous_name) == string.upper(new_name) then
    exit({{representation_id, model_name, entity_name, previous_name,
        previous_name, representation_role, false}}, result_columns)
end

local taken = scalar([[
    SELECT COUNT(*)
    FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS
    WHERE ENTITY_ID = :entity_id
      AND UPPER(REPRESENTATION_NAME) = UPPER(:new_name)
      AND STATUS = 'ACTIVE'
]], {entity_id = entity_id, new_name = new_name})
if tonumber(taken or 0) > 0 then
    error("SEMANTIC_ADMIN_046: duplicate representation name: " .. new_name)
end

query([[
    UPDATE SYS_SEMANTIC.ENTITY_REPRESENTATIONS
    SET REPRESENTATION_NAME = :new_name,
        UPDATED_AT = CURRENT_TIMESTAMP,
        UPDATED_BY = CURRENT_USER
    WHERE REPRESENTATION_ID = :representation_id
]], {new_name = new_name, representation_id = representation_id})
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = version_id})

exit({{representation_id, model_name, entity_name, previous_name, new_name,
    representation_role, true}}, result_columns)
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.REMOVE_ENTITY_REPRESENTATION(
  MODEL_NAME,
  ENTITY_NAME,
  REPRESENTATION_NAME
)
RETURNS TABLE AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end
local function trim(value) return tostring(value):match("^%s*(.-)%s*$") end
local function normalize_name(value, label)
    if missing(value) then error("SEMANTIC_ADMIN_001: " .. label .. " is required") end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local function scalar(sql_text, params)
    local scalar_rows = query(sql_text, params or {})
    if scalar_rows == nil or #scalar_rows == 0 then return nil end
    return scalar_rows[1][1]
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local entity_name = normalize_name(ENTITY_NAME, "ENTITY_NAME")
local representation_name = normalize_name(REPRESENTATION_NAME, "REPRESENTATION_NAME")
local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, er.REPRESENTATION_ID,
           er.REPRESENTATION_ROLE, m.STATUS
    FROM SYS_SEMANTIC.MODELS m
    JOIN SYS_SEMANTIC.ENTITIES e
      ON e.MODEL_ID = m.MODEL_ID
     AND e.VERSION_ID = m.ACTIVE_VERSION_ID
     AND UPPER(e.ENTITY_NAME) = UPPER(:entity_name)
    JOIN SYS_SEMANTIC.ENTITY_REPRESENTATIONS er
      ON er.ENTITY_ID = e.ENTITY_ID
     AND UPPER(er.REPRESENTATION_NAME) = UPPER(:representation_name)
     AND er.STATUS = 'ACTIVE'
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name, entity_name = entity_name,
    representation_name = representation_name})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_045: active representation not found: " .. representation_name)
end
local model_id = row_value(rows[1], "MODEL_ID", 1)
local version_id = row_value(rows[1], "ACTIVE_VERSION_ID", 2)
local representation_id = row_value(rows[1], "REPRESENTATION_ID", 3)
local model_status = row_value(rows[1], "STATUS", 5)
if tostring(row_value(rows[1], "REPRESENTATION_ROLE", 4)) == "PRIMARY" then
    error("SEMANTIC_ADMIN_047: cannot remove the PRIMARY representation; promote another representation first")
end
local binding_rows = query([[
    SELECT ATTRIBUTE_BINDING_ID FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS
    WHERE REPRESENTATION_ID = :representation_id AND STATUS = 'ACTIVE'
]], {representation_id = representation_id})
for _, binding_row in ipairs(binding_rows or {}) do
    query([[
        UPDATE SYS_SEMANTIC.ATTRIBUTE_BINDINGS SET STATUS = 'INACTIVE'
        WHERE ATTRIBUTE_BINDING_ID = :binding_id
    ]], {binding_id = row_value(binding_row, "ATTRIBUTE_BINDING_ID", 1)})
end
local identity_binding_count = scalar([[
    SELECT COUNT(*) FROM SYS_SEMANTIC.IDENTITY_BINDINGS
    WHERE REPRESENTATION_ID = :representation_id AND STATUS = 'ACTIVE'
]], {representation_id = representation_id})
if tonumber(identity_binding_count or 0) > 0 then
    error("SEMANTIC_ADMIN_057: cannot remove a representation with active identity bindings; remove mapping relations and identity bindings first")
end
local survivor_rows = query([[
    SELECT REPRESENTATION_ID, COVERAGE_PREDICATE, VALID_FROM, VALID_TO
    FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS
    WHERE ENTITY_ID = (
      SELECT ENTITY_ID FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS
      WHERE REPRESENTATION_ID = :representation_id
    )
      AND REPRESENTATION_ID <> :representation_id
      AND STATUS = 'ACTIVE'
    ORDER BY REPRESENTATION_ID
]], {representation_id = representation_id})
local survivor = nil
if survivor_rows ~= nil and #survivor_rows == 1 then
    survivor = {
        id = row_value(survivor_rows[1], "REPRESENTATION_ID", 1),
        predicate = row_value(survivor_rows[1], "COVERAGE_PREDICATE", 2) or null,
        valid_from = row_value(survivor_rows[1], "VALID_FROM", 3) or null,
        valid_to = row_value(survivor_rows[1], "VALID_TO", 4) or null,
    }
end
query("UPDATE SYS_SEMANTIC.ENTITY_REPRESENTATIONS SET STATUS = 'INACTIVE' WHERE REPRESENTATION_ID = :representation_id",
    {representation_id = representation_id})
if survivor ~= nil then
    query([[
        UPDATE SYS_SEMANTIC.ENTITY_REPRESENTATIONS
        SET COVERAGE_PREDICATE = NULL, VALID_FROM = NULL, VALID_TO = NULL,
            UPDATED_AT = CURRENT_TIMESTAMP, UPDATED_BY = CURRENT_USER
        WHERE REPRESENTATION_ID = :representation_id
    ]], {representation_id = survivor.id})
end
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = version_id})
query([[
    UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE'
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND STATUS IN ('OK', 'WARNING')
]], {model_id = model_id, version_id = version_id})

if tostring(model_status) == "PUBLISHED" then
    local candidate_validation = query(
        "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
        {model_name = model_name})
    for _, validation_row in ipairs(candidate_validation or {}) do
        if tostring(row_value(validation_row, "SEVERITY", 1)) == "ERROR"
            or tostring(row_value(validation_row, "SEVERITY", 1)) == "PRECONDITION" then
            local rule_code = row_value(validation_row, "RULE_CODE", 4)
                or "SEMANTIC_MODEL_ERROR"
            local message = row_value(validation_row, "MESSAGE", 5)
                or "model validation failed"
            query("UPDATE SYS_SEMANTIC.ENTITY_REPRESENTATIONS SET STATUS = 'ACTIVE' WHERE REPRESENTATION_ID = :representation_id",
                {representation_id = representation_id})
            for _, binding_row in ipairs(binding_rows or {}) do
                query([[
                    UPDATE SYS_SEMANTIC.ATTRIBUTE_BINDINGS SET STATUS = 'ACTIVE'
                    WHERE ATTRIBUTE_BINDING_ID = :binding_id
                ]], {binding_id = row_value(binding_row, "ATTRIBUTE_BINDING_ID", 1)})
            end
            if survivor ~= nil then
                query([[
                    UPDATE SYS_SEMANTIC.ENTITY_REPRESENTATIONS
                    SET COVERAGE_PREDICATE = :coverage_predicate,
                        VALID_FROM = :valid_from, VALID_TO = :valid_to,
                        UPDATED_AT = CURRENT_TIMESTAMP, UPDATED_BY = CURRENT_USER
                    WHERE REPRESENTATION_ID = :representation_id
                ]], {representation_id = survivor.id,
                      coverage_predicate = survivor.predicate,
                      valid_from = survivor.valid_from,
                      valid_to = survivor.valid_to})
            end
            query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
                {model_name = model_name})
            error("SEMANTIC_ADMIN_094: published representation removal rejected and restored; "
                .. "candidate introduced validation error: "
                .. tostring(rule_code) .. " " .. tostring(message))
        end
    end
end
query("DELETE FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS WHERE REPRESENTATION_ID = :representation_id",
    {representation_id = representation_id})
query("DELETE FROM SYS_SEMANTIC.REPRESENTATION_AUTHORITIES WHERE REPRESENTATION_ID = :representation_id",
    {representation_id = representation_id})
query("DELETE FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS WHERE REPRESENTATION_ID = :representation_id",
    {representation_id = representation_id})

exit({{representation_id, model_name, entity_name, representation_name, "REMOVED"}}, [[
  REPRESENTATION_ID DECIMAL(18,0),
  MODEL_NAME VARCHAR(256),
  ENTITY_NAME VARCHAR(256),
  REPRESENTATION_NAME VARCHAR(256),
  STATUS VARCHAR(32)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_SEMANTIC_OBJECT(
  MODEL_NAME,
  OBJECT_NAME,
  ROOT_ENTITY_NAME,
  DESCRIPTION
) AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end

local function optional_text(value)
    if missing(value) then
        return null
    end
    return tostring(value)
end

local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end

local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then
        return nil
    end
    return rows[1][1]
end

local function model_row(model_name)
    local rows = query([[
        SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID AS VERSION_ID
        FROM SYS_SEMANTIC.MODELS m
        WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
    ]], {model_name = model_name})
    if rows == nil or #rows == 0 then
        error("SEMANTIC_ADMIN_011: model not found: " .. model_name)
    end
    return {
        model_id = row_value(rows[1], "MODEL_ID", 1),
        version_id = row_value(rows[1], "VERSION_ID", 2)
    }
end

local function entity_id(model, entity_name)
    local id = scalar([[
        SELECT ENTITY_ID
        FROM SYS_SEMANTIC.ENTITIES
        WHERE MODEL_ID = :model_id
          AND VERSION_ID = :version_id
          AND UPPER(ENTITY_NAME) = UPPER(:entity_name)
    ]], {model_id = model.model_id, version_id = model.version_id, entity_name = entity_name})
    if id == nil then
        error("SEMANTIC_ADMIN_014: entity not found: " .. entity_name)
    end
    return id
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local object_name = normalize_name(OBJECT_NAME, "OBJECT_NAME")
local root_entity_name = normalize_name(ROOT_ENTITY_NAME, "ROOT_ENTITY_NAME")
local model = model_row(model_name)
local root_entity_id = entity_id(model, root_entity_name)

local duplicate = scalar([[
    SELECT COUNT(*)
    FROM SYS_SEMANTIC.SEMANTIC_OBJECTS
    WHERE MODEL_ID = :model_id
      AND VERSION_ID = :version_id
      AND UPPER(OBJECT_NAME) = UPPER(:object_name)
]], {model_id = model.model_id, version_id = model.version_id, object_name = object_name})
if tonumber(duplicate or 0) > 0 then
    error("SEMANTIC_ADMIN_015: duplicate semantic object: " .. object_name)
end

query([[
    INSERT INTO SYS_SEMANTIC.SEMANTIC_OBJECTS (
      MODEL_ID, VERSION_ID, OBJECT_NAME, ROOT_ENTITY_ID, DESCRIPTION, STATUS
    ) VALUES (
      :model_id, :version_id, :object_name, :root_entity_id, :description, 'ACTIVE'
    )
]], {
    model_id = model.model_id,
    version_id = model.version_id,
    object_name = object_name,
    root_entity_id = root_entity_id,
    description = optional_text(DESCRIPTION)
})
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.CREATE_SEMANTIC_OBJECT(
  MODEL_NAME,
  OBJECT_NAME,
  ROOT_ENTITY_NAME,
  DESCRIPTION
) AS
query([[
    EXECUTE SCRIPT SEMANTIC_ADMIN.ADD_SEMANTIC_OBJECT(
      :model_name, :object_name, :root_entity_name, :description
    )
]], {
    model_name = MODEL_NAME,
    object_name = OBJECT_NAME,
    root_entity_name = ROOT_ENTITY_NAME,
    description = DESCRIPTION
})
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_RELATIONSHIP(
  MODEL_NAME,
  RELATIONSHIP_NAME,
  FROM_ENTITY_NAME,
  TO_ENTITY_NAME,
  JOIN_CONDITION,
  CARDINALITY,
  JOIN_TYPE,
  FANOUT_POLICY
) AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end

local function normalize_choice(value, label, allowed)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local choice = string.upper(trim(value))
    for _, allowed_value in ipairs(allowed) do
        if choice == allowed_value then
            return choice
        end
    end
    error("SEMANTIC_ADMIN_003: invalid " .. label .. ": " .. tostring(value))
end

local function optional_text(value)
    if missing(value) then
        return null
    end
    return tostring(value)
end

local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end

local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then
        return nil
    end
    return rows[1][1]
end

local function model_row(model_name)
    local rows = query([[
        SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID AS VERSION_ID, m.STATUS
        FROM SYS_SEMANTIC.MODELS m
        WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
    ]], {model_name = model_name})
    if rows == nil or #rows == 0 then
        error("SEMANTIC_ADMIN_011: model not found: " .. model_name)
    end
    return {
        model_id = row_value(rows[1], "MODEL_ID", 1),
        version_id = row_value(rows[1], "VERSION_ID", 2),
        status = row_value(rows[1], "STATUS", 3)
    }
end

local function entity_id(model, entity_name)
    local id = scalar([[
        SELECT ENTITY_ID
        FROM SYS_SEMANTIC.ENTITIES
        WHERE MODEL_ID = :model_id
          AND VERSION_ID = :version_id
          AND UPPER(ENTITY_NAME) = UPPER(:entity_name)
    ]], {model_id = model.model_id, version_id = model.version_id, entity_name = entity_name})
    if id == nil then
        error("SEMANTIC_ADMIN_014: entity not found: " .. entity_name)
    end
    return id
end

if missing(JOIN_CONDITION) then
    error("SEMANTIC_ADMIN_001: JOIN_CONDITION is required")
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local relationship_name = normalize_name(RELATIONSHIP_NAME, "RELATIONSHIP_NAME")
local from_entity_name = normalize_name(FROM_ENTITY_NAME, "FROM_ENTITY_NAME")
local to_entity_name = normalize_name(TO_ENTITY_NAME, "TO_ENTITY_NAME")
local cardinality = normalize_choice(CARDINALITY, "CARDINALITY", {"ONE_TO_ONE", "ONE_TO_MANY", "MANY_TO_ONE", "MANY_TO_MANY"})
local join_type = "LEFT"
if not missing(JOIN_TYPE) then
    join_type = normalize_choice(JOIN_TYPE, "JOIN_TYPE", {"INNER", "LEFT"})
end

-- FANOUT_POLICY is a closed set, not free text. No value authorizes traversal
-- of a fanning edge; the policy records what the modeler intends a planner to
-- do if the technique is ever proven. Unrecognized values used to be stored
-- verbatim, which read as a safety override that did not exist. See
-- docs/validation-rules.md#fanout-policy.
local fanout_policy = null
if not missing(FANOUT_POLICY) then
    fanout_policy = normalize_choice(FANOUT_POLICY, "FANOUT_POLICY",
        {"ALLOCATE", "DEDUPLICATE", "REFERENCE_ONLY"})
end

local model = model_row(model_name)
local from_entity_id = entity_id(model, from_entity_name)
local to_entity_id = entity_id(model, to_entity_name)

local duplicate = scalar([[
    SELECT COUNT(*)
    FROM SYS_SEMANTIC.RELATIONSHIPS
    WHERE MODEL_ID = :model_id
      AND VERSION_ID = :version_id
      AND UPPER(RELATIONSHIP_NAME) = UPPER(:relationship_name)
      AND STATUS = 'ACTIVE'
]], {model_id = model.model_id, version_id = model.version_id, relationship_name = relationship_name})
if tonumber(duplicate or 0) > 0 then
    error("SEMANTIC_ADMIN_016: duplicate relationship: " .. relationship_name)
end

query([[
    INSERT INTO SYS_SEMANTIC.RELATIONSHIPS (
      MODEL_ID, VERSION_ID, RELATIONSHIP_NAME, FROM_ENTITY_ID, TO_ENTITY_ID,
      JOIN_CONDITION, RELATIONSHIP_CARDINALITY, JOIN_TYPE, IS_REQUIRED, FANOUT_POLICY,
      PATH_PRIORITY, STATUS
    ) VALUES (
      :model_id, :version_id, :relationship_name, :from_entity_id, :to_entity_id,
      :join_condition, :cardinality, :join_type, FALSE, :fanout_policy,
      100, 'ACTIVE'
    )
]], {
    model_id = model.model_id,
    version_id = model.version_id,
    relationship_name = relationship_name,
    from_entity_id = from_entity_id,
    to_entity_id = to_entity_id,
    join_condition = tostring(JOIN_CONDITION),
    cardinality = cardinality,
    join_type = join_type,
    fanout_policy = fanout_policy
})
local relationship_id = scalar([[
    SELECT RELATIONSHIP_ID FROM SYS_SEMANTIC.RELATIONSHIPS
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND UPPER(RELATIONSHIP_NAME) = UPPER(:relationship_name)
      AND STATUS = 'ACTIVE'
]], {model_id = model.model_id, version_id = model.version_id,
      relationship_name = relationship_name})
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = model.version_id})
query("UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE' WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id AND STATUS IN ('OK', 'WARNING')",
    {model_id = model.model_id, version_id = model.version_id})
if tostring(model.status) == "PUBLISHED" then
    local candidate_validation = query(
        "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
        {model_name = model_name})
    for _, validation_row in ipairs(candidate_validation or {}) do
        if tostring(row_value(validation_row, "SEVERITY", 1)) == "ERROR"
            or tostring(row_value(validation_row, "SEVERITY", 1)) == "PRECONDITION" then
            local rule_code = row_value(validation_row, "RULE_CODE", 4)
                or "SEMANTIC_MODEL_ERROR"
            local message = row_value(validation_row, "MESSAGE", 5)
                or "model validation failed"
            query("DELETE FROM SYS_SEMANTIC.RELATIONSHIPS WHERE RELATIONSHIP_ID = :relationship_id",
                {relationship_id = relationship_id})
            query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
                {model_name = model_name})
            error("SEMANTIC_ADMIN_094: published relationship change rejected and restored; "
                .. "candidate introduced validation error: "
                .. tostring(rule_code) .. " " .. tostring(message))
        end
    end
end
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_RELATIONSHIP_KEY_MAPPING(
  MODEL_NAME,
  RELATIONSHIP_NAME,
  FROM_COLUMN_NAME,
  FROM_EXPRESSION,
  TO_COLUMN_NAME,
  TO_EXPRESSION,
  ORDINAL_POSITION
) AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

local function optional_text(value)
    if missing(value) then
        return null
    end
    return trim(value)
end

local function validate_physical_column(value, label)
    if value == null then return end
    if value == "" or #value > 256 or string.find(value, "%c") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. tostring(value))
    end
end

local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end

local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then
        return nil
    end
    return row_value(rows[1], "VALUE", 1) or rows[1][1]
end

if missing(MODEL_NAME) or missing(RELATIONSHIP_NAME) then
    error("SEMANTIC_ADMIN_001: MODEL_NAME and RELATIONSHIP_NAME are required")
end
local ordinal = tonumber(ORDINAL_POSITION)
if ordinal == nil or ordinal < 1 or ordinal % 1 ~= 0 then
    error("SEMANTIC_ADMIN_003: ORDINAL_POSITION must be a positive integer")
end
local from_column = optional_text(FROM_COLUMN_NAME)
local from_expression = optional_text(FROM_EXPRESSION)
local to_column = optional_text(TO_COLUMN_NAME)
local to_expression = optional_text(TO_EXPRESSION)
if (from_column == null) == (from_expression == null) then
    error("SEMANTIC_ADMIN_003: exactly one of FROM_COLUMN_NAME and FROM_EXPRESSION is required")
end
if (to_column == null) == (to_expression == null) then
    error("SEMANTIC_ADMIN_003: exactly one of TO_COLUMN_NAME and TO_EXPRESSION is required")
end
if from_expression ~= null or to_expression ~= null then
    error("SEMANTIC_ADMIN_043: expression relationship key mappings are not supported by typed grain proofs; normalize the expression into a source view and map a column")
end
validate_physical_column(from_column, "FROM_COLUMN_NAME")
validate_physical_column(to_column, "TO_COLUMN_NAME")

local relationship_id = scalar([[
    SELECT r.RELATIONSHIP_ID
    FROM SYS_SEMANTIC.RELATIONSHIPS r
    JOIN SYS_SEMANTIC.MODELS m
      ON m.MODEL_ID = r.MODEL_ID
     AND m.ACTIVE_VERSION_ID = r.VERSION_ID
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
      AND UPPER(r.RELATIONSHIP_NAME) = UPPER(:relationship_name)
      AND r.STATUS = 'ACTIVE'
]], {
    model_name = trim(MODEL_NAME),
    relationship_name = trim(RELATIONSHIP_NAME),
})
if relationship_id == nil then
    error("SEMANTIC_ADMIN_016: relationship not found: " .. trim(RELATIONSHIP_NAME))
end

local existing = scalar([[
    SELECT COUNT(*)
    FROM SYS_SEMANTIC.RELATIONSHIP_KEY_MAPPINGS
    WHERE RELATIONSHIP_ID = :relationship_id
      AND ORDINAL_POSITION = :ordinal_position
]], {relationship_id = relationship_id, ordinal_position = ordinal})
if tonumber(existing or 0) > 0 then
    query([[
        UPDATE SYS_SEMANTIC.RELATIONSHIP_KEY_MAPPINGS
        SET FROM_COLUMN_NAME = :from_column_name,
            FROM_EXPRESSION = :from_expression,
            TO_COLUMN_NAME = :to_column_name,
            TO_EXPRESSION = :to_expression
        WHERE RELATIONSHIP_ID = :relationship_id
          AND ORDINAL_POSITION = :ordinal_position
    ]], {
        relationship_id = relationship_id,
        ordinal_position = ordinal,
        from_column_name = from_column,
        from_expression = from_expression,
        to_column_name = to_column,
        to_expression = to_expression,
    })
else
    query([[
        INSERT INTO SYS_SEMANTIC.RELATIONSHIP_KEY_MAPPINGS (
          RELATIONSHIP_ID, ORDINAL_POSITION, FROM_COLUMN_NAME, FROM_EXPRESSION,
          TO_COLUMN_NAME, TO_EXPRESSION
        ) VALUES (
          :relationship_id, :ordinal_position, :from_column_name, :from_expression,
          :to_column_name, :to_expression
        )
    ]], {
        relationship_id = relationship_id,
        ordinal_position = ordinal,
        from_column_name = from_column,
        from_expression = from_expression,
        to_column_name = to_column,
        to_expression = to_expression,
    })
end
query([[
    DELETE FROM SYS_SEMANTIC.COMPILE_CACHE
    WHERE MODEL_VERSION_ID = (
        SELECT VERSION_ID FROM SYS_SEMANTIC.RELATIONSHIPS
        WHERE RELATIONSHIP_ID = :relationship_id
    )
]], {relationship_id = relationship_id})
query([[
    UPDATE SYS_SEMANTIC.VALIDATION_RUNS
    SET STATUS = 'STALE'
    WHERE VERSION_ID = (
        SELECT VERSION_ID FROM SYS_SEMANTIC.RELATIONSHIPS
        WHERE RELATIONSHIP_ID = :relationship_id
    )
      AND STATUS IN ('OK', 'WARNING')
]], {relationship_id = relationship_id})
query("EXECUTE SCRIPT SEMANTIC_ADMIN.RECERTIFY_MODEL_IF_PUBLISHED(:model_name)",
    {model_name = trim(MODEL_NAME)})
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.REMOVE_RELATIONSHIP_KEY_MAPPING(
  MODEL_NAME,
  RELATIONSHIP_NAME,
  ORDINAL_POSITION
)
RETURNS TABLE AS
-- NULL arrives as userdata, and userdata is truthy: `value or ""` would render
-- it as an address and defeat the required-parameter check below.
local function trim(value)
    if value == nil or value == null then return "" end
    return tostring(value):match("^%s*(.-)%s*$")
end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local model_name = trim(MODEL_NAME)
local relationship_name = trim(RELATIONSHIP_NAME)
local ordinal = tonumber(ORDINAL_POSITION)
if model_name == "" or relationship_name == "" then
    error("SEMANTIC_ADMIN_001: MODEL_NAME and RELATIONSHIP_NAME are required")
end
if ordinal == nil or ordinal < 1 or ordinal % 1 ~= 0 then
    error("SEMANTIC_ADMIN_003: ORDINAL_POSITION must be a positive integer")
end
local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, m.STATUS, r.RELATIONSHIP_ID,
           rkm.FROM_COLUMN_NAME, rkm.FROM_EXPRESSION,
           rkm.TO_COLUMN_NAME, rkm.TO_EXPRESSION
    FROM SYS_SEMANTIC.MODELS m
    JOIN SYS_SEMANTIC.RELATIONSHIPS r
      ON r.MODEL_ID = m.MODEL_ID AND r.VERSION_ID = m.ACTIVE_VERSION_ID
     AND UPPER(r.RELATIONSHIP_NAME) = UPPER(:relationship_name)
     AND r.STATUS = 'ACTIVE'
    JOIN SYS_SEMANTIC.RELATIONSHIP_KEY_MAPPINGS rkm
      ON rkm.RELATIONSHIP_ID = r.RELATIONSHIP_ID
     AND rkm.ORDINAL_POSITION = :ordinal
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name, relationship_name = relationship_name,
      ordinal = ordinal})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_065: active relationship key mapping not found: "
        .. relationship_name .. "[" .. tostring(ordinal) .. "]")
end
local model_id = row_value(rows[1], "MODEL_ID", 1)
local version_id = row_value(rows[1], "ACTIVE_VERSION_ID", 2)
local model_status = row_value(rows[1], "STATUS", 3)
local relationship_id = row_value(rows[1], "RELATIONSHIP_ID", 4)
local from_column = row_value(rows[1], "FROM_COLUMN_NAME", 5) or null
local from_expression = row_value(rows[1], "FROM_EXPRESSION", 6) or null
local to_column = row_value(rows[1], "TO_COLUMN_NAME", 7) or null
local to_expression = row_value(rows[1], "TO_EXPRESSION", 8) or null
query([[
    DELETE FROM SYS_SEMANTIC.RELATIONSHIP_KEY_MAPPINGS
    WHERE RELATIONSHIP_ID = :relationship_id AND ORDINAL_POSITION = :ordinal
]], {relationship_id = relationship_id, ordinal = ordinal})
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = version_id})
query("UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE' WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id AND STATUS IN ('OK', 'WARNING')",
    {model_id = model_id, version_id = version_id})
if tostring(model_status) == "PUBLISHED" then
    local candidate_validation = query(
        "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
        {model_name = model_name})
    for _, validation_row in ipairs(candidate_validation or {}) do
        if tostring(row_value(validation_row, "SEVERITY", 1)) == "ERROR"
            or tostring(row_value(validation_row, "SEVERITY", 1)) == "PRECONDITION" then
            local rule_code = row_value(validation_row, "RULE_CODE", 4)
                or "SEMANTIC_MODEL_ERROR"
            local message = row_value(validation_row, "MESSAGE", 5)
                or "model validation failed"
            query([[
                INSERT INTO SYS_SEMANTIC.RELATIONSHIP_KEY_MAPPINGS (
                  RELATIONSHIP_ID, ORDINAL_POSITION, FROM_COLUMN_NAME,
                  FROM_EXPRESSION, TO_COLUMN_NAME, TO_EXPRESSION
                ) VALUES (
                  :relationship_id, :ordinal, :from_column, :from_expression,
                  :to_column, :to_expression
                )
            ]], {relationship_id = relationship_id, ordinal = ordinal,
                  from_column = from_column, from_expression = from_expression,
                  to_column = to_column, to_expression = to_expression})
            query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
                {model_name = model_name})
            error("SEMANTIC_ADMIN_094: published relationship-mapping removal rejected and restored; "
                .. "candidate introduced validation error: "
                .. tostring(rule_code) .. " " .. tostring(message))
        end
    end
end
exit({{model_name, relationship_name, ordinal, "REMOVED"}}, [[
  MODEL_NAME VARCHAR(256), RELATIONSHIP_NAME VARCHAR(256),
  ORDINAL_POSITION DECIMAL(18,0), STATUS VARCHAR(32)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.REMOVE_RELATIONSHIP(
  MODEL_NAME,
  RELATIONSHIP_NAME
)
RETURNS TABLE AS
-- NULL arrives as userdata, and userdata is truthy: `value or ""` would render
-- it as an address and defeat the required-parameter check below.
local function trim(value)
    if value == nil or value == null then return "" end
    return tostring(value):match("^%s*(.-)%s*$")
end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local model_name = trim(MODEL_NAME)
local relationship_name = trim(RELATIONSHIP_NAME)
if model_name == "" or relationship_name == "" then
    error("SEMANTIC_ADMIN_001: MODEL_NAME and RELATIONSHIP_NAME are required")
end
local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, m.STATUS, r.RELATIONSHIP_ID
    FROM SYS_SEMANTIC.MODELS m
    JOIN SYS_SEMANTIC.RELATIONSHIPS r
      ON r.MODEL_ID = m.MODEL_ID AND r.VERSION_ID = m.ACTIVE_VERSION_ID
     AND UPPER(r.RELATIONSHIP_NAME) = UPPER(:relationship_name)
     AND r.STATUS = 'ACTIVE'
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name, relationship_name = relationship_name})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_016: active relationship not found: " .. relationship_name)
end
local model_id = row_value(rows[1], "MODEL_ID", 1)
local version_id = row_value(rows[1], "ACTIVE_VERSION_ID", 2)
local model_status = row_value(rows[1], "STATUS", 3)
local relationship_id = row_value(rows[1], "RELATIONSHIP_ID", 4)
local mapping_rows = query([[
    SELECT COUNT(*) FROM SYS_SEMANTIC.RELATIONSHIP_KEY_MAPPINGS
    WHERE RELATIONSHIP_ID = :relationship_id
]], {relationship_id = relationship_id})
local mapping_count = mapping_rows ~= nil and #mapping_rows > 0
    and tonumber(mapping_rows[1][1]) or 0
if mapping_count > 0 then
    error("SEMANTIC_ADMIN_066: cannot remove a relationship with active key mappings; "
        .. "remove mappings in descending ordinal order first")
end
query([[
    UPDATE SYS_SEMANTIC.RELATIONSHIPS SET STATUS = 'REMOVED'
    WHERE RELATIONSHIP_ID = :relationship_id
]], {relationship_id = relationship_id})
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = version_id})
query("UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE' WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id AND STATUS IN ('OK', 'WARNING')",
    {model_id = model_id, version_id = version_id})
if tostring(model_status) == "PUBLISHED" then
    local candidate_validation = query(
        "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
        {model_name = model_name})
    for _, validation_row in ipairs(candidate_validation or {}) do
        if tostring(row_value(validation_row, "SEVERITY", 1)) == "ERROR"
            or tostring(row_value(validation_row, "SEVERITY", 1)) == "PRECONDITION" then
            local rule_code = row_value(validation_row, "RULE_CODE", 4)
                or "SEMANTIC_MODEL_ERROR"
            local message = row_value(validation_row, "MESSAGE", 5)
                or "model validation failed"
            query("UPDATE SYS_SEMANTIC.RELATIONSHIPS SET STATUS = 'ACTIVE' WHERE RELATIONSHIP_ID = :relationship_id",
                {relationship_id = relationship_id})
            query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
                {model_name = model_name})
            error("SEMANTIC_ADMIN_094: published relationship removal rejected and restored; "
                .. "candidate introduced validation error: "
                .. tostring(rule_code) .. " " .. tostring(message))
        end
    end
end
exit({{relationship_id, model_name, relationship_name, "REMOVED"}}, [[
  RELATIONSHIP_ID DECIMAL(18,0), MODEL_NAME VARCHAR(256),
  RELATIONSHIP_NAME VARCHAR(256), STATUS VARCHAR(32)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.SET_RELATIONSHIP(
  MODEL_NAME,
  RELATIONSHIP_NAME,
  JOIN_CONDITION,
  CARDINALITY,
  JOIN_TYPE,
  FANOUT_POLICY
)
RETURNS TABLE AS
-- Update one relationship in place. Without this, correcting a cardinality or
-- a fanout policy took four steps -- remove the key mappings in descending
-- ordinal order, remove the relationship, add it back, re-add the mappings --
-- which is exactly the operation the fan-out reason codes push modelers
-- toward.
--
-- Any argument left NULL keeps its stored value; FANOUT_POLICY = 'NONE' clears
-- it. Endpoints are deliberately not editable: changing them makes it a
-- different relationship whose key mappings no longer describe it. Remove and
-- re-add for that.
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end
-- NULL arrives as userdata, and userdata is truthy: `value or ""` would render
-- it as an address and defeat the required-parameter check below.
local function trim(value)
    if value == nil or value == null then return "" end
    return tostring(value):match("^%s*(.-)%s*$")
end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local function normalize_choice(value, label, allowed)
    local choice = string.upper(trim(value))
    for _, allowed_value in ipairs(allowed) do
        if choice == allowed_value then
            return choice
        end
    end
    error("SEMANTIC_ADMIN_003: invalid " .. label .. ": " .. tostring(value))
end

local model_name = trim(MODEL_NAME)
local relationship_name = trim(RELATIONSHIP_NAME)
if model_name == "" or relationship_name == "" then
    error("SEMANTIC_ADMIN_001: MODEL_NAME and RELATIONSHIP_NAME are required")
end
if missing(JOIN_CONDITION) and missing(CARDINALITY) and missing(JOIN_TYPE)
    and missing(FANOUT_POLICY) then
    error("SEMANTIC_ADMIN_001: at least one of JOIN_CONDITION, CARDINALITY, "
        .. "JOIN_TYPE, or FANOUT_POLICY is required")
end

local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, r.RELATIONSHIP_ID, r.JOIN_CONDITION,
           r.RELATIONSHIP_CARDINALITY, r.JOIN_TYPE, r.FANOUT_POLICY
    FROM SYS_SEMANTIC.MODELS m
    JOIN SYS_SEMANTIC.RELATIONSHIPS r
      ON r.MODEL_ID = m.MODEL_ID AND r.VERSION_ID = m.ACTIVE_VERSION_ID
     AND UPPER(r.RELATIONSHIP_NAME) = UPPER(:relationship_name)
     AND r.STATUS = 'ACTIVE'
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name, relationship_name = relationship_name})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_016: active relationship not found: " .. relationship_name)
end
local model_id = row_value(rows[1], "MODEL_ID", 1)
local version_id = row_value(rows[1], "ACTIVE_VERSION_ID", 2)
local relationship_id = row_value(rows[1], "RELATIONSHIP_ID", 3)
local previous_join_condition = row_value(rows[1], "JOIN_CONDITION", 4)
local previous_cardinality = row_value(rows[1], "RELATIONSHIP_CARDINALITY", 5)
local previous_join_type = row_value(rows[1], "JOIN_TYPE", 6)
local previous_fanout_policy = row_value(rows[1], "FANOUT_POLICY", 7)
if previous_fanout_policy == null then
    previous_fanout_policy = nil
end

local next_join_condition = previous_join_condition
if not missing(JOIN_CONDITION) then
    next_join_condition = tostring(JOIN_CONDITION)
end
local next_cardinality = previous_cardinality
if not missing(CARDINALITY) then
    next_cardinality = normalize_choice(CARDINALITY, "CARDINALITY",
        {"ONE_TO_ONE", "ONE_TO_MANY", "MANY_TO_ONE", "MANY_TO_MANY"})
end
local next_join_type = previous_join_type
if not missing(JOIN_TYPE) then
    next_join_type = normalize_choice(JOIN_TYPE, "JOIN_TYPE", {"INNER", "LEFT"})
end
-- Same closed set as ADD_RELATIONSHIP, plus NONE to clear. No value authorizes
-- traversal; see docs/validation-rules.md#fanout-policy.
local next_fanout_policy = previous_fanout_policy
if not missing(FANOUT_POLICY) then
    local choice = normalize_choice(FANOUT_POLICY, "FANOUT_POLICY",
        {"ALLOCATE", "DEDUPLICATE", "REFERENCE_ONLY", "NONE"})
    next_fanout_policy = choice ~= "NONE" and choice or nil
end

local function apply_values(join_condition, cardinality, join_type, fanout_policy)
    query([[
        UPDATE SYS_SEMANTIC.RELATIONSHIPS
        SET JOIN_CONDITION = :join_condition,
            RELATIONSHIP_CARDINALITY = :cardinality,
            JOIN_TYPE = :join_type,
            FANOUT_POLICY = :fanout_policy
        WHERE RELATIONSHIP_ID = :relationship_id
    ]], {
        relationship_id = relationship_id,
        join_condition = join_condition,
        cardinality = cardinality,
        join_type = join_type,
        fanout_policy = fanout_policy == nil and null or fanout_policy,
    })
    query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
        {version_id = version_id})
    query([[
        UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE'
        WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
          AND STATUS IN ('OK', 'WARNING')
    ]], {model_id = model_id, version_id = version_id})
    return query("EXECUTE SCRIPT SEMANTIC_ADMIN.RECERTIFY_MODEL_IF_PUBLISHED(:model_name)",
        {model_name = model_name})
end

local recertified = apply_values(next_join_condition, next_cardinality,
    next_join_type, next_fanout_policy)
-- RECERTIFY_MODEL_IF_PUBLISHED validates published models only, and reports
-- NOT_REQUIRED for a draft. A draft is left STALE on purpose: compilation is
-- gated on validation status, so nothing can query the model until the author
-- revalidates it, and reverting would block the repair this script exists for.
local validation_status = "NOT_REQUIRED"
if recertified ~= nil and #recertified > 0 then
    validation_status = tostring(row_value(recertified[1], "VALIDATION_STATUS", 3))
end
if validation_status == "ERROR" or validation_status == "PRECONDITION" then
    local detail_rows = query([[
        SELECT RULE_CODE, MESSAGE
        FROM SYS_SEMANTIC.VALIDATION_RESULTS
        WHERE VALIDATION_RUN_ID = (
            SELECT MAX(VALIDATION_RUN_ID) FROM SYS_SEMANTIC.VALIDATION_RUNS
            WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id)
          AND SEVERITY IN ('ERROR', 'PRECONDITION')
        ORDER BY VALIDATION_RESULT_ID
        LIMIT 1
    ]], {model_id = model_id, version_id = version_id})
    local detail = "model validation failed"
    if detail_rows ~= nil and #detail_rows > 0 then
        detail = tostring(row_value(detail_rows[1], "RULE_CODE", 1)) .. " "
            .. tostring(row_value(detail_rows[1], "MESSAGE", 2))
    end
    apply_values(previous_join_condition, previous_cardinality,
        previous_join_type, previous_fanout_policy)
    error("SEMANTIC_ADMIN_098: published relationship update rejected and restored; "
        .. "candidate introduced validation error: " .. detail)
end

exit({{relationship_id, model_name, relationship_name, next_join_condition,
       next_cardinality, next_join_type,
       next_fanout_policy == nil and null or next_fanout_policy,
       validation_status}}, [[
  RELATIONSHIP_ID DECIMAL(18,0), MODEL_NAME VARCHAR(256),
  RELATIONSHIP_NAME VARCHAR(256), JOIN_CONDITION VARCHAR(2000000),
  RELATIONSHIP_CARDINALITY VARCHAR(64), JOIN_TYPE VARCHAR(32),
  FANOUT_POLICY VARCHAR(64), VALIDATION_STATUS VARCHAR(32)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_DIMENSION(
  MODEL_NAME,
  OBJECT_NAME,
  ENTITY_NAME,
  DIMENSION_NAME,
  EXPRESSION,
  DATA_TYPE,
  DISPLAY_NAME,
  DESCRIPTION,
  FORMAT_HINT,
  IS_CERTIFIED
)
RETURNS TABLE AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end

local function optional_text(value)
    if missing(value) then
        return null
    end
    return tostring(value)
end

local function bool_value(value, default_value)
    if missing(value) then
        return default_value
    end
    local text = string.lower(tostring(value))
    return value == true or text == "true" or text == "1"
end

local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end

local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then
        return nil
    end
    return rows[1][1]
end

local function model_row(model_name)
    local rows = query([[
        SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID AS VERSION_ID
        FROM SYS_SEMANTIC.MODELS m
        WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
    ]], {model_name = model_name})
    if rows == nil or #rows == 0 then
        error("SEMANTIC_ADMIN_011: model not found: " .. model_name)
    end
    return {
        model_id = row_value(rows[1], "MODEL_ID", 1),
        version_id = row_value(rows[1], "VERSION_ID", 2)
    }
end

local function entity_id(model, entity_name)
    local id = scalar([[
        SELECT ENTITY_ID
        FROM SYS_SEMANTIC.ENTITIES
        WHERE MODEL_ID = :model_id
          AND VERSION_ID = :version_id
          AND UPPER(ENTITY_NAME) = UPPER(:entity_name)
    ]], {model_id = model.model_id, version_id = model.version_id, entity_name = entity_name})
    if id == nil then
        error("SEMANTIC_ADMIN_014: entity not found: " .. entity_name)
    end
    return id
end

local function object_id(model, object_name)
    local id = scalar([[
        SELECT OBJECT_ID
        FROM SYS_SEMANTIC.SEMANTIC_OBJECTS
        WHERE MODEL_ID = :model_id
          AND VERSION_ID = :version_id
          AND UPPER(OBJECT_NAME) = UPPER(:object_name)
    ]], {model_id = model.model_id, version_id = model.version_id, object_name = object_name})
    if id == nil then
        error("SEMANTIC_ADMIN_017: semantic object not found: " .. object_name)
    end
    return id
end

local function add_object_column(object_id_value, kind, ref_id, column_name)
    local duplicate = scalar([[
        SELECT COUNT(*)
        FROM SYS_SEMANTIC.OBJECT_COLUMNS
        WHERE OBJECT_ID = :object_id
          AND UPPER(COLUMN_NAME) = UPPER(:column_name)
    ]], {object_id = object_id_value, column_name = column_name})
    if tonumber(duplicate or 0) > 0 then
        error("SEMANTIC_ADMIN_018: duplicate object column: " .. column_name)
    end
    local ordinal = scalar([[
        SELECT COALESCE(MAX(ORDINAL_POSITION), 0) + 1
        FROM SYS_SEMANTIC.OBJECT_COLUMNS
        WHERE OBJECT_ID = :object_id
    ]], {object_id = object_id_value})
    query([[
        INSERT INTO SYS_SEMANTIC.OBJECT_COLUMNS (
          OBJECT_ID, COLUMN_KIND, OBJECT_REF_ID, COLUMN_NAME, ORDINAL_POSITION, IS_VISIBLE
        ) VALUES (
          :object_id, :kind, :ref_id, :column_name, :ordinal, TRUE
        )
    ]], {
        object_id = object_id_value,
        kind = kind,
        ref_id = ref_id,
        column_name = column_name,
        ordinal = ordinal
    })
end

local function ensure_object_column_available(object_id_value, column_name)
    local duplicate = scalar([[
        SELECT COUNT(*)
        FROM SYS_SEMANTIC.OBJECT_COLUMNS
        WHERE OBJECT_ID = :object_id
          AND UPPER(COLUMN_NAME) = UPPER(:column_name)
    ]], {object_id = object_id_value, column_name = column_name})
    if tonumber(duplicate or 0) > 0 then
        error("SEMANTIC_ADMIN_018: duplicate object column: " .. column_name)
    end
end

local function validation_error_summary(validation_rows)
    for _, row in ipairs(validation_rows or {}) do
        local severity = row_value(row, "SEVERITY", 1)
        if severity == "ERROR" or severity == "PRECONDITION" then
            local object_type = row_value(row, "OBJECT_TYPE", 2) or "OBJECT"
            local object_name = row_value(row, "OBJECT_NAME", 3) or "unknown"
            local rule_code = row_value(row, "RULE_CODE", 4) or "SEMANTIC_MODEL_ERROR"
            local message = row_value(row, "MESSAGE", 5) or "model validation failed"
            return tostring(object_type) .. " " .. tostring(object_name) .. " " .. tostring(rule_code) .. ": " .. tostring(message)
        end
    end
    return nil
end

local function rollback_dimension(model_name, dimension_id_value, object_id_value)
    query([[
        DELETE FROM SYS_SEMANTIC.OBJECT_COLUMNS
        WHERE OBJECT_ID = :object_id
          AND COLUMN_KIND = 'DIMENSION'
          AND OBJECT_REF_ID = :dimension_id
    ]], {object_id = object_id_value, dimension_id = dimension_id_value})
    query([[
        DELETE FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS
        WHERE ATTRIBUTE_TYPE = 'DIMENSION' AND ATTRIBUTE_ID = :dimension_id
    ]], {dimension_id = dimension_id_value})
    query([[
        DELETE FROM SYS_SEMANTIC.DIMENSIONS
        WHERE DIMENSION_ID = :dimension_id
    ]], {dimension_id = dimension_id_value})
    query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)", {model_name = model_name})
end

if missing(EXPRESSION) then
    error("SEMANTIC_ADMIN_001: EXPRESSION is required")
end
if missing(DATA_TYPE) then
    error("SEMANTIC_ADMIN_001: DATA_TYPE is required")
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local object_name = normalize_name(OBJECT_NAME, "OBJECT_NAME")
local entity_name = normalize_name(ENTITY_NAME, "ENTITY_NAME")
local dimension_name = normalize_name(DIMENSION_NAME, "DIMENSION_NAME")
local model = model_row(model_name)
local entity_id_value = entity_id(model, entity_name)
local object_id_value = object_id(model, object_name)

local duplicate = scalar([[
    SELECT COUNT(*)
    FROM SYS_SEMANTIC.DIMENSIONS
    WHERE MODEL_ID = :model_id
      AND VERSION_ID = :version_id
      AND UPPER(DIMENSION_NAME) = UPPER(:dimension_name)
]], {model_id = model.model_id, version_id = model.version_id, dimension_name = dimension_name})
if tonumber(duplicate or 0) > 0 then
    -- Dimension names are unique per *model*, not per semantic object, while
    -- membership lives in OBJECT_COLUMNS. "duplicate dimension: ship_mode" gave
    -- no hint that the name was taken by a different object, nor that the
    -- existing dimension can simply be added to this one.
    local owner_rows = query([[
        SELECT so.OBJECT_NAME, e.ENTITY_NAME
        FROM SYS_SEMANTIC.DIMENSIONS d
        JOIN SYS_SEMANTIC.ENTITIES e ON e.ENTITY_ID = d.ENTITY_ID
        LEFT JOIN SYS_SEMANTIC.OBJECT_COLUMNS oc
          ON oc.COLUMN_KIND = 'DIMENSION' AND oc.OBJECT_REF_ID = d.DIMENSION_ID
        LEFT JOIN SYS_SEMANTIC.SEMANTIC_OBJECTS so ON so.OBJECT_ID = oc.OBJECT_ID
        WHERE d.MODEL_ID = :model_id
          AND d.VERSION_ID = :version_id
          AND UPPER(d.DIMENSION_NAME) = UPPER(:dimension_name)
        ORDER BY so.OBJECT_NAME
    ]], {model_id = model.model_id, version_id = model.version_id,
          dimension_name = dimension_name})
    local owners = {}
    local owning_entity = nil
    for _, owner_row in ipairs(owner_rows or {}) do
        local owner_object = row_value(owner_row, "OBJECT_NAME", 1)
        owning_entity = owning_entity or row_value(owner_row, "ENTITY_NAME", 2)
        if owner_object ~= nil and tostring(owner_object) ~= "" then
            owners[#owners + 1] = tostring(owner_object)
        end
    end
    local detail = " Dimension names are unique per model, not per semantic"
        .. " view, so this name is taken."
    if #owners > 0 then
        detail = detail .. " It is defined on entity '" .. tostring(owning_entity)
            .. "' and exposed by semantic view(s): " .. table.concat(owners, ", ")
            .. "."
    elseif owning_entity ~= nil then
        detail = detail .. " It is defined on entity '" .. tostring(owning_entity)
            .. "' and belongs to no semantic view yet."
    end
    detail = detail .. " Choose a distinct name for this view's column; there is"
        .. " no operation that shares one dimension between views."
    error("SEMANTIC_ADMIN_019: duplicate dimension: " .. dimension_name .. "." .. detail)
end

query([[
    INSERT INTO SYS_SEMANTIC.DIMENSIONS (
      MODEL_ID, VERSION_ID, ENTITY_ID, DIMENSION_NAME, EXPRESSION, DATA_TYPE,
      DISPLAY_NAME, DESCRIPTION, FORMAT_HINT, IS_HIDDEN, IS_CERTIFIED, STATUS
    ) VALUES (
      :model_id, :version_id, :entity_id, :dimension_name, :expression, :data_type,
      :display_name, :description, :format_hint, FALSE, :is_certified, 'ACTIVE'
    )
]], {
    model_id = model.model_id,
    version_id = model.version_id,
    entity_id = entity_id_value,
    dimension_name = dimension_name,
    expression = tostring(EXPRESSION),
    data_type = tostring(DATA_TYPE),
    display_name = optional_text(DISPLAY_NAME),
    description = optional_text(DESCRIPTION),
    format_hint = optional_text(FORMAT_HINT),
    is_certified = bool_value(IS_CERTIFIED, false)
})

local dimension_id = scalar([[
    SELECT DIMENSION_ID
    FROM SYS_SEMANTIC.DIMENSIONS
    WHERE MODEL_ID = :model_id
      AND VERSION_ID = :version_id
      AND UPPER(DIMENSION_NAME) = UPPER(:dimension_name)
]], {model_id = model.model_id, version_id = model.version_id, dimension_name = dimension_name})
query([[
    INSERT INTO SYS_SEMANTIC.ATTRIBUTE_BINDINGS (
      MODEL_ID, VERSION_ID, ENTITY_ID, ATTRIBUTE_TYPE, ATTRIBUTE_ID,
      REPRESENTATION_ID, SOURCE_EXPRESSION, BINDING_ROLE, BINDING_PRIORITY, IS_DEFAULT, STATUS
    )
    SELECT :model_id, :version_id, :entity_id, 'DIMENSION', :attribute_id,
           er.REPRESENTATION_ID, :expression, 'PREFER', 1,
           CASE WHEN er.REPRESENTATION_ROLE = 'PRIMARY' THEN TRUE ELSE FALSE END,
           'ACTIVE'
    FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS er
    WHERE er.ENTITY_ID = :entity_id AND er.STATUS = 'ACTIVE'
      AND (er.REPRESENTATION_ROLE = 'PRIMARY' OR (
        (SELECT COUNT(*) FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS active_er
         WHERE active_er.ENTITY_ID = :entity_id AND active_er.STATUS = 'ACTIVE') > 1
        AND NOT EXISTS (
          SELECT 1 FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS uncovered_er
          WHERE uncovered_er.ENTITY_ID = :entity_id
            AND uncovered_er.STATUS = 'ACTIVE'
            AND uncovered_er.COVERAGE_PREDICATE IS NULL
        )
      ))
]], {
    model_id = model.model_id,
    version_id = model.version_id,
    entity_id = entity_id_value,
    attribute_id = dimension_id,
    expression = tostring(EXPRESSION),
})
add_object_column(object_id_value, "DIMENSION", dimension_id, dimension_name)
local validation_rows = query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)", {model_name = model_name})
local validation_error = validation_error_summary(validation_rows)
if validation_error ~= nil then
    rollback_dimension(model_name, dimension_id, object_id_value)
    error("SEMANTIC_ADMIN_091: dimension rejected; validation failed: " .. validation_error)
end
exit({{dimension_id, model_name, object_name, dimension_name, false, bool_value(IS_CERTIFIED, false), true}}, [[
  DIMENSION_ID DECIMAL(18,0),
  MODEL_NAME VARCHAR(256),
  OBJECT_NAME VARCHAR(256),
  DIMENSION_NAME VARCHAR(256),
  WAS_UPDATE BOOLEAN,
  IS_CERTIFIED BOOLEAN,
  OBJECT_COLUMN_REGISTERED BOOLEAN
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_OR_REPLACE_DIMENSION(
  MODEL_NAME,
  OBJECT_NAME,
  ENTITY_NAME,
  DIMENSION_NAME,
  EXPRESSION,
  DATA_TYPE,
  DISPLAY_NAME,
  DESCRIPTION,
  FORMAT_HINT,
  IS_CERTIFIED
)
RETURNS TABLE AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end

local function optional_text(value)
    if missing(value) then
        return null
    end
    return tostring(value)
end

local function bool_value(value, default_value)
    if missing(value) then
        return default_value
    end
    local text = string.lower(tostring(value))
    return value == true or text == "true" or text == "1"
end

local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end

local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then
        return nil
    end
    return rows[1][1]
end

local function model_row(model_name)
    local rows = query([[
        SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID AS VERSION_ID
        FROM SYS_SEMANTIC.MODELS m
        WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
    ]], {model_name = model_name})
    if rows == nil or #rows == 0 then
        error("SEMANTIC_ADMIN_011: model not found: " .. model_name)
    end
    return {
        model_id = row_value(rows[1], "MODEL_ID", 1),
        version_id = row_value(rows[1], "VERSION_ID", 2)
    }
end

local function entity_id(model, entity_name)
    local id = scalar([[
        SELECT ENTITY_ID
        FROM SYS_SEMANTIC.ENTITIES
        WHERE MODEL_ID = :model_id
          AND VERSION_ID = :version_id
          AND UPPER(ENTITY_NAME) = UPPER(:entity_name)
    ]], {model_id = model.model_id, version_id = model.version_id, entity_name = entity_name})
    if id == nil then
        error("SEMANTIC_ADMIN_014: entity not found: " .. entity_name)
    end
    return id
end

local function object_id(model, object_name)
    local id = scalar([[
        SELECT OBJECT_ID
        FROM SYS_SEMANTIC.SEMANTIC_OBJECTS
        WHERE MODEL_ID = :model_id
          AND VERSION_ID = :version_id
          AND UPPER(OBJECT_NAME) = UPPER(:object_name)
    ]], {model_id = model.model_id, version_id = model.version_id, object_name = object_name})
    if id == nil then
        error("SEMANTIC_ADMIN_017: semantic object not found: " .. object_name)
    end
    return id
end

local function validation_error_summary(validation_rows)
    for _, row in ipairs(validation_rows or {}) do
        local severity = row_value(row, "SEVERITY", 1)
        if severity == "ERROR" or severity == "PRECONDITION" then
            local object_type = row_value(row, "OBJECT_TYPE", 2) or "OBJECT"
            local object_name = row_value(row, "OBJECT_NAME", 3) or "unknown"
            local rule_code = row_value(row, "RULE_CODE", 4) or "SEMANTIC_MODEL_ERROR"
            local message = row_value(row, "MESSAGE", 5) or "model validation failed"
            return tostring(object_type) .. " " .. tostring(object_name) .. " " .. tostring(rule_code) .. ": " .. tostring(message)
        end
    end
    return nil
end

if missing(EXPRESSION) then
    error("SEMANTIC_ADMIN_001: EXPRESSION is required")
end
if missing(DATA_TYPE) then
    error("SEMANTIC_ADMIN_001: DATA_TYPE is required")
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local object_name = normalize_name(OBJECT_NAME, "OBJECT_NAME")
local entity_name = normalize_name(ENTITY_NAME, "ENTITY_NAME")
local dimension_name = normalize_name(DIMENSION_NAME, "DIMENSION_NAME")
local model = model_row(model_name)
local entity_id_value = entity_id(model, entity_name)
local object_id_value = object_id(model, object_name)

local existing_id = scalar([[
    SELECT DIMENSION_ID
    FROM SYS_SEMANTIC.DIMENSIONS
    WHERE MODEL_ID = :model_id
      AND VERSION_ID = :version_id
      AND UPPER(DIMENSION_NAME) = UPPER(:dimension_name)
]], {model_id = model.model_id, version_id = model.version_id, dimension_name = dimension_name})

local was_update = existing_id ~= nil
local dimension_id

if was_update then
    query([[
        UPDATE SYS_SEMANTIC.DIMENSIONS
           SET ENTITY_ID    = :entity_id,
               EXPRESSION   = :expression,
               DATA_TYPE    = :data_type,
               DISPLAY_NAME = :display_name,
               DESCRIPTION  = :description,
               FORMAT_HINT  = :format_hint,
               IS_CERTIFIED = :is_certified
         WHERE DIMENSION_ID = :dimension_id
    ]], {
        entity_id    = entity_id_value,
        expression   = tostring(EXPRESSION),
        data_type    = tostring(DATA_TYPE),
        display_name = optional_text(DISPLAY_NAME),
        description  = optional_text(DESCRIPTION),
        format_hint  = optional_text(FORMAT_HINT),
        is_certified = bool_value(IS_CERTIFIED, false),
        dimension_id = existing_id,
    })
    dimension_id = existing_id
else
    query([[
        INSERT INTO SYS_SEMANTIC.DIMENSIONS (
          MODEL_ID, VERSION_ID, ENTITY_ID, DIMENSION_NAME, EXPRESSION, DATA_TYPE,
          DISPLAY_NAME, DESCRIPTION, FORMAT_HINT, IS_HIDDEN, IS_CERTIFIED, STATUS
        ) VALUES (
          :model_id, :version_id, :entity_id, :dimension_name, :expression, :data_type,
          :display_name, :description, :format_hint, FALSE, :is_certified, 'ACTIVE'
        )
    ]], {
        model_id     = model.model_id,
        version_id   = model.version_id,
        entity_id    = entity_id_value,
        dimension_name = dimension_name,
        expression   = tostring(EXPRESSION),
        data_type    = tostring(DATA_TYPE),
        display_name = optional_text(DISPLAY_NAME),
        description  = optional_text(DESCRIPTION),
        format_hint  = optional_text(FORMAT_HINT),
        is_certified = bool_value(IS_CERTIFIED, false)
    })
    dimension_id = scalar([[
        SELECT DIMENSION_ID
        FROM SYS_SEMANTIC.DIMENSIONS
        WHERE MODEL_ID = :model_id
          AND VERSION_ID = :version_id
          AND UPPER(DIMENSION_NAME) = UPPER(:dimension_name)
    ]], {model_id = model.model_id, version_id = model.version_id, dimension_name = dimension_name})
    local ordinal = scalar([[
        SELECT COALESCE(MAX(ORDINAL_POSITION), 0) + 1
        FROM SYS_SEMANTIC.OBJECT_COLUMNS
        WHERE OBJECT_ID = :object_id
    ]], {object_id = object_id_value})
    query([[
        INSERT INTO SYS_SEMANTIC.OBJECT_COLUMNS (
          OBJECT_ID, COLUMN_KIND, OBJECT_REF_ID, COLUMN_NAME, ORDINAL_POSITION, IS_VISIBLE
        ) VALUES (
          :object_id, 'DIMENSION', :dimension_id, :column_name, :ordinal, TRUE
        )
    ]], {
        object_id    = object_id_value,
        dimension_id = dimension_id,
        column_name  = dimension_name,
        ordinal      = ordinal,
    })
end

local default_binding_id = scalar([[
    SELECT ATTRIBUTE_BINDING_ID
    FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS
    WHERE ATTRIBUTE_TYPE = 'DIMENSION'
      AND ATTRIBUTE_ID = :dimension_id
      AND IS_DEFAULT = TRUE
      AND STATUS = 'ACTIVE'
]], {dimension_id = dimension_id})
local primary_representation_id = scalar([[
    SELECT REPRESENTATION_ID
    FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS
    WHERE ENTITY_ID = :entity_id
      AND REPRESENTATION_ROLE = 'PRIMARY'
      AND STATUS = 'ACTIVE'
]], {entity_id = entity_id_value})
if default_binding_id == nil then
    query([[
        INSERT INTO SYS_SEMANTIC.ATTRIBUTE_BINDINGS (
          MODEL_ID, VERSION_ID, ENTITY_ID, ATTRIBUTE_TYPE, ATTRIBUTE_ID,
          REPRESENTATION_ID, SOURCE_EXPRESSION, BINDING_ROLE,
          BINDING_PRIORITY, IS_DEFAULT, STATUS
        ) VALUES (
          :model_id, :version_id, :entity_id, 'DIMENSION', :dimension_id,
          :representation_id, :expression, 'PREFER', 1, TRUE, 'ACTIVE'
        )
    ]], {model_id = model.model_id, version_id = model.version_id,
        entity_id = entity_id_value, dimension_id = dimension_id,
        representation_id = primary_representation_id, expression = tostring(EXPRESSION)})
else
    query([[
        UPDATE SYS_SEMANTIC.ATTRIBUTE_BINDINGS
        SET ENTITY_ID = :entity_id, REPRESENTATION_ID = :representation_id,
            SOURCE_EXPRESSION = :expression,
            UPDATED_AT = CURRENT_TIMESTAMP, UPDATED_BY = CURRENT_USER
        WHERE ATTRIBUTE_BINDING_ID = :binding_id
    ]], {entity_id = entity_id_value, representation_id = primary_representation_id,
        expression = tostring(EXPRESSION), binding_id = default_binding_id})
end

-- A partitioned entity requires every attribute on every partition. Preserve
-- source-specific bindings and seed only missing partitions from the governed
-- dimension expression.
query([[
    INSERT INTO SYS_SEMANTIC.ATTRIBUTE_BINDINGS (
      MODEL_ID, VERSION_ID, ENTITY_ID, ATTRIBUTE_TYPE, ATTRIBUTE_ID,
      REPRESENTATION_ID, SOURCE_EXPRESSION, BINDING_ROLE,
      BINDING_PRIORITY, IS_DEFAULT, STATUS
    )
    SELECT :model_id, :version_id, :entity_id, 'DIMENSION', :dimension_id,
           er.REPRESENTATION_ID, :expression, 'PREFER', 1, FALSE, 'ACTIVE'
    FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS er
    WHERE er.ENTITY_ID = :entity_id AND er.STATUS = 'ACTIVE'
      AND er.REPRESENTATION_ROLE <> 'PRIMARY'
      AND (SELECT COUNT(*) FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS active_er
           WHERE active_er.ENTITY_ID = :entity_id AND active_er.STATUS = 'ACTIVE') > 1
      AND NOT EXISTS (
        SELECT 1 FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS uncovered_er
        WHERE uncovered_er.ENTITY_ID = :entity_id
          AND uncovered_er.STATUS = 'ACTIVE'
          AND uncovered_er.COVERAGE_PREDICATE IS NULL
      )
      AND NOT EXISTS (
        SELECT 1 FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS existing_binding
        WHERE existing_binding.ATTRIBUTE_TYPE = 'DIMENSION'
          AND existing_binding.ATTRIBUTE_ID = :dimension_id
          AND existing_binding.REPRESENTATION_ID = er.REPRESENTATION_ID
          AND existing_binding.STATUS = 'ACTIVE'
      )
]], {model_id = model.model_id, version_id = model.version_id,
    entity_id = entity_id_value, dimension_id = dimension_id,
    expression = tostring(EXPRESSION)})

local validation_rows = query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)", {model_name = model_name})
local validation_error = validation_error_summary(validation_rows)
if validation_error ~= nil then
    if not was_update then
        query([[DELETE FROM SYS_SEMANTIC.OBJECT_COLUMNS WHERE OBJECT_ID = :object_id AND COLUMN_KIND = 'DIMENSION' AND OBJECT_REF_ID = :dimension_id]], {object_id = object_id_value, dimension_id = dimension_id})
        query([[DELETE FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS WHERE ATTRIBUTE_TYPE = 'DIMENSION' AND ATTRIBUTE_ID = :dimension_id]], {dimension_id = dimension_id})
        query([[DELETE FROM SYS_SEMANTIC.DIMENSIONS WHERE DIMENSION_ID = :dimension_id]], {dimension_id = dimension_id})
        query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)", {model_name = model_name})
    end
    error("SEMANTIC_ADMIN_091: dimension rejected; validation failed: " .. validation_error)
end
exit({{dimension_id, model_name, object_name, dimension_name, was_update, bool_value(IS_CERTIFIED, false), not was_update}}, [[
  DIMENSION_ID DECIMAL(18,0),
  MODEL_NAME VARCHAR(256),
  OBJECT_NAME VARCHAR(256),
  DIMENSION_NAME VARCHAR(256),
  WAS_UPDATE BOOLEAN,
  IS_CERTIFIED BOOLEAN,
  OBJECT_COLUMN_REGISTERED BOOLEAN
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.REMOVE_DIMENSION(
  MODEL_NAME,
  OBJECT_NAME,
  DIMENSION_NAME
)
RETURNS TABLE AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end

local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end

local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then
        return nil
    end
    return rows[1][1]
end

local function model_row(model_name)
    local rows = query([[
        SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID AS VERSION_ID
        FROM SYS_SEMANTIC.MODELS m
        WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
    ]], {model_name = model_name})
    if rows == nil or #rows == 0 then
        error("SEMANTIC_ADMIN_011: model not found: " .. model_name)
    end
    return {
        model_id = row_value(rows[1], "MODEL_ID", 1),
        version_id = row_value(rows[1], "VERSION_ID", 2)
    }
end

local function object_id(model, object_name)
    local id = scalar([[
        SELECT OBJECT_ID
        FROM SYS_SEMANTIC.SEMANTIC_OBJECTS
        WHERE MODEL_ID = :model_id
          AND VERSION_ID = :version_id
          AND UPPER(OBJECT_NAME) = UPPER(:object_name)
    ]], {model_id = model.model_id, version_id = model.version_id, object_name = object_name})
    if id == nil then
        error("SEMANTIC_ADMIN_017: semantic object not found: " .. object_name)
    end
    return id
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local object_name = normalize_name(OBJECT_NAME, "OBJECT_NAME")
local dimension_name = normalize_name(DIMENSION_NAME, "DIMENSION_NAME")
local model = model_row(model_name)
local object_id_value = object_id(model, object_name)

local dimension_id = scalar([[
    SELECT DIMENSION_ID
    FROM SYS_SEMANTIC.DIMENSIONS
    WHERE MODEL_ID = :model_id
      AND VERSION_ID = :version_id
      AND UPPER(DIMENSION_NAME) = UPPER(:dimension_name)
]], {model_id = model.model_id, version_id = model.version_id, dimension_name = dimension_name})

if dimension_id == nil then
    error("SEMANTIC_ADMIN_015: dimension not found: " .. dimension_name)
end

query([[
    DELETE FROM SYS_SEMANTIC.OBJECT_COLUMNS
     WHERE OBJECT_ID = :object_id
       AND COLUMN_KIND = 'DIMENSION'
       AND OBJECT_REF_ID = :dimension_id
]], {object_id = object_id_value, dimension_id = dimension_id})

query([[
    DELETE FROM SYS_SEMANTIC.ATTRIBUTE_FUSION_POLICIES
     WHERE ATTRIBUTE_TYPE = 'DIMENSION'
       AND ATTRIBUTE_ID = :dimension_id
]], {dimension_id = dimension_id})

query([[
    DELETE FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS
     WHERE ATTRIBUTE_TYPE = 'DIMENSION'
       AND ATTRIBUTE_ID = :dimension_id
]], {dimension_id = dimension_id})

query([[
    DELETE FROM SYS_SEMANTIC.DIMENSIONS
     WHERE DIMENSION_ID = :dimension_id
]], {dimension_id = dimension_id})

query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)", {model_name = model_name})

exit({{"OK", model_name, object_name, dimension_name}}, [[
  STATUS VARCHAR(32),
  MODEL_NAME VARCHAR(256),
  OBJECT_NAME VARCHAR(256),
  DIMENSION_NAME VARCHAR(256)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_FACT(
  MODEL_NAME,
  ENTITY_NAME,
  FACT_NAME,
  EXPRESSION,
  DATA_TYPE,
  ADDITIVE_POLICY,
  DISPLAY_NAME,
  DESCRIPTION,
  IS_PRIVATE,
  IS_CERTIFIED
)
RETURNS TABLE AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end

local function normalize_choice(value, label, allowed)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local choice = string.upper(trim(value))
    for _, allowed_value in ipairs(allowed) do
        if choice == allowed_value then
            return choice
        end
    end
    error("SEMANTIC_ADMIN_003: invalid " .. label .. ": " .. tostring(value))
end

local function optional_text(value)
    if missing(value) then
        return null
    end
    return tostring(value)
end

local function bool_value(value, default_value)
    if missing(value) then
        return default_value
    end
    local text = string.lower(tostring(value))
    return value == true or text == "true" or text == "1"
end

local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end

local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then
        return nil
    end
    return rows[1][1]
end

local function model_row(model_name)
    local rows = query([[
        SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID AS VERSION_ID
        FROM SYS_SEMANTIC.MODELS m
        WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
    ]], {model_name = model_name})
    if rows == nil or #rows == 0 then
        error("SEMANTIC_ADMIN_011: model not found: " .. model_name)
    end
    return {
        model_id = row_value(rows[1], "MODEL_ID", 1),
        version_id = row_value(rows[1], "VERSION_ID", 2)
    }
end

local function entity_id(model, entity_name)
    local id = scalar([[
        SELECT ENTITY_ID
        FROM SYS_SEMANTIC.ENTITIES
        WHERE MODEL_ID = :model_id
          AND VERSION_ID = :version_id
          AND UPPER(ENTITY_NAME) = UPPER(:entity_name)
    ]], {model_id = model.model_id, version_id = model.version_id, entity_name = entity_name})
    if id == nil then
        error("SEMANTIC_ADMIN_014: entity not found: " .. entity_name)
    end
    return id
end

local function validation_error_summary(validation_rows)
    for _, row in ipairs(validation_rows or {}) do
        local severity = row_value(row, "SEVERITY", 1)
        if severity == "ERROR" or severity == "PRECONDITION" then
            local object_type = row_value(row, "OBJECT_TYPE", 2) or "OBJECT"
            local object_name = row_value(row, "OBJECT_NAME", 3) or "unknown"
            local rule_code = row_value(row, "RULE_CODE", 4) or "SEMANTIC_MODEL_ERROR"
            local message = row_value(row, "MESSAGE", 5) or "model validation failed"
            return tostring(object_type) .. " " .. tostring(object_name) .. " " .. tostring(rule_code) .. ": " .. tostring(message)
        end
    end
    return nil
end

local function rollback_fact(model_name, fact_id_value)
    query([[
        DELETE FROM SYS_SEMANTIC.ATTRIBUTE_FUSION_POLICIES
        WHERE ATTRIBUTE_TYPE = 'FACT' AND ATTRIBUTE_ID = :fact_id
    ]], {fact_id = fact_id_value})
    query([[
        DELETE FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS
        WHERE ATTRIBUTE_TYPE = 'FACT' AND ATTRIBUTE_ID = :fact_id
    ]], {fact_id = fact_id_value})
    query([[
        DELETE FROM SYS_SEMANTIC.FACTS
        WHERE FACT_ID = :fact_id
    ]], {fact_id = fact_id_value})
    query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)", {model_name = model_name})
end

if missing(EXPRESSION) then
    error("SEMANTIC_ADMIN_001: EXPRESSION is required")
end
if missing(DATA_TYPE) then
    error("SEMANTIC_ADMIN_001: DATA_TYPE is required")
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local entity_name = normalize_name(ENTITY_NAME, "ENTITY_NAME")
local fact_name = normalize_name(FACT_NAME, "FACT_NAME")
local additive_policy = normalize_choice(ADDITIVE_POLICY, "ADDITIVE_POLICY", {"ADDITIVE", "SEMI_ADDITIVE", "NON_ADDITIVE"})
local model = model_row(model_name)
local entity_id_value = entity_id(model, entity_name)

local duplicate = scalar([[
    SELECT COUNT(*)
    FROM SYS_SEMANTIC.FACTS
    WHERE MODEL_ID = :model_id
      AND VERSION_ID = :version_id
      AND UPPER(FACT_NAME) = UPPER(:fact_name)
]], {model_id = model.model_id, version_id = model.version_id, fact_name = fact_name})
if tonumber(duplicate or 0) > 0 then
    error("SEMANTIC_ADMIN_020: duplicate fact: " .. fact_name)
end

query([[
    INSERT INTO SYS_SEMANTIC.FACTS (
      MODEL_ID, VERSION_ID, ENTITY_ID, FACT_NAME, EXPRESSION, DATA_TYPE,
      ADDITIVE_POLICY, DISPLAY_NAME, DESCRIPTION, IS_PRIVATE, IS_CERTIFIED, STATUS
    ) VALUES (
      :model_id, :version_id, :entity_id, :fact_name, :expression, :data_type,
      :additive_policy, :display_name, :description, :is_private, :is_certified, 'ACTIVE'
    )
]], {
    model_id = model.model_id,
    version_id = model.version_id,
    entity_id = entity_id_value,
    fact_name = fact_name,
    expression = tostring(EXPRESSION),
    data_type = tostring(DATA_TYPE),
    additive_policy = additive_policy,
    display_name = optional_text(DISPLAY_NAME),
    description = optional_text(DESCRIPTION),
    is_private = bool_value(IS_PRIVATE, false),
    is_certified = bool_value(IS_CERTIFIED, false)
})
local fact_id = scalar([[
    SELECT FACT_ID
    FROM SYS_SEMANTIC.FACTS
    WHERE MODEL_ID = :model_id
      AND VERSION_ID = :version_id
      AND UPPER(FACT_NAME) = UPPER(:fact_name)
]], {model_id = model.model_id, version_id = model.version_id, fact_name = fact_name})
query([[
    INSERT INTO SYS_SEMANTIC.ATTRIBUTE_BINDINGS (
      MODEL_ID, VERSION_ID, ENTITY_ID, ATTRIBUTE_TYPE, ATTRIBUTE_ID,
      REPRESENTATION_ID, SOURCE_EXPRESSION, BINDING_ROLE, BINDING_PRIORITY, IS_DEFAULT, STATUS
    )
    SELECT :model_id, :version_id, :entity_id, 'FACT', :attribute_id,
           er.REPRESENTATION_ID, :expression, 'PREFER', 1,
           CASE WHEN er.REPRESENTATION_ROLE = 'PRIMARY' THEN TRUE ELSE FALSE END,
           'ACTIVE'
    FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS er
    WHERE er.ENTITY_ID = :entity_id AND er.STATUS = 'ACTIVE'
      AND (er.REPRESENTATION_ROLE = 'PRIMARY' OR (
        (SELECT COUNT(*) FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS active_er
         WHERE active_er.ENTITY_ID = :entity_id AND active_er.STATUS = 'ACTIVE') > 1
        AND NOT EXISTS (
          SELECT 1 FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS uncovered_er
          WHERE uncovered_er.ENTITY_ID = :entity_id
            AND uncovered_er.STATUS = 'ACTIVE'
            AND uncovered_er.COVERAGE_PREDICATE IS NULL
        )
      ))
]], {
    model_id = model.model_id,
    version_id = model.version_id,
    entity_id = entity_id_value,
    attribute_id = fact_id,
    expression = tostring(EXPRESSION),
})
local validation_rows = query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)", {model_name = model_name})
local validation_error = validation_error_summary(validation_rows)
if validation_error ~= nil then
    rollback_fact(model_name, fact_id)
    error("SEMANTIC_ADMIN_092: fact rejected; validation failed: " .. validation_error)
end
exit({{fact_id, model_name, entity_name, fact_name, false, bool_value(IS_PRIVATE, false), bool_value(IS_CERTIFIED, false)}}, [[
  FACT_ID DECIMAL(18,0),
  MODEL_NAME VARCHAR(256),
  ENTITY_NAME VARCHAR(256),
  FACT_NAME VARCHAR(256),
  WAS_UPDATE BOOLEAN,
  IS_PRIVATE BOOLEAN,
  IS_CERTIFIED BOOLEAN
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ATTRIBUTE_WITH_BINDINGS(
  ATTRIBUTE_TYPE, MODEL_NAME, OBJECT_NAME, ENTITY_NAME, ATTRIBUTE_NAME,
  EXPRESSION, DATA_TYPE, ADDITIVE_POLICY, DISPLAY_NAME, DESCRIPTION,
  FORMAT_HINT, IS_PRIVATE, IS_CERTIFIED, BINDINGS_JSON
)
RETURNS TABLE AS
import("SEMANTIC_ADMIN.SEMANTIC_DEFINITION_RUNTIME", "semantic_definition")
local function missing(value)
    return value == nil or value == null or string.match(tostring(value), "^%s*$") ~= nil
end
-- NULL arrives as userdata, and userdata is truthy: `value or ""` would render
-- it as an address and defeat the required-parameter check below.
local function trim(value)
    if value == nil or value == null then return "" end
    return tostring(value):match("^%s*(.-)%s*$")
end
local function upper(value) return string.upper(trim(value)) end
local function normalized(value, label)
    if missing(value) then error("SEMANTIC_ADMIN_001: " .. label .. " is required") end
    local result = trim(value)
    if not string.match(result, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. result)
    end
    return result
end
local function optional_text(value)
    if missing(value) then return null end
    return tostring(value)
end
local function bool_value(value, default_value)
    if missing(value) then return default_value end
    local text = string.lower(tostring(value))
    return value == true or text == "true" or text == "1"
end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then return nil end
    return rows[1][1]
end
local function validation_error_summary(rows)
    for _, row in ipairs(rows or {}) do
        if tostring(row_value(row, "SEVERITY", 1)) == "ERROR"
            or tostring(row_value(row, "SEVERITY", 1)) == "PRECONDITION" then
            return tostring(row_value(row, "OBJECT_TYPE", 2) or "OBJECT") .. " "
                .. tostring(row_value(row, "OBJECT_NAME", 3) or "unknown") .. " "
                .. tostring(row_value(row, "RULE_CODE", 4) or "SEMANTIC_MODEL_ERROR")
                .. ": " .. tostring(row_value(row, "MESSAGE", 5) or "model validation failed")
        end
    end
    return nil
end

local attribute_type = upper(ATTRIBUTE_TYPE)
if attribute_type ~= "DIMENSION" and attribute_type ~= "FACT" then
    error("SEMANTIC_ADMIN_001: ATTRIBUTE_TYPE must be DIMENSION or FACT")
end
local model_name = normalized(MODEL_NAME, "MODEL_NAME")
local entity_name = normalized(ENTITY_NAME, "ENTITY_NAME")
local attribute_name = normalized(ATTRIBUTE_NAME, "ATTRIBUTE_NAME")
if missing(EXPRESSION) or missing(DATA_TYPE) then
    error("SEMANTIC_ADMIN_001: EXPRESSION and DATA_TYPE are required")
end
local expression = trim(EXPRESSION)
local data_type = trim(DATA_TYPE)
local object_name = nil
if attribute_type == "DIMENSION" then
    object_name = normalized(OBJECT_NAME, "OBJECT_NAME")
end
local additive_policy = nil
if attribute_type == "FACT" then
    additive_policy = upper(ADDITIVE_POLICY)
    if additive_policy ~= "ADDITIVE" and additive_policy ~= "SEMI_ADDITIVE"
            and additive_policy ~= "NON_ADDITIVE" then
        error("SEMANTIC_ADMIN_003: invalid ADDITIVE_POLICY: " .. tostring(ADDITIVE_POLICY))
    end
end
if missing(BINDINGS_JSON) or string.sub(trim(BINDINGS_JSON), 1, 1) ~= "[" then
    error("SEMANTIC_ADMIN_213: BINDINGS_JSON must be a JSON array")
end
local decoded, binding_specs = pcall(
    semantic_definition.decode_json, trim(BINDINGS_JSON))
if not decoded or type(binding_specs) ~= "table" then
    error("SEMANTIC_ADMIN_213: BINDINGS_JSON must be a JSON array: "
        .. tostring(binding_specs))
end

local model_rows = query([[
    SELECT MODEL_ID, ACTIVE_VERSION_ID
    FROM SYS_SEMANTIC.MODELS
    WHERE UPPER(MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name})
if model_rows == nil or #model_rows == 0 then
    error("SEMANTIC_ADMIN_011: model not found: " .. model_name)
end
local model_id = row_value(model_rows[1], "MODEL_ID", 1)
local version_id = row_value(model_rows[1], "ACTIVE_VERSION_ID", 2)
local entity_id = scalar([[
    SELECT ENTITY_ID FROM SYS_SEMANTIC.ENTITIES
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND UPPER(ENTITY_NAME) = UPPER(:entity_name) AND STATUS = 'ACTIVE'
]], {model_id = model_id, version_id = version_id, entity_name = entity_name})
if entity_id == nil then
    error("SEMANTIC_ADMIN_014: entity not found: " .. entity_name)
end
local object_id = nil
if attribute_type == "DIMENSION" then
    object_id = scalar([[
        SELECT OBJECT_ID FROM SYS_SEMANTIC.SEMANTIC_OBJECTS
        WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
          AND UPPER(OBJECT_NAME) = UPPER(:object_name) AND STATUS = 'ACTIVE'
    ]], {model_id = model_id, version_id = version_id, object_name = object_name})
    if object_id == nil then
        error("SEMANTIC_ADMIN_017: semantic object not found: " .. object_name)
    end
end

local table_name = attribute_type == "DIMENSION" and "DIMENSIONS" or "FACTS"
local id_column = attribute_type == "DIMENSION" and "DIMENSION_ID" or "FACT_ID"
local name_column = attribute_type == "DIMENSION" and "DIMENSION_NAME" or "FACT_NAME"
local duplicate = scalar(
    "SELECT COUNT(*) FROM SYS_SEMANTIC." .. table_name
      .. " WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id"
      .. " AND UPPER(" .. name_column .. ") = UPPER(:attribute_name)",
    {model_id = model_id, version_id = version_id, attribute_name = attribute_name})
if tonumber(duplicate or 0) > 0 then
    local code = attribute_type == "DIMENSION" and "SEMANTIC_ADMIN_019" or "SEMANTIC_ADMIN_020"
    error(code .. ": duplicate " .. string.lower(attribute_type) .. ": " .. attribute_name)
end
if attribute_type == "DIMENSION" then
    local duplicate_column = scalar([[
        SELECT COUNT(*) FROM SYS_SEMANTIC.OBJECT_COLUMNS
        WHERE OBJECT_ID = :object_id AND UPPER(COLUMN_NAME) = UPPER(:attribute_name)
    ]], {object_id = object_id, attribute_name = attribute_name})
    if tonumber(duplicate_column or 0) > 0 then
        error("SEMANTIC_ADMIN_018: duplicate object column: " .. attribute_name)
    end
end

local representation_rows = query([[
    SELECT REPRESENTATION_ID, REPRESENTATION_NAME, REPRESENTATION_ROLE,
           COVERAGE_PREDICATE
    FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND ENTITY_ID = :entity_id AND STATUS = 'ACTIVE'
]], {model_id = model_id, version_id = version_id, entity_id = entity_id})
local primary = nil
local alternates = {}
local partitions = {}
local partitions_by_name = {}
for _, representation_row in ipairs(representation_rows or {}) do
    local representation = {
        id = row_value(representation_row, "REPRESENTATION_ID", 1),
        name = row_value(representation_row, "REPRESENTATION_NAME", 2),
        role = row_value(representation_row, "REPRESENTATION_ROLE", 3),
        coverage_predicate = row_value(representation_row, "COVERAGE_PREDICATE", 4),
    }
    if tostring(representation.role) == "PRIMARY" then
        if primary ~= nil then
            error("SEMANTIC_ADMIN_213: entity has more than one active primary representation")
        end
        primary = representation
    elseif representation.coverage_predicate ~= nil
            and representation.coverage_predicate ~= null
            and trim(representation.coverage_predicate) ~= "" then
        partitions[#partitions + 1] = representation
        partitions_by_name[upper(representation.name)] = representation
    else
        alternates[upper(representation.name)] = representation
    end
end
if primary == nil then
    error("SEMANTIC_ADMIN_213: entity has no active primary representation")
end

-- What a binding object may say, and what to do about a near miss.
--
-- Every refusal below used to be precise about the fault and silent about the
-- vocabulary, and they arrive one per round trip: "representation_name is
-- required" (because `representation` was silently ignored), then "binding_role
-- is required", then the primary rule, then "binding_role must be PREFER or
-- FALLBACK". Five attempts to write one dimension, each one buying a single
-- fact. So the contract is closed like DECLARATIONS_JSON's -- a misspelled key
-- is a refusal, not a silent drop -- every fault in an object is reported
-- together, and the refusal carries the shape and this entity's actual
-- alternate names, so one attempt is enough.
local BINDING_KEYS = {representation_name = true, source_expression = true,
    binding_role = true, binding_priority = true}
local BINDING_KEY_HINTS = {
    representation = "representation_name", name = "representation_name",
    rep = "representation_name", representationname = "representation_name",
    expression = "source_expression", source = "source_expression",
    sourceexpression = "source_expression", expr = "source_expression",
    role = "binding_role", bindingrole = "binding_role",
    priority = "binding_priority", bindingpriority = "binding_priority",
}
local function binding_shape_help()
    local alternate_names = {}
    for _, alternate in pairs(alternates) do
        alternate_names[#alternate_names + 1] = tostring(alternate.name)
    end
    table.sort(alternate_names)
    local help = ' Each binding is {"representation_name": ..., "source_expression":'
        .. ' ..., "binding_role": "PREFER" or "FALLBACK", "binding_priority":'
        .. ' <positive integer>}.'
    if #alternate_names > 0 then
        help = help .. " Alternates to bind: " .. table.concat(alternate_names, ", ") .. "."
    else
        help = help .. " This entity has no active alternate to bind."
    end
    return help .. ' The primary "' .. tostring(primary.name) .. '" takes'
        .. " binding_role and binding_priority only, because EXPRESSION supplies"
        .. " its expression."
end
local function positive_integer_fault(value, label, required_here)
    if value == nil or value == null then
        if required_here then return label .. " is required" end
        return nil
    end
    if type(value) == "table" then return label .. " must be a positive integer" end
    local number = tonumber(value)
    if number == nil or number < 1 or number % 1 ~= 0 then
        return label .. " must be a positive integer"
    end
    return nil
end
-- Every fault in one object, in one refusal.
local function binding_faults(item)
    local faults = {}
    local unknown = {}
    for supplied_key, _ in pairs(item) do
        local key_text = tostring(supplied_key)
        if not BINDING_KEYS[key_text] then unknown[#unknown + 1] = key_text end
    end
    table.sort(unknown)
    for _, key_text in ipairs(unknown) do
        local hint = BINDING_KEY_HINTS[string.lower(string.gsub(key_text, "[_%s]", ""))]
        faults[#faults + 1] = 'unknown key "' .. key_text .. '"'
            .. (hint ~= nil and (' (did you mean "' .. hint .. '"?)') or "")
    end
    local representation_name = item.representation_name
    local binds_primary = false
    if type(representation_name) == "table" or missing(representation_name) then
        faults[#faults + 1] = "representation_name is required"
    else
        binds_primary = upper(representation_name) == upper(primary.name)
    end
    if binds_primary then
        if item.source_expression ~= nil and item.source_expression ~= null then
            faults[#faults + 1] = "source_expression is not accepted for the"
                .. " primary; EXPRESSION supplies it"
        end
    elseif type(item.source_expression) == "table"
            or missing(item.source_expression) then
        faults[#faults + 1] = "source_expression is required"
    end
    if type(item.binding_role) == "table" or missing(item.binding_role) then
        faults[#faults + 1] = "binding_role is required"
    elseif upper(item.binding_role) ~= "PREFER" and upper(item.binding_role) ~= "FALLBACK" then
        faults[#faults + 1] = 'binding_role must be "PREFER" or "FALLBACK", not "'
            .. tostring(item.binding_role) .. '"'
    end
    local priority_fault = positive_integer_fault(
        item.binding_priority, "binding_priority", not binds_primary)
    if priority_fault ~= nil then faults[#faults + 1] = priority_fault end
    return faults
end

local prepared = {}
local primary_role = "PREFER"
local primary_priority = 1
for _, partition in ipairs(partitions) do
    prepared[#prepared + 1] = {
        representation = partition,
        source_expression = expression,
        binding_role = "PREFER",
        binding_priority = 1,
    }
end
local seen = {}
for index, item in ipairs(binding_specs) do
    if type(item) ~= "table" then
        error("SEMANTIC_ADMIN_213: binding " .. tostring(index) .. " must be an object")
    end
    local faults = binding_faults(item)
    if #faults > 0 then
        error("SEMANTIC_ADMIN_213: binding " .. tostring(index) .. " is not usable: "
            .. table.concat(faults, "; ") .. "." .. binding_shape_help())
    end
    local representation_name = trim(item.representation_name)
    if upper(representation_name) == upper(primary.name) then
        -- The primary's *expression* still comes from EXPRESSION -- two places
        -- to write it is two places to disagree. Its *role* is another matter,
        -- and refusing to take one is what made the canonical fusion case
        -- return NULL for every row: surfacing an attribute only a supplemental
        -- source carries forces EXPRESSION to be a CAST(NULL AS ...) placeholder,
        -- and this script pinned that placeholder at PREFER priority 1, which is
        -- what the compiler's candidate sort chooses first. The caller could
        -- describe the shape and not the resolution, so the only reachable
        -- outcome was the wrong one.
        primary_role = upper(item.binding_role)
        if item.binding_priority ~= nil and item.binding_priority ~= null then
            primary_priority = tonumber(item.binding_priority)
        end
        if seen[upper(representation_name)] then
            error("SEMANTIC_ADMIN_213: duplicate binding for representation: "
                .. representation_name)
        end
        seen[upper(representation_name)] = true
    else
        if partitions_by_name[upper(representation_name)] ~= nil then
            error("SEMANTIC_ADMIN_213: binding " .. tostring(index) .. " names the F3"
                .. " partition '" .. representation_name .. "'; EXPRESSION supplies"
                .. " every partition's binding." .. binding_shape_help())
        end
        local representation = alternates[upper(representation_name)]
        if representation == nil then
            error("SEMANTIC_ADMIN_213: binding " .. tostring(index) .. " names '"
                .. representation_name .. "', which is not an active alternate of"
                .. " entity '" .. entity_name .. "'." .. binding_shape_help())
        end
        if seen[upper(representation_name)] then
            error("SEMANTIC_ADMIN_213: duplicate binding for representation: "
                .. representation_name)
        end
        seen[upper(representation_name)] = true
        prepared[#prepared + 1] = {
            representation = representation,
            source_expression = trim(item.source_expression),
            binding_role = upper(item.binding_role),
            binding_priority = tonumber(item.binding_priority),
        }
    end
end
for representation_key, representation in pairs(alternates) do
    if not seen[representation_key] then
        error("SEMANTIC_ADMIN_213: no binding supplied for active alternate '"
            .. tostring(representation.name) .. "'; every active alternate needs"
            .. " one, so the attribute resolves whichever source a query picks."
            .. binding_shape_help())
    end
end

if attribute_type == "DIMENSION" then
    query([[
        INSERT INTO SYS_SEMANTIC.DIMENSIONS (
          MODEL_ID, VERSION_ID, ENTITY_ID, DIMENSION_NAME, EXPRESSION, DATA_TYPE,
          DISPLAY_NAME, DESCRIPTION, FORMAT_HINT, IS_HIDDEN, IS_CERTIFIED, STATUS
        ) VALUES (
          :model_id, :version_id, :entity_id, :attribute_name, :expression, :data_type,
          :display_name, :description, :format_hint, FALSE, :is_certified, 'ACTIVE'
        )
    ]], {model_id = model_id, version_id = version_id, entity_id = entity_id,
          attribute_name = attribute_name, expression = expression, data_type = data_type,
          display_name = optional_text(DISPLAY_NAME), description = optional_text(DESCRIPTION),
          format_hint = optional_text(FORMAT_HINT),
          is_certified = bool_value(IS_CERTIFIED, false)})
else
    query([[
        INSERT INTO SYS_SEMANTIC.FACTS (
          MODEL_ID, VERSION_ID, ENTITY_ID, FACT_NAME, EXPRESSION, DATA_TYPE,
          ADDITIVE_POLICY, DISPLAY_NAME, DESCRIPTION, IS_PRIVATE, IS_CERTIFIED, STATUS
        ) VALUES (
          :model_id, :version_id, :entity_id, :attribute_name, :expression, :data_type,
          :additive_policy, :display_name, :description, :is_private, :is_certified, 'ACTIVE'
        )
    ]], {model_id = model_id, version_id = version_id, entity_id = entity_id,
          attribute_name = attribute_name, expression = expression, data_type = data_type,
          additive_policy = additive_policy, display_name = optional_text(DISPLAY_NAME),
          description = optional_text(DESCRIPTION), is_private = bool_value(IS_PRIVATE, false),
          is_certified = bool_value(IS_CERTIFIED, false)})
end
local attribute_id = scalar(
    "SELECT " .. id_column .. " FROM SYS_SEMANTIC." .. table_name
      .. " WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id"
      .. " AND UPPER(" .. name_column .. ") = UPPER(:attribute_name)",
    {model_id = model_id, version_id = version_id, attribute_name = attribute_name})
if attribute_type == "DIMENSION" then
    local ordinal = scalar([[
        SELECT COALESCE(MAX(ORDINAL_POSITION), 0) + 1
        FROM SYS_SEMANTIC.OBJECT_COLUMNS WHERE OBJECT_ID = :object_id
    ]], {object_id = object_id})
    query([[
        INSERT INTO SYS_SEMANTIC.OBJECT_COLUMNS (
          OBJECT_ID, COLUMN_KIND, OBJECT_REF_ID, COLUMN_NAME, ORDINAL_POSITION, IS_VISIBLE
        ) VALUES (
          :object_id, 'DIMENSION', :attribute_id, :attribute_name, :ordinal, TRUE
        )
    ]], {object_id = object_id, attribute_id = attribute_id,
          attribute_name = attribute_name, ordinal = ordinal})
end
query([[
    INSERT INTO SYS_SEMANTIC.ATTRIBUTE_BINDINGS (
      MODEL_ID, VERSION_ID, ENTITY_ID, ATTRIBUTE_TYPE, ATTRIBUTE_ID,
      REPRESENTATION_ID, SOURCE_EXPRESSION, BINDING_ROLE, BINDING_PRIORITY,
      IS_DEFAULT, STATUS
    ) VALUES (
      :model_id, :version_id, :entity_id, :attribute_type, :attribute_id,
      :representation_id, :source_expression, :binding_role, :binding_priority,
      TRUE, 'ACTIVE'
    )
]], {model_id = model_id, version_id = version_id, entity_id = entity_id,
      attribute_type = attribute_type, attribute_id = attribute_id,
      representation_id = primary.id, source_expression = expression,
      binding_role = primary_role, binding_priority = primary_priority})
for _, item in ipairs(prepared) do
    query([[
        INSERT INTO SYS_SEMANTIC.ATTRIBUTE_BINDINGS (
          MODEL_ID, VERSION_ID, ENTITY_ID, ATTRIBUTE_TYPE, ATTRIBUTE_ID,
          REPRESENTATION_ID, SOURCE_EXPRESSION, BINDING_ROLE, BINDING_PRIORITY,
          IS_DEFAULT, STATUS
        ) VALUES (
          :model_id, :version_id, :entity_id, :attribute_type, :attribute_id,
          :representation_id, :source_expression, :binding_role, :binding_priority,
          FALSE, 'ACTIVE'
        )
    ]], {model_id = model_id, version_id = version_id, entity_id = entity_id,
          attribute_type = attribute_type, attribute_id = attribute_id,
          representation_id = item.representation.id,
          source_expression = item.source_expression, binding_role = item.binding_role,
          binding_priority = item.binding_priority})
end

local validation_rows = query(
    "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
    {model_name = model_name})
local validation_error = validation_error_summary(validation_rows)
if validation_error ~= nil then
    if attribute_type == "DIMENSION" then
        query([[
            DELETE FROM SYS_SEMANTIC.OBJECT_COLUMNS
            WHERE OBJECT_ID = :object_id AND COLUMN_KIND = 'DIMENSION'
              AND OBJECT_REF_ID = :attribute_id
        ]], {object_id = object_id, attribute_id = attribute_id})
    end
    query([[
        DELETE FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS
        WHERE ATTRIBUTE_TYPE = :attribute_type AND ATTRIBUTE_ID = :attribute_id
    ]], {attribute_type = attribute_type, attribute_id = attribute_id})
    query(
        "DELETE FROM SYS_SEMANTIC." .. table_name .. " WHERE " .. id_column
          .. " = :attribute_id",
        {attribute_id = attribute_id})
    query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
        {model_name = model_name})
    local code = attribute_type == "DIMENSION" and "SEMANTIC_ADMIN_091" or "SEMANTIC_ADMIN_092"
    error(code .. ": " .. string.lower(attribute_type)
        .. " with bindings rejected; validation failed: " .. validation_error)
end
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = version_id})
exit({{attribute_id, model_name, entity_name, attribute_type, attribute_name,
    #prepared + 1}}, [[
  ATTRIBUTE_ID DECIMAL(18,0), MODEL_NAME VARCHAR(256), ENTITY_NAME VARCHAR(256),
  ATTRIBUTE_TYPE VARCHAR(32), ATTRIBUTE_NAME VARCHAR(256),
  BINDING_COUNT DECIMAL(18,0)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_DIMENSION_WITH_BINDINGS(
  MODEL_NAME, OBJECT_NAME, ENTITY_NAME, DIMENSION_NAME, EXPRESSION, DATA_TYPE,
  DISPLAY_NAME, DESCRIPTION, FORMAT_HINT, IS_CERTIFIED, BINDINGS_JSON
)
RETURNS TABLE AS
query([[
    EXECUTE SCRIPT SEMANTIC_ADMIN.ATTRIBUTE_WITH_BINDINGS(
      'DIMENSION', :model_name, :object_name, :entity_name, :attribute_name,
      :expression, :data_type, NULL, :display_name, :description, :format_hint,
      FALSE, :is_certified, :bindings_json
    )
]], {model_name = MODEL_NAME, object_name = OBJECT_NAME, entity_name = ENTITY_NAME,
      attribute_name = DIMENSION_NAME, expression = EXPRESSION, data_type = DATA_TYPE,
      display_name = DISPLAY_NAME, description = DESCRIPTION, format_hint = FORMAT_HINT,
      is_certified = IS_CERTIFIED, bindings_json = BINDINGS_JSON})
local rows = query([[
    SELECT d.DIMENSION_ID, m.MODEL_NAME, e.ENTITY_NAME, 'DIMENSION',
           d.DIMENSION_NAME, COUNT(ab.ATTRIBUTE_BINDING_ID)
    FROM SYS_SEMANTIC.DIMENSIONS d
    JOIN SYS_SEMANTIC.MODELS m ON m.MODEL_ID = d.MODEL_ID
    JOIN SYS_SEMANTIC.ENTITIES e
      ON e.ENTITY_ID = d.ENTITY_ID AND e.VERSION_ID = d.VERSION_ID
    LEFT JOIN SYS_SEMANTIC.ATTRIBUTE_BINDINGS ab
      ON ab.ATTRIBUTE_TYPE = 'DIMENSION' AND ab.ATTRIBUTE_ID = d.DIMENSION_ID
     AND ab.STATUS = 'ACTIVE'
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
      AND d.VERSION_ID = m.ACTIVE_VERSION_ID
      AND UPPER(d.DIMENSION_NAME) = UPPER(:attribute_name)
      AND d.STATUS = 'ACTIVE'
    GROUP BY d.DIMENSION_ID, m.MODEL_NAME, e.ENTITY_NAME, d.DIMENSION_NAME
]], {model_name = MODEL_NAME, attribute_name = DIMENSION_NAME})
local result = {}
for _, row in ipairs(rows or {}) do
    result[#result + 1] = {row[1], row[2], row[3], row[4], row[5], row[6]}
end
exit(result, [[
  ATTRIBUTE_ID DECIMAL(18,0), MODEL_NAME VARCHAR(256), ENTITY_NAME VARCHAR(256),
  ATTRIBUTE_TYPE VARCHAR(32), ATTRIBUTE_NAME VARCHAR(256),
  BINDING_COUNT DECIMAL(18,0)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_FACT_WITH_BINDINGS(
  MODEL_NAME, ENTITY_NAME, FACT_NAME, EXPRESSION, DATA_TYPE, ADDITIVE_POLICY,
  DISPLAY_NAME, DESCRIPTION, IS_PRIVATE, IS_CERTIFIED, BINDINGS_JSON
)
RETURNS TABLE AS
query([[
    EXECUTE SCRIPT SEMANTIC_ADMIN.ATTRIBUTE_WITH_BINDINGS(
      'FACT', :model_name, NULL, :entity_name, :attribute_name,
      :expression, :data_type, :additive_policy, :display_name, :description, NULL,
      :is_private, :is_certified, :bindings_json
    )
]], {model_name = MODEL_NAME, entity_name = ENTITY_NAME,
      attribute_name = FACT_NAME, expression = EXPRESSION, data_type = DATA_TYPE,
      additive_policy = ADDITIVE_POLICY, display_name = DISPLAY_NAME,
      description = DESCRIPTION, is_private = IS_PRIVATE, is_certified = IS_CERTIFIED,
      bindings_json = BINDINGS_JSON})
local rows = query([[
    SELECT f.FACT_ID, m.MODEL_NAME, e.ENTITY_NAME, 'FACT',
           f.FACT_NAME, COUNT(ab.ATTRIBUTE_BINDING_ID)
    FROM SYS_SEMANTIC.FACTS f
    JOIN SYS_SEMANTIC.MODELS m ON m.MODEL_ID = f.MODEL_ID
    JOIN SYS_SEMANTIC.ENTITIES e
      ON e.ENTITY_ID = f.ENTITY_ID AND e.VERSION_ID = f.VERSION_ID
    LEFT JOIN SYS_SEMANTIC.ATTRIBUTE_BINDINGS ab
      ON ab.ATTRIBUTE_TYPE = 'FACT' AND ab.ATTRIBUTE_ID = f.FACT_ID
     AND ab.STATUS = 'ACTIVE'
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
      AND f.VERSION_ID = m.ACTIVE_VERSION_ID
      AND UPPER(f.FACT_NAME) = UPPER(:attribute_name)
      AND f.STATUS = 'ACTIVE'
    GROUP BY f.FACT_ID, m.MODEL_NAME, e.ENTITY_NAME, f.FACT_NAME
]], {model_name = MODEL_NAME, attribute_name = FACT_NAME})
local result = {}
for _, row in ipairs(rows or {}) do
    result[#result + 1] = {row[1], row[2], row[3], row[4], row[5], row[6]}
end
exit(result, [[
  ATTRIBUTE_ID DECIMAL(18,0), MODEL_NAME VARCHAR(256), ENTITY_NAME VARCHAR(256),
  ATTRIBUTE_TYPE VARCHAR(32), ATTRIBUTE_NAME VARCHAR(256),
  BINDING_COUNT DECIMAL(18,0)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_ATTRIBUTE_BINDING(
  MODEL_NAME,
  ATTRIBUTE_TYPE,
  ATTRIBUTE_NAME,
  REPRESENTATION_NAME,
  SOURCE_EXPRESSION,
  BINDING_ROLE,
  BINDING_PRIORITY
)
RETURNS TABLE AS
local function missing(value)
    return value == nil or value == null or string.match(tostring(value), "^%s*$") ~= nil
end
local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then return nil end
    return rows[1][1]
end
local function normalized(value, label)
    if missing(value) then error("SEMANTIC_ADMIN_001: " .. label .. " is required") end
    return string.match(tostring(value), "^%s*(.-)%s*$")
end
local function choice(value, label, allowed)
    local result = string.upper(normalized(value, label))
    if not allowed[result] then
        error("SEMANTIC_ADMIN_001: unsupported " .. label .. ": " .. tostring(value))
    end
    return result
end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local function validation_error_signatures(rows)
    local signatures = {}
    for _, validation_row in ipairs(rows or {}) do
        if tostring(row_value(validation_row, "SEVERITY", 1)) == "ERROR"
            or tostring(row_value(validation_row, "SEVERITY", 1)) == "PRECONDITION" then
            local signature = table.concat({
                tostring(row_value(validation_row, "OBJECT_TYPE", 2) or ""),
                tostring(row_value(validation_row, "OBJECT_NAME", 3) or ""),
                tostring(row_value(validation_row, "RULE_CODE", 4) or ""),
                tostring(row_value(validation_row, "MESSAGE", 5) or ""),
            }, "\31")
            signatures[signature] = true
        end
    end
    return signatures
end

local model_name = normalized(MODEL_NAME, "MODEL_NAME")
local attribute_type = choice(ATTRIBUTE_TYPE, "ATTRIBUTE_TYPE", {DIMENSION = true, FACT = true})
local attribute_name = normalized(ATTRIBUTE_NAME, "ATTRIBUTE_NAME")
local representation_name = normalized(REPRESENTATION_NAME, "REPRESENTATION_NAME")
local source_expression = normalized(SOURCE_EXPRESSION, "SOURCE_EXPRESSION")
local binding_role = choice(BINDING_ROLE, "BINDING_ROLE", {PREFER = true, FALLBACK = true})
local priority = tonumber(BINDING_PRIORITY)
if priority == nil or priority < 1 or priority % 1 ~= 0 then
    error("SEMANTIC_ADMIN_001: BINDING_PRIORITY must be a positive integer")
end

local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID
    FROM SYS_SEMANTIC.MODELS m
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name})
if rows == nil or #rows == 0 then error("SEMANTIC_ADMIN_011: model not found: " .. model_name) end
local model_id = rows[1][1]
local version_id = rows[1][2]
local table_name = attribute_type == "DIMENSION" and "DIMENSIONS" or "FACTS"
local id_column = attribute_type == "DIMENSION" and "DIMENSION_ID" or "FACT_ID"
local name_column = attribute_type == "DIMENSION" and "DIMENSION_NAME" or "FACT_NAME"
local attribute_rows = query(
    "SELECT " .. id_column .. ", ENTITY_ID FROM SYS_SEMANTIC." .. table_name
      .. " WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id"
      .. " AND UPPER(" .. name_column .. ") = UPPER(:attribute_name) AND STATUS = 'ACTIVE'",
    {model_id = model_id, version_id = version_id, attribute_name = attribute_name})
if attribute_rows == nil or #attribute_rows == 0 then
    error("SEMANTIC_ADMIN_021: " .. attribute_type .. " not found: " .. attribute_name)
end
local attribute_id = attribute_rows[1][1]
local entity_id = attribute_rows[1][2]
local representation_id = scalar([[
    SELECT REPRESENTATION_ID
    FROM SYS_SEMANTIC.ENTITY_REPRESENTATIONS
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND ENTITY_ID = :entity_id
      AND UPPER(REPRESENTATION_NAME) = UPPER(:representation_name)
      AND STATUS = 'ACTIVE'
]], {model_id = model_id, version_id = version_id, entity_id = entity_id,
      representation_name = representation_name})
if representation_id == nil then
    error("SEMANTIC_ADMIN_015: representation not found for attribute entity: " .. representation_name)
end
local duplicate = scalar([[
    SELECT COUNT(*) FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS
    WHERE ATTRIBUTE_TYPE = :attribute_type AND ATTRIBUTE_ID = :attribute_id
      AND REPRESENTATION_ID = :representation_id AND STATUS = 'ACTIVE'
]], {attribute_type = attribute_type, attribute_id = attribute_id,
      representation_id = representation_id})
if tonumber(duplicate or 0) > 0 then
    error("SEMANTIC_ADMIN_024: duplicate attribute binding: " .. attribute_name
        .. " -> " .. representation_name
        .. "; use REPLACE_ATTRIBUTE_BINDING to update it, or remove the existing binding first")
end

-- Binding authoring is a repair operation: an alternate with renamed columns
-- can be invalid until all of its bindings exist. Preserve the pre-application
-- errors and reject only errors introduced by this candidate binding.
local baseline_validation_rows = query(
    "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
    {model_name = model_name})
local baseline_errors = validation_error_signatures(baseline_validation_rows)

query([[
    INSERT INTO SYS_SEMANTIC.ATTRIBUTE_BINDINGS (
      MODEL_ID, VERSION_ID, ENTITY_ID, ATTRIBUTE_TYPE, ATTRIBUTE_ID,
      REPRESENTATION_ID, SOURCE_EXPRESSION, BINDING_ROLE, BINDING_PRIORITY, STATUS
    ) VALUES (
      :model_id, :version_id, :entity_id, :attribute_type, :attribute_id,
      :representation_id, :source_expression, :binding_role, :priority, 'ACTIVE'
    )
]], {model_id = model_id, version_id = version_id, entity_id = entity_id,
      attribute_type = attribute_type, attribute_id = attribute_id,
      representation_id = representation_id, source_expression = source_expression,
      binding_role = binding_role, priority = priority})
local binding_id = scalar([[
    SELECT ATTRIBUTE_BINDING_ID FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS
    WHERE ATTRIBUTE_TYPE = :attribute_type AND ATTRIBUTE_ID = :attribute_id
      AND REPRESENTATION_ID = :representation_id AND STATUS = 'ACTIVE'
]], {attribute_type = attribute_type, attribute_id = attribute_id,
      representation_id = representation_id})
local validation_rows = query(
    "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
    {model_name = model_name})
for _, validation_row in ipairs(validation_rows or {}) do
    local severity = row_value(validation_row, "SEVERITY", 1)
    if tostring(severity) == "ERROR" or tostring(severity) == "PRECONDITION" then
        local signature = table.concat({
            tostring(row_value(validation_row, "OBJECT_TYPE", 2) or ""),
            tostring(row_value(validation_row, "OBJECT_NAME", 3) or ""),
            tostring(row_value(validation_row, "RULE_CODE", 4) or ""),
            tostring(row_value(validation_row, "MESSAGE", 5) or ""),
        }, "\31")
        if not baseline_errors[signature] then
            local rule_code = row_value(validation_row, "RULE_CODE", 4)
                or "SEMANTIC_MODEL_ERROR"
            local message = row_value(validation_row, "MESSAGE", 5)
                or "model validation failed"
            query("DELETE FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS WHERE ATTRIBUTE_BINDING_ID = :binding_id",
                {binding_id = binding_id})
            query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
                {model_name = model_name})
            error("SEMANTIC_ADMIN_093: attribute binding rejected; candidate introduced validation error: "
                .. tostring(rule_code) .. " " .. tostring(message))
        end
    end
end
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = version_id})
exit({{binding_id, model_name, attribute_type, attribute_name, representation_name,
    binding_role, priority}}, [[
  ATTRIBUTE_BINDING_ID DECIMAL(18,0), MODEL_NAME VARCHAR(256),
  ATTRIBUTE_TYPE VARCHAR(32), ATTRIBUTE_NAME VARCHAR(256),
  REPRESENTATION_NAME VARCHAR(256), BINDING_ROLE VARCHAR(32),
  BINDING_PRIORITY DECIMAL(18,0)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.REPLACE_ATTRIBUTE_BINDING(
  MODEL_NAME,
  ATTRIBUTE_TYPE,
  ATTRIBUTE_NAME,
  REPRESENTATION_NAME,
  SOURCE_EXPRESSION,
  BINDING_ROLE,
  BINDING_PRIORITY
)
RETURNS TABLE AS
local function missing(value)
    return value == nil or value == null or string.match(tostring(value), "^%s*$") ~= nil
end
local function normalized(value, label)
    if missing(value) then error("SEMANTIC_ADMIN_001: " .. label .. " is required") end
    return string.match(tostring(value), "^%s*(.-)%s*$")
end
local function choice(value, label, allowed)
    local result = string.upper(normalized(value, label))
    if not allowed[result] then
        error("SEMANTIC_ADMIN_001: unsupported " .. label .. ": " .. tostring(value))
    end
    return result
end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local function validation_error_signatures(rows)
    local signatures = {}
    for _, validation_row in ipairs(rows or {}) do
        if tostring(row_value(validation_row, "SEVERITY", 1)) == "ERROR"
            or tostring(row_value(validation_row, "SEVERITY", 1)) == "PRECONDITION" then
            local signature = table.concat({
                tostring(row_value(validation_row, "OBJECT_TYPE", 2) or ""),
                tostring(row_value(validation_row, "OBJECT_NAME", 3) or ""),
                tostring(row_value(validation_row, "RULE_CODE", 4) or ""),
                tostring(row_value(validation_row, "MESSAGE", 5) or ""),
            }, "\31")
            signatures[signature] = true
        end
    end
    return signatures
end

local model_name = normalized(MODEL_NAME, "MODEL_NAME")
local attribute_type = choice(
    ATTRIBUTE_TYPE, "ATTRIBUTE_TYPE", {DIMENSION = true, FACT = true})
local attribute_name = normalized(ATTRIBUTE_NAME, "ATTRIBUTE_NAME")
local representation_name = normalized(REPRESENTATION_NAME, "REPRESENTATION_NAME")
local source_expression = normalized(SOURCE_EXPRESSION, "SOURCE_EXPRESSION")
local binding_role = choice(
    BINDING_ROLE, "BINDING_ROLE", {PREFER = true, FALLBACK = true})
local priority = tonumber(BINDING_PRIORITY)
if priority == nil or priority < 1 or priority % 1 ~= 0 then
    error("SEMANTIC_ADMIN_001: BINDING_PRIORITY must be a positive integer")
end

local table_name = attribute_type == "DIMENSION" and "DIMENSIONS" or "FACTS"
local id_column = attribute_type == "DIMENSION" and "DIMENSION_ID" or "FACT_ID"
local name_column = attribute_type == "DIMENSION" and "DIMENSION_NAME" or "FACT_NAME"
local binding_rows = query(
    "SELECT ab.ATTRIBUTE_BINDING_ID, ab.MODEL_ID, ab.VERSION_ID, ab.ENTITY_ID,"
      .. " ab.SOURCE_EXPRESSION, ab.BINDING_ROLE, ab.BINDING_PRIORITY, m.STATUS"
      .. " FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS ab"
      .. " JOIN SYS_SEMANTIC.MODELS m ON m.MODEL_ID = ab.MODEL_ID"
      .. " JOIN SYS_SEMANTIC." .. table_name .. " a"
      .. " ON a." .. id_column .. " = ab.ATTRIBUTE_ID"
      .. " JOIN SYS_SEMANTIC.ENTITY_REPRESENTATIONS er"
      .. " ON er.REPRESENTATION_ID = ab.REPRESENTATION_ID"
      .. " WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)"
      .. " AND ab.VERSION_ID = m.ACTIVE_VERSION_ID"
      .. " AND ab.ATTRIBUTE_TYPE = :attribute_type"
      .. " AND UPPER(a." .. name_column .. ") = UPPER(:attribute_name)"
      .. " AND UPPER(er.REPRESENTATION_NAME) = UPPER(:representation_name)"
      .. " AND ab.STATUS = 'ACTIVE' AND a.STATUS = 'ACTIVE' AND er.STATUS = 'ACTIVE'",
    {model_name = model_name, attribute_type = attribute_type,
     attribute_name = attribute_name, representation_name = representation_name})
if binding_rows == nil or #binding_rows == 0 then
    error("SEMANTIC_ADMIN_025: attribute binding not found: " .. attribute_name
        .. " -> " .. representation_name .. "; use ADD_ATTRIBUTE_BINDING to create it")
end
local binding_id = row_value(binding_rows[1], "ATTRIBUTE_BINDING_ID", 1)
local model_id = row_value(binding_rows[1], "MODEL_ID", 2)
local version_id = row_value(binding_rows[1], "VERSION_ID", 3)
local previous_expression = row_value(binding_rows[1], "SOURCE_EXPRESSION", 5)
local previous_role = row_value(binding_rows[1], "BINDING_ROLE", 6)
local previous_priority = row_value(binding_rows[1], "BINDING_PRIORITY", 7)

-- A replacement may repair an already-invalid draft. Reject only errors that
-- the candidate introduces, and restore the exact previous binding on failure.
local baseline_validation_rows = query(
    "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
    {model_name = model_name})
local baseline_errors = validation_error_signatures(baseline_validation_rows)
query([[
    UPDATE SYS_SEMANTIC.ATTRIBUTE_BINDINGS
    SET SOURCE_EXPRESSION = :source_expression,
        BINDING_ROLE = :binding_role,
        BINDING_PRIORITY = :priority,
        UPDATED_AT = CURRENT_TIMESTAMP,
        UPDATED_BY = CURRENT_USER
    WHERE ATTRIBUTE_BINDING_ID = :binding_id
]], {source_expression = source_expression, binding_role = binding_role,
      priority = priority, binding_id = binding_id})
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = version_id})
query([[
    UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE'
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND STATUS IN ('OK', 'WARNING')
]], {model_id = model_id, version_id = version_id})
local validation_rows = query(
    "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
    {model_name = model_name})
for _, validation_row in ipairs(validation_rows or {}) do
        if tostring(row_value(validation_row, "SEVERITY", 1)) == "ERROR"
            or tostring(row_value(validation_row, "SEVERITY", 1)) == "PRECONDITION" then
        local signature = table.concat({
            tostring(row_value(validation_row, "OBJECT_TYPE", 2) or ""),
            tostring(row_value(validation_row, "OBJECT_NAME", 3) or ""),
            tostring(row_value(validation_row, "RULE_CODE", 4) or ""),
            tostring(row_value(validation_row, "MESSAGE", 5) or ""),
        }, "\31")
        if not baseline_errors[signature] then
            local rule_code = row_value(validation_row, "RULE_CODE", 4)
                or "SEMANTIC_MODEL_ERROR"
            local message = row_value(validation_row, "MESSAGE", 5)
                or "model validation failed"
            query([[
                UPDATE SYS_SEMANTIC.ATTRIBUTE_BINDINGS
                SET SOURCE_EXPRESSION = :source_expression,
                    BINDING_ROLE = :binding_role,
                    BINDING_PRIORITY = :priority,
                    UPDATED_AT = CURRENT_TIMESTAMP,
                    UPDATED_BY = CURRENT_USER
                WHERE ATTRIBUTE_BINDING_ID = :binding_id
            ]], {source_expression = previous_expression, binding_role = previous_role,
                  priority = previous_priority, binding_id = binding_id})
            query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
                {model_name = model_name})
            error("SEMANTIC_ADMIN_093: attribute binding replacement rejected and restored; "
                .. "candidate introduced validation error: "
                .. tostring(rule_code) .. " " .. tostring(message))
        end
    end
end
exit({{binding_id, model_name, attribute_type, attribute_name, representation_name,
    source_expression, binding_role, priority}}, [[
  ATTRIBUTE_BINDING_ID DECIMAL(18,0), MODEL_NAME VARCHAR(256),
  ATTRIBUTE_TYPE VARCHAR(32), ATTRIBUTE_NAME VARCHAR(256),
  REPRESENTATION_NAME VARCHAR(256), SOURCE_EXPRESSION VARCHAR(2000000),
  BINDING_ROLE VARCHAR(32), BINDING_PRIORITY DECIMAL(18,0)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.REMOVE_ATTRIBUTE_BINDING(
  MODEL_NAME,
  ATTRIBUTE_TYPE,
  ATTRIBUTE_NAME,
  REPRESENTATION_NAME
)
RETURNS TABLE AS
local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then return nil end
    return rows[1][1]
end
-- NULL arrives as userdata, and userdata is truthy: `value or ""` would
-- render an address and report it back in the "not found" errors below.
local function trim(value)
    if value == nil or value == null then return "" end
    return tostring(value):match("^%s*(.-)%s*$")
end
local model_name = trim(MODEL_NAME)
local attribute_type = string.upper(trim(ATTRIBUTE_TYPE))
local attribute_name = trim(ATTRIBUTE_NAME)
local representation_name = trim(REPRESENTATION_NAME)
if attribute_type ~= "DIMENSION" and attribute_type ~= "FACT" then
    error("SEMANTIC_ADMIN_001: ATTRIBUTE_TYPE must be DIMENSION or FACT")
end
local table_name = attribute_type == "DIMENSION" and "DIMENSIONS" or "FACTS"
local id_column = attribute_type == "DIMENSION" and "DIMENSION_ID" or "FACT_ID"
local name_column = attribute_type == "DIMENSION" and "DIMENSION_NAME" or "FACT_NAME"
local binding_rows = query(
    "SELECT ab.ATTRIBUTE_BINDING_ID, ab.MODEL_ID, ab.VERSION_ID, m.STATUS FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS ab"
      .. " JOIN SYS_SEMANTIC.MODELS m ON m.MODEL_ID = ab.MODEL_ID"
      .. " JOIN SYS_SEMANTIC." .. table_name .. " a ON a." .. id_column .. " = ab.ATTRIBUTE_ID"
      .. " JOIN SYS_SEMANTIC.ENTITY_REPRESENTATIONS er ON er.REPRESENTATION_ID = ab.REPRESENTATION_ID"
      .. " WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)"
      .. " AND ab.ATTRIBUTE_TYPE = :attribute_type"
      .. " AND UPPER(a." .. name_column .. ") = UPPER(:attribute_name)"
      .. " AND UPPER(er.REPRESENTATION_NAME) = UPPER(:representation_name)"
      .. " AND ab.STATUS = 'ACTIVE'",
    {model_name = model_name, attribute_type = attribute_type,
     attribute_name = attribute_name, representation_name = representation_name})
if binding_rows == nil or #binding_rows == 0 then
    error("SEMANTIC_ADMIN_025: attribute binding not found")
end
local binding_id = binding_rows[1][1]
local model_id = binding_rows[1][2]
local version_id = binding_rows[1][3]
local model_status = binding_rows[1][4]
query("UPDATE SYS_SEMANTIC.ATTRIBUTE_BINDINGS SET STATUS = 'INACTIVE' WHERE ATTRIBUTE_BINDING_ID = :binding_id",
    {binding_id = binding_id})
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = version_id})
query([[
    UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE'
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND STATUS IN ('OK', 'WARNING')
]], {model_id = model_id, version_id = version_id})
if tostring(model_status) == "PUBLISHED" then
    local candidate_validation = query(
        "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
        {model_name = model_name})
    for _, validation_row in ipairs(candidate_validation or {}) do
        local severity = validation_row.SEVERITY or validation_row.severity or validation_row[1]
        if tostring(severity) == "ERROR" or tostring(severity) == "PRECONDITION" then
            local rule_code = validation_row.RULE_CODE or validation_row.rule_code
                or validation_row[4] or "SEMANTIC_MODEL_ERROR"
            local message = validation_row.MESSAGE or validation_row.message
                or validation_row[5] or "model validation failed"
            query("UPDATE SYS_SEMANTIC.ATTRIBUTE_BINDINGS SET STATUS = 'ACTIVE' WHERE ATTRIBUTE_BINDING_ID = :binding_id",
                {binding_id = binding_id})
            query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
                {model_name = model_name})
            error("SEMANTIC_ADMIN_094: published attribute-binding removal rejected and restored; "
                .. "candidate introduced validation error: "
                .. tostring(rule_code) .. " " .. tostring(message))
        end
    end
end
query("DELETE FROM SYS_SEMANTIC.ATTRIBUTE_BINDINGS WHERE ATTRIBUTE_BINDING_ID = :binding_id",
    {binding_id = binding_id})
exit({{binding_id, model_name, attribute_type, attribute_name, representation_name, "REMOVED"}}, [[
  ATTRIBUTE_BINDING_ID DECIMAL(18,0), MODEL_NAME VARCHAR(256),
  ATTRIBUTE_TYPE VARCHAR(32), ATTRIBUTE_NAME VARCHAR(256),
  REPRESENTATION_NAME VARCHAR(256), STATUS VARCHAR(32)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_METRIC(
  MODEL_NAME,
  OBJECT_NAME,
  METRIC_NAME,
  EXPRESSION,
  FILTER_EXPR,
  METRIC_TYPE,
  BASE_ENTITY_NAME,
  DATA_TYPE,
  DISPLAY_NAME,
  DESCRIPTION,
  FORMAT_HINT,
  IS_PRIVATE,
  IS_CERTIFIED
)
RETURNS TABLE AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end

local function normalize_choice(value, label, allowed)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local choice = string.upper(trim(value))
    for _, allowed_value in ipairs(allowed) do
        if choice == allowed_value then
            return choice
        end
    end
    error("SEMANTIC_ADMIN_003: invalid " .. label .. ": " .. tostring(value))
end

local function optional_text(value)
    if missing(value) then
        return null
    end
    return tostring(value)
end

local function bool_value(value, default_value)
    if missing(value) then
        return default_value
    end
    local text = string.lower(tostring(value))
    return value == true or text == "true" or text == "1"
end

local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end

local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then
        return nil
    end
    return rows[1][1]
end

local function model_row(model_name)
    local rows = query([[
        SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID AS VERSION_ID
        FROM SYS_SEMANTIC.MODELS m
        WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
    ]], {model_name = model_name})
    if rows == nil or #rows == 0 then
        error("SEMANTIC_ADMIN_011: model not found: " .. model_name)
    end
    return {
        model_id = row_value(rows[1], "MODEL_ID", 1),
        version_id = row_value(rows[1], "VERSION_ID", 2)
    }
end

local function entity_id(model, entity_name)
    local id = scalar([[
        SELECT ENTITY_ID
        FROM SYS_SEMANTIC.ENTITIES
        WHERE MODEL_ID = :model_id
          AND VERSION_ID = :version_id
          AND UPPER(ENTITY_NAME) = UPPER(:entity_name)
    ]], {model_id = model.model_id, version_id = model.version_id, entity_name = entity_name})
    if id == nil then
        error("SEMANTIC_ADMIN_014: entity not found: " .. entity_name)
    end
    return id
end

local function object_id(model, object_name)
    local id = scalar([[
        SELECT OBJECT_ID
        FROM SYS_SEMANTIC.SEMANTIC_OBJECTS
        WHERE MODEL_ID = :model_id
          AND VERSION_ID = :version_id
          AND UPPER(OBJECT_NAME) = UPPER(:object_name)
    ]], {model_id = model.model_id, version_id = model.version_id, object_name = object_name})
    if id == nil then
        error("SEMANTIC_ADMIN_017: semantic object not found: " .. object_name)
    end
    return id
end

local function add_object_column(object_id_value, kind, ref_id, column_name)
    local duplicate = scalar([[
        SELECT COUNT(*)
        FROM SYS_SEMANTIC.OBJECT_COLUMNS
        WHERE OBJECT_ID = :object_id
          AND UPPER(COLUMN_NAME) = UPPER(:column_name)
    ]], {object_id = object_id_value, column_name = column_name})
    if tonumber(duplicate or 0) > 0 then
        error("SEMANTIC_ADMIN_018: duplicate object column: " .. column_name)
    end
    local ordinal = scalar([[
        SELECT COALESCE(MAX(ORDINAL_POSITION), 0) + 1
        FROM SYS_SEMANTIC.OBJECT_COLUMNS
        WHERE OBJECT_ID = :object_id
    ]], {object_id = object_id_value})
    query([[
        INSERT INTO SYS_SEMANTIC.OBJECT_COLUMNS (
          OBJECT_ID, COLUMN_KIND, OBJECT_REF_ID, COLUMN_NAME, ORDINAL_POSITION, IS_VISIBLE
        ) VALUES (
          :object_id, :kind, :ref_id, :column_name, :ordinal, TRUE
        )
    ]], {
        object_id = object_id_value,
        kind = kind,
        ref_id = ref_id,
        column_name = column_name,
        ordinal = ordinal
    })
end

local function ensure_metric_object_column_available(object_id_value, column_name)
    local duplicate = scalar([[
        SELECT COUNT(*)
        FROM SYS_SEMANTIC.OBJECT_COLUMNS
        WHERE OBJECT_ID = :object_id
          AND UPPER(COLUMN_NAME) = UPPER(:column_name)
    ]], {object_id = object_id_value, column_name = column_name})
    if tonumber(duplicate or 0) > 0 then
        error("SEMANTIC_ADMIN_018: duplicate object column: " .. column_name)
    end
end

local function validation_error_summary(validation_rows)
    for _, row in ipairs(validation_rows or {}) do
        local severity = row_value(row, "SEVERITY", 1)
        if severity == "ERROR" or severity == "PRECONDITION" then
            local rule_code = row_value(row, "RULE_CODE", 4) or "SEMANTIC_MODEL_ERROR"
            local message = row_value(row, "MESSAGE", 5) or "model validation failed"
            return tostring(rule_code) .. ": " .. tostring(message)
        end
    end
    return nil
end

local function rollback_metric(model_name, metric_id_value, object_id_value)
    query([[
        DELETE FROM SYS_SEMANTIC.OBJECT_COLUMNS
        WHERE OBJECT_ID = :object_id
          AND COLUMN_KIND = 'METRIC'
          AND OBJECT_REF_ID = :metric_id
    ]], {object_id = object_id_value, metric_id = metric_id_value})
    query([[
        DELETE FROM SYS_SEMANTIC.METRICS
        WHERE METRIC_ID = :metric_id
    ]], {metric_id = metric_id_value})
    query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)", {model_name = model_name})
end

if missing(EXPRESSION) then
    error("SEMANTIC_ADMIN_001: EXPRESSION is required")
end
if missing(DATA_TYPE) then
    error("SEMANTIC_ADMIN_001: DATA_TYPE is required")
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local object_name = normalize_name(OBJECT_NAME, "OBJECT_NAME")
local metric_name = normalize_name(METRIC_NAME, "METRIC_NAME")
local base_entity_name = normalize_name(BASE_ENTITY_NAME, "BASE_ENTITY_NAME")
local metric_type = normalize_choice(METRIC_TYPE, "METRIC_TYPE", {"ADDITIVE", "RATIO", "DISTINCT", "SEMI_ADDITIVE", "WINDOW", "DERIVED"})
local model = model_row(model_name)
local object_id_value = object_id(model, object_name)
local base_entity_id = entity_id(model, base_entity_name)

local duplicate = scalar([[
    SELECT COUNT(*)
    FROM SYS_SEMANTIC.METRICS
    WHERE MODEL_ID = :model_id
      AND VERSION_ID = :version_id
      AND UPPER(METRIC_NAME) = UPPER(:metric_name)
]], {model_id = model.model_id, version_id = model.version_id, metric_name = metric_name})
if tonumber(duplicate or 0) > 0 then
    error("SEMANTIC_ADMIN_021: duplicate metric: " .. metric_name)
end
ensure_metric_object_column_available(object_id_value, metric_name)

query([[
    INSERT INTO SYS_SEMANTIC.METRICS (
      MODEL_ID, VERSION_ID, METRIC_NAME, EXPRESSION, FILTER_EXPR, METRIC_TYPE,
      BASE_ENTITY_ID, DATA_TYPE, DISPLAY_NAME, DESCRIPTION, FORMAT_HINT,
      IS_PRIVATE, IS_CERTIFIED, STATUS
    ) VALUES (
      :model_id, :version_id, :metric_name, :expression, :filter_expr, :metric_type,
      :base_entity_id, :data_type, :display_name, :description, :format_hint,
      :is_private, :is_certified, 'ACTIVE'
    )
]], {
    model_id = model.model_id,
    version_id = model.version_id,
    metric_name = metric_name,
    expression = tostring(EXPRESSION),
    filter_expr = optional_text(FILTER_EXPR),
    metric_type = metric_type,
    base_entity_id = base_entity_id,
    data_type = tostring(DATA_TYPE),
    display_name = optional_text(DISPLAY_NAME),
    description = optional_text(DESCRIPTION),
    format_hint = optional_text(FORMAT_HINT),
    is_private = bool_value(IS_PRIVATE, false),
    is_certified = bool_value(IS_CERTIFIED, false)
})

local metric_id = scalar([[
    SELECT METRIC_ID
    FROM SYS_SEMANTIC.METRICS
    WHERE MODEL_ID = :model_id
      AND VERSION_ID = :version_id
      AND UPPER(METRIC_NAME) = UPPER(:metric_name)
]], {model_id = model.model_id, version_id = model.version_id, metric_name = metric_name})
add_object_column(object_id_value, "METRIC", metric_id, metric_name)
local validation_rows = query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)", {model_name = model_name})
local validation_error = validation_error_summary(validation_rows)
if validation_error ~= nil then
    rollback_metric(model_name, metric_id, object_id_value)
    error("SEMANTIC_ADMIN_090: metric rejected; validation failed: " .. validation_error)
end
exit({{metric_id, model_name, object_name, metric_name, false, bool_value(IS_PRIVATE, false), bool_value(IS_CERTIFIED, false), true}}, [[
  METRIC_ID DECIMAL(18,0),
  MODEL_NAME VARCHAR(256),
  OBJECT_NAME VARCHAR(256),
  METRIC_NAME VARCHAR(256),
  WAS_UPDATE BOOLEAN,
  IS_PRIVATE BOOLEAN,
  IS_CERTIFIED BOOLEAN,
  OBJECT_COLUMN_REGISTERED BOOLEAN
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_CUSTOM_EXTENSION(
  MODEL_NAME,
  SCOPE_TYPE,
  SCOPE_NAME,
  VENDOR_NAME,
  DATA_JSON,
  SOURCE_FORMAT,
  EXTENSION_NAME
)
RETURNS TABLE AS
local JSON_NULL = {}

local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

local function upper(value)
    return string.upper(tostring(value))
end

local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end

local function normalize_choice(value, label, allowed)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local choice = upper(trim(value))
    for _, allowed_value in ipairs(allowed) do
        if choice == allowed_value then
            return choice
        end
    end
    error("SEMANTIC_ADMIN_003: invalid " .. label .. ": " .. tostring(value))
end

local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end

local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then
        return nil
    end
    return rows[1][1]
end

local function model_row(model_name)
    local rows = query([[
        SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID AS VERSION_ID
        FROM SYS_SEMANTIC.MODELS m
        WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
    ]], {model_name = model_name})
    if rows == nil or #rows == 0 then
        error("SEMANTIC_ADMIN_011: model not found: " .. model_name)
    end
    return {
        model_id = row_value(rows[1], "MODEL_ID", 1),
        version_id = row_value(rows[1], "VERSION_ID", 2)
    }
end

local function json_decode(text)
    if missing(text) then
        error("empty JSON payload")
    end
    text = tostring(text)
    local pos = 1

    local function peek()
        return string.sub(text, pos, pos)
    end

    local function skip_ws()
        while pos <= #text do
            local c = peek()
            if c == " " or c == "\n" or c == "\r" or c == "\t" then
                pos = pos + 1
            else
                return
            end
        end
    end

    local function parse_string()
        if peek() ~= '"' then
            error("expected string at byte " .. tostring(pos))
        end
        pos = pos + 1
        while pos <= #text do
            local c = peek()
            if c == '"' then
                pos = pos + 1
                return true
            elseif c == "\\" then
                local e = string.sub(text, pos + 1, pos + 1)
                if e == '"' or e == "\\" or e == "/" or e == "b" or e == "f"
                    or e == "n" or e == "r" or e == "t" then
                    pos = pos + 2
                elseif e == "u" then
                    pos = pos + 6
                else
                    error("invalid escape at byte " .. tostring(pos))
                end
            else
                pos = pos + 1
            end
        end
        error("unterminated string")
    end

    local parse_value

    local function parse_number()
        local start_pos = pos
        if peek() == "-" then
            pos = pos + 1
        end
        while string.match(peek(), "%d") do
            pos = pos + 1
        end
        if peek() == "." then
            pos = pos + 1
            while string.match(peek(), "%d") do
                pos = pos + 1
            end
        end
        local c = peek()
        if c == "e" or c == "E" then
            pos = pos + 1
            c = peek()
            if c == "+" or c == "-" then
                pos = pos + 1
            end
            while string.match(peek(), "%d") do
                pos = pos + 1
            end
        end
        if tonumber(string.sub(text, start_pos, pos - 1)) == nil then
            error("invalid number at byte " .. tostring(start_pos))
        end
        return true
    end

    local function parse_array()
        pos = pos + 1
        skip_ws()
        if peek() == "]" then
            pos = pos + 1
            return true
        end
        while true do
            parse_value()
            skip_ws()
            local c = peek()
            if c == "]" then
                pos = pos + 1
                return true
            elseif c == "," then
                pos = pos + 1
            else
                error("expected array comma or close at byte " .. tostring(pos))
            end
        end
    end

    local function parse_object()
        pos = pos + 1
        skip_ws()
        if peek() == "}" then
            pos = pos + 1
            return true
        end
        while true do
            skip_ws()
            parse_string()
            skip_ws()
            if peek() ~= ":" then
                error("expected object colon at byte " .. tostring(pos))
            end
            pos = pos + 1
            parse_value()
            skip_ws()
            local c = peek()
            if c == "}" then
                pos = pos + 1
                return true
            elseif c == "," then
                pos = pos + 1
            else
                error("expected object comma or close at byte " .. tostring(pos))
            end
        end
    end

    function parse_value()
        skip_ws()
        local c = peek()
        if c == '"' then
            return parse_string()
        elseif c == "{" then
            return parse_object()
        elseif c == "[" then
            return parse_array()
        elseif c == "-" or string.match(c, "%d") then
            return parse_number()
        elseif string.sub(text, pos, pos + 3) == "true" then
            pos = pos + 4
            return true
        elseif string.sub(text, pos, pos + 4) == "false" then
            pos = pos + 5
            return false
        elseif string.sub(text, pos, pos + 3) == "null" then
            pos = pos + 4
            return JSON_NULL
        end
        error("unexpected JSON token at byte " .. tostring(pos))
    end

    parse_value()
    skip_ws()
    if pos <= #text then
        error("unexpected trailing JSON at byte " .. tostring(pos))
    end
end

local function scoped_object_id(model, scope_type, scope_name)
    if scope_type == "MODEL" then
        return model.model_id
    end
    if missing(scope_name) then
        error("SEMANTIC_ADMIN_001: SCOPE_NAME is required for " .. scope_type)
    end
    local table_name
    local id_column
    local name_column
    if scope_type == "SEMANTIC_OBJECT" then
        table_name = "SYS_SEMANTIC.SEMANTIC_OBJECTS"
        id_column = "OBJECT_ID"
        name_column = "OBJECT_NAME"
    elseif scope_type == "ENTITY" then
        table_name = "SYS_SEMANTIC.ENTITIES"
        id_column = "ENTITY_ID"
        name_column = "ENTITY_NAME"
    elseif scope_type == "RELATIONSHIP" then
        table_name = "SYS_SEMANTIC.RELATIONSHIPS"
        id_column = "RELATIONSHIP_ID"
        name_column = "RELATIONSHIP_NAME"
    elseif scope_type == "DIMENSION" then
        table_name = "SYS_SEMANTIC.DIMENSIONS"
        id_column = "DIMENSION_ID"
        name_column = "DIMENSION_NAME"
    elseif scope_type == "FACT" then
        table_name = "SYS_SEMANTIC.FACTS"
        id_column = "FACT_ID"
        name_column = "FACT_NAME"
    elseif scope_type == "METRIC" then
        table_name = "SYS_SEMANTIC.METRICS"
        id_column = "METRIC_ID"
        name_column = "METRIC_NAME"
    else
        error("SEMANTIC_ADMIN_003: invalid SCOPE_TYPE: " .. tostring(scope_type))
    end
    local sql_text = "SELECT " .. id_column .. " FROM " .. table_name ..
        " WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id AND UPPER(" .. name_column .. ") = UPPER(:scope_name)"
    local id = scalar(sql_text, {model_id = model.model_id, version_id = model.version_id, scope_name = scope_name})
    if id == nil then
        error("SEMANTIC_ADMIN_022: " .. scope_type .. " not found: " .. tostring(scope_name))
    end
    return id
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local scope_type = normalize_choice(SCOPE_TYPE, "SCOPE_TYPE", {"MODEL", "SEMANTIC_OBJECT", "ENTITY", "RELATIONSHIP", "DIMENSION", "FACT", "METRIC"})
if missing(VENDOR_NAME) then
    error("SEMANTIC_ADMIN_001: VENDOR_NAME is required")
end
if missing(DATA_JSON) then
    error("SEMANTIC_ADMIN_001: DATA_JSON is required")
end
local ok, json_error = pcall(json_decode, DATA_JSON)
if not ok then
    error("SEMANTIC_ADMIN_040: DATA_JSON must be valid JSON: " .. tostring(json_error))
end
local vendor_name = trim(VENDOR_NAME)
local source_format = missing(SOURCE_FORMAT) and "OSI" or upper(trim(SOURCE_FORMAT))
local extension_name = missing(EXTENSION_NAME) and "default" or trim(EXTENSION_NAME)
local scope_name = missing(SCOPE_NAME) and null or trim(SCOPE_NAME)
local model = model_row(model_name)
local scope_id = scoped_object_id(model, scope_type, scope_name)

local existing_id = scalar([[
    SELECT CUSTOM_EXTENSION_ID
    FROM SYS_SEMANTIC.CUSTOM_EXTENSIONS
    WHERE MODEL_ID = :model_id
      AND VERSION_ID = :version_id
      AND SCOPE_TYPE = :scope_type
      AND SCOPE_ID = :scope_id
      AND UPPER(VENDOR_NAME) = UPPER(:vendor_name)
      AND UPPER(SOURCE_FORMAT) = UPPER(:source_format)
      AND UPPER(EXTENSION_NAME) = UPPER(:extension_name)
]], {
    model_id = model.model_id,
    version_id = model.version_id,
    scope_type = scope_type,
    scope_id = scope_id,
    vendor_name = vendor_name,
    source_format = source_format,
    extension_name = extension_name,
})

local was_update = false
if existing_id ~= nil then
    was_update = true
    query([[
        UPDATE SYS_SEMANTIC.CUSTOM_EXTENSIONS
        SET DATA_JSON = :data_json,
            UPDATED_AT = CURRENT_TIMESTAMP,
            UPDATED_BY = CURRENT_USER
        WHERE CUSTOM_EXTENSION_ID = :custom_extension_id
    ]], {custom_extension_id = existing_id, data_json = tostring(DATA_JSON)})
else
    query([[
        INSERT INTO SYS_SEMANTIC.CUSTOM_EXTENSIONS (
          MODEL_ID, VERSION_ID, SCOPE_TYPE, SCOPE_ID, VENDOR_NAME,
          EXTENSION_NAME, SOURCE_FORMAT, DATA_JSON
        ) VALUES (
          :model_id, :version_id, :scope_type, :scope_id, :vendor_name,
          :extension_name, :source_format, :data_json
        )
    ]], {
        model_id = model.model_id,
        version_id = model.version_id,
        scope_type = scope_type,
        scope_id = scope_id,
        vendor_name = vendor_name,
        extension_name = extension_name,
        source_format = source_format,
        data_json = tostring(DATA_JSON),
    })
    existing_id = scalar([[
        SELECT MAX(CUSTOM_EXTENSION_ID)
        FROM SYS_SEMANTIC.CUSTOM_EXTENSIONS
        WHERE MODEL_ID = :model_id
          AND VERSION_ID = :version_id
          AND SCOPE_TYPE = :scope_type
          AND SCOPE_ID = :scope_id
          AND UPPER(VENDOR_NAME) = UPPER(:vendor_name)
          AND UPPER(SOURCE_FORMAT) = UPPER(:source_format)
          AND UPPER(EXTENSION_NAME) = UPPER(:extension_name)
    ]], {
        model_id = model.model_id,
        version_id = model.version_id,
        scope_type = scope_type,
        scope_id = scope_id,
        vendor_name = vendor_name,
        source_format = source_format,
        extension_name = extension_name,
    })
end

exit({{existing_id, model_name, scope_type, scope_name, vendor_name, extension_name, source_format, was_update}}, [[
  CUSTOM_EXTENSION_ID DECIMAL(18,0),
  MODEL_NAME VARCHAR(256),
  SCOPE_TYPE VARCHAR(64),
  SCOPE_NAME VARCHAR(512),
  VENDOR_NAME VARCHAR(256),
  EXTENSION_NAME VARCHAR(256),
  SOURCE_FORMAT VARCHAR(64),
  WAS_UPDATE BOOLEAN
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.GET_CUSTOM_EXTENSIONS(
  MODEL_NAME,
  SCOPE_TYPE,
  SCOPE_NAME,
  VENDOR_NAME
)
RETURNS TABLE AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

local function upper(value)
    return string.upper(tostring(value))
end

local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end

local function normalize_choice(value, label, allowed)
    if missing(value) then
        return null
    end
    local choice = upper(trim(value))
    for _, allowed_value in ipairs(allowed) do
        if choice == allowed_value then
            return choice
        end
    end
    error("SEMANTIC_ADMIN_003: invalid " .. label .. ": " .. tostring(value))
end

local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end

local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then
        return nil
    end
    return rows[1][1]
end

local function model_row(model_name)
    local rows = query([[
        SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID AS VERSION_ID
        FROM SYS_SEMANTIC.MODELS m
        WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
    ]], {model_name = model_name})
    if rows == nil or #rows == 0 then
        error("SEMANTIC_ADMIN_011: model not found: " .. model_name)
    end
    return {
        model_id = row_value(rows[1], "MODEL_ID", 1),
        version_id = row_value(rows[1], "VERSION_ID", 2)
    }
end

local function scoped_object_id(model, scope_type, scope_name)
    if missing(scope_type) then
        return null
    end
    if scope_type == "MODEL" then
        return model.model_id
    end
    if missing(scope_name) then
        error("SEMANTIC_ADMIN_001: SCOPE_NAME is required for " .. scope_type)
    end
    local table_name
    local id_column
    local name_column
    if scope_type == "SEMANTIC_OBJECT" then
        table_name = "SYS_SEMANTIC.SEMANTIC_OBJECTS"
        id_column = "OBJECT_ID"
        name_column = "OBJECT_NAME"
    elseif scope_type == "ENTITY" then
        table_name = "SYS_SEMANTIC.ENTITIES"
        id_column = "ENTITY_ID"
        name_column = "ENTITY_NAME"
    elseif scope_type == "RELATIONSHIP" then
        table_name = "SYS_SEMANTIC.RELATIONSHIPS"
        id_column = "RELATIONSHIP_ID"
        name_column = "RELATIONSHIP_NAME"
    elseif scope_type == "DIMENSION" then
        table_name = "SYS_SEMANTIC.DIMENSIONS"
        id_column = "DIMENSION_ID"
        name_column = "DIMENSION_NAME"
    elseif scope_type == "FACT" then
        table_name = "SYS_SEMANTIC.FACTS"
        id_column = "FACT_ID"
        name_column = "FACT_NAME"
    elseif scope_type == "METRIC" then
        table_name = "SYS_SEMANTIC.METRICS"
        id_column = "METRIC_ID"
        name_column = "METRIC_NAME"
    else
        error("SEMANTIC_ADMIN_003: invalid SCOPE_TYPE: " .. tostring(scope_type))
    end
    local id = scalar("SELECT " .. id_column .. " FROM " .. table_name ..
        " WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id AND UPPER(" .. name_column .. ") = UPPER(:scope_name)",
        {model_id = model.model_id, version_id = model.version_id, scope_name = scope_name})
    if id == nil then
        error("SEMANTIC_ADMIN_022: " .. scope_type .. " not found: " .. tostring(scope_name))
    end
    return id
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local scope_type = normalize_choice(SCOPE_TYPE, "SCOPE_TYPE", {"MODEL", "SEMANTIC_OBJECT", "ENTITY", "RELATIONSHIP", "DIMENSION", "FACT", "METRIC"})
local vendor_name = missing(VENDOR_NAME) and null or trim(VENDOR_NAME)
local model = model_row(model_name)
local scope_id = scoped_object_id(model, scope_type, SCOPE_NAME)

local rows = query([[
    SELECT CUSTOM_EXTENSION_ID, SCOPE_TYPE, SCOPE_ID, SCOPE_NAME, VENDOR_NAME,
           EXTENSION_NAME, SOURCE_FORMAT, DATA_JSON
    FROM SEMANTIC_CATALOG.CUSTOM_EXTENSIONS
    WHERE MODEL_NAME = :model_name
      AND (:scope_type IS NULL OR SCOPE_TYPE = :scope_type)
      AND (:scope_id IS NULL OR SCOPE_ID = :scope_id)
      AND (:vendor_name IS NULL OR UPPER(VENDOR_NAME) = UPPER(:vendor_name))
    ORDER BY SCOPE_TYPE, SCOPE_NAME, VENDOR_NAME, EXTENSION_NAME, CUSTOM_EXTENSION_ID
]], {model_name = model_name, scope_type = scope_type, scope_id = scope_id, vendor_name = vendor_name})

local result = {}
for _, row in ipairs(rows or {}) do
    table.insert(result, {
        row_value(row, "CUSTOM_EXTENSION_ID", 1),
        row_value(row, "SCOPE_TYPE", 2),
        row_value(row, "SCOPE_ID", 3),
        row_value(row, "SCOPE_NAME", 4),
        row_value(row, "VENDOR_NAME", 5),
        row_value(row, "EXTENSION_NAME", 6),
        row_value(row, "SOURCE_FORMAT", 7),
        row_value(row, "DATA_JSON", 8),
    })
end

exit(result, [[
  CUSTOM_EXTENSION_ID DECIMAL(18,0),
  SCOPE_TYPE VARCHAR(64),
  SCOPE_ID DECIMAL(18,0),
  SCOPE_NAME VARCHAR(512),
  VENDOR_NAME VARCHAR(256),
  EXTENSION_NAME VARCHAR(256),
  SOURCE_FORMAT VARCHAR(64),
  DATA_JSON VARCHAR(2000000)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_UNIQUE_KEY(
  MODEL_NAME,
  ENTITY_NAME,
  KEY_NAME,
  KEY_KIND,
  DESCRIPTION,
  SOURCE_FORMAT
)
RETURNS TABLE AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

local function upper(value)
    return string.upper(tostring(value))
end

local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end

local function normalize_choice(value, label, allowed)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local choice = upper(trim(value))
    for _, allowed_value in ipairs(allowed) do
        if choice == allowed_value then
            return choice
        end
    end
    error("SEMANTIC_ADMIN_003: invalid " .. label .. ": " .. tostring(value))
end

local function optional_text(value)
    if missing(value) then
        return null
    end
    return tostring(value)
end

local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end

local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then
        return nil
    end
    return rows[1][1]
end

local function model_row(model_name)
    local rows = query([[
        SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID AS VERSION_ID, m.STATUS
        FROM SYS_SEMANTIC.MODELS m
        WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
    ]], {model_name = model_name})
    if rows == nil or #rows == 0 then
        error("SEMANTIC_ADMIN_011: model not found: " .. model_name)
    end
    return {
        model_id = row_value(rows[1], "MODEL_ID", 1),
        version_id = row_value(rows[1], "VERSION_ID", 2),
        status = row_value(rows[1], "STATUS", 3)
    }
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local entity_name = normalize_name(ENTITY_NAME, "ENTITY_NAME")
local key_name = normalize_name(KEY_NAME, "KEY_NAME")
local key_kind = missing(KEY_KIND) and "UNIQUE" or normalize_choice(KEY_KIND, "KEY_KIND", {"PRIMARY", "UNIQUE", "ALTERNATE"})
local source_format = missing(SOURCE_FORMAT) and "OSI" or upper(trim(SOURCE_FORMAT))
local model = model_row(model_name)
local entity_id = scalar([[
    SELECT ENTITY_ID
    FROM SYS_SEMANTIC.ENTITIES
    WHERE MODEL_ID = :model_id
      AND VERSION_ID = :version_id
      AND UPPER(ENTITY_NAME) = UPPER(:entity_name)
]], {model_id = model.model_id, version_id = model.version_id, entity_name = entity_name})
if entity_id == nil then
    error("SEMANTIC_ADMIN_014: entity not found: " .. entity_name)
end

local existing_key_rows = query([[
    SELECT UNIQUE_KEY_ID, KEY_KIND, DESCRIPTION, SOURCE_FORMAT
    FROM SYS_SEMANTIC.UNIQUE_KEYS
    WHERE MODEL_ID = :model_id
      AND VERSION_ID = :version_id
      AND ENTITY_ID = :entity_id
      AND UPPER(KEY_NAME) = UPPER(:key_name)
]], {model_id = model.model_id, version_id = model.version_id, entity_id = entity_id, key_name = key_name})
local unique_key_id = nil
local previous_key_kind = nil
local previous_description = nil
local previous_source_format = nil
if existing_key_rows ~= nil and #existing_key_rows > 0 then
    unique_key_id = row_value(existing_key_rows[1], "UNIQUE_KEY_ID", 1)
    previous_key_kind = row_value(existing_key_rows[1], "KEY_KIND", 2)
    previous_description = row_value(existing_key_rows[1], "DESCRIPTION", 3) or null
    previous_source_format = row_value(existing_key_rows[1], "SOURCE_FORMAT", 4)
end
local was_update = false
if unique_key_id ~= nil then
    was_update = true
    query([[
        UPDATE SYS_SEMANTIC.UNIQUE_KEYS
        SET KEY_KIND = :key_kind,
            DESCRIPTION = :description,
            SOURCE_FORMAT = :source_format,
            UPDATED_AT = CURRENT_TIMESTAMP,
            UPDATED_BY = CURRENT_USER
        WHERE UNIQUE_KEY_ID = :unique_key_id
    ]], {unique_key_id = unique_key_id, key_kind = key_kind, description = optional_text(DESCRIPTION), source_format = source_format})
else
    query([[
        INSERT INTO SYS_SEMANTIC.UNIQUE_KEYS (
          MODEL_ID, VERSION_ID, ENTITY_ID, KEY_NAME, KEY_KIND, DESCRIPTION, SOURCE_FORMAT
        ) VALUES (
          :model_id, :version_id, :entity_id, :key_name, :key_kind, :description, :source_format
        )
    ]], {
        model_id = model.model_id,
        version_id = model.version_id,
        entity_id = entity_id,
        key_name = key_name,
        key_kind = key_kind,
        description = optional_text(DESCRIPTION),
        source_format = source_format,
    })
    unique_key_id = scalar([[
        SELECT UNIQUE_KEY_ID
        FROM SYS_SEMANTIC.UNIQUE_KEYS
        WHERE MODEL_ID = :model_id
          AND VERSION_ID = :version_id
          AND ENTITY_ID = :entity_id
          AND UPPER(KEY_NAME) = UPPER(:key_name)
    ]], {model_id = model.model_id, version_id = model.version_id, entity_id = entity_id, key_name = key_name})
end

query([[
    DELETE FROM SYS_SEMANTIC.COMPILE_CACHE
    WHERE MODEL_VERSION_ID = :version_id
]], {version_id = model.version_id})
query([[
    UPDATE SYS_SEMANTIC.VALIDATION_RUNS
    SET STATUS = 'STALE'
    WHERE MODEL_ID = :model_id
      AND VERSION_ID = :version_id
      AND STATUS IN ('OK', 'WARNING')
]], {model_id = model.model_id, version_id = model.version_id})

if tostring(model.status) == "PUBLISHED" then
    local candidate_validation = query(
        "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
        {model_name = model_name})
    for _, validation_row in ipairs(candidate_validation or {}) do
        if tostring(row_value(validation_row, "SEVERITY", 1)) == "ERROR"
            or tostring(row_value(validation_row, "SEVERITY", 1)) == "PRECONDITION" then
            local rule_code = row_value(validation_row, "RULE_CODE", 4)
                or "SEMANTIC_MODEL_ERROR"
            local message = row_value(validation_row, "MESSAGE", 5)
                or "model validation failed"
            if was_update then
                query([[
                    UPDATE SYS_SEMANTIC.UNIQUE_KEYS
                    SET KEY_KIND = :key_kind, DESCRIPTION = :description,
                        SOURCE_FORMAT = :source_format,
                        UPDATED_AT = CURRENT_TIMESTAMP, UPDATED_BY = CURRENT_USER
                    WHERE UNIQUE_KEY_ID = :unique_key_id
                ]], {unique_key_id = unique_key_id, key_kind = previous_key_kind,
                      description = previous_description,
                      source_format = previous_source_format})
            else
                query("DELETE FROM SYS_SEMANTIC.UNIQUE_KEYS WHERE UNIQUE_KEY_ID = :unique_key_id",
                    {unique_key_id = unique_key_id})
            end
            query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
                {model_name = model_name})
            error("SEMANTIC_ADMIN_094: published unique-key change rejected and restored; "
                .. "candidate introduced validation error: "
                .. tostring(rule_code) .. " " .. tostring(message))
        end
    end
end

exit({{unique_key_id, model_name, entity_name, key_name, key_kind, source_format, was_update}}, [[
  UNIQUE_KEY_ID DECIMAL(18,0),
  MODEL_NAME VARCHAR(256),
  ENTITY_NAME VARCHAR(256),
  KEY_NAME VARCHAR(256),
  KEY_KIND VARCHAR(64),
  SOURCE_FORMAT VARCHAR(64),
  WAS_UPDATE BOOLEAN
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_UNIQUE_KEY_COLUMN(
  MODEL_NAME,
  ENTITY_NAME,
  KEY_NAME,
  COLUMN_NAME,
  EXPRESSION,
  ORDINAL_POSITION
)
RETURNS TABLE AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end

local function optional_text(value)
    if missing(value) then
        return null
    end
    return tostring(value)
end

local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end

local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then
        return nil
    end
    return rows[1][1]
end

local function model_row(model_name)
    local rows = query([[
        SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID AS VERSION_ID, m.STATUS
        FROM SYS_SEMANTIC.MODELS m
        WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
    ]], {model_name = model_name})
    if rows == nil or #rows == 0 then
        error("SEMANTIC_ADMIN_011: model not found: " .. model_name)
    end
    return {
        model_id = row_value(rows[1], "MODEL_ID", 1),
        version_id = row_value(rows[1], "VERSION_ID", 2),
        status = row_value(rows[1], "STATUS", 3)
    }
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local entity_name = normalize_name(ENTITY_NAME, "ENTITY_NAME")
local key_name = normalize_name(KEY_NAME, "KEY_NAME")
if missing(COLUMN_NAME) and missing(EXPRESSION) then
    error("SEMANTIC_ADMIN_001: COLUMN_NAME or EXPRESSION is required")
end
if not missing(COLUMN_NAME) and not missing(EXPRESSION) then
    error("SEMANTIC_ADMIN_041: specify either COLUMN_NAME or EXPRESSION, not both")
end
local column_name = missing(COLUMN_NAME) and null or trim(COLUMN_NAME)
if column_name ~= null and not string.match(column_name, "^[A-Za-z_][A-Za-z0-9_]*$") then
    error("SEMANTIC_ADMIN_002: invalid COLUMN_NAME: " .. column_name)
end
local expression = optional_text(EXPRESSION)
local model = model_row(model_name)
local unique_key_id = scalar([[
    SELECT uk.UNIQUE_KEY_ID
    FROM SYS_SEMANTIC.UNIQUE_KEYS uk
    JOIN SYS_SEMANTIC.ENTITIES e
      ON e.ENTITY_ID = uk.ENTITY_ID
    WHERE uk.MODEL_ID = :model_id
      AND uk.VERSION_ID = :version_id
      AND UPPER(e.ENTITY_NAME) = UPPER(:entity_name)
      AND UPPER(uk.KEY_NAME) = UPPER(:key_name)
]], {model_id = model.model_id, version_id = model.version_id, entity_name = entity_name, key_name = key_name})
if unique_key_id == nil then
    error("SEMANTIC_ADMIN_042: unique key not found: " .. key_name)
end
local ordinal = ORDINAL_POSITION
if missing(ordinal) then
    ordinal = scalar([[
        SELECT COALESCE(MAX(ORDINAL_POSITION), 0) + 1
        FROM SYS_SEMANTIC.UNIQUE_KEY_COLUMNS
        WHERE UNIQUE_KEY_ID = :unique_key_id
    ]], {unique_key_id = unique_key_id})
end

local existing_rows = query([[
    SELECT COLUMN_NAME, EXPRESSION
    FROM SYS_SEMANTIC.UNIQUE_KEY_COLUMNS
    WHERE UNIQUE_KEY_ID = :unique_key_id
      AND ORDINAL_POSITION = :ordinal
]], {unique_key_id = unique_key_id, ordinal = ordinal})
local was_update = existing_rows ~= nil and #existing_rows > 0
local previous_column_name = was_update
    and (row_value(existing_rows[1], "COLUMN_NAME", 1) or null) or null
local previous_expression = was_update
    and (row_value(existing_rows[1], "EXPRESSION", 2) or null) or null
if was_update then
    query([[
        UPDATE SYS_SEMANTIC.UNIQUE_KEY_COLUMNS
        SET COLUMN_NAME = :column_name,
            EXPRESSION = :expression
        WHERE UNIQUE_KEY_ID = :unique_key_id
          AND ORDINAL_POSITION = :ordinal
    ]], {unique_key_id = unique_key_id, ordinal = ordinal, column_name = column_name, expression = expression})
else
    query([[
        INSERT INTO SYS_SEMANTIC.UNIQUE_KEY_COLUMNS (
          UNIQUE_KEY_ID, ORDINAL_POSITION, COLUMN_NAME, EXPRESSION
        ) VALUES (
          :unique_key_id, :ordinal, :column_name, :expression
        )
    ]], {unique_key_id = unique_key_id, ordinal = ordinal, column_name = column_name, expression = expression})
end

query([[
    DELETE FROM SYS_SEMANTIC.COMPILE_CACHE
    WHERE MODEL_VERSION_ID = :version_id
]], {version_id = model.version_id})
query([[
    UPDATE SYS_SEMANTIC.VALIDATION_RUNS
    SET STATUS = 'STALE'
    WHERE MODEL_ID = :model_id
      AND VERSION_ID = :version_id
      AND STATUS IN ('OK', 'WARNING')
]], {model_id = model.model_id, version_id = model.version_id})

if tostring(model.status) == "PUBLISHED" then
    local candidate_validation = query(
        "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
        {model_name = model_name})
    for _, validation_row in ipairs(candidate_validation or {}) do
        if tostring(row_value(validation_row, "SEVERITY", 1)) == "ERROR"
            or tostring(row_value(validation_row, "SEVERITY", 1)) == "PRECONDITION" then
            local rule_code = row_value(validation_row, "RULE_CODE", 4)
                or "SEMANTIC_MODEL_ERROR"
            local message = row_value(validation_row, "MESSAGE", 5)
                or "model validation failed"
            if was_update then
                query([[
                    UPDATE SYS_SEMANTIC.UNIQUE_KEY_COLUMNS
                    SET COLUMN_NAME = :column_name, EXPRESSION = :expression
                    WHERE UNIQUE_KEY_ID = :unique_key_id
                      AND ORDINAL_POSITION = :ordinal
                ]], {unique_key_id = unique_key_id, ordinal = ordinal,
                      column_name = previous_column_name,
                      expression = previous_expression})
            else
                query([[
                    DELETE FROM SYS_SEMANTIC.UNIQUE_KEY_COLUMNS
                    WHERE UNIQUE_KEY_ID = :unique_key_id
                      AND ORDINAL_POSITION = :ordinal
                ]], {unique_key_id = unique_key_id, ordinal = ordinal})
            end
            query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
                {model_name = model_name})
            error("SEMANTIC_ADMIN_094: published unique-key column change rejected and restored; "
                .. "candidate introduced validation error: "
                .. tostring(rule_code) .. " " .. tostring(message))
        end
    end
end

exit({{unique_key_id, model_name, entity_name, key_name, ordinal, column_name, expression, was_update}}, [[
  UNIQUE_KEY_ID DECIMAL(18,0),
  MODEL_NAME VARCHAR(256),
  ENTITY_NAME VARCHAR(256),
  KEY_NAME VARCHAR(256),
  ORDINAL_POSITION DECIMAL(18,0),
  COLUMN_NAME VARCHAR(256),
  EXPRESSION VARCHAR(2000000),
  WAS_UPDATE BOOLEAN
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_UNIQUE_KEY_WITH_COLUMNS(
  MODEL_NAME,
  ENTITY_NAME,
  KEY_NAME,
  KEY_KIND,
  DESCRIPTION,
  SOURCE_FORMAT,
  COLUMNS_JSON
)
RETURNS TABLE AS
import("SEMANTIC_ADMIN.SEMANTIC_DEFINITION_RUNTIME", "semantic_definition")
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end
local function trim(value) return tostring(value):match("^%s*(.-)%s*$") end
local function upper(value) return string.upper(trim(value)) end
local function normalize_name(value, label)
    if missing(value) then error("SEMANTIC_ADMIN_001: " .. label .. " is required") end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local function json_scalar(value)
    if type(value) == "table" then return nil end
    return value
end
local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then return nil end
    return rows[1][1]
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local entity_name = normalize_name(ENTITY_NAME, "ENTITY_NAME")
local key_name = normalize_name(KEY_NAME, "KEY_NAME")
local key_kind = missing(KEY_KIND) and "UNIQUE" or upper(KEY_KIND)
if key_kind ~= "PRIMARY" and key_kind ~= "UNIQUE" and key_kind ~= "ALTERNATE" then
    error("SEMANTIC_ADMIN_003: invalid KEY_KIND: " .. tostring(KEY_KIND))
end
local source_format = missing(SOURCE_FORMAT) and "OSI" or upper(SOURCE_FORMAT)
local decoded, columns = pcall(semantic_definition.decode_json,
    missing(COLUMNS_JSON) and "" or tostring(COLUMNS_JSON))
if not decoded or type(columns) ~= "table" or #columns == 0 then
    error("SEMANTIC_ADMIN_062: COLUMNS_JSON must be a non-empty JSON array: "
        .. tostring(columns))
end
local prepared = {}
local ordinals = {}
for index, item in ipairs(columns) do
    if type(item) ~= "table" then
        error("SEMANTIC_ADMIN_062: key column " .. tostring(index) .. " must be an object")
    end
    local ordinal = tonumber(json_scalar(item.ordinal_position) or index)
    if ordinal == nil or ordinal < 1 or ordinal % 1 ~= 0 then
        error("SEMANTIC_ADMIN_062: key-column ordinals must be positive integers")
    end
    if ordinals[ordinal] then
        error("SEMANTIC_ADMIN_062: duplicate key-column ordinal: " .. tostring(ordinal))
    end
    ordinals[ordinal] = true
    local column_name = json_scalar(item.column_name)
    local expression = json_scalar(item.expression)
    if not missing(column_name) then column_name = trim(column_name) else column_name = nil end
    if not missing(expression) then expression = trim(expression) else expression = nil end
    if (column_name == nil) == (expression == nil) then
        error("SEMANTIC_ADMIN_041: key column " .. tostring(ordinal)
            .. " must specify either column_name or expression, not both")
    end
    if column_name ~= nil
        and not string.match(column_name, "^[A-Za-z_][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid column_name: " .. column_name)
    end
    prepared[#prepared + 1] = {
        ordinal = ordinal,
        column_name = column_name == nil and null or column_name,
        expression = expression == nil and null or expression,
    }
end
table.sort(prepared, function(left, right) return left.ordinal < right.ordinal end)
for index, item in ipairs(prepared) do
    if item.ordinal ~= index then
        error("SEMANTIC_ADMIN_062: key-column ordinals must be contiguous from 1")
    end
end

local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, m.STATUS, e.ENTITY_ID
    FROM SYS_SEMANTIC.MODELS m
    JOIN SYS_SEMANTIC.ENTITIES e
      ON e.MODEL_ID = m.MODEL_ID AND e.VERSION_ID = m.ACTIVE_VERSION_ID
     AND UPPER(e.ENTITY_NAME) = UPPER(:entity_name) AND e.STATUS = 'ACTIVE'
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name, entity_name = entity_name})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_014: entity not found: " .. entity_name)
end
local model_id = row_value(rows[1], "MODEL_ID", 1)
local version_id = row_value(rows[1], "ACTIVE_VERSION_ID", 2)
local model_status = row_value(rows[1], "STATUS", 3)
local entity_id = row_value(rows[1], "ENTITY_ID", 4)
local duplicate = scalar([[
    SELECT COUNT(*) FROM SYS_SEMANTIC.UNIQUE_KEYS
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND ENTITY_ID = :entity_id AND UPPER(KEY_NAME) = UPPER(:key_name)
]], {model_id = model_id, version_id = version_id,
      entity_id = entity_id, key_name = key_name})
if tonumber(duplicate or 0) > 0 then
    error("SEMANTIC_ADMIN_011: duplicate unique key name: " .. key_name)
end
query([[
    INSERT INTO SYS_SEMANTIC.UNIQUE_KEYS (
      MODEL_ID, VERSION_ID, ENTITY_ID, KEY_NAME, KEY_KIND,
      DESCRIPTION, SOURCE_FORMAT, STATUS
    ) VALUES (
      :model_id, :version_id, :entity_id, :key_name, :key_kind,
      :description, :source_format, 'ACTIVE'
    )
]], {model_id = model_id, version_id = version_id, entity_id = entity_id,
      key_name = key_name, key_kind = key_kind,
      description = missing(DESCRIPTION) and null or tostring(DESCRIPTION),
      source_format = source_format})
local unique_key_id = scalar([[
    SELECT UNIQUE_KEY_ID FROM SYS_SEMANTIC.UNIQUE_KEYS
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND ENTITY_ID = :entity_id AND UPPER(KEY_NAME) = UPPER(:key_name)
]], {model_id = model_id, version_id = version_id,
      entity_id = entity_id, key_name = key_name})
for _, item in ipairs(prepared) do
    query([[
        INSERT INTO SYS_SEMANTIC.UNIQUE_KEY_COLUMNS (
          UNIQUE_KEY_ID, ORDINAL_POSITION, COLUMN_NAME, EXPRESSION
        ) VALUES (:unique_key_id, :ordinal, :column_name, :expression)
    ]], {unique_key_id = unique_key_id, ordinal = item.ordinal,
          column_name = item.column_name, expression = item.expression})
end
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = version_id})
query([[
    UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE'
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND STATUS IN ('OK', 'WARNING')
]], {model_id = model_id, version_id = version_id})
if tostring(model_status) == "PUBLISHED" then
    local candidate_validation = query(
        "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
        {model_name = model_name})
    for _, validation_row in ipairs(candidate_validation or {}) do
        if tostring(row_value(validation_row, "SEVERITY", 1)) == "ERROR"
            or tostring(row_value(validation_row, "SEVERITY", 1)) == "PRECONDITION" then
            local rule_code = row_value(validation_row, "RULE_CODE", 4)
                or "SEMANTIC_MODEL_ERROR"
            local message = row_value(validation_row, "MESSAGE", 5)
                or "model validation failed"
            query("DELETE FROM SYS_SEMANTIC.UNIQUE_KEY_COLUMNS WHERE UNIQUE_KEY_ID = :unique_key_id",
                {unique_key_id = unique_key_id})
            query("DELETE FROM SYS_SEMANTIC.UNIQUE_KEYS WHERE UNIQUE_KEY_ID = :unique_key_id",
                {unique_key_id = unique_key_id})
            query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
                {model_name = model_name})
            error("SEMANTIC_ADMIN_094: published unique-key candidate rejected and restored; "
                .. "candidate introduced validation error: "
                .. tostring(rule_code) .. " " .. tostring(message))
        end
    end
end
local result = {}
for _, item in ipairs(prepared) do
    result[#result + 1] = {unique_key_id, model_name, entity_name, key_name,
        key_kind, item.ordinal, item.column_name, item.expression}
end
exit(result, [[
  UNIQUE_KEY_ID DECIMAL(18,0), MODEL_NAME VARCHAR(256), ENTITY_NAME VARCHAR(256),
  KEY_NAME VARCHAR(256), KEY_KIND VARCHAR(64), ORDINAL_POSITION DECIMAL(18,0),
  COLUMN_NAME VARCHAR(256), EXPRESSION VARCHAR(2000000)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.REMOVE_UNIQUE_KEY_COLUMN(
  MODEL_NAME,
  ENTITY_NAME,
  KEY_NAME,
  ORDINAL_POSITION
)
RETURNS TABLE AS
-- NULL arrives as userdata, and userdata is truthy: `value or ""` would render
-- it as an address and defeat the required-parameter check below.
local function trim(value)
    if value == nil or value == null then return "" end
    return tostring(value):match("^%s*(.-)%s*$")
end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local model_name = trim(MODEL_NAME)
local entity_name = trim(ENTITY_NAME)
local key_name = trim(KEY_NAME)
local ordinal = tonumber(ORDINAL_POSITION)
if model_name == "" or entity_name == "" or key_name == "" then
    error("SEMANTIC_ADMIN_001: model, entity, and key names are required")
end
if ordinal == nil or ordinal < 1 or ordinal % 1 ~= 0 then
    error("SEMANTIC_ADMIN_001: ORDINAL_POSITION must be a positive integer")
end
local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, m.STATUS, uk.UNIQUE_KEY_ID,
           ukc.COLUMN_NAME, ukc.EXPRESSION
    FROM SYS_SEMANTIC.MODELS m
    JOIN SYS_SEMANTIC.ENTITIES e
      ON e.MODEL_ID = m.MODEL_ID AND e.VERSION_ID = m.ACTIVE_VERSION_ID
     AND UPPER(e.ENTITY_NAME) = UPPER(:entity_name)
    JOIN SYS_SEMANTIC.UNIQUE_KEYS uk
      ON uk.ENTITY_ID = e.ENTITY_ID AND uk.VERSION_ID = e.VERSION_ID
     AND UPPER(uk.KEY_NAME) = UPPER(:key_name) AND uk.STATUS = 'ACTIVE'
    JOIN SYS_SEMANTIC.UNIQUE_KEY_COLUMNS ukc
      ON ukc.UNIQUE_KEY_ID = uk.UNIQUE_KEY_ID
     AND ukc.ORDINAL_POSITION = :ordinal
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name, entity_name = entity_name,
      key_name = key_name, ordinal = ordinal})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_095: unique-key column not found: " .. key_name
        .. "[" .. tostring(ordinal) .. "]")
end
local model_id = row_value(rows[1], "MODEL_ID", 1)
local version_id = row_value(rows[1], "ACTIVE_VERSION_ID", 2)
local model_status = row_value(rows[1], "STATUS", 3)
local unique_key_id = row_value(rows[1], "UNIQUE_KEY_ID", 4)
local column_name = row_value(rows[1], "COLUMN_NAME", 5) or null
local expression = row_value(rows[1], "EXPRESSION", 6) or null
query([[
    DELETE FROM SYS_SEMANTIC.UNIQUE_KEY_COLUMNS
    WHERE UNIQUE_KEY_ID = :unique_key_id AND ORDINAL_POSITION = :ordinal
]], {unique_key_id = unique_key_id, ordinal = ordinal})
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = version_id})
query([[
    UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE'
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND STATUS IN ('OK', 'WARNING')
]], {model_id = model_id, version_id = version_id})
if tostring(model_status) == "PUBLISHED" then
    local candidate_validation = query(
        "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
        {model_name = model_name})
    for _, validation_row in ipairs(candidate_validation or {}) do
        if tostring(row_value(validation_row, "SEVERITY", 1)) == "ERROR"
            or tostring(row_value(validation_row, "SEVERITY", 1)) == "PRECONDITION" then
            local rule_code = row_value(validation_row, "RULE_CODE", 4)
                or "SEMANTIC_MODEL_ERROR"
            local message = row_value(validation_row, "MESSAGE", 5)
                or "model validation failed"
            query([[
                INSERT INTO SYS_SEMANTIC.UNIQUE_KEY_COLUMNS (
                  UNIQUE_KEY_ID, ORDINAL_POSITION, COLUMN_NAME, EXPRESSION
                ) VALUES (:unique_key_id, :ordinal, :column_name, :expression)
            ]], {unique_key_id = unique_key_id, ordinal = ordinal,
                  column_name = column_name, expression = expression})
            query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
                {model_name = model_name})
            error("SEMANTIC_ADMIN_094: published unique-key column removal rejected and restored; "
                .. "candidate introduced validation error: "
                .. tostring(rule_code) .. " " .. tostring(message))
        end
    end
end
exit({{unique_key_id, model_name, entity_name, key_name, ordinal, "REMOVED"}}, [[
  UNIQUE_KEY_ID DECIMAL(18,0), MODEL_NAME VARCHAR(256), ENTITY_NAME VARCHAR(256),
  KEY_NAME VARCHAR(256), ORDINAL_POSITION DECIMAL(18,0), STATUS VARCHAR(32)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.REMOVE_UNIQUE_KEY(
  MODEL_NAME,
  ENTITY_NAME,
  KEY_NAME
)
RETURNS TABLE AS
-- NULL arrives as userdata, and userdata is truthy: `value or ""` would render
-- it as an address and defeat the required-parameter check below.
local function trim(value)
    if value == nil or value == null then return "" end
    return tostring(value):match("^%s*(.-)%s*$")
end
local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end
local model_name = trim(MODEL_NAME)
local entity_name = trim(ENTITY_NAME)
local key_name = trim(KEY_NAME)
if model_name == "" or entity_name == "" or key_name == "" then
    error("SEMANTIC_ADMIN_001: model, entity, and key names are required")
end
local rows = query([[
    SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID, m.STATUS, uk.UNIQUE_KEY_ID
    FROM SYS_SEMANTIC.MODELS m
    JOIN SYS_SEMANTIC.ENTITIES e
      ON e.MODEL_ID = m.MODEL_ID AND e.VERSION_ID = m.ACTIVE_VERSION_ID
     AND UPPER(e.ENTITY_NAME) = UPPER(:entity_name)
    JOIN SYS_SEMANTIC.UNIQUE_KEYS uk
      ON uk.ENTITY_ID = e.ENTITY_ID AND uk.VERSION_ID = e.VERSION_ID
     AND UPPER(uk.KEY_NAME) = UPPER(:key_name) AND uk.STATUS = 'ACTIVE'
    WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name, entity_name = entity_name, key_name = key_name})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_096: active unique key not found: " .. key_name)
end
local model_id = row_value(rows[1], "MODEL_ID", 1)
local version_id = row_value(rows[1], "ACTIVE_VERSION_ID", 2)
local model_status = row_value(rows[1], "STATUS", 3)
local unique_key_id = row_value(rows[1], "UNIQUE_KEY_ID", 4)
local column_rows = query([[
    SELECT ORDINAL_POSITION FROM SYS_SEMANTIC.UNIQUE_KEY_COLUMNS
    WHERE UNIQUE_KEY_ID = :unique_key_id LIMIT 1
]], {unique_key_id = unique_key_id})
if column_rows ~= nil and #column_rows > 0 then
    error("SEMANTIC_ADMIN_097: cannot remove a unique key with columns; "
        .. "remove its unique-key columns first")
end
query([[
    UPDATE SYS_SEMANTIC.UNIQUE_KEYS SET STATUS = 'INACTIVE',
        UPDATED_AT = CURRENT_TIMESTAMP, UPDATED_BY = CURRENT_USER
    WHERE UNIQUE_KEY_ID = :unique_key_id
]], {unique_key_id = unique_key_id})
query("DELETE FROM SYS_SEMANTIC.COMPILE_CACHE WHERE MODEL_VERSION_ID = :version_id",
    {version_id = version_id})
query([[
    UPDATE SYS_SEMANTIC.VALIDATION_RUNS SET STATUS = 'STALE'
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
      AND STATUS IN ('OK', 'WARNING')
]], {model_id = model_id, version_id = version_id})
if tostring(model_status) == "PUBLISHED" then
    local candidate_validation = query(
        "EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
        {model_name = model_name})
    for _, validation_row in ipairs(candidate_validation or {}) do
        if tostring(row_value(validation_row, "SEVERITY", 1)) == "ERROR"
            or tostring(row_value(validation_row, "SEVERITY", 1)) == "PRECONDITION" then
            local rule_code = row_value(validation_row, "RULE_CODE", 4)
                or "SEMANTIC_MODEL_ERROR"
            local message = row_value(validation_row, "MESSAGE", 5)
                or "model validation failed"
            query([[
                UPDATE SYS_SEMANTIC.UNIQUE_KEYS SET STATUS = 'ACTIVE',
                    UPDATED_AT = CURRENT_TIMESTAMP, UPDATED_BY = CURRENT_USER
                WHERE UNIQUE_KEY_ID = :unique_key_id
            ]], {unique_key_id = unique_key_id})
            query("EXECUTE SCRIPT SEMANTIC_ADMIN.VALIDATE_MODEL(:model_name)",
                {model_name = model_name})
            error("SEMANTIC_ADMIN_094: published unique-key removal rejected and restored; "
                .. "candidate introduced validation error: "
                .. tostring(rule_code) .. " " .. tostring(message))
        end
    end
end
query("DELETE FROM SYS_SEMANTIC.UNIQUE_KEYS WHERE UNIQUE_KEY_ID = :unique_key_id",
    {unique_key_id = unique_key_id})
exit({{unique_key_id, model_name, entity_name, key_name, "REMOVED"}}, [[
  UNIQUE_KEY_ID DECIMAL(18,0), MODEL_NAME VARCHAR(256), ENTITY_NAME VARCHAR(256),
  KEY_NAME VARCHAR(256), STATUS VARCHAR(32)
]])
/

