CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_SYNONYM(
  MODEL_NAME,
  OBJECT_TYPE,
  OBJECT_NAME,
  SYNONYM,
  SOURCE
)
RETURNS TABLE AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end

local function normalize_choice(value, label, allowed)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local choice = string.upper(trim(value))
    for _, allowed_value in ipairs(allowed) do
        if choice == allowed_value then
            return choice
        end
    end
    error("SEMANTIC_ADMIN_003: invalid " .. label .. ": " .. tostring(value))
end

local function optional_text(value)
    if missing(value) then
        return null
    end
    return tostring(value)
end

local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end

local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then
        return nil
    end
    return rows[1][1]
end

local function model_row(model_name)
    local rows = query([[
        SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID AS VERSION_ID
        FROM SYS_SEMANTIC.MODELS m
        WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
    ]], {model_name = model_name})
    if rows == nil or #rows == 0 then
        error("SEMANTIC_ADMIN_011: model not found: " .. model_name)
    end
    return {
        model_id = row_value(rows[1], "MODEL_ID", 1),
        version_id = row_value(rows[1], "VERSION_ID", 2)
    }
end

local function semantic_object_id(model, object_type, object_name)
    local table_name
    local id_column
    local name_column
    if object_type == "SEMANTIC_OBJECT" then
        table_name = "SYS_SEMANTIC.SEMANTIC_OBJECTS"
        id_column = "OBJECT_ID"
        name_column = "OBJECT_NAME"
    elseif object_type == "ENTITY" then
        table_name = "SYS_SEMANTIC.ENTITIES"
        id_column = "ENTITY_ID"
        name_column = "ENTITY_NAME"
    elseif object_type == "DIMENSION" then
        table_name = "SYS_SEMANTIC.DIMENSIONS"
        id_column = "DIMENSION_ID"
        name_column = "DIMENSION_NAME"
    elseif object_type == "FACT" then
        table_name = "SYS_SEMANTIC.FACTS"
        id_column = "FACT_ID"
        name_column = "FACT_NAME"
    elseif object_type == "METRIC" then
        table_name = "SYS_SEMANTIC.METRICS"
        id_column = "METRIC_ID"
        name_column = "METRIC_NAME"
    else
        error("SEMANTIC_ADMIN_003: invalid OBJECT_TYPE: " .. object_type)
    end

    local sql_text = "SELECT " .. id_column .. " FROM " .. table_name ..
        " WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id AND UPPER(" .. name_column .. ") = UPPER(:object_name)"
    local id = scalar(sql_text, {model_id = model.model_id, version_id = model.version_id, object_name = object_name})
    if id == nil then
        error("SEMANTIC_ADMIN_022: " .. object_type .. " not found: " .. object_name)
    end
    return id
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local object_type = normalize_choice(OBJECT_TYPE, "OBJECT_TYPE", {"SEMANTIC_OBJECT", "ENTITY", "DIMENSION", "FACT", "METRIC"})
local object_name = normalize_name(OBJECT_NAME, "OBJECT_NAME")
if missing(SYNONYM) then
    error("SEMANTIC_ADMIN_001: SYNONYM is required")
end
local synonym = trim(SYNONYM)
local source = "MANUAL"
if not missing(SOURCE) then
    source = string.upper(trim(SOURCE))
end

local model = model_row(model_name)
local object_id = semantic_object_id(model, object_type, object_name)

local duplicate = scalar([[
    SELECT COUNT(*)
    FROM SYS_SEMANTIC.SYNONYMS
    WHERE MODEL_ID = :model_id
      AND VERSION_ID = :version_id
      AND OBJECT_TYPE = :object_type
      AND OBJECT_ID = :object_id
      AND UPPER(SYNONYM) = UPPER(:synonym)
]], {
    model_id = model.model_id,
    version_id = model.version_id,
    object_type = object_type,
    object_id = object_id,
    synonym = synonym
})
if tonumber(duplicate or 0) > 0 then
    error("SEMANTIC_ADMIN_023: duplicate synonym for object: " .. synonym)
end

query([[
    INSERT INTO SYS_SEMANTIC.SYNONYMS (
      MODEL_ID, VERSION_ID, OBJECT_TYPE, OBJECT_ID, SYNONYM, SYNONYM_SOURCE
    ) VALUES (
      :model_id, :version_id, :object_type, :object_id, :synonym, :source
    )
]], {
    model_id = model.model_id,
    version_id = model.version_id,
    object_type = object_type,
    object_id = object_id,
    synonym = synonym,
    source = source
})
exit({{model_name, object_type, object_name, synonym, source, true}}, [[
  MODEL_NAME VARCHAR(256),
  OBJECT_TYPE VARCHAR(64),
  OBJECT_NAME VARCHAR(256),
  SYNONYM VARCHAR(512),
  SYNONYM_SOURCE VARCHAR(64),
  WAS_INSERTED BOOLEAN
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.REGISTER_MATERIALIZATION(
  MODEL_NAME,
  MATERIALIZATION_NAME,
  PHYSICAL_SCHEMA,
  PHYSICAL_OBJECT,
  MATERIALIZATION_TYPE,
  FRESHNESS_POLICY
) AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end

local function normalize_choice(value, label, allowed)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local choice = string.upper(trim(value))
    for _, allowed_value in ipairs(allowed) do
        if choice == allowed_value then
            return choice
        end
    end
    error("SEMANTIC_ADMIN_003: invalid " .. label .. ": " .. tostring(value))
end

local function optional_text(value)
    if missing(value) then
        return null
    end
    return tostring(value)
end

local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end

local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then
        return nil
    end
    return rows[1][1]
end

local function model_row(model_name)
    local rows = query([[
        SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID AS VERSION_ID
        FROM SYS_SEMANTIC.MODELS m
        WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
    ]], {model_name = model_name})
    if rows == nil or #rows == 0 then
        error("SEMANTIC_ADMIN_011: model not found: " .. model_name)
    end
    return {
        model_id = row_value(rows[1], "MODEL_ID", 1),
        version_id = row_value(rows[1], "VERSION_ID", 2)
    }
end

local function source_object_exists(schema_name, object_name)
    local count = scalar([[
        SELECT COUNT(*)
        FROM (
          SELECT TABLE_NAME AS OBJECT_NAME
          FROM SYS.EXA_ALL_TABLES
          WHERE TABLE_SCHEMA = UPPER(:schema_name)
            AND TABLE_NAME = UPPER(:object_name)
          UNION ALL
          SELECT VIEW_NAME AS OBJECT_NAME
          FROM SYS.EXA_ALL_VIEWS
          WHERE VIEW_SCHEMA = UPPER(:schema_name)
            AND VIEW_NAME = UPPER(:object_name)
        ) visible_objects
    ]], {schema_name = schema_name, object_name = object_name})
    return tonumber(count or 0) > 0
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local materialization_name = normalize_name(MATERIALIZATION_NAME, "MATERIALIZATION_NAME")
local physical_schema = normalize_name(PHYSICAL_SCHEMA, "PHYSICAL_SCHEMA")
local physical_object = normalize_name(PHYSICAL_OBJECT, "PHYSICAL_OBJECT")
local materialization_type = normalize_choice(MATERIALIZATION_TYPE, "MATERIALIZATION_TYPE", {"AGGREGATE"})
local model = model_row(model_name)

if not source_object_exists(physical_schema, physical_object) then
    error("SEMANTIC_ADMIN_030: materialization physical object not found: " .. physical_schema .. "." .. physical_object)
end

local duplicate = scalar([[
    SELECT COUNT(*)
    FROM SYS_SEMANTIC.MATERIALIZATIONS
    WHERE MODEL_ID = :model_id
      AND VERSION_ID = :version_id
      AND UPPER(MATERIALIZATION_NAME) = UPPER(:materialization_name)
]], {
    model_id = model.model_id,
    version_id = model.version_id,
    materialization_name = materialization_name
})
if tonumber(duplicate or 0) > 0 then
    error("SEMANTIC_ADMIN_031: duplicate materialization: " .. materialization_name)
end

query([[
    INSERT INTO SYS_SEMANTIC.MATERIALIZATIONS (
      MODEL_ID, VERSION_ID, MATERIALIZATION_NAME, PHYSICAL_SCHEMA,
      PHYSICAL_OBJECT, MATERIALIZATION_TYPE, FRESHNESS_POLICY, STATUS
    ) VALUES (
      :model_id, :version_id, :materialization_name, :physical_schema,
      :physical_object, :materialization_type, :freshness_policy, 'ACTIVE'
    )
]], {
    model_id = model.model_id,
    version_id = model.version_id,
    materialization_name = materialization_name,
    physical_schema = physical_schema,
    physical_object = physical_object,
    materialization_type = materialization_type,
    freshness_policy = optional_text(FRESHNESS_POLICY)
})
-- A new materialization expands the set of candidate plans, so drop cached
-- compile results for this model version (BUG-D-002 cache coherence).
query([[
    DELETE FROM SYS_SEMANTIC.COMPILE_CACHE
    WHERE MODEL_VERSION_ID = :version_id
]], {version_id = model.version_id})
-- SOURCE_TRUST classifies the relations this model reads, and this call changed
-- that set, so the stored classes no longer describe it. They are derived by
-- VALIDATE_MODEL and cannot be recomputed here; clearing them makes the gap
-- visible as an empty SOURCE_TRUST_FOR_MODEL rather than as a picture that
-- quietly omits the relation just registered. The next VALIDATE_MODEL rebuilds
-- them, which is the next step in the authoring order anyway.
query([[
    DELETE FROM SYS_SEMANTIC.SOURCE_TRUST
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
]], {model_id = model.model_id, version_id = model.version_id})
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.ADD_MATERIALIZATION_COLUMN(
  MODEL_NAME,
  MATERIALIZATION_NAME,
  OBJECT_TYPE,
  OBJECT_NAME,
  PHYSICAL_COLUMN,
  ROLLUP_POLICY
) AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end

local function normalize_choice(value, label, allowed)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local choice = string.upper(trim(value))
    for _, allowed_value in ipairs(allowed) do
        if choice == allowed_value then
            return choice
        end
    end
    error("SEMANTIC_ADMIN_003: invalid " .. label .. ": " .. tostring(value))
end

local function optional_choice(value, allowed, default_value)
    if missing(value) then
        return default_value
    end
    local choice = string.upper(trim(value))
    for _, allowed_value in ipairs(allowed) do
        if choice == allowed_value then
            return choice
        end
    end
    error("SEMANTIC_ADMIN_003: invalid ROLLUP_POLICY: " .. tostring(value))
end

local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end

local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then
        return nil
    end
    return rows[1][1]
end

local function model_row(model_name)
    local rows = query([[
        SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID AS VERSION_ID
        FROM SYS_SEMANTIC.MODELS m
        WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
    ]], {model_name = model_name})
    if rows == nil or #rows == 0 then
        error("SEMANTIC_ADMIN_011: model not found: " .. model_name)
    end
    return {
        model_id = row_value(rows[1], "MODEL_ID", 1),
        version_id = row_value(rows[1], "VERSION_ID", 2)
    }
end

local function materialization_id(model, materialization_name)
    local id = scalar([[
        SELECT MATERIALIZATION_ID
        FROM SYS_SEMANTIC.MATERIALIZATIONS
        WHERE MODEL_ID = :model_id
          AND VERSION_ID = :version_id
          AND UPPER(MATERIALIZATION_NAME) = UPPER(:materialization_name)
    ]], {
        model_id = model.model_id,
        version_id = model.version_id,
        materialization_name = materialization_name
    })
    if id == nil then
        error("SEMANTIC_ADMIN_032: materialization not found: " .. materialization_name)
    end
    return id
end

local function semantic_object_id(model, object_type, object_name)
    local table_name
    local id_column
    local name_column
    if object_type == "DIMENSION" then
        table_name = "SYS_SEMANTIC.DIMENSIONS"
        id_column = "DIMENSION_ID"
        name_column = "DIMENSION_NAME"
    elseif object_type == "METRIC" then
        table_name = "SYS_SEMANTIC.METRICS"
        id_column = "METRIC_ID"
        name_column = "METRIC_NAME"
    else
        error("SEMANTIC_ADMIN_003: invalid OBJECT_TYPE: " .. object_type)
    end

    local sql_text = "SELECT " .. id_column .. " FROM " .. table_name ..
        " WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id AND UPPER(" .. name_column .. ") = UPPER(:object_name)"
    local id = scalar(sql_text, {model_id = model.model_id, version_id = model.version_id, object_name = object_name})
    if id == nil then
        error("SEMANTIC_ADMIN_022: " .. object_type .. " not found: " .. object_name)
    end
    return id
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local materialization_name = normalize_name(MATERIALIZATION_NAME, "MATERIALIZATION_NAME")
local object_type = normalize_choice(OBJECT_TYPE, "OBJECT_TYPE", {"DIMENSION", "METRIC"})
local object_name = normalize_name(OBJECT_NAME, "OBJECT_NAME")
local physical_column = normalize_name(PHYSICAL_COLUMN, "PHYSICAL_COLUMN")
local rollup_policy = optional_choice(ROLLUP_POLICY, {"DIRECT", "NONE", "SUM", "MIN", "MAX", "COUNT"}, object_type == "DIMENSION" and "DIRECT" or "DIRECT")
local model = model_row(model_name)
local mat_id = materialization_id(model, materialization_name)
local object_id = semantic_object_id(model, object_type, object_name)

local duplicate = scalar([[
    SELECT COUNT(*)
    FROM SYS_SEMANTIC.MATERIALIZATION_COLUMNS
    WHERE MATERIALIZATION_ID = :materialization_id
      AND OBJECT_TYPE = :object_type
      AND OBJECT_ID = :object_id
]], {
    materialization_id = mat_id,
    object_type = object_type,
    object_id = object_id
})
if tonumber(duplicate or 0) > 0 then
    error("SEMANTIC_ADMIN_033: duplicate materialization column: " .. object_type .. " " .. object_name)
end

query([[
    INSERT INTO SYS_SEMANTIC.MATERIALIZATION_COLUMNS (
      MATERIALIZATION_ID, OBJECT_TYPE, OBJECT_ID, PHYSICAL_COLUMN, ROLLUP_POLICY
    ) VALUES (
      :materialization_id, :object_type, :object_id, :physical_column, :rollup_policy
    )
]], {
    materialization_id = mat_id,
    object_type = object_type,
    object_id = object_id,
    physical_column = physical_column,
    rollup_policy = rollup_policy
})
-- New materialization column means selection of this materialization may now
-- apply to additional requests, so drop cached compile results for this model
-- version (BUG-D-002 cache coherence).
query([[
    DELETE FROM SYS_SEMANTIC.COMPILE_CACHE
    WHERE MODEL_VERSION_ID = :version_id
]], {version_id = model.version_id})
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.SET_MODEL_GOVERNANCE_MODE(
  MODEL_NAME,
  GOVERNANCE_MODE
) AS
-- The one declared input to the trust boundary. Everything else about it --
-- which relations are governed, which materializations carry their policy -- is
-- derived by VALIDATE_MODEL from what the database says, never declared twice.
--
-- OPEN reports; GOVERNED refuses. A model is not moved to GOVERNED silently: the
-- caller sets it, then validates, and the validation tells them what it costs.
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end

local function normalize_choice(value, label, allowed)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local choice = string.upper(trim(value))
    for _, allowed_value in ipairs(allowed) do
        if choice == allowed_value then
            return choice
        end
    end
    error("SEMANTIC_ADMIN_003: invalid " .. label .. ": " .. tostring(value))
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local mode = normalize_choice(GOVERNANCE_MODE, "GOVERNANCE_MODE", {"OPEN", "GOVERNED"})

local rows = query([[
    SELECT MODEL_ID FROM SYS_SEMANTIC.MODELS
    WHERE UPPER(MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_011: model not found: " .. model_name)
end

query([[
    UPDATE SYS_SEMANTIC.MODELS
    SET GOVERNANCE_MODE = :mode, UPDATED_AT = CURRENT_TIMESTAMP, UPDATED_BY = CURRENT_USER
    WHERE UPPER(MODEL_NAME) = UPPER(:model_name)
]], {mode = mode, model_name = model_name})

-- The stored trust classes were derived under the previous mode's rules, so they
-- no longer describe this model. Clearing them keeps a stale answer from being
-- read as a current one; the next VALIDATE_MODEL rebuilds them.
query([[
    DELETE FROM SYS_SEMANTIC.SOURCE_TRUST
    WHERE MODEL_ID IN (
      SELECT MODEL_ID FROM SYS_SEMANTIC.MODELS WHERE UPPER(MODEL_NAME) = UPPER(:model_name)
    )
]], {model_name = model_name})

-- And the compile cache with them. Moving to GOVERNED can make the model fail
-- validation, and the compiler binds to the latest run that *succeeded* -- so a
-- cached statement would go on being served by a model that no longer validates.
query([[
    DELETE FROM SYS_SEMANTIC.COMPILE_CACHE
    WHERE MODEL_VERSION_ID IN (
      SELECT ACTIVE_VERSION_ID FROM SYS_SEMANTIC.MODELS
      WHERE UPPER(MODEL_NAME) = UPPER(:model_name)
    )
]], {model_name = model_name})
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.CHECK_FROZEN_VIEWS(
  MODEL_NAME
)
RETURNS TABLE AS
-- Which views compiled from this model no longer match what it would compile.
--
-- This is the exact question, and it needs the compiler to answer, which is why
-- it is a script rather than a VALIDATE_MODEL rule. The cheaper proxies do not
-- work here: ESV creates exactly one model version -- CREATE_MODEL makes version
-- 1 and nothing makes a second -- and MODELS.UPDATED_AT does not move on
-- authoring either, so there is nothing to compare a version against. What does
-- move is the definition, and the only faithful test of that is to compile the
-- same columns again and see whether the SQL comes back the same.
--
-- STATUS is CURRENT, STALE or DROPPED. A STALE view still answers; it answers
-- with the model as it was when the view was made.
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end
local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end
local function row_value(row, name, position)
    if row == nil then return nil end
    return row[name] or row[string.lower(name)] or row[position]
end
local function quote_ident(name)
    return '"' .. string.gsub(tostring(name), '"', '""') .. '"'
end
local function sql_string(value)
    return "'" .. string.gsub(tostring(value), "'", "''") .. "'"
end

if missing(MODEL_NAME) then
    error("SEMANTIC_ADMIN_001: MODEL_NAME is required")
end
local model_name = trim(MODEL_NAME)

local model_rows = query([[
    SELECT MODEL_ID, PUBLISHED_SCHEMA FROM SYS_SEMANTIC.MODELS
    WHERE UPPER(MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name})
if model_rows == nil or #model_rows == 0 then
    error("SEMANTIC_ADMIN_011: model not found: " .. model_name)
end
local model_id = row_value(model_rows[1], "MODEL_ID", 1)
local published_schema = row_value(model_rows[1], "PUBLISHED_SCHEMA", 2)

local frozen = query([[
    SELECT fv.VIEW_SCHEMA, fv.VIEW_NAME, fv.OBJECT_NAME, fv.FROZEN_COLUMNS,
           fv.FROZEN_SQL,
           CASE WHEN v.VIEW_NAME IS NULL THEN 0 ELSE 1 END AS STILL_EXISTS
      FROM SYS_SEMANTIC.FROZEN_VIEWS fv
      LEFT JOIN SYS.EXA_ALL_VIEWS v
        ON UPPER(v.VIEW_SCHEMA) = UPPER(fv.VIEW_SCHEMA)
       AND UPPER(v.VIEW_NAME) = UPPER(fv.VIEW_NAME)
     WHERE fv.MODEL_ID = :model_id
     ORDER BY fv.FROZEN_VIEW_ID
]], {model_id = model_id})

local output_rows = {}
for _, row in ipairs(frozen or {}) do
    local view_schema = tostring(row_value(row, "VIEW_SCHEMA", 1))
    local view_name = tostring(row_value(row, "VIEW_NAME", 2))
    local object_name = row_value(row, "OBJECT_NAME", 3)
    local frozen_columns = tostring(row_value(row, "FROZEN_COLUMNS", 4) or "")
    local frozen_sql = row_value(row, "FROZEN_SQL", 5)
    local still_exists = tonumber(row_value(row, "STILL_EXISTS", 6) or 0) == 1

    if not still_exists then
        output_rows[#output_rows + 1] = {view_schema, view_name, "DROPPED",
            "The view is gone; the record can be deleted."}
    elseif missing(frozen_sql) or frozen_columns == "" then
        -- Frozen by a build that did not record a baseline. Saying so beats
        -- reporting CURRENT, which would be a guess wearing an answer's clothes.
        output_rows[#output_rows + 1] = {view_schema, view_name, "UNKNOWN",
            "No compiled baseline was recorded for this view; re-create it to"
            .. " start tracking it."}
    else
        local parts = {}
        for column in string.gmatch(frozen_columns, "[^,]+") do
            parts[#parts + 1] = quote_ident(column)
        end
        local probe = "SELECT " .. table.concat(parts, ", ") .. " FROM "
            .. quote_ident(published_schema) .. "." .. quote_ident(tostring(object_name))
        local compiled = query("EXECUTE SCRIPT SEMANTIC_ADMIN.COMPILE_SQL("
            .. sql_string(probe) .. ")")
        local status = row_value(compiled and compiled[1], "STATUS", 1)
        local current_sql = row_value(compiled and compiled[1], "GENERATED_SQL", 5)
        if status ~= "OK" then
            output_rows[#output_rows + 1] = {view_schema, view_name, "STALE",
                "The model no longer compiles the columns this view froze: "
                .. tostring(row_value(compiled and compiled[1], "ERROR_MESSAGE", 3))}
        elseif tostring(current_sql) ~= tostring(frozen_sql) then
            output_rows[#output_rows + 1] = {view_schema, view_name, "STALE",
                "The model now compiles different SQL for the same columns."
                .. " This view still answers, with the definition as it was when"
                .. " the view was created. Re-create it to pick the change up."}
        else
            output_rows[#output_rows + 1] = {view_schema, view_name, "CURRENT",
                "Matches what the model compiles today."}
        end
    end
end

if #output_rows == 0 then
    output_rows[#output_rows + 1] = {null, null, "NONE",
        "No view has been compiled from this model."}
end

exit(output_rows, [[
  VIEW_SCHEMA VARCHAR(256),
  VIEW_NAME VARCHAR(256),
  STATUS VARCHAR(32),
  DETAIL VARCHAR(2000000)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.SET_MODEL_DERIVED_COMPOSITION(
  MODEL_NAME,
  ALLOWED
) AS
-- Whether this model's published objects may be composed with other relations
-- in ordinary SQL.
--
-- Reference expansion turns a semantic object into a derived table, and a
-- derived table can be joined. That join can repeat the semantic result's rows,
-- and anything re-aggregating above it then double-counts -- the same fan-out a
-- Virtual Schema would produce, arriving by a different route. One thing is
-- better here: the author wrote the join themselves, so the boundary is visible
-- in their own SQL rather than chosen by an optimizer. That makes it
-- explainable, not safe, which is why the default is FALSE and refusing.
--
-- TRUE is for deployments that would rather have ordinary-SQL semantics over a
-- derived table than a refusal. It is a real choice with a real cost, so it is
-- made per model, by an administrator, in a statement that says so.
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

if missing(MODEL_NAME) then
    error("SEMANTIC_ADMIN_001: MODEL_NAME is required")
end
local model_name = trim(MODEL_NAME)

if missing(ALLOWED) then
    error("SEMANTIC_ADMIN_001: ALLOWED is required (TRUE or FALSE)")
end
local raw = string.upper(trim(ALLOWED))
local allowed
if raw == "TRUE" or raw == "YES" or raw == "1" then
    allowed = true
elseif raw == "FALSE" or raw == "NO" or raw == "0" then
    allowed = false
else
    error("SEMANTIC_ADMIN_002: ALLOWED must be TRUE or FALSE, got: " .. raw)
end

local rows = query([[
    SELECT MODEL_ID, ACTIVE_VERSION_ID FROM SYS_SEMANTIC.MODELS
    WHERE UPPER(MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name})
if rows == nil or #rows == 0 then
    error("SEMANTIC_ADMIN_011: model not found: " .. model_name)
end

query([[
    UPDATE SYS_SEMANTIC.MODELS
    SET ALLOW_DERIVED_COMPOSITION = :allowed,
        UPDATED_AT = CURRENT_TIMESTAMP, UPDATED_BY = CURRENT_USER
    WHERE UPPER(MODEL_NAME) = UPPER(:model_name)
]], {allowed = allowed, model_name = model_name})

-- Compiled SQL does not depend on this flag -- it decides whether a statement is
-- refused, not what it compiles to -- but a statement refused under FALSE was
-- never cached, and one accepted under TRUE must not survive the flag going
-- back. Clearing is cheap and removes the need to reason about which of those
-- applies.
query([[
    DELETE FROM SYS_SEMANTIC.COMPILE_CACHE
    WHERE MODEL_VERSION_ID IN (
      SELECT ACTIVE_VERSION_ID FROM SYS_SEMANTIC.MODELS
      WHERE UPPER(MODEL_NAME) = UPPER(:model_name)
    )
]], {model_name = model_name})
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.SET_MATERIALIZATION_STATUS(
  MODEL_NAME,
  MATERIALIZATION_NAME,
  STATUS
) AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end

local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_002: invalid " .. label .. ": " .. name)
    end
    return name
end

local function normalize_choice(value, label, allowed)
    if missing(value) then
        error("SEMANTIC_ADMIN_001: " .. label .. " is required")
    end
    local choice = string.upper(trim(value))
    for _, allowed_value in ipairs(allowed) do
        if choice == allowed_value then
            return choice
        end
    end
    error("SEMANTIC_ADMIN_003: invalid " .. label .. ": " .. tostring(value))
end

local function row_value(row, name, position)
    return row[name] or row[string.lower(name)] or row[position]
end

local function scalar(sql_text, params)
    local rows = query(sql_text, params or {})
    if rows == nil or #rows == 0 then
        return nil
    end
    return rows[1][1]
end

local function model_row(model_name)
    local rows = query([[
        SELECT m.MODEL_ID, m.ACTIVE_VERSION_ID AS VERSION_ID
        FROM SYS_SEMANTIC.MODELS m
        WHERE UPPER(m.MODEL_NAME) = UPPER(:model_name)
    ]], {model_name = model_name})
    if rows == nil or #rows == 0 then
        error("SEMANTIC_ADMIN_011: model not found: " .. model_name)
    end
    return {
        model_id = row_value(rows[1], "MODEL_ID", 1),
        version_id = row_value(rows[1], "VERSION_ID", 2)
    }
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local materialization_name = normalize_name(MATERIALIZATION_NAME, "MATERIALIZATION_NAME")
local status = normalize_choice(STATUS, "STATUS", {"ACTIVE", "INACTIVE", "STALE"})
local model = model_row(model_name)
local affected = scalar([[
    SELECT COUNT(*)
    FROM SYS_SEMANTIC.MATERIALIZATIONS
    WHERE MODEL_ID = :model_id
      AND VERSION_ID = :version_id
      AND UPPER(MATERIALIZATION_NAME) = UPPER(:materialization_name)
]], {
    model_id = model.model_id,
    version_id = model.version_id,
    materialization_name = materialization_name
})
if tonumber(affected or 0) == 0 then
    error("SEMANTIC_ADMIN_032: materialization not found: " .. materialization_name)
end

query([[
    UPDATE SYS_SEMANTIC.MATERIALIZATIONS
    SET STATUS = :status
    WHERE MODEL_ID = :model_id
      AND VERSION_ID = :version_id
      AND UPPER(MATERIALIZATION_NAME) = UPPER(:materialization_name)
]], {
    status = status,
    model_id = model.model_id,
    version_id = model.version_id,
    materialization_name = materialization_name
})
-- Materialization status changes affect materialization selection, so drop
-- cached compile results for this model version (BUG-D-002 cache coherence).
query([[
    DELETE FROM SYS_SEMANTIC.COMPILE_CACHE
    WHERE MODEL_VERSION_ID = :version_id
]], {version_id = model.version_id})
-- SOURCE_TRUST classifies the relations this model reads, and activating or
-- retiring a materialization changes that set, so the stored classes no longer
-- describe it. They are derived by VALIDATE_MODEL and cannot be recomputed
-- here; clearing them makes the gap visible as an empty SOURCE_TRUST_FOR_MODEL
-- rather than as a picture that still classifies a relation the planner can no
-- longer choose. The next VALIDATE_MODEL rebuilds them.
query([[
    DELETE FROM SYS_SEMANTIC.SOURCE_TRUST
    WHERE MODEL_ID = :model_id AND VERSION_ID = :version_id
]], {model_id = model.model_id, version_id = model.version_id})
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.GRANT_MODEL_ROLE(
    MODEL_NAME,
    ROLE_NAME
)
RETURNS TABLE AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end
local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end
local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_200: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_201: invalid " .. label .. ": " .. name)
    end
    return string.upper(name)
end
local function row_value(row, name, position)
    if row == nil then return nil end
    return row[name] or row[string.lower(name)] or row[position]
end
local function quote_ident(name)
    return '"' .. string.gsub(tostring(name), '"', '""') .. '"'
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local role_name = normalize_name(ROLE_NAME, "ROLE_NAME")

local model_rows = query([[
    SELECT MODEL_ID, MODEL_NAME, PUBLISHED_SCHEMA
    FROM SYS_SEMANTIC.MODELS
    WHERE UPPER(MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name})
if model_rows == nil or #model_rows == 0 then
    error("SEMANTIC_ADMIN_202: model not found: " .. model_name)
end
local model_id = row_value(model_rows[1], "MODEL_ID", 1)
local model_name_actual = row_value(model_rows[1], "MODEL_NAME", 2)
local published_schema = row_value(model_rows[1], "PUBLISHED_SCHEMA", 3)

local dup_rows = query([[
    SELECT GRANT_ID FROM SYS_SEMANTIC.MODEL_ROLE_GRANTS
    WHERE MODEL_ID = :model_id AND UPPER(ROLE_NAME) = UPPER(:role_name) AND STATUS = 'ACTIVE'
    LIMIT 1
]], {model_id = model_id, role_name = role_name})
local grant_status = 'GRANTED'
if dup_rows ~= nil and #dup_rows > 0 then
    grant_status = 'ALREADY_GRANTED'
else
    query([[
        INSERT INTO SYS_SEMANTIC.MODEL_ROLE_GRANTS (MODEL_ID, MODEL_NAME, ROLE_NAME, PUBLISHED_SCHEMA)
        VALUES (:model_id, :model_name, :role_name, :published_schema)
    ]], {model_id = model_id, model_name = model_name_actual, role_name = role_name, published_schema = published_schema})
end

-- Grant the published schema only when it is actually there. A model can be
-- granted before it is published -- the seed does exactly that -- and this used
-- to raise "object SEMANTIC_X does not exist" *after* writing the grant row,
-- leaving the caller an error and the catalog a grant. That was survivable while
-- nothing read MODEL_ROLE_GRANTS; now that authorization does, a half-applied
-- grant silently makes a model private. PUBLISH_MODEL grants the schema to every
-- role already holding the model, so the ordering no longer matters either way.
local schema_present = false
if published_schema ~= nil and tostring(published_schema) ~= "" then
    local schema_rows = query([[
        SELECT 1 FROM EXA_ALL_SCHEMAS WHERE UPPER(SCHEMA_NAME) = UPPER(:schema_name)
    ]], {schema_name = published_schema})
    schema_present = schema_rows ~= nil and #schema_rows > 0
end
if schema_present then
    query("GRANT SELECT ON SCHEMA " .. quote_ident(published_schema) .. " TO " .. quote_ident(role_name))
end

-- The role also needs to be able to *use* the layer: read the principal-scoped
-- catalog and call the compiler. Without this, granting a model produced a role
-- that could see the published views and nothing else, and the first compile
-- failed on a privilege the caller had no way to know it needed. Best effort --
-- a deployment that manages the baseline itself, or has already granted it,
-- should not have GRANT_MODEL_ROLE fail on the second call.
pcall(query, "GRANT SEMANTIC_USER TO " .. quote_ident(role_name))

exit({{ model_name_actual, role_name, published_schema, grant_status }}, [[
    MODEL_NAME VARCHAR(256),
    ROLE_NAME VARCHAR(256),
    PUBLISHED_SCHEMA VARCHAR(256),
    STATUS VARCHAR(32)
]])
/

CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.REVOKE_MODEL_ROLE(
    MODEL_NAME,
    ROLE_NAME
)
RETURNS TABLE AS
local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end
local function trim(value)
    return tostring(value):match("^%s*(.-)%s*$")
end
local function normalize_name(value, label)
    if missing(value) then
        error("SEMANTIC_ADMIN_210: " .. label .. " is required")
    end
    local name = trim(value)
    if not string.match(name, "^[A-Za-z][A-Za-z0-9_]*$") then
        error("SEMANTIC_ADMIN_211: invalid " .. label .. ": " .. name)
    end
    return string.upper(name)
end
local function row_value(row, name, position)
    if row == nil then return nil end
    return row[name] or row[string.lower(name)] or row[position]
end
local function quote_ident(name)
    return '"' .. string.gsub(tostring(name), '"', '""') .. '"'
end

local model_name = normalize_name(MODEL_NAME, "MODEL_NAME")
local role_name = normalize_name(ROLE_NAME, "ROLE_NAME")

local model_rows = query([[
    SELECT MODEL_ID, MODEL_NAME, PUBLISHED_SCHEMA
    FROM SYS_SEMANTIC.MODELS
    WHERE UPPER(MODEL_NAME) = UPPER(:model_name)
]], {model_name = model_name})
if model_rows == nil or #model_rows == 0 then
    error("SEMANTIC_ADMIN_212: model not found: " .. model_name)
end
local model_id = row_value(model_rows[1], "MODEL_ID", 1)
local model_name_actual = row_value(model_rows[1], "MODEL_NAME", 2)
local published_schema = row_value(model_rows[1], "PUBLISHED_SCHEMA", 3)

query([[
    UPDATE SYS_SEMANTIC.MODEL_ROLE_GRANTS
    SET STATUS = 'REVOKED'
    WHERE MODEL_ID = :model_id AND UPPER(ROLE_NAME) = UPPER(:role_name) AND STATUS = 'ACTIVE'
]], {model_id = model_id, role_name = role_name})

if published_schema ~= nil and tostring(published_schema) ~= "" then
    query("REVOKE SELECT ON SCHEMA " .. quote_ident(published_schema) .. " FROM " .. quote_ident(role_name))
end

exit({{ model_name_actual, role_name, published_schema, 'REVOKED' }}, [[
    MODEL_NAME VARCHAR(256),
    ROLE_NAME VARCHAR(256),
    PUBLISHED_SCHEMA VARCHAR(256),
    STATUS VARCHAR(32)
]])
/

-- BEGIN GENERATED VALIDATOR_RUNTIME
CREATE OR REPLACE SCRIPT SEMANTIC_ADMIN.VALIDATOR_RUNTIME AS
-- One JSON implementation for the whole runtime.
--
-- There were four. `compiler/request_json.lua` and `admin/semantic_definition.lua`
-- carried a byte-identical 179-line block (encoder, decoder, `is_array`, escape);
-- `agent/runtime.lua` carried a third copy of the encoder half; and
-- `admin/validator.lua` carried a fourth parser of its own for well-formedness
-- checks. `admin/fusion_declaration.lua` avoided becoming a fifth only by taking
-- a dependency on the 4 600-line DDL parser to reach an encoder.
--
-- The copies had already drifted, and the drift was invisible because nothing
-- compared them. `compiler/query_spec.lua`'s `is_array` omitted the `JSON_NULL`
-- guard the other three had -- it had no sentinel in scope to compare against --
-- so `{"metrics": null}` reached the planner as an empty list on one code path
-- and as a refusal on another. `admin/fusion_declaration.lua` borrowed a decoder
-- whose sentinel its own `missing()` did not recognise, so a JSON `null` in a
-- declaration read as a *present* value that rendered as "table: 0x...".
--
-- Both defects are the same defect: a sentinel is only meaningful to code that
-- shares its identity, and identity cannot be shared across copies. Hence one
-- module, embedded by tools/package_lua_scripts.py into every runtime script
-- that needs it, the way shared/identity_join.lua already is.
--
-- Two entry points read text, and they are deliberately not the same function:
--
--   M.decode(text)    builds a value; lenient about scalar spelling
--   M.is_valid(text)  answers yes/no; strict RFC 8259 scalar grammar
--
-- The difference is real and load-bearing, so it is one parser with one `strict`
-- flag rather than two files. `M.decode` is applied to payloads this runtime
-- wrote and must keep accepting what it accepted before; `M.is_valid` backs
-- SEMANTIC_MODEL validation of user-supplied extension JSON, where "looks close
-- enough" is the wrong answer. tests/lua/json_unit_test.lua pins each input the
-- two disagree about.

local M = {}

-- The decoded spelling of JSON `null`.
--
-- A sentinel table, not Lua `nil`: in a Lua table an explicit null and an absent
-- key are the same thing, and the difference matters wherever a document's
-- omitted key means "leave alone" and an explicit null means "unset". Callers
-- test identity (`value == json.NULL`), never `type` or `tostring`, so this
-- stays a bare table with no metatable -- giving it a `__tostring` would make
-- the wrong test look like it worked.
M.NULL = {}

function M.is_array(value)
    if type(value) ~= "table" or value == M.NULL then
        return false
    end
    local max_index = 0
    local count = 0
    for k, _ in pairs(value) do
        if type(k) ~= "number" or k < 1 or k % 1 ~= 0 then
            return false
        end
        if k > max_index then
            max_index = k
        end
        count = count + 1
    end
    return max_index == count
end

function M.escape(value)
    local text = tostring(value)
    text = string.gsub(text, "\\", "\\\\")
    text = string.gsub(text, '"', '\\"')
    text = string.gsub(text, "\n", "\\n")
    text = string.gsub(text, "\r", "\\r")
    text = string.gsub(text, "\t", "\\t")
    return text
end

-- Object keys are emitted in sorted order, which is what makes an exported
-- document comparable to a re-exported one -- the round-trip contract behind
-- EXPORT_FUSION_DECLARATION and EXPORT_SEMANTIC_DEFINITION.
function M.encode(value)
    local value_type = type(value)
    if value == nil or value == null or value == M.NULL then
        return "null"
    elseif value_type == "string" then
        return '"' .. M.escape(value) .. '"'
    elseif value_type == "number" then
        return tostring(value)
    elseif value_type == "boolean" then
        return value and "true" or "false"
    elseif value_type == "table" then
        local parts = {}
        if M.is_array(value) then
            for i = 1, #value do
                parts[#parts + 1] = M.encode(value[i])
            end
            return "[" .. table.concat(parts, ",") .. "]"
        end
        local keys = {}
        for k, _ in pairs(value) do
            keys[#keys + 1] = tostring(k)
        end
        table.sort(keys)
        for _, k in ipairs(keys) do
            parts[#parts + 1] = M.encode(k) .. ":" .. M.encode(value[k])
        end
        return "{" .. table.concat(parts, ",") .. "}"
    end
    return M.encode(tostring(value))
end

-- One recursive-descent parser. `strict` selects the scalar grammar:
--
--   strict = false  numbers are scanned loosely and handed to tonumber, a \u
--                   escape is accepted without checking its digits and decodes
--                   to "?", and a raw control character inside a string passes.
--   strict = true   numbers follow RFC 8259 exactly (no leading zero, a
--                   fraction and an exponent must have digits), \u must be four
--                   hex digits, and a byte below 0x20 inside a string is an
--                   error.
--
-- The structure -- whitespace, arrays, objects, keywords, the trailing-input
-- check -- is shared, because that half never differed between the two copies
-- this replaces. Values are built in both modes; is_valid discards them, which
-- costs less than a second traversal would cost to maintain.
local function parse(text, strict)
    if text == nil or text == null or text == M.NULL or tostring(text) == "" then
        error("empty JSON payload")
    end
    text = tostring(text)
    local pos = 1

    local function peek()
        return string.sub(text, pos, pos)
    end

    local function is_digit(c)
        return string.match(c, "^%d$") ~= nil
    end

    local function skip_ws()
        while pos <= #text do
            local c = peek()
            if c == " " or c == "\n" or c == "\r" or c == "\t" then
                pos = pos + 1
            else
                return
            end
        end
    end

    local function read_digits()
        local count = 0
        while is_digit(peek()) do
            count = count + 1
            pos = pos + 1
        end
        return count
    end

    local ESCAPES = {['"'] = '"', ["\\"] = "\\", ["/"] = "/", b = "\b",
        f = "\f", n = "\n", r = "\r", t = "\t"}

    local function parse_string()
        if peek() ~= '"' then
            error("expected string at byte " .. tostring(pos))
        end
        pos = pos + 1
        local out = {}
        while pos <= #text do
            local c = peek()
            if c == '"' then
                pos = pos + 1
                return table.concat(out)
            elseif c == "\\" then
                local e = string.sub(text, pos + 1, pos + 1)
                if ESCAPES[e] ~= nil then
                    out[#out + 1] = ESCAPES[e]
                    pos = pos + 2
                elseif e == "u" then
                    if strict then
                        for offset = 2, 5 do
                            local digit = string.sub(text, pos + offset, pos + offset)
                            if string.match(digit, "^[0-9A-Fa-f]$") == nil then
                                error("invalid unicode escape at byte " .. tostring(pos))
                            end
                        end
                    end
                    -- Lossy and long-standing: the runtime stores model metadata
                    -- as ASCII, and a decoder that expanded escapes would have to
                    -- encode them again to keep a round-trip stable.
                    out[#out + 1] = "?"
                    pos = pos + 6
                else
                    error("invalid escape at byte " .. tostring(pos))
                end
            elseif strict and (c == "" or string.byte(c) < 32) then
                error("invalid control character in string at byte " .. tostring(pos))
            else
                out[#out + 1] = c
                pos = pos + 1
            end
        end
        error("unterminated string")
    end

    local parse_value

    local function parse_number()
        local start_pos = pos
        if peek() == "-" then
            pos = pos + 1
        end
        if strict then
            if peek() == "0" then
                pos = pos + 1
            elseif string.match(peek(), "^[1-9]$") then
                read_digits()
            else
                error("invalid number at byte " .. tostring(start_pos))
            end
        else
            read_digits()
        end
        if peek() == "." then
            pos = pos + 1
            if read_digits() == 0 and strict then
                error("invalid number fraction at byte " .. tostring(pos))
            end
        end
        local c = peek()
        if c == "e" or c == "E" then
            pos = pos + 1
            c = peek()
            if c == "+" or c == "-" then
                pos = pos + 1
            end
            if read_digits() == 0 and strict then
                error("invalid number exponent at byte " .. tostring(pos))
            end
        end
        local value = tonumber(string.sub(text, start_pos, pos - 1))
        if value == nil then
            error("invalid number at byte " .. tostring(start_pos))
        end
        return value
    end

    local function parse_array()
        pos = pos + 1
        local out = {}
        skip_ws()
        if peek() == "]" then
            pos = pos + 1
            return out
        end
        while true do
            out[#out + 1] = parse_value()
            skip_ws()
            local c = peek()
            if c == "]" then
                pos = pos + 1
                return out
            elseif c == "," then
                pos = pos + 1
            else
                error("expected array comma or close at byte " .. tostring(pos))
            end
        end
    end

    local function parse_object()
        pos = pos + 1
        local out = {}
        skip_ws()
        if peek() == "}" then
            pos = pos + 1
            return out
        end
        while true do
            skip_ws()
            local name = parse_string()
            skip_ws()
            if peek() ~= ":" then
                error("expected object colon at byte " .. tostring(pos))
            end
            pos = pos + 1
            out[name] = parse_value()
            skip_ws()
            local c = peek()
            if c == "}" then
                pos = pos + 1
                return out
            elseif c == "," then
                pos = pos + 1
            else
                error("expected object comma or close at byte " .. tostring(pos))
            end
        end
    end

    function parse_value()
        skip_ws()
        local c = peek()
        if c == '"' then
            return parse_string()
        elseif c == "{" then
            return parse_object()
        elseif c == "[" then
            return parse_array()
        elseif c == "-" or is_digit(c) then
            return parse_number()
        elseif string.sub(text, pos, pos + 3) == "true" then
            pos = pos + 4
            return true
        elseif string.sub(text, pos, pos + 4) == "false" then
            pos = pos + 5
            return false
        elseif string.sub(text, pos, pos + 3) == "null" then
            pos = pos + 4
            return M.NULL
        end
        error("unexpected JSON token at byte " .. tostring(pos))
    end

    local value = parse_value()
    skip_ws()
    if pos <= #text then
        error("unexpected trailing JSON at byte " .. tostring(pos))
    end
    return value
end

-- Raises on malformed input; the message names the byte offset.
function M.decode(text)
    return parse(text, false)
end

-- Well-formedness only, under the strict scalar grammar. Never raises.
function M.is_valid(text)
    local ok = pcall(parse, text, true)
    return ok
end

ESV_JSON = M

-- Reading a driver result row, once.
--
-- Every runtime opened with the same four helpers, and the copies had drifted in
-- one way that matters: `row[name] or row[lower] or row[position]` treats a
-- boolean FALSE as absent and falls through to an ordinal that is usually nil,
-- so a FALSE read out of a row could arrive as NULL. shared/catalog_rollback.lua
-- was given an explicit nil test when it was extracted; the other six modules
-- kept the `or` chain. This is that fix, in the one place it can now be made.
--
-- The bigger reason for the module is what `row_value`'s third argument is.
--
-- Exasol returns named rows, so production reads `row[name]`. The offline test
-- harness stubs `query` with positional arrays (`{{"CUSTOMER_ID"}}`), so tests
-- read `row[position]`. Both branches are covered; the *agreement* between them
-- was not, across 763 call sites carrying a hand-counted ordinal. Worse, a
-- misspelled name in production does not fail -- it falls through to the ordinal
-- and returns whatever column happens to sit there.
--
-- ESV_TEST_MODE makes that reachable. A row that carries names is what
-- production sees; asking such a row for a name it does not have is the defect,
-- and the ordinal fallback is what hides it. A row with no names at all is a
-- positional stub, where the ordinal is the only thing there is. So the check is
-- not "the ordinal was used" -- it is "the ordinal was used on a row that could
-- have answered by name".

local M = {}

-- Everything below is inside a `do` block so this module costs the runtime one
-- main-chunk local instead of five. Exasol caps a function at 200 locals and a
-- generated runtime script is every source concatenated into one chunk, so a
-- shared module's top-level names are spent from the same budget as its
-- callers' -- see CLAUDE.md, "The 200-Local Ceiling Applies to the Sum".
do

    local json = assert(ESV_JSON, "shared JSON runtime is required")
    local STRICT = rawget(_G, "ESV_TEST_MODE") == true

    -- A SQL NULL parameter reaches an Exasol Lua script as *userdata*, and userdata
    -- is truthy, so `value or default` silently yields the address. `null` is the
    -- script-context global for it; comparing against it is the only reliable test.
    -- json.NULL is here too because a decoded document's explicit null means the
    -- same thing as an omitted key everywhere in this runtime.
    function M.missing(value)
        return value == nil or value == null or value == json.NULL
            or tostring(value) == ""
    end

    function M.null_if_missing(value)
        if M.missing(value) then
            return null
        end
        return value
    end

    -- Does this row know its own column names?
    --
    -- A named row has at least one string key. A positional row has only integers.
    -- Both shapes reach this module: the first from Exasol, the second from a test
    -- stub, and telling them apart is what makes the strict check safe to turn on.
    local function is_named(row)
        for key, _ in pairs(row) do
            if type(key) ~= "number" then return true end
        end
        return false
    end

    local function lookup(row, name, position)
        local value = row[name]
        if value == nil then value = row[string.lower(name)] end
        if value ~= nil then return value, true end
        return row[position], false
    end

    -- One column of one row, by name, with its ordinal as the fallback.
    function M.row_value(row, name, position)
        if row == nil then return nil end
        local value, by_name = lookup(row, name, position)
        -- The defect is narrower than "the ordinal was used". A named row that has
        -- neither the name nor the ordinal yields nil either way -- no ambiguity, and
        -- a partially-populated test fixture is allowed to do that. What loses data
        -- is a named row that lacks the name while *something* sits at the ordinal:
        -- the caller then gets a different column's value and cannot tell.
        if STRICT and not by_name and value ~= nil and is_named(row) then
            error("row_value: row has named columns but not '" .. tostring(name)
                .. "', so ordinal " .. tostring(position) .. " returned a different "
                .. "column's value. Fix the name, or the SELECT that was supposed to "
                .. "project it.", 2)
        end
        return value
    end

    -- The first column of the first row of a single-value query.
    --
    -- Deliberately not strict: it probes three conventional aliases before falling
    -- back to the ordinal, because `SELECT MAX(x)` names its column after the
    -- expression and no caller wants to spell that out. Missing names are the normal
    -- case here, which is exactly why it cannot use M.row_value.
    function M.scalar(sql_text, params)
        local rows = query(sql_text, params or {})
        if rows == nil or #rows == 0 then
            return nil
        end
        local row = rows[1]
        for _, name in ipairs({"VALUE", "COUNT", "MAX"}) do
            local value = row[name]
            if value == nil then value = row[string.lower(name)] end
            if value ~= nil then return value end
        end
        return row[1]
    end

end

ESV_ROWS = M

-- Reading and writing SQL text, shared by every runtime that does either.
--
-- `shared/grain_graph.lua` exists because relationship proofs must not drift
-- between the validator and the compiler, and CLAUDE.md states that invariant.
-- Nothing stated it for *SQL rendering*, and the rendering drifted the same way:
-- BUG-G03 was one defect -- a declared column name quoted verbatim -- living
-- independently in five copies of the F5 mapping join, and fixing it meant
-- finding all five.
--
-- `shared/identity_join.lua` closed that instance and, in its own header,
-- named this module as the thing it could not yet call:
--
--   > Quoting is duplicated from the caller runtimes deliberately: three lines
--   > each, against a module that would otherwise have to receive them as
--   > arguments at every call. The alternative -- a shared SQL module -- is a
--   > bigger change than this one earns.
--
-- This is that module, so identity_join now calls it instead.
--
-- Two of the routines here are the ones worth the move. `replace_qualified_alias`
-- rewrites a table alias inside an expression while respecting string literals --
-- it is how a representation's expression gets re-pointed at a different source --
-- and `strip_string_literals` backs the alias and column analysis the validator
-- proves expressions with. They were byte-identical in admin/validator.lua and
-- compiler/request_json.lua, which means the validator proved an expression safe
-- with one copy while the compiler emitted SQL with the other. A divergence
-- there is not a crash; it is SQL that is wrong and validates.

local json = assert(ESV_JSON, "shared JSON runtime is required")

local M = {}

local function upper(value)
    return string.upper(tostring(value))
end

-- ---------------------------------------------------------------------------
-- Quoting
-- ---------------------------------------------------------------------------

-- Exasol resolves an unquoted identifier case-insensitively and a quoted one
-- exactly, so everything the compiler emits is quoted and everything it quotes
-- has to be the physical spelling (see shared/source_columns.lua).
function M.quote_ident(value)
    return '"' .. string.gsub(tostring(value), '"', '""') .. '"'
end

function M.quote_qualified(schema_name, object_name)
    return M.quote_ident(schema_name) .. "." .. M.quote_ident(object_name)
end

function M.sql_string(value)
    return "'" .. string.gsub(tostring(value), "'", "''") .. "'"
end

-- A filter value rendered for its declared column type.
--
-- The type matters because Exasol will not silently coerce a string to a DATE in
-- every position, and an unadorned numeric literal compares differently from a
-- quoted one. `data_type` may be absent; an unknown type falls through to a
-- quoted string, which is the safe default.
function M.sql_literal(value, data_type)
    if value == nil or value == null or value == json.NULL then
        return "NULL"
    end
    local value_type = type(value)
    if value_type == "number" then
        return tostring(value)
    elseif value_type == "boolean" then
        return value and "TRUE" or "FALSE"
    end
    local text = tostring(value)
    local dtype = upper(data_type or "")
    if string.sub(dtype, 1, 4) == "DATE"
        and string.match(text, "^%d%d%d%d%-%d%d%-%d%d$") then
        return "DATE " .. M.sql_string(text)
    end
    if string.find(dtype, "TIMESTAMP", 1, true) == 1
        and string.match(text, "^%d%d%d%d%-%d%d%-%d%d") then
        return "TIMESTAMP " .. M.sql_string(text)
    end
    if string.find(dtype, "DECIMAL", 1, true)
        or string.find(dtype, "INT", 1, true)
        or string.find(dtype, "NUMBER", 1, true)
        or string.find(dtype, "DOUBLE", 1, true) then
        if string.match(text, "^%-?%d+%.?%d*$") then
            return text
        end
    end
    return M.sql_string(text)
end

-- ---------------------------------------------------------------------------
-- Expression rewriting
-- ---------------------------------------------------------------------------

-- Replace `source_alias.` with `target_alias.` throughout an expression, without
-- touching anything inside a string literal.
--
-- This is how an attribute bound to one representation is re-pointed at another,
-- so it runs on every fusion path. The literal handling is the part that has to
-- be right: `'o.name'` is data, `o.name` is a column reference, and a naive
-- gsub cannot tell them apart.
function M.replace_qualified_alias(expression, source_alias, target_alias)
    local source = upper(source_alias)
    local text = tostring(expression)
    local out = {}
    local i = 1
    local in_quote = false
    while i <= #text do
        local c = string.sub(text, i, i)
        local n = string.sub(text, i + 1, i + 1)
        if c == "'" then
            out[#out + 1] = c
            if in_quote and n == "'" then
                out[#out + 1] = n
                i = i + 2
            else
                in_quote = not in_quote
                i = i + 1
            end
        elseif not in_quote and string.match(c, "[A-Za-z_]") then
            local j = i + 1
            while j <= #text and string.match(string.sub(text, j, j), "[A-Za-z0-9_]") do
                j = j + 1
            end
            local cursor = j
            while string.match(string.sub(text, cursor, cursor), "%s") do cursor = cursor + 1 end
            local token = string.sub(text, i, j - 1)
            if upper(token) == source and string.sub(text, cursor, cursor) == "." then
                out[#out + 1] = target_alias
            else
                out[#out + 1] = token
            end
            i = j
        else
            out[#out + 1] = c
            i = i + 1
        end
    end
    return table.concat(out)
end

-- Blank out the contents of every string literal, preserving byte offsets.
--
-- Offsets are preserved so a caller can scan the result for aliases, column
-- references or function calls and still index back into the original text.
function M.strip_string_literals(text)
    local out = {}
    local in_quote = false
    local i = 1
    while i <= #text do
        local c = string.sub(text, i, i)
        local n = string.sub(text, i + 1, i + 1)
        if c == "'" then
            if in_quote and n == "'" then
                out[#out + 1] = " "
                out[#out + 1] = " "
                i = i + 2
            else
                in_quote = not in_quote
                out[#out + 1] = " "
                i = i + 1
            end
        elseif in_quote then
            out[#out + 1] = " "
            i = i + 1
        else
            out[#out + 1] = c
            i = i + 1
        end
    end
    return table.concat(out)
end

-- Is this expression a bare SQL NULL constant?
--
-- A binding whose expression is a literal NULL means one thing: "this
-- representation does not carry this attribute." That is a legitimate and
-- necessary declaration -- it is how a caller says the primary has no such
-- column -- but it is only ever correct as the *least* preferred binding, and
-- the catalog cannot tell a placeholder from real data without asking.
--
-- Deliberately narrow. It matches NULL and CAST(NULL AS <type>), with optional
-- wrapping parentheses, and nothing else. An exotic spelling that is also
-- constant-NULL -- COALESCE(NULL, NULL), a UDF that returns NULL -- is not
-- matched, and that is the safe direction to be wrong in: the rules built on
-- this refuse a model, so a false positive costs a user a valid model while a
-- false negative only costs the diagnostic that was missing anyway.
function M.is_null_literal(expression)
    if expression == nil then return false end
    local text = tostring(expression):match("^%s*(.-)%s*$")
    -- Peel wrapping parens: ((NULL)) is the same constant as NULL.
    while true do
        local inner = text:match("^%(%s*(.-)%s*%)$")
        if inner == nil or inner == text then break end
        text = inner
    end
    local upper_text = string.upper(text)
    if upper_text == "NULL" then return true end
    local cast_target = upper_text:match("^CAST%s*%(%s*NULL%s+AS%s+(.+)%)$")
    if cast_target == nil then return false end
    -- The target has to look like a type name, not another expression that
    -- happens to close a paren early: VARCHAR(10), DECIMAL(18,2), DATE.
    return cast_target:match("^[A-Z][A-Z0-9_ ]*%s*%(?[%d%s,%)]*$") ~= nil
end

-- ---------------------------------------------------------------------------
-- Lexing
-- ---------------------------------------------------------------------------

function M.decode_quoted_identifier(token_text)
    return string.gsub(string.sub(tostring(token_text), 2, -2), '""', '"')
end

-- The uppercase form of a token for keyword comparison.
--
-- Falls back to the token's raw `text`, which for a quoted identifier still
-- carries its quotes -- so `"AND"` never compares equal to the keyword AND
-- unless the lexer was asked to fold identifiers (see `upper_identifiers`).
function M.token_upper(token)
    if token == nil then
        return nil
    end
    return token.upper or upper(token.text)
end

-- One lexer for the Exasol dialect, with two options where its two callers
-- genuinely disagree.
--
-- Everything else -- whitespace, `--` and `/* */` comments, single-quoted
-- literals with `''` escapes, double-quoted identifiers with `""` escapes,
-- words, numbers, symbols, the trailing semicolon -- was character-for-character
-- identical in compiler/request_json.lua's `sql_tokens` and
-- admin/semantic_definition.lua's `tokenize`. A new literal form or comment
-- syntax had to be taught twice.
--
--   options.operators          fuse `>=`, `<=`, `<>`, `!=` into one token. The
--                              semantic-SQL parser compares whole operators; the
--                              DDL parser slices expressions by byte offset and
--                              never looks at them, and has always seen two
--                              symbols. Changing that for the DDL would alter a
--                              4 600-line parser for no gain.
--
--   options.upper_identifiers  set `upper` on a quoted identifier from its
--                              *decoded* value. The DDL parser wants it, because
--                              it reads names out of quoted tokens. The
--                              semantic-SQL parser must not have it: `token_upper`
--                              is what its clause scanner compares against
--                              keywords, so folding `"AND"` to `AND` would make a
--                              quoted column named "and" parse as a conjunction.
--
-- Every token carries `start_pos`, `end_pos` and `depth` regardless. The
-- semantic-SQL parser ignores them; that costs three assignments and removes the
-- reason to keep a second lexer.
function M.tokenize(text, options)
    options = options or {}
    local fuse_operators = options.operators == true
    local fold_identifiers = options.upper_identifiers == true
    local tokens = {}
    text = tostring(text)
    local i = 1
    local depth = 0
    while i <= #text do
        local c = string.sub(text, i, i)
        local n = string.sub(text, i + 1, i + 1)
        if string.match(c, "%s") then
            i = i + 1
        elseif c == "-" and n == "-" then
            i = i + 2
            while i <= #text and string.sub(text, i, i) ~= "\n" do
                i = i + 1
            end
        elseif c == "/" and n == "*" then
            i = i + 2
            while i <= #text - 1 and string.sub(text, i, i + 1) ~= "*/" do
                i = i + 1
            end
            i = math.min(i + 2, #text + 1)
        elseif c == "'" then
            local start_pos = i
            i = i + 1
            while i <= #text do
                c = string.sub(text, i, i)
                n = string.sub(text, i + 1, i + 1)
                if c == "'" and n == "'" then
                    i = i + 2
                elseif c == "'" then
                    i = i + 1
                    break
                else
                    i = i + 1
                end
            end
            tokens[#tokens + 1] = {text = string.sub(text, start_pos, i - 1),
                kind = "literal", start_pos = start_pos, end_pos = i - 1,
                depth = depth}
        elseif c == '"' then
            local start_pos = i
            i = i + 1
            while i <= #text do
                c = string.sub(text, i, i)
                n = string.sub(text, i + 1, i + 1)
                if c == '"' and n == '"' then
                    i = i + 2
                elseif c == '"' then
                    i = i + 1
                    break
                else
                    i = i + 1
                end
            end
            local token_text = string.sub(text, start_pos, i - 1)
            local decoded = M.decode_quoted_identifier(token_text)
            tokens[#tokens + 1] = {text = token_text, kind = "identifier",
                value = decoded,
                upper = fold_identifiers and upper(decoded) or nil,
                start_pos = start_pos, end_pos = i - 1, depth = depth}
        elseif string.match(c, "[A-Za-z_]") then
            local start_pos = i
            i = i + 1
            while i <= #text and string.match(string.sub(text, i, i), "[A-Za-z0-9_]") do
                i = i + 1
            end
            local token_text = string.sub(text, start_pos, i - 1)
            tokens[#tokens + 1] = {text = token_text, kind = "word",
                value = token_text, upper = upper(token_text),
                start_pos = start_pos, end_pos = i - 1, depth = depth}
        elseif string.match(c, "%d") then
            local start_pos = i
            i = i + 1
            while i <= #text and string.match(string.sub(text, i, i), "[0-9.]") do
                i = i + 1
            end
            tokens[#tokens + 1] = {text = string.sub(text, start_pos, i - 1),
                kind = "number", start_pos = start_pos, end_pos = i - 1,
                depth = depth}
        else
            local two = string.sub(text, i, i + 1)
            if fuse_operators and (two == ">=" or two == "<=" or two == "<>"
                or two == "!=") then
                tokens[#tokens + 1] = {text = two, kind = "operator", upper = two,
                    start_pos = i, end_pos = i + 1, depth = depth}
                i = i + 2
            else
                -- A closing paren carries the depth it returns to, which is the
                -- depth its matching opening paren was emitted at. Both
                -- parentheses of a top-level group therefore sit at 0 and only
                -- their contents are nested, which is what lets a clause scanner
                -- find top-level commas by reading `depth == 0`.
                local token_depth = depth
                if c == ")" then
                    depth = math.max(depth - 1, 0)
                    token_depth = depth
                end
                tokens[#tokens + 1] = {text = c, kind = "symbol", upper = c,
                    start_pos = i, end_pos = i, depth = token_depth}
                if c == "(" then
                    depth = depth + 1
                end
                i = i + 1
            end
        end
    end
    if #tokens > 0 and tokens[#tokens].text == ";" then
        table.remove(tokens, #tokens)
    end
    return tokens
end

--- Re-project compiled SQL so its result columns are the ones the caller asked
--- for, in the order they asked for them.
--
-- The planner emits columns in its own order (dimensions, then metrics) named
-- after the semantic field. A SQL client gets neither: `SELECT total_revenue,
-- customer_region` came back reversed, `AS "c11"` came back as
-- `customer_region`, and an unaliased column came back lower-case where the
-- published view advertises it upper-case. A client that binds by position gets
-- the wrong data silently; one that binds by name gets nothing.
--
-- `columns` is an ordered list of {source = <name in the compiled SQL>,
-- output = <name to present>}. Returns the SQL unchanged when the projection
-- would be the identity, so the structured lane and `SELECT *` pay nothing.
function M.output_projection(sql, columns)
    if type(sql) ~= "string" or type(columns) ~= "table" or #columns == 0 then
        return sql
    end
    local parts = {}
    for index, column in ipairs(columns) do
        local source = tostring(column.source or "")
        local output = tostring(column.output or source)
        if source == "" then
            return sql
        end
        parts[index] = M.quote_ident(source) .. " AS " .. M.quote_ident(output)
    end
    return "SELECT " .. table.concat(parts, ", ") .. "\nFROM (\n" .. sql .. "\n)"
end

ESV_SQL_TEXT = M

-- Canonical relationship graph and path-proof implementation shared by the
-- validator and compiler runtimes. The packaging step embeds this source into
-- both Exasol scripts so the installed runtime has no external dependency.

local M = {}

local function key(value)
    return tostring(value)
end

local function upper(value)
    return string.upper(tostring(value or ""))
end

local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function copy_list(values)
    local out = {}
    for _, value in ipairs(values or {}) do
        out[#out + 1] = value
    end
    return out
end

local function edge_order(left, right)
    local left_priority = tonumber(left.path_priority) or 100
    local right_priority = tonumber(right.path_priority) or 100
    if left_priority ~= right_priority then
        return left_priority < right_priority
    end
    local left_id = tonumber(left.relationship and left.relationship.id) or math.huge
    local right_id = tonumber(right.relationship and right.relationship.id) or math.huge
    if left_id ~= right_id then
        return left_id < right_id
    end
    if tostring(left.name) ~= tostring(right.name) then
        return tostring(left.name) < tostring(right.name)
    end
    return key(left.to_id) < key(right.to_id)
end

local function add_edge(target, from_id, to_id, relationship, safe, reason)
    local from_key = key(from_id)
    target[from_key] = target[from_key] or {}
    target[from_key][#target[from_key] + 1] = {
        from_id = from_id,
        to_id = to_id,
        name = relationship.name,
        relationship = relationship,
        safe = safe,
        reason = reason,
        path_priority = relationship.path_priority,
    }
end

-- Build both the cardinality-preserving graph and the complete relationship
-- graph. Fanning edges are present in the complete graph for diagnostics but
-- are never safe, and no declaration changes that: traversing one is what
-- attributes one fact row to several dimension rows. FANOUT_POLICY records
-- modeler intent for a many-to-many relationship; it is not an allocation
-- proof. Reason codes therefore name the cardinality that blocks the walk, not
-- a remedy. See
-- plans/architecture-decisions/001-grain-aware-result-semantics.md.
function M.build_edges(relationships)
    local safe_edges = {}
    local all_edges = {}

    for _, relationship in ipairs(relationships or {}) do
        local cardinality = upper(relationship.cardinality)
        local function add(from_id, to_id, safe, reason)
            add_edge(all_edges, from_id, to_id, relationship, safe, reason)
            if safe then
                add_edge(safe_edges, from_id, to_id, relationship, true, "OK")
            end
        end

        if cardinality == "ONE_TO_ONE" then
            add(relationship.from_entity_id, relationship.to_entity_id, true, "OK")
            add(relationship.to_entity_id, relationship.from_entity_id, true, "OK")
        elseif cardinality == "MANY_TO_ONE" then
            add(relationship.from_entity_id, relationship.to_entity_id, true, "OK")
            -- Walking back to the many-side attributes one row to several. No
            -- declaration makes that safe, so the reason must not name one: the
            -- strict lane already reports this direction the same way.
            add(relationship.to_entity_id, relationship.from_entity_id, false,
                "ONE_TO_MANY_ATTRIBUTION_UNSUPPORTED")
        elseif cardinality == "ONE_TO_MANY" then
            add(relationship.to_entity_id, relationship.from_entity_id, true, "OK")
            add(relationship.from_entity_id, relationship.to_entity_id, false,
                "ONE_TO_MANY_ATTRIBUTION_UNSUPPORTED")
        elseif cardinality == "MANY_TO_MANY" then
            add(relationship.from_entity_id, relationship.to_entity_id, false,
                "MANY_TO_MANY_UNSUPPORTED")
            add(relationship.to_entity_id, relationship.from_entity_id, false,
                "MANY_TO_MANY_UNSUPPORTED")
        end
    end

    for _, edge_map in ipairs({safe_edges, all_edges}) do
        for _, edges in pairs(edge_map) do
            table.sort(edges, edge_order)
        end
    end
    return safe_edges, all_edges
end

local function path_signature(path)
    local parts = {}
    for _, edge in ipairs(path) do
        parts[#parts + 1] = tostring(edge.name) .. ":" .. key(edge.to_id)
    end
    return table.concat(parts, ">")
end

local function path_text(path)
    local names = {}
    for _, edge in ipairs(path or {}) do
        names[#names + 1] = edge.name
    end
    return #names == 0 and "SELF" or table.concat(names, " > ")
end

-- Return a proof object instead of only a path. All shortest safe paths are
-- retained so semantic ambiguity cannot be hidden by relationship ordering or
-- PATH_PRIORITY.
function M.prove_path(edge_map, from_id, to_id, options)
    options = options or {}
    if missing(from_id) or missing(to_id) then
        return {ok = false, reason = "MISSING_ENTITY", candidates = {}}
    end
    if key(from_id) == key(to_id) then
        return {
            ok = true,
            reason = "OK",
            edges = {},
            path = "SELF",
            candidates = {{}},
            ambiguous = false,
        }
    end

    local queue = {{id = from_id, path = {}, visited = {[key(from_id)] = true}}}
    local best_depth_by_node = {[key(from_id)] = 0}
    local candidates = {}
    local candidate_seen = {}
    local shortest = nil
    local first_blocked_reason = nil
    local index = 1

    local max_depth = tonumber(options.max_depth) or 64
    -- Enumerating paths of every length (reject_any_ambiguity) is unbounded in a
    -- densely connected graph. These caps bound that walk, and a walk that hit
    -- one reports truncated = true so no caller can read "there is no
    -- alternative path" out of a search that stopped early.
    local max_candidates = tonumber(options.max_candidates)
    local max_visits = tonumber(options.max_visits)
    local truncated = false
    while index <= #queue do
        if max_visits ~= nil and index > max_visits then
            truncated = true
            break
        end
        local current = queue[index]
        index = index + 1
        local depth = #current.path
        if depth < max_depth
            and (shortest == nil or depth < shortest or options.reject_any_ambiguity) then
            for _, edge in ipairs(edge_map[key(current.id)] or {}) do
                if options.require_safe and not edge.safe then
                    first_blocked_reason = first_blocked_reason or edge.reason
                else
                    local next_key = key(edge.to_id)
                    if not current.visited[next_key] then
                        local next_path = copy_list(current.path)
                        next_path[#next_path + 1] = edge
                        local next_depth = #next_path
                        if next_key == key(to_id) then
                            shortest = shortest or next_depth
                            if next_depth == shortest or options.reject_any_ambiguity then
                                local signature = path_signature(next_path)
                                if not candidate_seen[signature] then
                                    if max_candidates ~= nil
                                        and #candidates >= max_candidates then
                                        truncated = true
                                    else
                                        candidate_seen[signature] = true
                                        candidates[#candidates + 1] = next_path
                                    end
                                end
                            end
                        elseif (shortest == nil or options.reject_any_ambiguity)
                            and (options.reject_any_ambiguity
                                or best_depth_by_node[next_key] == nil
                                or next_depth <= best_depth_by_node[next_key]) then
                            best_depth_by_node[next_key] = next_depth
                            local visited = {}
                            for entity_key, seen in pairs(current.visited) do
                                visited[entity_key] = seen
                            end
                            visited[next_key] = true
                            queue[#queue + 1] = {
                                id = edge.to_id,
                                path = next_path,
                                visited = visited,
                            }
                        end
                    end
                end
            end
        end
    end

    if #candidates == 0 then
        return {
            ok = false,
            reason = first_blocked_reason or "NO_RELATIONSHIP_PATH",
            candidates = {},
            ambiguous = false,
            truncated = truncated,
        }
    end

    table.sort(candidates, function(left, right)
        if #left ~= #right then return #left < #right end
        return path_signature(left) < path_signature(right)
    end)
    local ambiguous = #candidates > 1
    if ambiguous and options.reject_ambiguous then
        local descriptions = {}
        for _, candidate in ipairs(candidates) do
            descriptions[#descriptions + 1] = path_text(candidate)
        end
        return {
            ok = false,
            reason = "AMBIGUOUS_RELATIONSHIP_PATH",
            candidates = candidates,
            candidate_paths = descriptions,
            ambiguous = true,
            truncated = truncated,
        }
    end

    return {
        ok = true,
        reason = "OK",
        edges = candidates[1],
        path = path_text(candidates[1]),
        candidates = candidates,
        ambiguous = ambiguous,
        truncated = truncated,
    }
end

-- Every distinct safe path between two entities, shortest first, not only the
-- shortest ones.
--
-- prove_path measures ambiguity as "more than one shortest path" and refuses
-- that. An alternative of a different length is invisible to it: the shortest
-- path simply wins. But path length is not a semantic authority — a longer
-- path can attribute a fact row to a different dimension row and so change the
-- number. Callers use this to report the choice instead of making it silently.
-- STRICT_GRAIN refuses any such alternative outright (reject_any_ambiguity).
function M.safe_path_alternatives(edge_map, from_id, to_id, options)
    options = options or {}
    local proof = M.prove_path(edge_map, from_id, to_id, {
        require_safe = true,
        reject_ambiguous = false,
        reject_any_ambiguity = true,
        max_depth = tonumber(options.max_depth) or 64,
        max_candidates = tonumber(options.max_candidates) or 8,
        max_visits = tonumber(options.max_visits) or 50000,
    })
    local paths = {}
    for _, candidate in ipairs(proof.candidates or {}) do
        paths[#paths + 1] = {
            path = path_text(candidate),
            length = #candidate,
        }
    end
    local alternates = {}
    for index = 2, #paths do
        alternates[#alternates + 1] = paths[index]
    end
    return {
        selected = paths[1],
        alternates = alternates,
        paths = paths,
        truncated = proof.truncated == true,
    }
end

function M.path_text(path)
    return path_text(path)
end

-- Render the path a walk would take if unsafe edges were allowed, annotating
-- each unsafe edge with the reason it was rejected. Validator provenance and
-- compiler refusal messages both go through this so a rejected traversal names
-- the same blocking edge in both runtimes.
function M.rejected_path_text(edges)
    local parts = {}
    local first_reason = nil
    for _, edge in ipairs(edges or {}) do
        local name = tostring(edge.name)
        if edge.safe == false then
            local reason = tostring(edge.reason or "UNSAFE_RELATIONSHIP_EDGE")
            first_reason = first_reason or reason
            name = name .. " (rejected: " .. reason .. ")"
        end
        parts[#parts + 1] = name
    end
    if #parts == 0 then
        return nil, first_reason
    end
    return table.concat(parts, " > "), first_reason
end

-- Diagnostic for a failed safe walk: the annotated path over the complete
-- graph, plus the reason of the first edge that made it unsafe.
function M.attempted_path(all_edges, from_id, to_id)
    local proof = M.prove_path(all_edges, from_id, to_id, {
        require_safe = false,
        reject_ambiguous = true,
    })
    if proof.ok then
        return M.rejected_path_text(proof.edges)
    end
    if proof.ambiguous then
        local paths = {}
        for _, candidate in ipairs(proof.candidates or {}) do
            paths[#paths + 1] = M.rejected_path_text(candidate)
        end
        return table.concat(paths, " | "), proof.reason
    end
    return nil, proof.reason
end

-- The first unique key on an entity whose columns are all *physical*.
--
-- A key with an expression column cannot be matched against a mapping relation
-- or a join, so identity and fusion proofs need the column-only one. This lived
-- in compiler/request_json.lua as `physical_unique_key` and in
-- admin/validator.lua as `physical_fusion_key`, byte-identical under two names,
-- which is the shape that let the compiler and the validator disagree about
-- which key they were proving against. Key matching already lives here.
function M.physical_unique_key(unique_keys)
    for _, unique_key in ipairs(unique_keys or {}) do
        if #(unique_key.columns or {}) > 0 then
            local physical = true
            for _, column in ipairs(unique_key.columns) do
                if missing(column.column_name) or not missing(column.expression) then
                    physical = false
                    break
                end
            end
            if physical then return unique_key end
        end
    end
    return nil
end

function M.canonical_key(unique_key)
    local columns = {}
    for _, column in ipairs((unique_key or {}).columns or {}) do
        local column_name = nil
        local expression = nil
        if not missing(column.column_name) then
            column_name = tostring(column.column_name)
        end
        if not missing(column.expression) then
            expression = tostring(column.expression)
        end
        columns[#columns + 1] = {
            ordinal_position = tonumber(column.ordinal_position),
            column_name = column_name,
            expression = expression,
        }
    end
    table.sort(columns, function(left, right)
        return (left.ordinal_position or math.huge) < (right.ordinal_position or math.huge)
    end)
    return {
        id = unique_key and unique_key.id or nil,
        entity_id = unique_key and unique_key.entity_id or nil,
        name = unique_key and unique_key.name or nil,
        kind = upper(unique_key and unique_key.kind or "UNIQUE"),
        columns = columns,
    }
end

function M.mapping_matches_key(mappings, side, unique_key)
    local columns = (unique_key or {}).columns or {}
    if #mappings == 0 or #mappings ~= #columns then
        return false
    end
    for index, mapping in ipairs(mappings) do
        local mapped_column = mapping[side .. "_column_name"]
        local mapped_expression = mapping[side .. "_expression"]
        local key_column = columns[index]
        if not missing(key_column.column_name) then
            if upper(mapped_column) ~= upper(key_column.column_name) then
                return false
            end
        elseif tostring(mapped_expression or "") ~= tostring(key_column.expression or "") then
            return false
        end
    end
    return true
end

local function direct_column_expression(expression, source_alias)
    local text = tostring(expression or ""):match("^%s*(.-)%s*$")
    local alias, column = string.match(text,
        "^([A-Za-z_][A-Za-z0-9_]*)%s*%.%s*([A-Za-z_][A-Za-z0-9_]*)$")
    if alias ~= nil and upper(alias) == upper(source_alias) then
        return upper(column)
    end
    alias, column = string.match(text,
        '^([A-Za-z_][A-Za-z0-9_]*)%s*%.%s*"([^"]+)"$')
    if alias ~= nil and upper(alias) == upper(source_alias) then
        return column
    end
    return nil
end

function M.scalar_mapping_key(unique_keys, mappings, side)
    if #(mappings or {}) ~= 1 then
        return nil, "COMPOSITE_RELATIONSHIP_KEY_UNSUPPORTED"
    end
    local mapping = mappings[1]
    if missing(mapping[side .. "_column_name"])
        or not missing(mapping[side .. "_expression"]) then
        return nil, "EXPRESSION_RELATIONSHIP_KEY_UNSUPPORTED"
    end
    for _, unique_key in ipairs(unique_keys or {}) do
        local columns = unique_key.columns or {}
        if #columns == 1 and not missing(columns[1].column_name)
            and missing(columns[1].expression)
            and M.mapping_matches_key(mappings, side, unique_key) then
            return unique_key, nil
        end
    end
    return nil, "RELATIONSHIP_ENDPOINT_IS_NOT_SCALAR_UNIQUE_KEY"
end

function M.direct_identity_remap(identity, primary_representation,
        target_representation, unique_key)
    if identity == nil or primary_representation == nil
        or target_representation == nil or unique_key == nil then
        return nil, "SEMANTIC_IDENTITY_REMAP_METADATA_MISSING"
    end
    local primary_binding = identity.binding_by_representation
        and identity.binding_by_representation[key(primary_representation.id)] or nil
    local target_binding = identity.binding_by_representation
        and identity.binding_by_representation[key(target_representation.id)] or nil
    if primary_binding == nil or upper(primary_binding.kind) ~= "DIRECT" then
        return nil, "PRIMARY_IDENTITY_BINDING_NOT_DIRECT"
    end
    if target_binding == nil or upper(target_binding.kind) ~= "DIRECT" then
        return nil, "REPRESENTATION_IDENTITY_BINDING_NOT_DIRECT"
    end
    local key_column = unique_key.columns and unique_key.columns[1]
        and unique_key.columns[1].column_name or nil
    local anchor_column = direct_column_expression(primary_binding.expression,
        primary_representation.alias)
    if missing(key_column) or anchor_column == nil
        or upper(anchor_column) ~= upper(key_column) then
        return nil, "SEMANTIC_IDENTITY_NOT_ANCHORED_TO_RELATIONSHIP_KEY"
    end
    return {
        identity = identity,
        unique_key = unique_key,
        primary_binding = primary_binding,
        binding = target_binding,
    }, nil
end

ESV_GRAIN_GRAPH = M

-- Physical column-name resolution shared by the validator and compiler
-- runtimes. The packaging step embeds this source into both Exasol scripts so
-- the installed runtime has no external dependency.
--
-- A declared unique-key column carries the name the modeler typed, in whatever
-- case they typed it. Exasol resolves an unquoted identifier case-insensitively
-- but a quoted one exactly, so rendering a declared `customer_id` as
-- `alias."customer_id"` against a physical `CUSTOMER_ID` produces SQL that
-- parses, plans, and then fails at execution.
--
-- The validator resolved declared names against EXA_ALL_COLUMNS before probing;
-- the compiler quoted them verbatim. That asymmetry is exactly what let a model
-- validate clean, compile to `STATUS = OK`, and then fail to execute. Both
-- runtimes now resolve through this module, so what the validator probes and
-- what the compiler renders cannot drift apart.

local M = {}

local function missing(value)
    return value == nil or value == null or tostring(value) == ""
end

local function cache_key(source_schema, source_object, column_name)
    return string.upper(tostring(source_schema)) .. "."
        .. string.upper(tostring(source_object)) .. "."
        .. string.upper(tostring(column_name))
end

-- Return the physical column name as the database spells it, or nil plus a
-- reason. An exact match wins over a case-insensitive one, so a source that
-- genuinely carries two columns differing only in case still resolves to the
-- declared spelling. `cache` is an optional caller-owned table; the module
-- keeps no state of its own so a long-running session cannot serve a stale
-- name after a source is redefined.
-- Resolve two declared column names against one source in a single call.
--
-- The F5 identity mapping relation is always addressed as a pair -- the
-- source-local key and the semantic key of the same cross-reference table -- and
-- both used to be quoted verbatim, so a lower-case declaration probed as
-- `"account_id"` against a physical ACCOUNT_ID and failed (BUG-G03). Living here
-- rather than in each runtime keeps the validator's probes and the compiler's
-- rendering on one implementation, and costs neither runtime a file-scope local:
-- Exasol caps a Lua function at 200 locals and the compiler runtime's main chunk
-- is already at that ceiling.
--
-- Each name falls back to its declared spelling when the metadata cannot answer,
-- so a source outside EXA_ALL_COLUMNS probes exactly as it did before and
-- reports its own error rather than one invented here.
function M.resolve_pair(query_fn, source_schema, source_object, first, second, cache)
    local first_name = M.resolve(query_fn, source_schema, source_object,
        first, cache) or first
    local second_name = M.resolve(query_fn, source_schema, source_object,
        second, cache) or second
    return first_name, second_name
end

function M.resolve(query_fn, source_schema, source_object, column_name, cache)
    if missing(source_schema) or missing(source_object) or missing(column_name) then
        return nil, "source column is not visible: " .. tostring(column_name)
    end
    local key = cache_key(source_schema, source_object, column_name)
    if cache ~= nil and cache[key] ~= nil then
        local cached = cache[key]
        if cached.name ~= nil then return cached.name, nil end
        return nil, cached.error
    end

    local ok, rows = pcall(query_fn, [[
        SELECT COLUMN_NAME
        FROM SYS.EXA_ALL_COLUMNS
        WHERE (COLUMN_SCHEMA = :schema_name OR COLUMN_SCHEMA = UPPER(:schema_name))
          AND (COLUMN_TABLE = :object_name OR COLUMN_TABLE = UPPER(:object_name))
          AND (COLUMN_NAME = :column_name OR COLUMN_NAME = UPPER(:column_name))
        ORDER BY CASE WHEN COLUMN_NAME = :column_name THEN 0 ELSE 1 END
        LIMIT 1
    ]], {
        schema_name = source_schema,
        object_name = source_object,
        column_name = column_name,
    })
    if not ok then
        return nil, tostring(rows)
    end
    if rows == nil or #rows == 0 then
        local reason = "source column is not visible: " .. tostring(column_name)
        if cache ~= nil then cache[key] = {error = reason} end
        return nil, reason
    end
    local row = rows[1]
    local name = row["COLUMN_NAME"] or row["column_name"] or row[1]
    if missing(name) then
        local reason = "source column is not visible: " .. tostring(column_name)
        if cache ~= nil then cache[key] = {error = reason} end
        return nil, reason
    end
    name = tostring(name)
    if cache ~= nil then cache[key] = {name = name} end
    return name, nil
end

ESV_SOURCE_COLUMNS = M

-- Rendering of the F5 identity mapping join, shared by the validator's probes
-- and the compiler's generated SQL. The packaging step embeds this source into
-- both Exasol scripts so the installed runtime has no external dependency.
--
-- A MAPPED identity binding reaches its semantic key through a certified
-- two-column mapping relation, and that one join used to be written out in five
-- places: the compiler's base and alternate key expressions, and the validator's
-- grouped-key query, mapping probes, and F4 conflict probe. BUG-G03 was a single
-- defect -- a declared column name quoted verbatim, so a lower-case
-- `account_id` rendered as `"account_id"` against a physical `ACCOUNT_ID` -- and
-- it existed independently in every one of them. Fixing it meant finding and
-- editing all five, and the last was found only by grepping after the fix looked
-- complete.
--
-- This module owns the two things they were duplicating: the physical spelling of
-- the mapping relation's declared columns, and the shape of the join onto it.
-- Callers still assemble their own statement around those pieces, because a
-- COUNT probe, a grouped key set and a compiled query legitimately want
-- different shapes -- forcing one function to emit all of them would trade a
-- duplication problem for a parameter problem.

local source_columns = assert(ESV_SOURCE_COLUMNS,
    "shared source column runtime is required")
local sql_text = assert(ESV_SQL_TEXT, "shared SQL text runtime is required")

local M = {}

-- The column a semantic-key view projects. Callers reference it through
-- M.semantic_key_reference so the name is written once.
M.SEMANTIC_KEY_COLUMN = "F5_SEMANTIC_KEY"

-- The physical spelling of the mapping relation's two declared columns.
--
-- ADD_IDENTITY_MAPPING_RELATION stores what the modeler typed, and Exasol
-- resolves an unquoted identifier case-insensitively but a quoted one exactly.
-- Everything here quotes, so everything here has to resolve first.
function M.columns(query_fn, mapping, cache)
    return source_columns.resolve_pair(query_fn, mapping.source_schema,
        mapping.source_object, mapping.local_column, mapping.semantic_column,
        cache)
end

-- `"SCHEMA"."OBJECT"` for the mapping relation.
function M.mapping_source(mapping)
    return sql_text.quote_qualified(mapping.source_schema, mapping.source_object)
end

-- The semantic key as read from the mapping relation: `alias."SEMANTIC_COLUMN"`.
function M.key(map_alias, semantic_column)
    return tostring(map_alias) .. "." .. sql_text.quote_ident(semantic_column)
end

-- The join predicate onto the mapping relation:
-- `<local expression> = alias."LOCAL_COLUMN"`.
function M.predicate(local_expression, map_alias, local_column)
    return tostring(local_expression) .. " = " .. tostring(map_alias) .. "."
        .. sql_text.quote_ident(local_column)
end

-- A representation projected alongside its resolved semantic key.
--
-- Used wherever a representation has to be joined *as if* it carried the
-- canonical key: the compiler's alternate-representation source and the
-- validator's F4 conflict probe were byte-identical here apart from their alias
-- prefixes, which is the duplication this replaces.
function M.semantic_key_view(query_fn, representation, mapping, source_alias,
        map_alias, local_expression, cache)
    local local_column, semantic_column = M.columns(query_fn, mapping, cache)
    return "(SELECT " .. tostring(source_alias) .. ".*, "
        .. M.key(map_alias, semantic_column) .. " AS "
        .. sql_text.quote_ident(M.SEMANTIC_KEY_COLUMN) .. " FROM "
        .. sql_text.quote_qualified(representation.source_schema, representation.source_object)
        .. " " .. tostring(source_alias) .. " JOIN "
        .. M.mapping_source(mapping) .. " " .. tostring(map_alias)
        .. " ON " .. M.predicate(local_expression, map_alias, local_column) .. ")"
end

-- How a caller refers to the column M.semantic_key_view projected.
function M.semantic_key_reference(alias)
    return tostring(alias) .. "." .. sql_text.quote_ident(M.SEMANTIC_KEY_COLUMN)
end

ESV_IDENTITY_JOIN = M

-- Typed metric planning and strict grain-proof boundary.

local M = {PLAN_VERSION = 10}
local graph = assert(ESV_GRAIN_GRAPH, "shared grain graph runtime is required")

local function key(value) return tostring(value) end
local function upper(value) return string.upper(tostring(value or "")) end
local function missing(value)
    return value == nil or value == null or type(value) == "userdata"
        or tostring(value) == ""
end

local function sorted_keys(values)
    local out = {}
    for value_key, present in pairs(values or {}) do
        if present then out[#out + 1] = value_key end
    end
    table.sort(out)
    return out
end

local function classification(metric)
    local kind = upper(metric.metric_kind or metric.metric_type)
    local aggregate = upper(metric.aggregation_function)
    local expression = upper(metric.expression)
    if not missing(metric.window_spec_json) or kind == "WINDOW" then
        return "UNSUPPORTED_WINDOW"
    end
    if not missing(metric.distinct_key_expr) or aggregate == "COUNT_DISTINCT"
        or string.find(expression, "DISTINCT", 1, true) then
        return "UNSUPPORTED_DISTINCT"
    end
    if not missing(metric.non_additive_dimension_id) then
        return "UNSUPPORTED_NON_ADDITIVE"
    end
    if aggregate == "SUM" or string.match(expression, "^%s*SUM%s*%(") then
        return (#(metric.filters or {}) > 0 or not missing(metric.filter_expr))
            and "FILTERED_SUM" or "SUM"
    end
    if aggregate == "COUNT" or string.match(expression, "^%s*COUNT%s*%(") then
        return (#(metric.filters or {}) > 0 or not missing(metric.filter_expr))
            and "FILTERED_COUNT" or "COUNT"
    end
    if kind == "RATIO" or string.find(expression, "/", 1, true) then return "RATIO" end
    if kind == "DERIVED" or kind == "CALCULATED" then return "DERIVED_ARITHMETIC" end
    return "LEGACY_AGGREGATE"
end

local function authoritative_inputs(metric)
    local source = metric.inputs or {}
    local source_kind = "STRUCTURED_INPUTS"
    if #source == 0 then
        source = metric.dependencies or {}
        source_kind = "DEPENDENCY_FALLBACK"
    end
    local inputs = {}
    local seen = {}
    for index, input in ipairs(source) do
        local object_type = upper(input.object_type)
        local object_id = input.object_id
        local role = input.role or input.input_role
        local signature = object_type .. ":" .. key(object_id) .. ":" .. upper(role)
        if not seen[signature] then
            seen[signature] = true
            inputs[#inputs + 1] = {
                object_type = object_type,
                object_id = object_id,
                role = role,
                ordinal_position = input.ordinal_position or index,
                expression_alias = input.expression_alias,
                filter_expr = input.filter_expr,
            }
        end
    end
    return inputs, source_kind
end

local function state_spec(state_class, data_type)
    if state_class == "SUM" or state_class == "FILTERED_SUM" then
        return {
            state_kind = "SUM",
            merge_operator = "SUM",
            data_type = data_type,
            empty_behavior = "NULL",
        }
    end
    if state_class == "COUNT" or state_class == "FILTERED_COUNT" then
        return {
            state_kind = "COUNT",
            merge_operator = "SUM",
            data_type = data_type,
            empty_behavior = "ZERO",
        }
    end
    return nil
end

function M.build_dag(snapshot, selected_metrics)
    local nodes = {}
    local node_by_id = {}
    local metric_by_id = snapshot.metric_by_id or {}
    local fact_by_id = snapshot.fact_by_id or {}
    local visiting = {}
    local visited = {}
    local diagnostics = {}

    local function fact_node(fact)
        local node_id = "fact:" .. key(fact.id)
        if node_by_id[node_id] == nil then
            local node = {
                node_id = node_id,
                node_kind = "FACT_INPUT",
                fact_id = fact.id,
                name = fact.name,
                entity_id = fact.entity_id,
                data_type = fact.data_type,
            }
            nodes[#nodes + 1] = node
            node_by_id[node_id] = node
        end
        return node_by_id[node_id]
    end

    local function visit(metric)
        local metric_key = key(metric.id)
        local node_id = "metric:" .. metric_key
        if visiting[metric_key] then return nil, "METRIC_DEPENDENCY_CYCLE" end
        if visited[metric_key] then return node_by_id[node_id] end
        visiting[metric_key] = true

        local normalized_inputs, input_source = authoritative_inputs(metric)
        local inputs = {}
        local leaf_set = {}
        for _, input in ipairs(normalized_inputs) do
            if input.object_type == "METRIC" then
                local dependency = metric_by_id[key(input.object_id)]
                if dependency == nil then return nil, "MISSING_PRIVATE_METRIC_DEPENDENCY" end
                local dependency_node, err = visit(dependency)
                if err ~= nil then return nil, err end
                inputs[#inputs + 1] = {
                    kind = "METRIC",
                    id = dependency.id,
                    node_id = dependency_node.node_id,
                    role = input.role,
                    expression_alias = input.expression_alias,
                    filter_expr = input.filter_expr,
                }
                for _, entity_id in ipairs(dependency_node.leaf_entity_ids or {}) do
                    leaf_set[key(entity_id)] = entity_id
                end
            elseif input.object_type == "FACT" then
                local fact = fact_by_id[key(input.object_id)]
                if fact == nil then return nil, "MISSING_FACT_DEPENDENCY" end
                local dependency_node = fact_node(fact)
                inputs[#inputs + 1] = {
                    kind = "FACT",
                    id = fact.id,
                    node_id = dependency_node.node_id,
                    entity_id = fact.entity_id,
                    role = input.role,
                    expression_alias = input.expression_alias,
                    filter_expr = input.filter_expr,
                }
                leaf_set[key(fact.entity_id)] = fact.entity_id
            else
                inputs[#inputs + 1] = {
                    kind = input.object_type,
                    id = input.object_id,
                    role = input.role,
                    expression_alias = input.expression_alias,
                    filter_expr = input.filter_expr,
                }
            end
        end

        local leaf_entities = {}
        for _, entity_key in ipairs(sorted_keys(leaf_set)) do
            leaf_entities[#leaf_entities + 1] = leaf_set[entity_key]
        end
        local state_class = classification(metric)
        local state = state_spec(state_class, metric.data_type)
        local node_kind
        if state ~= nil then
            node_kind = "AGGREGATE_STATE"
        elseif state_class == "RATIO" or state_class == "DERIVED_ARITHMETIC" then
            node_kind = "SCALAR_FINALIZER"
        elseif string.sub(state_class, 1, 12) == "UNSUPPORTED_" then
            node_kind = "UNSUPPORTED"
        else
            node_kind = "LEGACY_AGGREGATE"
        end
        local node = {
            node_id = node_id,
            node_kind = node_kind,
            metric_id = metric.id,
            name = metric.name,
            expression = metric.expression,
            data_type = metric.data_type,
            state_class = state_class,
            aggregation_function = metric.aggregation_function,
            state_spec = state,
            base_entity_id = metric.base_entity_id,
            leaf_entity_ids = leaf_entities,
            inputs = inputs,
            input_source = input_source,
            local_filters = metric.filters or {},
            legacy_filter_expr = metric.filter_expr,
            stage = node_kind == "AGGREGATE_STATE" and "AGGREGATE"
                or (node_kind == "SCALAR_FINALIZER" and "FINALIZE" or "LEGACY"),
        }
        if node_kind == "AGGREGATE_STATE" and #leaf_entities == 0 then
            node.invalid_reason = "METRIC_INPUT_GRAIN_MISSING"
        elseif node_kind == "AGGREGATE_STATE" and #leaf_entities > 1 then
            node.invalid_reason = "METRIC_INPUT_GRAIN_AMBIGUOUS"
        end
        if metric.base_entity_id ~= nil and #leaf_entities > 0 then
            local matches_base = false
            for _, entity_id in ipairs(leaf_entities) do
                if key(entity_id) == key(metric.base_entity_id) then matches_base = true end
            end
            if not matches_base then
                diagnostics[#diagnostics + 1] = {
                    reason_code = "BASE_ENTITY_MISMATCH",
                    metric_id = metric.id,
                    declared_entity_id = metric.base_entity_id,
                    leaf_entity_ids = leaf_entities,
                }
            end
        end
        visiting[metric_key] = nil
        visited[metric_key] = true
        nodes[#nodes + 1] = node
        node_by_id[node_id] = node
        node_by_id[metric_key] = node
        return node
    end

    local selected_node_ids = {}
    for _, metric in ipairs(selected_metrics or {}) do
        local node, err = visit(metric_by_id[key(metric.id)] or metric)
        if err ~= nil then return nil, err end
        selected_node_ids[#selected_node_ids + 1] = node.node_id
    end
    return {
        nodes = nodes,
        node_by_id = node_by_id,
        selected_node_ids = selected_node_ids,
        diagnostics = diagnostics,
    }
end

local function field_ref(field)
    return {
        id = field.id or field.field_id,
        name = field.name or field.field,
        kind = field.kind or field.field_kind,
        entity_id = field.entity_id,
        data_type = field.data_type,
    }
end

function M.bind_query(spec, dimensions, metrics, global_filters, having_filters, relationship_targets)
    local bound = {
        bound_query_version = 1,
        selected_dimensions = {},
        selected_metrics = {},
        global_filters = {},
        having_filters = {},
        relationship_targets = relationship_targets or {},
        order_by = spec.order_by or {},
        limit = spec.limit,
    }
    for _, dimension in ipairs(dimensions or {}) do
        bound.selected_dimensions[#bound.selected_dimensions + 1] = field_ref(dimension)
    end
    for _, metric in ipairs(metrics or {}) do
        bound.selected_metrics[#bound.selected_metrics + 1] = field_ref(metric)
    end
    for _, filter in ipairs(global_filters or {}) do
        bound.global_filters[#bound.global_filters + 1] = {
            scope = "GLOBAL",
            field_id = filter.field_id,
            field = filter.field,
            entity_id = filter.entity_id,
            operator = filter.op,
            value = filter.value,
            value_sql = filter.value_sql,
            data_type = filter.data_type,
        }
    end
    for _, filter in ipairs(having_filters or {}) do
        bound.having_filters[#bound.having_filters + 1] = {
            scope = "HAVING",
            metric_id = filter.metric_id,
            metric = filter.metric,
            operator = filter.op,
            value = filter.value,
            value_sql = filter.value_sql,
            data_type = filter.data_type,
        }
    end
    return bound
end

local function mapping_has_expression(mapping)
    return not missing(mapping.from_expression) or not missing(mapping.to_expression)
end

local function keys_for(snapshot, entity_id)
    return (snapshot.unique_keys_by_entity or {})[key(entity_id)] or {}
end

local function matching_key(snapshot, relationship, side)
    local mappings = relationship.key_mappings or {}
    for _, mapping in ipairs(mappings) do
        if mapping_has_expression(mapping) then
            return nil, "EXPRESSION_KEY_PROOF_UNSUPPORTED"
        end
    end
    local expression_key_seen = false
    local column_key_seen = false
    for _, unique_key in ipairs(keys_for(snapshot,
        side == "from" and relationship.from_entity_id or relationship.to_entity_id)) do
        local has_expression = false
        for _, column in ipairs(unique_key.columns or {}) do
            if not missing(column.expression) then has_expression = true end
        end
        if has_expression then
            expression_key_seen = true
        else
            column_key_seen = true
            if graph.mapping_matches_key(mappings, side, unique_key) then return unique_key end
        end
    end
    if expression_key_seen and not column_key_seen then
        return nil, "EXPRESSION_KEY_PROOF_UNSUPPORTED"
    end
    return nil, "MISMATCHED_UNIQUE_KEY"
end

local function add_strict_edge(snapshot, edges, rejected, relationship, from_id, to_id, target_side)
    if #(relationship.key_mappings or {}) == 0 then
        rejected[#rejected + 1] = {
            relationship_id = relationship.id,
            from_entity_id = from_id,
            to_entity_id = to_id,
            reason = "MISSING_RELATIONSHIP_KEY_MAPPING",
        }
        return
    end
    local unique_key, reason = matching_key(snapshot, relationship, target_side)
    if unique_key == nil then
        rejected[#rejected + 1] = {
            relationship_id = relationship.id,
            from_entity_id = from_id,
            to_entity_id = to_id,
            reason = reason,
        }
        return
    end
    local from_key = key(from_id)
    edges[from_key] = edges[from_key] or {}
    local edge = {
        from_id = from_id,
        to_id = to_id,
        name = relationship.name,
        relationship = relationship,
        safe = true,
        reason = "OK",
        unique_key_id = unique_key.id,
        mapping_ordinals = {},
    }
    for _, mapping in ipairs(relationship.key_mappings or {}) do
        edge.mapping_ordinals[#edge.mapping_ordinals + 1] = mapping.ordinal_position
    end
    edges[from_key][#edges[from_key] + 1] = edge
end

function M.strict_edges(snapshot)
    local edges = {}
    local rejected = {}
    for _, relationship in ipairs(snapshot.relationships or {}) do
        local cardinality = upper(relationship.cardinality)
        if cardinality == "ONE_TO_ONE" then
            add_strict_edge(snapshot, edges, rejected, relationship,
                relationship.from_entity_id, relationship.to_entity_id, "to")
            add_strict_edge(snapshot, edges, rejected, relationship,
                relationship.to_entity_id, relationship.from_entity_id, "from")
        elseif cardinality == "MANY_TO_ONE" then
            add_strict_edge(snapshot, edges, rejected, relationship,
                relationship.from_entity_id, relationship.to_entity_id, "to")
        elseif cardinality == "ONE_TO_MANY" then
            add_strict_edge(snapshot, edges, rejected, relationship,
                relationship.to_entity_id, relationship.from_entity_id, "from")
        else
            rejected[#rejected + 1] = {
                relationship_id = relationship.id,
                reason = "MANY_TO_MANY_PROOF_UNSUPPORTED",
            }
        end
    end
    return edges, rejected
end

local function proof_json(mode, proof)
    local result = {
        mode = mode,
        status = proof.ok and "PROVEN" or "REJECTED",
        reason = proof.reason,
        candidate_paths = proof.candidate_paths or {},
        edges = {},
    }
    for _, edge in ipairs(proof.edges or {}) do
        result.edges[#result.edges + 1] = {
            relationship_id = edge.relationship and edge.relationship.id,
            relationship_name = edge.name,
            from_entity_id = edge.from_id,
            to_entity_id = edge.to_id,
            unique_key_id = edge.unique_key_id,
            mapping_ordinals = edge.mapping_ordinals or {},
        }
    end
    return result
end

local STABLE_REASONS = {
    MISSING_RELATIONSHIP_KEY_MAPPING = "RELATIONSHIP_MAPPING_MISSING",
    MISMATCHED_UNIQUE_KEY = "RELATIONSHIP_TARGET_NOT_UNIQUE",
    EXPRESSION_KEY_PROOF_UNSUPPORTED = "EXPRESSION_KEY_PROOF_UNSUPPORTED",
    MANY_TO_MANY_PROOF_UNSUPPORTED = "MANY_TO_MANY_UNSUPPORTED",
    AMBIGUOUS_RELATIONSHIP_PATH = "RELATIONSHIP_PATH_AMBIGUOUS",
}

local function strict_edge_exists(edges, edge)
    for _, candidate in ipairs(edges[key(edge.from_id)] or {}) do
        if key(candidate.to_id) == key(edge.to_id)
            and key(candidate.relationship.id) == key(edge.relationship.id) then
            return true
        end
    end
    return false
end

local function direction_reason(edge)
    local relationship = edge.relationship
    local cardinality = upper(relationship.cardinality)
    if cardinality == "MANY_TO_MANY" then return "MANY_TO_MANY_UNSUPPORTED" end
    if cardinality == "MANY_TO_ONE"
        and key(edge.from_id) == key(relationship.to_entity_id) then
        return "ONE_TO_MANY_ATTRIBUTION_UNSUPPORTED"
    end
    if cardinality == "ONE_TO_MANY"
        and key(edge.from_id) == key(relationship.from_entity_id) then
        return "ONE_TO_MANY_ATTRIBUTION_UNSUPPORTED"
    end
    return nil
end

local function blocking_rejection(rejected, edge)
    for _, item in ipairs(rejected or {}) do
        if key(item.relationship_id) == key(edge.relationship.id)
            and (item.from_entity_id == nil or key(item.from_entity_id) == key(edge.from_id))
            and (item.to_entity_id == nil or key(item.to_entity_id) == key(edge.to_id)) then
            return STABLE_REASONS[item.reason] or item.reason, item
        end
    end
    return direction_reason(edge), nil
end

function M.prove_strict(snapshot, from_id, to_id)
    local edges, rejected = M.strict_edges(snapshot)
    local proof = graph.prove_path(edges, from_id, to_id, {
        require_safe = true,
        reject_ambiguous = true,
        reject_any_ambiguity = true,
    })
    local rendered = proof_json("STRICT_GRAIN", proof)
    rendered.from_entity_id = from_id
    rendered.to_entity_id = to_id
    rendered.rejected_edges = rejected
    if proof.ok then return rendered end
    if proof.reason == "AMBIGUOUS_RELATIONSHIP_PATH" then
        rendered.reason_code = "RELATIONSHIP_PATH_AMBIGUOUS"
        return rendered
    end

    local _, all_edges = graph.build_edges(snapshot.relationships or {})
    local attempted = graph.prove_path(all_edges, from_id, to_id, {
        require_safe = false,
        reject_ambiguous = true,
        reject_any_ambiguity = true,
    })
    if attempted.reason == "AMBIGUOUS_RELATIONSHIP_PATH" then
        rendered.reason_code = "RELATIONSHIP_PATH_AMBIGUOUS"
        rendered.candidate_paths = attempted.candidate_paths or {}
        return rendered
    end
    if attempted.ok then
        rendered.attempted_path = graph.path_text(attempted.edges)
        for _, edge in ipairs(attempted.edges) do
            if not strict_edge_exists(edges, edge) then
                local reason_code, detail = blocking_rejection(rejected, edge)
                rendered.reason_code = reason_code or "DIMENSION_NOT_CONFORMED"
                rendered.blocking_edge = {
                    relationship_id = edge.relationship.id,
                    relationship_name = edge.relationship.name,
                    from_entity_id = edge.from_id,
                    to_entity_id = edge.to_id,
                    detail = detail and detail.reason or nil,
                }
                return rendered
            end
        end
    end
    rendered.reason_code = "DIMENSION_NOT_CONFORMED"
    return rendered
end

function M.prove(snapshot, from_id, to_id, mode)
    if upper(mode) == "STRICT_GRAIN" then return M.prove_strict(snapshot, from_id, to_id) end
    local edges = graph.build_edges(snapshot.relationships or {})
    local proof = graph.prove_path(edges, from_id, to_id, {
        require_safe = true,
        reject_ambiguous = true,
    })
    local rendered = proof_json("LEGACY_JOIN", proof)
    rendered.from_entity_id = from_id
    rendered.to_entity_id = to_id
    -- A proof that succeeded still has to say what it chose over what. This
    -- lane selects the shortest safe path and rejects only a tie, so an
    -- alternative of a different length would otherwise be selected against
    -- without ever being named. STRICT_GRAIN reports the same candidate list
    -- when it refuses the request.
    if proof.ok then
        local alternatives = graph.safe_path_alternatives(edges, from_id, to_id)
        -- Recorded whether or not an alternative was kept: a capped search
        -- proves nothing about what it did not reach.
        rendered.candidate_search_truncated = alternatives.truncated or nil
        if #alternatives.alternates > 0 then
            rendered.selected_path = alternatives.selected.path
            rendered.selection_reason = "SHORTEST_SAFE_PATH"
            rendered.candidate_paths = {}
            for _, candidate in ipairs(alternatives.paths) do
                rendered.candidate_paths[#rendered.candidate_paths + 1] = candidate.path
            end
            rendered.alternate_paths = {}
            for _, alternate in ipairs(alternatives.alternates) do
                rendered.alternate_paths[#rendered.alternate_paths + 1] = alternate.path
            end
        end
    end
    return rendered
end

local function add_requirement(requirements, seen, target_entity_id, dimension_id,
    dimension_name, scope, metric_id)
    if target_entity_id == nil then return end
    local signature = key(target_entity_id) .. ":" .. key(dimension_id) .. ":"
        .. tostring(scope) .. ":" .. key(metric_id)
    if seen[signature] then return end
    seen[signature] = true
    requirements[#requirements + 1] = {
        target_entity_id = target_entity_id,
        dimension_id = dimension_id,
        dimension_name = dimension_name,
        scope = scope,
        metric_id = metric_id,
    }
end

local function requirement_id(branch_id, requirement)
    return table.concat({
        branch_id,
        "requirement",
        tostring(requirement.scope),
        "entity",
        key(requirement.target_entity_id),
        "dimension",
        key(requirement.dimension_id),
        "metric",
        key(requirement.metric_id),
    }, ":")
end

local function entity_name(snapshot, entity_id)
    local entity = (snapshot.entity_by_id or {})[key(entity_id)]
    return entity and entity.name or nil
end

function M.logical_plan(spec, snapshot, bound_query, selected_metrics, relationship_targets)
    if bound_query == nil or bound_query.selected_dimensions == nil then
        bound_query = M.bind_query(spec, bound_query or {}, selected_metrics or {},
            {}, {}, relationship_targets or {})
    end
    local dag, dag_error = M.build_dag(snapshot, selected_metrics or snapshot.visible_metrics)
    if dag == nil then return nil, dag_error end

    local aggregate_nodes = {}
    local leaf_set = {}
    local failure = nil
    local legacy_state_failure = nil
    for _, node in ipairs(dag.nodes) do
        if node.node_kind == "UNSUPPORTED" or node.node_kind == "LEGACY_AGGREGATE" then
            if legacy_state_failure == nil then
                legacy_state_failure = {
                    reason_code = "METRIC_STATE_UNSUPPORTED",
                    metric_id = node.metric_id,
                    metric = node.name,
                    state_class = node.state_class,
                    aggregation_function = node.aggregation_function,
                    leaf_entity_ids = node.leaf_entity_ids,
                }
            end
            for _, entity_id in ipairs(node.leaf_entity_ids or {}) do
                leaf_set[key(entity_id)] = entity_id
            end
        elseif node.node_kind == "AGGREGATE_STATE" then
            aggregate_nodes[#aggregate_nodes + 1] = node
            if node.invalid_reason ~= nil and failure == nil then
                failure = {
                    reason_code = node.invalid_reason,
                    metric_id = node.metric_id,
                    metric = node.name,
                }
            end
            for _, entity_id in ipairs(node.leaf_entity_ids or {}) do
                leaf_set[key(entity_id)] = entity_id
            end
        end
    end

    local leaf_entities = {}
    for _, entity_key in ipairs(sorted_keys(leaf_set)) do
        leaf_entities[#leaf_entities + 1] = leaf_set[entity_key]
    end
    local has_partitioned_leaf = false
    for _, entity_id in ipairs(leaf_entities) do
        local entity = (snapshot.entity_by_id or {})[key(entity_id)]
        if entity ~= nil and upper(entity.fusion_strategy) == "UNION" then
            has_partitioned_leaf = true
            if legacy_state_failure ~= nil then
                for _, failure_entity_id in ipairs(
                    legacy_state_failure.leaf_entity_ids or {}) do
                    if key(failure_entity_id) == key(entity.id) then
                        legacy_state_failure.entity_id = entity.id
                        legacy_state_failure.entity_name = entity.name
                        legacy_state_failure.fusion_strategy = "UNION"
                        break
                    end
                end
            end
        end
    end
    local plan_kind = (#leaf_entities > 1 or has_partitioned_leaf)
        and "MULTI_BRANCH" or "SINGLE_BRANCH"
    -- Non-mergeable legacy aggregates remain valid on the unchanged
    -- single-branch compatibility renderer. They are rejected when a caller
    -- explicitly requests the strict typed boundary or when multiple leaves
    -- would require state merging.
    if failure == nil and legacy_state_failure ~= nil
        and (plan_kind == "MULTI_BRANCH" or spec.proof_mode == "STRICT_GRAIN") then
        failure = legacy_state_failure
    end
    local plan = {
        plan_version = M.PLAN_VERSION,
        plan_kind = plan_kind,
        query_spec_version = spec.query_spec_version,
        catalog_snapshot_version = snapshot.catalog_snapshot_version,
        bound_query = bound_query,
        proof_mode = plan_kind == "MULTI_BRANCH" and "STRICT_GRAIN" or spec.proof_mode,
        leaf_entity_ids = leaf_entities,
        metric_stages = dag.nodes,
        diagnostics = dag.diagnostics,
        branches = {},
        relationship_proofs = {},
        requested_dimensions = bound_query.selected_dimensions,
        requested_metrics = bound_query.selected_metrics,
        failure = failure,
        fusion_strategy = has_partitioned_leaf and "UNION" or nil,
    }

    local leaf_lookup = {}
    for _, entity_id in ipairs(leaf_entities) do leaf_lookup[key(entity_id)] = true end
    for _, dimension in ipairs(bound_query.selected_dimensions or {}) do
        local entity = (snapshot.entity_by_id or {})[key(dimension.entity_id)]
        if entity ~= nil and upper(entity.fusion_strategy) == "UNION"
            and not leaf_lookup[key(entity.id)] and plan.failure == nil then
            plan.failure = {
                reason_code = "FUSION_PARTITION_DIMENSION_UNSUPPORTED",
                entity_id = entity.id,
                entity_name = entity.name,
                dimension_id = dimension.id,
                dimension = dimension.name,
                usage = "SELECTED_DIMENSION",
            }
        end
    end
    for _, filter in ipairs(bound_query.global_filters or {}) do
        local entity = (snapshot.entity_by_id or {})[key(filter.entity_id)]
        if entity ~= nil and upper(entity.fusion_strategy) == "UNION"
            and not leaf_lookup[key(entity.id)] and plan.failure == nil then
            plan.failure = {
                reason_code = "FUSION_PARTITION_DIMENSION_UNSUPPORTED",
                entity_id = entity.id,
                entity_name = entity.name,
                dimension_id = filter.field_id,
                dimension = filter.field,
                usage = "GLOBAL_FILTER",
            }
        end
    end

    if plan_kind == "MULTI_BRANCH" then
        for _, leaf_entity_id in ipairs(leaf_entities) do
            local branch = {
                branch_id = "branch:" .. key(leaf_entity_id),
                leaf_entity_id = leaf_entity_id,
                leaf_entity_name = entity_name(snapshot, leaf_entity_id),
                state_node_ids = {},
                requirements = {},
                proofs = {},
            }
            for _, node in ipairs(aggregate_nodes) do
                if #node.leaf_entity_ids == 1
                    and key(node.leaf_entity_ids[1]) == key(leaf_entity_id) then
                    branch.state_node_ids[#branch.state_node_ids + 1] = node.node_id
                end
            end
            local requirement_seen = {}
            for _, dimension in ipairs(bound_query.selected_dimensions or {}) do
                add_requirement(branch.requirements, requirement_seen,
                    dimension.entity_id, dimension.id, dimension.name, "SELECTED", nil)
            end
            for _, filter in ipairs(bound_query.global_filters or {}) do
                add_requirement(branch.requirements, requirement_seen,
                    filter.entity_id, filter.field_id, filter.field, "GLOBAL_FILTER", nil)
            end
            for _, node in ipairs(aggregate_nodes) do
                if #node.leaf_entity_ids == 1
                    and key(node.leaf_entity_ids[1]) == key(leaf_entity_id) then
                    for _, filter in ipairs(node.local_filters or {}) do
                        local dimension_id = not missing(filter.required_dimension_id)
                            and filter.required_dimension_id or nil
                        local dimension = dimension_id ~= nil
                            and (snapshot.dimension_by_id or {})[key(dimension_id)] or nil
                        local entity_id = not missing(filter.required_entity_id)
                            and filter.required_entity_id
                            or (dimension and dimension.entity_id)
                        -- A metric-local predicate expressed directly against
                        -- its owning leaf needs no relationship proof. Only a
                        -- semantic dimension dependency adds a branch
                        -- requirement.
                        if not missing(entity_id) then
                            add_requirement(branch.requirements, requirement_seen,
                                entity_id,
                                dimension_id,
                                dimension and dimension.name or nil,
                                "METRIC_LOCAL",
                                node.metric_id)
                        end
                    end
                end
            end
            table.sort(branch.requirements, function(left, right)
                local left_key = key(left.target_entity_id) .. ":" .. key(left.dimension_id)
                    .. ":" .. tostring(left.scope) .. ":" .. key(left.metric_id)
                local right_key = key(right.target_entity_id) .. ":" .. key(right.dimension_id)
                    .. ":" .. tostring(right.scope) .. ":" .. key(right.metric_id)
                return left_key < right_key
            end)
            for _, requirement in ipairs(branch.requirements) do
                requirement.requirement_id = requirement_id(branch.branch_id, requirement)
                local proof = M.prove_strict(snapshot, leaf_entity_id,
                    requirement.target_entity_id)
                proof.proof_id = "proof:" .. requirement.requirement_id
                proof.requirement = requirement
                if proof.status == "PROVEN" and #(proof.edges or {}) > 0 then
                    proof.target_unique_key_id =
                        proof.edges[#proof.edges].unique_key_id
                elseif proof.status ~= "PROVEN" then
                    proof.rejection_id = proof.proof_id .. ":rejection"
                end
                branch.proofs[#branch.proofs + 1] = proof
                plan.relationship_proofs[#plan.relationship_proofs + 1] = proof
                if proof.status ~= "PROVEN" and plan.failure == nil then
                    plan.failure = {
                        reason_code = proof.reason_code or "DIMENSION_NOT_CONFORMED",
                        proof_id = proof.proof_id,
                        rejection_id = proof.rejection_id,
                        branch_id = branch.branch_id,
                        leaf_entity_id = leaf_entity_id,
                        metric_id = requirement.metric_id,
                        dimension_id = requirement.dimension_id,
                        dimension = requirement.dimension_name,
                        blocking_edge = proof.blocking_edge,
                        candidate_paths = proof.candidate_paths,
                    }
                end
            end
            plan.branches[#plan.branches + 1] = branch
        end
        if plan.failure == nil then
            plan.execution = {
                status = "PLANNING_ONLY",
                reason_code = "MULTI_BRANCH_EXECUTION_NOT_ENABLED",
            }
        end
    else
        local root_id = snapshot.object.root_entity_id
        for _, target in ipairs(bound_query.relationship_targets or {}) do
            local proof = M.prove(snapshot, root_id, target.target_entity_id, spec.proof_mode)
            plan.relationship_proofs[#plan.relationship_proofs + 1] = proof
        end
    end

    -- F3 expands a partitioned entity only where it is a metric's own leaf: the
    -- branch is duplicated per partition and the mergeable aggregate states are
    -- combined. Anywhere else the entity appears it is rendered from its PRIMARY
    -- representation alone, which drops every other partition's rows.
    --
    -- The two checks above catch that only when the partitioned entity is where
    -- a *dimension or filter resolves*. They miss it when the entity is merely
    -- traversed to reach a dimension on the far side, and that is the more
    -- dangerous shape: order_line -> order(F3) -> customer, grouping by a
    -- customer attribute, dropped 89% of revenue on a validated and published
    -- model while the plan recorded fusion_strategy=UNION with two partitions
    -- and rendered one source (BUG-G01). Keying on the proven path instead of on
    -- where the dimension lives covers both, since the dimension's own entity is
    -- the last node of its path.
    if plan.failure == nil then
        for _, proof in ipairs(plan.relationship_proofs or {}) do
            if proof.status == "PROVEN" and plan.failure == nil then
                local traversed = {}
                local relationship_names = {}
                for _, edge in ipairs(proof.edges or {}) do
                    traversed[#traversed + 1] = edge.from_entity_id
                    traversed[#traversed + 1] = edge.to_entity_id
                    relationship_names[#relationship_names + 1] =
                        tostring(edge.relationship_name)
                end
                for _, entity_id in ipairs(traversed) do
                    local entity = (snapshot.entity_by_id or {})[key(entity_id)]
                    if entity ~= nil and upper(entity.fusion_strategy) == "UNION"
                        and not leaf_lookup[key(entity_id)]
                        and plan.failure == nil then
                        plan.failure = {
                            reason_code = "FUSION_PARTITION_JOIN_UNSUPPORTED",
                            entity_id = entity.id,
                            entity_name = entity.name,
                            proof_id = proof.proof_id,
                            path = #relationship_names > 0
                                and table.concat(relationship_names, " > ") or nil,
                            usage = "JOIN_PATH",
                        }
                    end
                end
            end
        end
    end
    return plan, nil
end

